ClinicalChunks.register("data/templates-044.js",[{"id":"templates-115002101ba122c1eb69","key":"v1-c9ccc21dfe2a3058|templates-115002101ba122c1eb69","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肠结核","category":"门诊病历模板","raw":{"name":"肠结核","category":"门诊病历模板","case":{"case_name":"门诊病历710","templates":{"主诉":"腹痛、腹泻伴低热盗汗3个月","现病史":"患者存在肠结核相关危险因素（合并肺结核，约1/3的患者可经吞咽带菌痰液或血行播散而继发；肠外结核累及腹膜、淋巴结；有开放性肺结核接触史；免疫功能低下，如HIV感染、免疫抑制治疗、营养不良；青壮年及农村地区人群）。患者于3个月前（慢性、亚急性起病，病程数周至数月）出现以下表现：腹痛，位于右下腹或脐周，系回盲部好发部位（回肠末端与盲肠为结核好发部位）所致，呈隐痛或胀痛，进食后加重、排便后缓解，可因瘢痕狭窄引起肠梗阻而表现为阵发性绞痛，伴腹胀、呕吐；腹泻，为糊状便，每日2~4次，多见于溃疡型，也可表现为便秘与腹泻交替；右下腹包块，多见于增生型，为肉芽肿性肿块，形似肿瘤，需与克罗恩病、盲肠癌鉴别；低热、盗汗等结核全身症状；乏力、消瘦。需注意以下鉴别要点：克罗恩病为慢性炎症性肠病，以腹泻、腹痛、瘘管为主要表现，与肠结核极为相似，鉴别十分重要，因两者治疗不同，激素在肠结核患者中禁用，否则可致结核播散；病理上肠结核为干酪样坏死性肉芽肿，克罗恩病为非干酪样肉芽肿；盲肠癌多见于老年人，以肿块、便血为主要表现，需经结肠镜及活检鉴别；此外还需与溃疡性结肠炎、肠淋巴瘤鉴别。辅助检查方面可行X线及影像学检查，确诊依靠结肠镜，可观察回盲瓣溃疡并取活检行病理检查。今日来我院消化科或感染科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.6℃，P88次/分，R19次/分，BP112/70mmHg。右下腹压痛，程度较轻；右下腹可触及包块，多见于增生型，质中、不活动；合并肠梗阻者可见腹胀、肠鸣音亢进；消瘦及营养不良；低热、盗汗等全身结核表现；浅表淋巴结肿大；合并肺结核者肺部听诊可闻及啰音；腹部可有揉面感，提示腹膜结核并存。","辅助检查":"【必做】血常规（可有贫血，白细胞多正常）、血沉（明显增快）、CRP、结核菌素试验或γ-干扰素释放试验（阳性提示结核感染，支持诊断）、胸片或胸部CT（了解有无肺结核并存，约1/3患者可合并，并寻找原发灶）、粪便抗酸杆菌检查（阳性率低）、结核培养或聚合酶链反应（可送检组织或粪便标本）、肝功能（作为抗结核治疗的基线）；【确诊】结肠镜（为核心检查，可见回盲部溃疡，呈环形或匍行溃疡，边缘呈鼠咬状，伴增生性结节）、活检（可见肉芽肿，干酪样坏死为结核的特征性表现，可与克罗恩病的非干酪样肉芽肿鉴别）、抗酸杆菌染色（病理）、结核聚合酶链反应（组织）、多块活检（为诊断关键）、X线钡灌肠或小肠造影（可见回盲部狭窄、溃疡及激惹征，现已少用）、腹部CT（可见肠壁增厚、回盲部淋巴结肿大，淋巴结钙化提示结核）；【鉴别】克罗恩病（行小肠镜或结肠镜加病理，可见非干酪样肉芽肿及瘘管，注意鉴别）、结肠癌（活检）、γ-干扰素释放试验或结核菌素试验（克罗恩病多为阴性，支持肠结核）、抗结核试验性治疗（观察疗效，可作为诊断性治疗；对疑似结核与克罗恩病难以鉴别者，可试用抗结核治疗2~4周，肠结核症状改善，克罗恩病则无效）。","初步诊断":"1. 肠结核（回盲部，溃疡型或增生型待定；合并肺结核；病理见干酪样坏死肉芽肿及抗酸杆菌；需与克罗恩病及盲肠癌鉴别；评估肠梗阻、穿孔等并发症）\n（注：治疗以抗结核治疗为核心，并发症多需手术且较少见：①抗结核化疗：采用标准方案，即2HRZE/4HR，异烟肼加利福平加吡嗪酰胺加乙胺丁醇强化治疗2个月，之后改为异烟肼加利福平巩固治疗4个月；肠结核疗程为6~12个月，肺外结核多主张长疗程，即9~12个月；强调规则、全程用药及督导管理，以防耐药与复发，此点重要；疗效方面，用药2~4周后腹痛、发热等症状改善，若无效需考虑耐药或误诊为克罗恩病，应重新评估。②对症治疗：营养支持，予高蛋白饮食，因结核患者多有消耗及吸收不良；合并肠梗阻者予禁食、胃肠减压，不完全性梗阻可保守治疗；腹泻予对症处理。③手术：指征包括肠穿孔（急症）、大出血、完全性肠梗阻（因瘢痕狭窄所致，保守治疗无效）、增生型肿块与癌难以鉴别、肠瘘经保守治疗不愈；手术方式为肠切除，多行回盲部切除，需在抗结核治疗下进行，术前抗结核治疗对防止播散十分重要，术后继续抗结核治疗。④并发症处理：肠梗阻多因狭窄所致，随访中若反复发作可考虑扩张或手术；并存结核性腹膜炎者行抗结核及腹水处理；肛周瘘少见。⑤随访：完成疗程，不可自行停药；症状方面腹痛、腹泻、发热多于1~3个月消退，体重增加；复查结肠镜，于疗程末观察溃疡愈合及瘢痕情况；监测肝功能，抗结核药物肝毒性监测重要；复发率低，多见于未全程治疗者；注意营养恢复；合并肺结核者随访痰菌。消化科或感染科应规范抗结核治疗，并与克罗恩病鉴别，切勿误用激素；手术及并发症的处理亦十分重要。","处理方案":"【药物治疗】\n1. 抗结核化疗（首选初治标准方案2HRZE/4HR，全程督导、规律、足量、联合）：异烟肼片0.3g qd、利福平胶囊0.45g qd（晨起空腹顿服）、吡嗪酰胺片0.5g tid、乙胺丁醇片0.75g qd，四药联合强化治疗2个月；之后改为异烟肼片0.3g qd+利福平胶囊0.45g qd，巩固治疗4个月，总疗程6个月。\n2. 营养支持：复方氨基酸胶囊/肠内营养粉（如安素）1袋 tid，或维生素B6片10mg tid、复合维生素片1片 qd，改善营养、促进病灶修复。\n3. 对症处理：腹痛明显者予山莨菪碱片5mg tid（青光眼、前列腺肥大者禁用）；腹泻频繁者予蒙脱石散3g tid；完全性肠梗阻或穿孔征象者立即外科会诊。\n【一般治疗及生活指导】\n1. 休息：活动期（发热、腹痛、消瘦明显）卧床休息，症状缓解后适当活动，避免劳累、熬夜，保证充足睡眠。\n2. 饮食：高热量、高蛋白、高维生素、少渣易消化饮食，少量多餐；忌生冷、辛辣、粗糙、油腻及产气食物（豆类、洋葱），禁烟酒。\n3. 消毒隔离：若合并活动性肺结核，餐具、痰液注意消毒，咳嗽、打喷嚏掩口鼻，痰菌转阴前避免与家人密切接触。\n4. 用药监护：服药期间出现黄疸、肝区不适、皮疹、视力模糊或下降、关节痛、食欲减退等，及时就诊，切勿自行停药或减量。\n【随诊要求】\n1. 治疗期间每月复诊1次，复查血常规、肝肾功能、血尿酸；服乙胺丁醇者每月查视力、辨色力，服异烟肼者注意周围神经炎表现。\n2. 每1-2个月复查胸部X线或CT、腹部CT/结肠镜（必要时活检），评估肠道病灶吸收及梗阻、瘘管并发症情况。\n3. 完成全程6个月化疗后复查结肠镜及影像学评估治愈，随访1-2年；出现腹痛加剧、呕吐、便血、腹部包块增大或黄疸等随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":842,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fae5a496399a4b40471d45d3757388e5cf159a9f38e55b2b623e2a8d38aede91","pinyin":"changjiehe","initials":"cjh","setting":"out","caseName":"门诊病历710","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历710",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-45e65fb05d26cdea8a7b","key":"v1-c9ccc21dfe2a3058|templates-45e65fb05d26cdea8a7b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"缺血性结肠炎","category":"门诊病历模板","raw":{"name":"缺血性结肠炎","category":"门诊病历模板","case":{"case_name":"门诊病历711","templates":{"主诉":"突发左下腹痛伴便血、腹泻6小时","现病史":"患者存在缺血性结肠炎相关危险因素（老年人，常伴动脉粥样硬化、高血压、糖尿病、冠心病、房颤，后者作为栓子来源较少见；心衰、低血压等低灌注状态为常见诱因；近期手术、休克、脱水；药物因素，如洋地黄、血管收缩药、NSAIDs、降压药致低血压；便秘、排便用力致腹内压升高；结肠以左半结肠及脾曲为易缺血部位，属分水岭区域；全身血管病变）。患者于6小时前（突发）出现以下表现：腹痛，位于左下腹或左侧，呈突发绞痛或隐痛，轻重程度较轻，与腹部体征不符，此为缺血性结肠炎的典型特征；便血，呈暗红或鲜红色，多于24小时内出现，系黏膜坏死出血所致；腹泻，为血性便；恶心、呕吐；腹胀，提示肠麻痹。需注意腹痛重而腹部压痛轻为缺血早期的重要提示，须警惕肠坏死，全层坏死时可出现腹膜炎、剧痛、反跳痛、肌紧张及休克，属急症，需手术；发热多见于坏死或穿孔的晚期。本病多为可逆性、自限性，黏膜缺血坏死后可于数日至数周恢复；部分患者愈合后因瘢痕形成狭窄，导致慢性梗阻，属远期并发症。需与急性肠系膜缺血鉴别，后者多为肠系膜上动脉病变，表现为剧痛与体征不符，属急症，参见缺血性肠病相关章节；本病为结肠缺血，以左下腹痛、便血为主要表现。今日来我院消化科或急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P96次/分，R20次/分，BP100/62mmHg，血压偏低提示血容量不足或坏死所致休克。腹部检查：左下腹压痛，程度轻于腹痛；注意有无反跳痛及肌紧张，若出现则提示坏死、穿孔，属急症；腹胀，肠鸣音减弱；直肠指诊可见指套染血；全身情况提示脱水及组织灌注不足。","辅助检查":"【必做】血常规（白细胞升高）、CRP、D-二聚体、乳酸（升高提示肠坏死，是判断肠缺血坏死的重要指标）、血气分析（酸中毒提示坏死）、肝肾功能、电解质、心肌肌钙蛋白（了解有无心衰并存）、大便隐血；【影像】腹部CT增强（为核心检查，可见结肠肠壁节段性增厚，呈靶征，肠壁积气提示坏死，可评估肠系膜血管有无闭塞及血供下降，必要时行CTA检查肠系膜动脉及静脉，并判断有无穿孔所致气腹）、结肠镜（用于缺血性结肠炎的诊断，可见节段性黏膜充血、水肿、瘀斑及溃疡，病变与正常黏膜界限清楚，以脾曲、降结肠为特征性部位；活检可见黏膜坏死及含铁血黄素沉着的巨噬细胞，为特征性表现；急性期严重缺血或已坏死者行结肠镜需谨慎，因有穿孔风险，轻中度患者可行结肠镜检查以明确诊断；随访结肠镜可于4~6周后复查，评估愈合情况及有无瘢痕性狭窄）；【血管检查】疑有栓子或血管病变者行CTA血管造影评估，超声可检查肠系膜血管（多普勒），心脏方面可行超声心动图以评估房颤及栓子来源。","初步诊断":"1. 缺血性结肠炎（结肠缺血，多为非闭塞性，与低灌注、心衰、低血压相关，或为闭塞性但血管病因较少见；病变位于左半结肠即脾曲；腹痛与体征不符；需评估坏死后腹膜炎、乳酸升高及远期狭窄）\n（注：治疗上轻中度以保守治疗为主，多数为自限性，重度或已坏死者需手术：①一般治疗：禁食、胃肠减压以利肠道休息，静脉补液纠正低血压及低灌注是关键，恢复灌注为核心，升压药应避免过度使用，以免加重肠缺血，血管收缩药须慎用，此点重要；必要时氧疗。②药物治疗：予广谱抗生素覆盖肠道菌群，因黏膜屏障破坏可致细菌移位，可选用哌拉西林他唑巴坦或头孢类加甲硝唑，以预防坏死性感染，此点重要；避免使用血管收缩药及洋地黄，以免加重缺血；扩血管药物如罂粟碱可经动脉内给药，用于血管痉挛性缺血的评估与治疗；抗凝治疗用于房颤所致栓子，需评估后决定，无肠坏死者可考虑。③监测：观察腹痛有无加重及是否出现腹膜炎，提示坏死，属急症；监测乳酸，升高提示坏死；注意发热及感染中毒表现；观察便血量。④手术：指征包括坏死、腹膜炎、穿孔，属急症，须急诊手术，切除坏死肠段并造口，污染重者行二期吻合；休克伴坏死者亦需手术；内镜下见黏膜发黑提示严重坏死。⑤随访：恢复期腹痛、便血多于数日内消退；4~6周后复查结肠镜确认愈合，并评估有无狭窄，缺血后狭窄发生率约10~20%，可致慢性梗阻，表现为腹胀、便秘，必要时行扩张或手术；复发者需控制基础血管病，如心衰、血压、房颤及抗凝治疗，戒烟并抗动脉粥样硬化治疗，可评估他汀及抗血小板药物。消化科与血管外科协作，以保守治疗为主，纠正低灌注，监测坏死，并重视远期狭窄的随访。","处理方案":"【药物治疗】\n1. 改善肠道微循环、缓解肠系膜血管痉挛：盐酸罂粟碱片30mg tid po，疗程5~7天；或前列地尔注射液10μg+0.9%氯化钠注射液100ml ivdrip qd（腹痛明显或便血较重者，疗程3~5天，门诊静脉输液完成）。\n2. 抗感染预防肠源性感染（覆盖肠道需氧及厌氧菌）：左氧氟沙星片0.5g qd po×5天，联合甲硝唑片0.4g tid po×5天。\n3. 解痉止痛：匹维溴铵片50mg tid po，餐前服用，疗程5~7天；腹痛剧烈时可临时加用山莨菪碱片10mg tid po（青光眼、前列腺肥大者禁用）。\n4. 调节肠道菌群、修复肠黏膜屏障：双歧杆菌三联活菌胶囊420mg（2粒）tid po，与抗生素间隔2小时以上服用，疗程1~2周；便血、腹泻明显者可加用蒙脱石散3g tid po。\n【一般治疗及生活指导】\n1. 休息：急性期卧床休息1~3天，减少活动及肠道耗氧，避免剧烈运动和长时间站立；症状缓解后可逐步恢复日常活动。\n2. 饮食：急性期暂进流质饮食（米汤、藕粉、稀粥），症状缓解后过渡至低渣半流质、低脂软食，少量多餐；避免生冷、辛辣、过甜及粗纤维食物（韭菜、芹菜、粗粮），戒烟限酒。\n3. 禁忌：禁用收缩血管药物（麦角胺类、伪麻黄碱、加压素等）；避免用力排便，保持大便通畅，便秘者可加用乳果糖口服液15ml qd；避免脱水及低血压（大汗、腹泻后及时补液）。\n4. 基础病管理：合并高血压、糖尿病、冠心病者规律服药，平稳控制血压、血糖、血脂，避免血压过低或波动过大诱发肠缺血再发。\n【随诊要求】\n1. 治疗3天后门诊复诊评估腹痛、便血情况；若腹痛持续加重、便血量明显增多、出现发热、呕吐、腹胀或腹膜炎体征，立即急诊就诊。\n2. 症状缓解后4~6周复查肠镜，评估结肠黏膜愈合情况并排除结肠肿瘤、肠系膜血管病变等继发病因。\n3. 反复发作或伴严重动脉粥样硬化者，建议心内科/血管外科进一步行腹部血管超声或CTA评估肠系膜血供，明确病因后长期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":843,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"79cd05be1bf064d5c2bfc735ea4451324530ccf4e5f9925c0f5e087286a9d01b","pinyin":"quexuexingjiechangyan","initials":"qxxjcy","setting":"out","caseName":"门诊病历711","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历711",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1d09d1d2a844cc382021","key":"v1-c9ccc21dfe2a3058|templates-1d09d1d2a844cc382021","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"抗生素相关性肠炎","category":"门诊病历模板","raw":{"name":"抗生素相关性肠炎","category":"门诊病历模板","case":{"case_name":"门诊病历712","templates":{"主诉":"腹泻1天","现病史":"患者1周前无明显诱因出现抗生素相关性肠炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者1周前起病，腹泻1天，急性腹泻次数多，需先明确有无感染性腹泻、脱水及贫血，入院即刻完善血常规，了解白细胞及中性粒细胞比例以鉴别细菌感染、了解血红蛋白以排除贫血；查便常规+潜血，了解粪便性状、有无白细胞及红细胞，排除细菌性痢疾、侵袭性肠炎并明确有无消化道出血；本次腹泻与近期抗菌药物使用相关，需评估药物对肝酶的影响及肠黏膜吸收功能，完善肝功能检查，了解转氨酶、胆红素及白蛋白水平；患者伴轻度乏力，为排除胰腺炎所致腹泻，完善淀粉酶与脂肪酶检查；腹部超声检查了解肝胆胰脾形态、有无胆道梗阻及肠管积液扩张以鉴别器质性病变；腹泻持续不缓解者完善胃镜/肠镜（必要时）检查，直接观察肠黏膜有无充血糜烂、假膜形成，明确诊断并留取活检；腹部CT检查进一步明确肠壁增厚、肠腔扩张及有无腹腔脓肿等并发症；因本病常继发于幽门螺杆菌根除治疗后，完善幽门螺杆菌检测（C13/C14呼气试验），明确有无现症感染以指导后续抗菌治疗；患者存在肠道炎症及潜在出血风险，完善凝血功能检查评估凝血状态，为必要时的内镜下操作做准备；发病以来虽无明显发热、恶心呕吐，仍应定期复查上述指标，动态评估病情变化并调整治疗方案。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 抗生素相关性肠炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 立即停用或调整可疑诱发抗生素；轻中度感染首选：甲硝唑片0.4g po tid，疗程10~14天。\n2. 中重度或甲硝唑无效/复发者：万古霉素胶囊125mg po qid，疗程10~14天，重症可根据患者具体情况制定个体化方案延长至14天以上。\n3. 调节肠道菌群：双歧杆菌三联活菌胶囊420mg po tid，与抗菌药物间隔2小时以上服用，疗程2~4周。\n4. 对症止泻：蒙脱石散3g po tid，空腹服用，与其他药物间隔2小时以上；腹泻频次多伴脱水者口服补液盐Ⅲ 250ml，按需分次服用。\n\n【一般治疗及生活指导】\n1. 注意休息，腹泻急性期以卧床休息为主，避免劳累，减少肠蠕动刺激。\n2. 饮食：清淡易消化流质或半流质饮食（米汤、稀粥、烂面条），少量多餐，避免高纤维、高脂、生冷、辛辣食物及乳制品，暂禁饮酒。\n3. 注意手卫生及便后物品消毒，防止粪-口途径传播；不与他人共用毛巾餐具。\n4. 严禁自行服用抗生素及洛哌丁胺等抑制肠蠕动止泻药，以免加重毒素蓄积诱发中毒性巨结肠。\n\n【随诊要求】\n1. 治疗后3~5天复诊，评估腹泻、腹痛、发热等症状缓解情况。\n2. 若治疗48小时症状无改善或加重，或出现高热、剧烈腹痛、明显腹胀，需立即就诊，必要时住院治疗。\n3. 症状缓解后1~2周复查大便常规及艰难梭菌毒素检测，评估疗效及复发风险；曾有复发史者建议延长随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":844,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bba5eebb723386d64d659bf68cb918055c8acab281bf8aab8b75e708138c2573","pinyin":"kangshengsuxiangguanxingchangyan","initials":"kssxgxcy","setting":"out","caseName":"门诊病历712","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历712",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b3d240b9b01a8e2884f4","key":"v1-c9ccc21dfe2a3058|templates-b3d240b9b01a8e2884f4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"嗜酸细胞性胃肠炎","category":"门诊病历模板","raw":{"name":"嗜酸细胞性胃肠炎","category":"门诊病历模板","case":{"case_name":"门诊病历713","templates":{"主诉":"腹泻1天","现病史":"患者1周前无明显诱因出现嗜酸细胞性胃肠炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者1周前无明显诱因出现腹泻，本次就诊以腹泻1天为主诉，伴轻度乏力，本病以胃肠道嗜酸粒细胞浸润为特征，需先评估外周血嗜酸粒细胞水平以支持诊断，入院即刻完善血常规，了解白细胞、血红蛋白及血小板水平，排除感染、贫血及脾功能亢进所致血细胞减少；查便常规+潜血，了解有无消化道出血及肠道炎症，排除肠道感染、炎症性肠病并明确有无隐匿性失血；完善肝功能检查，了解转氨酶、胆红素、白蛋白及凝血相关指标水平，明确有无肝细胞损伤及合成功能障碍；患者伴轻度乏力，为排除胰腺疾病所致消化道症状，完善淀粉酶与脂肪酶检查，明确有无急性胰腺炎；腹部超声检查了解肝、胆、胰、脾形态及有无腹水、门静脉增宽，鉴别胆道梗阻及占位性病变；上述检查仍不能明确者，完善胃镜/肠镜（必要时）检查，直接观察食管胃底静脉、胃十二指肠及结直肠黏膜情况，明确有无静脉曲张、溃疡、占位并留取活检；腹部CT检查进一步明确腹腔实质脏器、肠壁及腹膜后有无占位、积液及血管异常，评估病变范围；因本病常与幽门螺杆菌感染相关，完善幽门螺杆菌检测（C13/C14呼气试验），明确有无现症感染以指导治疗；患者存在潜在出血及凝血异常风险，完善凝血功能检查，评估凝血酶原时间及纤维蛋白原水平，为必要时的内镜或介入操作做准备；结合初步诊断，必要时完善肿瘤标志物检查，鉴别消化道恶性肿瘤，并定期复查上述指标动态评估病情变化。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 嗜酸细胞性胃肠炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 糖皮质激素（首选）：泼尼松片 30-40mg qd 晨起顿服，连用2-4周，症状缓解后每周减量5mg，总疗程6-8周；用药期间监测血压、血糖及电解质，注意防治激素相关不良反应。\n2. 肥大细胞膜稳定剂：色甘酸钠胶囊 200mg qid 餐前30分钟口服，疗程4-8周，可作为轻症患者的一线选择或激素的辅助用药。\n3. 抗组胺药：氯雷他定片 10mg qd，疗程2-4周，用于有明确食物/药物过敏史或伴荨麻疹、过敏性鼻炎等过敏表现者。\n4. 对症治疗：腹痛明显者加用匹维溴铵片 50mg tid；腹泻明显者加用蒙脱石散 3g tid，腹泻缓解后即停；恶心呕吐明显者加用甲氧氯普胺片 5mg tid。\n\n【一般治疗及生活指导】\n1. 饮食：严格规避可疑致敏食物（如海鲜、牛奶、鸡蛋、花生、大豆、小麦等），建议记录饮食日记以查找并避免诱发食物；急性期予低敏、易消化、低纤维饮食，少食多餐，避免生冷、辛辣、油腻及含防腐剂、人工色素食品。\n2. 休息与活动：急性期注意休息，避免劳累、熬夜及精神紧张；缓解期可正常活动，适当进行有氧运动，增强体质，但避免剧烈运动诱发症状。\n3. 禁忌：戒烟戒酒；避免服用阿司匹林、布洛芬等非甾体抗炎药及可疑过敏药物；避免接触花粉、尘螨、宠物皮毛等常见过敏原。\n4. 合并哮喘、过敏性鼻炎等过敏性疾病者，应同时规范治疗基础过敏性疾病，控制过敏状态。\n\n【随诊要求】\n1. 激素治疗期间每2-4周复诊一次，评估症状改善情况及激素不良反应（血压、血糖、血钾、体质量等），据此调整激素减量速度。\n2. 治疗结束后1-3个月复查血常规，观察外周血嗜酸性粒细胞计数变化；症状反复者必要时复查胃镜/肠镜及多点黏膜活检评估黏膜嗜酸性粒细胞浸润情况。\n3. 若出现剧烈腹痛、便血、腹水、肠梗阻征象、吞咽困难或明显体重下降等病情加重表现，应立即就诊，必要时住院治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":845,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"87ad8d8dcc544f2b5e02bac1083f61c93215edf85d4cde36e5697d710de6316b","pinyin":"shisuanxibaoxingweichangyan","initials":"ssxbxwcy","setting":"out","caseName":"门诊病历713","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历713",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-80900737edd1bab2a8ca","key":"v1-c9ccc21dfe2a3058|templates-80900737edd1bab2a8ca","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"蛋白丢失性胃肠病","category":"门诊病历模板","raw":{"name":"蛋白丢失性胃肠病","category":"门诊病历模板","case":{"case_name":"门诊病历714","templates":{"主诉":"水肿1天","现病史":"患者1周前无明显诱因出现蛋白丢失性胃肠病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以水肿1天为主诉，起病1周，伴轻度乏力，本病核心为胃肠道蛋白异常丢失导致低蛋白血症，需评估营养及蛋白合成状态以支持诊断，入院即刻完善血常规，了解白细胞、血红蛋白及血小板水平，排除感染、贫血及脾功能亢进所致血细胞减少；查便常规+潜血，了解有无消化道出血及肠道炎症，排除肠道感染、炎症性肠病并明确有无隐匿性失血；完善肝功能检查，了解转氨酶、胆红素、白蛋白及凝血相关指标水平，明确有无肝细胞损伤及合成功能障碍；患者伴轻度乏力，为排除胰腺疾病所致消化道症状，完善淀粉酶与脂肪酶检查，明确有无急性胰腺炎；腹部超声检查了解肝、胆、胰、脾形态及有无腹水、门静脉增宽，鉴别胆道梗阻及占位性病变；上述检查仍不能明确者，完善胃镜/肠镜（必要时）检查，直接观察食管胃底静脉、胃十二指肠及结直肠黏膜情况，明确有无静脉曲张、溃疡、占位并留取活检；腹部CT检查进一步明确腹腔实质脏器、肠壁及腹膜后有无占位、积液及血管异常，评估病变范围；因本病常与幽门螺杆菌感染相关，完善幽门螺杆菌检测（C13/C14呼气试验），明确有无现症感染以指导治疗；患者存在潜在出血及凝血异常风险，完善凝血功能检查，评估凝血酶原时间及纤维蛋白原水平，为必要时的内镜或介入操作做准备；结合初步诊断，必要时完善肿瘤标志物检查，鉴别消化道恶性肿瘤，并定期复查上述指标动态评估病情变化。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 蛋白丢失性胃肠病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 奥曲肽注射液（生长抑素类似物，小肠淋巴管扩张致蛋白丢失的首选药）：首剂0.05mg皮下注射，后0.1mg皮下注射 q8h，连用2周评估疗效；有效者改用长效奥曲肽微球20mg深部肌注 q4w维持，疗程2~3个月，据血清白蛋白回升情况调整。\n2. 泼尼松片（糖皮质激素，用于炎症性肠病、自身免疫性病因所致蛋白丢失性胃肠病）：30~40mg qd晨起顿服（约0.75~1mg/kg·d），病情缓解后每1~2周减量5mg，总疗程8~12周，缓慢减量，用药期间监测血糖、血压及血钾。\n3. 螺内酯片+呋塞米片（利尿消肿）：螺内酯20mg tid口服，联合呋塞米20mg qd晨服，水肿明显消退后减量或间歇给药，每周复查血电解质、肾功能，注意补钾，避免过度利尿诱发低血压。\n4. 利伐沙班片（抗凝，PLGE因抗凝血酶Ⅲ经肠丢失致高凝状态，用于预防血栓）：10mg qd口服，疗程3~6个月，定期复查凝血功能及出血风险；治疗期间避免合用强效CYP3A4抑制剂及抗血小板药物。\n\n【一般治疗及生活指导】\n1. 饮食：低脂、高蛋白、低盐饮食，脂肪以中链甘油三酯（MCT）油或粉替代（30~50g/d分次混入食物烹饪），减少长链脂肪酸致肠淋巴管内压增高，忌油腻、辛辣刺激及粗硬纤维食物。\n2. 休息与活动：急性期或低蛋白血症性水肿明显时卧床休息、抬高双下肢减轻水肿；缓解期适度活动，避免剧烈运动及久站久坐，防止淋巴回流负担加重。\n3. 禁忌：戒烟酒，禁用非甾体抗炎药（布洛芬、双氯芬酸等）及刺激性泻药，避免加重腹泻与蛋白丢失；注意保暖、防感染，避免人群聚集。\n4. 自我监测：每日晨起空腹称体重、记录24小时出入量，体重短期增加提示水肿加重，及时联系医生。\n\n【随诊要求】\n1. 每2~4周门诊复诊，复查血清白蛋白、前白蛋白、电解质、肝肾功能及凝血功能（警惕静脉血栓）；水肿明显者每周复诊并监测体重。\n2. 每3~6个月复查胶囊内镜/小肠镜及腹部CT或淋巴核素显像，评估原发病（淋巴管扩张、IBD等）控制情况。\n3. 出现以下情况立即就诊：腹泻或腹痛进行性加重、黑便/血便、单侧肢体肿胀疼痛、突发胸闷胸痛或呼吸困难（提示血栓栓塞）、白蛋白持续下降或水肿进行性加重。\n4. 长期随访：定期评估营养状况及有无继发免疫球蛋白丢失、反复感染、贫血等并发症，必要时联合营养科制定长期MCT饮食方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":846,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"403e40d3978c838c9eef53fe702db94980a9040a6d04ca5ee395ae2f2097fefc","pinyin":"danbaidiushixingweichangbing","initials":"dbdsxwcb","setting":"out","caseName":"门诊病历714","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历714",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-17c0ece785826154c422","key":"v1-c9ccc21dfe2a3058|templates-17c0ece785826154c422","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"小肠细菌过度生长","category":"门诊病历模板","raw":{"name":"小肠细菌过度生长","category":"门诊病历模板","case":{"case_name":"门诊病历715","templates":{"主诉":"腹胀1天","现病史":"患者1周前无明显诱因出现小肠细菌过度生长相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以腹胀1天为主诉，起病1周，伴轻度乏力，本病多因小肠动力障碍或解剖异常致细菌过度繁殖、产气增多，需评估有无感染、吸收不良及器质性疾病以支持诊断，入院即刻完善血常规，了解白细胞、血红蛋白及血小板水平，排除感染、贫血及脾功能亢进所致血细胞减少；查便常规+潜血，了解有无消化道出血及肠道炎症，排除肠道感染、炎症性肠病并明确有无隐匿性失血；完善肝功能检查，了解转氨酶、胆红素、白蛋白及凝血相关指标水平，明确有无肝细胞损伤及合成功能障碍；患者伴轻度乏力，为排除胰腺疾病所致消化道症状，完善淀粉酶与脂肪酶检查，明确有无急性胰腺炎；腹部超声检查了解肝、胆、胰、脾形态及有无腹水、门静脉增宽，鉴别胆道梗阻及占位性病变；上述检查仍不能明确者，完善胃镜/肠镜（必要时）检查，直接观察食管胃底静脉、胃十二指肠及结直肠黏膜情况，明确有无静脉曲张、溃疡、占位并留取活检；腹部CT检查进一步明确腹腔实质脏器、肠壁及腹膜后有无占位、积液及血管异常，评估病变范围；因本病常与幽门螺杆菌感染相关，完善幽门螺杆菌检测（C13/C14呼气试验），明确有无现症感染以指导治疗；患者存在潜在出血及凝血异常风险，完善凝血功能检查，评估凝血酶原时间及纤维蛋白原水平，为必要时的内镜或介入操作做准备；结合初步诊断，必要时完善肿瘤标志物检查，鉴别消化道恶性肿瘤，并定期复查上述指标动态评估病情变化。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 小肠细菌过度生长\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 利福昔明片（肠道选择性不吸收抗生素，首选）：0.4g po tid×14天；甲烷型SIBO（产甲烷菌为主）可联合甲硝唑片 0.4g po tid×10～14天。\n2. 促动力药（改善小肠淤滞、减少复发）：莫沙必利片 5mg po tid，餐前15～30分钟服用，连用2～4周；便秘明显者可选普芦卡必利片 2mg po qd×4周。\n3. 肠道微生态调节：双歧杆菌三联活菌胶囊 420mg po bid，餐后服用，与抗生素间隔≥2小时，连用4周。\n\n【一般治疗及生活指导】\n1. 饮食：低FODMAP饮食2～6周，减少乳制品、豆类、洋葱、大蒜、小麦及高果糖水果等发酵产气食物摄入，忌酒精及含糖饮料。\n2. 活动：每日适度有氧运动（快走、慢跑等）30分钟，促进肠蠕动、缓解腹胀。\n3. 作息：保证规律作息与充足睡眠，避免熬夜、焦虑紧张等应激因素加重胃肠动力障碍。\n4. 禁忌：避免长期或反复使用质子泵抑制剂（PPI）及其他抑酸药，不滥用抗生素与泻药；治疗期间暂停除上述益生菌外的各类营养/膳食补充剂。\n\n【随诊要求】\n1. 完成抗生素疗程后2～4周复诊，复查葡萄糖/乳果糖氢呼气试验评估根除效果。\n2. 症状无明显缓解或复发者复诊调整疗程与联合用药，必要时完善小肠镜、胶囊内镜及粪菌分析，排查小肠解剖异常、憩室等基础病因。\n3. 治疗期间若出现剧烈腹痛、发热、呕吐、黑便等急腹症表现，应立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":847,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3fa6307eb894142219077946b3e743c89ecd40f2bfabe4f43c31c57a0ff1f0ce","pinyin":"xiaochangxijunguodushengzhang","initials":"xcxjgdsz","setting":"out","caseName":"门诊病历715","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历715",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e1da55fdda7f461be3c6","key":"v1-c9ccc21dfe2a3058|templates-e1da55fdda7f461be3c6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"酒精性肝硬化","category":"门诊病历模板","raw":{"name":"酒精性肝硬化","category":"门诊病历模板","case":{"case_name":"门诊病历716","templates":{"主诉":"乏力、食欲减退、腹胀多年","现病史":"患者存在以下致病因素（长期大量饮酒所致的酒精性肝病，女性每日酒精摄入>20g、男性>40g即为危险饮酒；酒精摄入量按纯酒精克数计算，即饮酒量乘度数再乘0.8；饮酒年限多超过5~10年，乙醇的肝毒性可致脂肪肝、进而发展为酒精性肝炎、纤维化，最终形成肝硬化；叠加因素包括合并乙肝或丙肝，病毒与酒精协同可加速肝损伤，肥胖所致脂肪肝以及遗传因素）。患者于多年饮酒后出现以下表现：乏力，呈进行性加重；食欲减退、腹胀；黄疸，多见于酒精性肝炎，急性加重常于饮酒后出现，表现为黄疸加重及发热，需考虑合并感染或酒精性肝炎活动；腹水，由门脉高压所致，提示进入失代偿期；消化道出血，可因食管静脉曲张破裂引起；肝性脑病；脾大；蜘蛛痣及肝掌；男性乳房发育、睾丸萎缩，与雌激素代谢异常有关；体重下降。同时需了解戒酒情况，是否已戒酒，因戒酒后肝病可改善，早期脂肪肝及酒精性肝炎可逆，肝硬化虽不可逆，但戒酒可防止病情进展，此点重要；并需评估酒精依赖及戒断症状，以便进行相应治疗，同时了解饮酒量及频率。今日来我院消化科或肝病科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒10年，约4两/日。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P84次/分，R19次/分，BP108/68mmHg。黄疸，可见皮肤及巩膜黄染；肝掌、蜘蛛痣；腹水，移动性浊音阳性，需测量腹围；脾大；肝脏早期可增大，因脂肪浸润所致，晚期缩小，质硬并可触及结节；男性乳房发育、睾丸萎缩；腮腺肿大，为酒精性肝病表现；掌挛缩（Dupuytren征）少见；扑翼样震颤，提示肝性脑病；出血点；营养状况差，可见消瘦及肌少症。","辅助检查":"【必做】肝功能（转氨酶方面，酒精性肝炎者AST高于ALT，AST/ALT>2为其特征，因酒精对ALT的抑制较AST更为明显；γ-谷氨酰转移酶显著升高，为酒精性肝病的特征性改变，戒酒后下降；胆红素升高；白蛋白降低；凝血酶原时间延长；GGT及MCV即平均红细胞容积升高，为酒精标志物）、血常规（血小板降低，与脾功能亢进有关）、Child-Pugh评分、肝瞬时弹性检测（FibroScan，可评估肝硬度及纤维化程度）、超声（肝脏回声增强，提示脂肪变或结节，肝脏缩小，脾大及腹水，可测量门脉内径；肝癌筛查采用超声加甲胎蛋白，每6个月1次，酒精性肝硬化有肝癌风险，戒酒可降低）、乙肝及丙肝标志物（了解有无病毒合并感染，酒精与病毒可加速肝损伤）；【酒精评估】评估饮酒量及依赖程度（CAGE问卷）；肝活检（用于诊断不明或判断酒精性肝炎严重程度，临床较少需要，多数可依据戒酒史及实验室指标作出诊断）；【并发症】胃镜（评估食管静脉曲张）、肾功能及电解质（腹水利尿治疗，警惕肝肾综合征）、血氨（肝性脑病）、腹水检查（排查感染）。","初步诊断":"1. 酒精性肝硬化（代偿期或失代偿期待定；Child-Pugh分级；酒精性肝炎活动，表现为AST/ALT>2伴GGT升高；并发症包括腹水、食管静脉曲张、肝性脑病、肝癌；评估戒酒状态）\n（注：治疗以戒酒为核心，为绝对最重要的一环，也是唯一可改善预后的措施，戒酒后肝病可停止进展，部分甚至可逆；对酒精依赖者需处理戒断综合征，如震颤、谵妄，可用苯二氮卓类药物治疗，并补充维生素B1以预防Wernicke脑病，补充B1应先于葡萄糖输注，此点重要；同时给予心理支持、戒酒互助会及戒酒后的随访。②营养支持：予高蛋白及维生素饮食，酒精性肝病者营养不良常见，补充营养十分重要；合并腹水者限制钠盐摄入。③酒精性肝炎：严重者可用糖皮质激素，如Maddrey判别函数≥32或终末期肝病模型评分≥21者，予泼尼松40mg/日共28天，可改善生存；重症患者需权衡感染风险，合并感染者不宜使用；同时给予营养支持。④并发症处理：腹水者限盐并予利尿剂，如螺内酯联合呋塞米，大量腹水可行放液并补充白蛋白；食管静脉曲张可行套扎或使用β受体阻滞剂预防出血；肝性脑病予乳果糖及利福昔明；肝肾综合征需相应处理；肝癌应筛查并治疗，参见相关章节。⑤随访：持续评估戒酒状态，复发者再次干预；定期复查肝功能及Child-Pugh分级；每6个月行超声加甲胎蛋白筛查肝癌，此点重要；胃镜随访静脉曲张；评估营养状态；酒精性肝炎可因再次饮酒而复发；失代偿者评估肝移植，需戒酒≥6个月方可进入移植评估；肝移植是终末期酒精性肝病的有效治疗，移植后戒酒者复发少，评估十分重要）。肝病科应重视戒酒这一核心环节，同时注意营养支持、并发症处理、肝癌筛查及移植评估。","处理方案":"【药物治疗】\n1. 戒酒与维生素补充：戒酒为本病治疗根本；维生素B1片10mg tid、复合维生素B片2片 tid、叶酸片5mg qd，连续服用3个月后评估，必要时改维生素B1 100mg im qd×7天。\n2. 保肝抗炎：多烯磷脂酰胆碱胶囊456mg tid，餐后服，疗程3-6个月；或水飞蓟宾胶囊70mg tid，疗程3个月；可联合用药，每3个月复查肝功能评估疗效。\n3. 腹水（如有）：螺内酯片20mg qd晨服起始，若3-5天体重下降不明显，加用呋塞米片20mg qd，二者比例约100mg:40mg调整；用药期间每周复查电解质、肾功能，防低钠低钾血症。\n4. 预防食管胃底静脉曲张破裂出血（如有）：盐酸普萘洛尔片10mg bid起始，每3-5天加量至静息心率较基础下降约25%或降至55-60次/分维持，需专科指导下调整；窦性心动过缓、低血压、哮喘者禁用。\n\n【一般治疗及生活指导】\n1. 绝对戒酒：停用一切含酒精饮品及含酒精食物、药物（如藿香正气水、酒炖食品），家人监督，戒断困难者转戒酒门诊，必要时予纳曲酮/阿坎酸辅助戒酒。\n2. 营养支持：高热量、高蛋白（1.2-1.5g/kg/d，发生肝性脑病者减至0.6-0.8g/kg/d）、低脂饮食；少食多餐，睡前加餐（牛奶、藕粉等）防夜间低血糖；常规补充复合维生素B及叶酸。\n3. 休息与活动：代偿期避免剧烈运动及重体力劳动，保证每日7-8小时睡眠；失代偿期以卧床休息为主，可床边适度活动，避免久站久坐。\n4. 禁忌与注意事项：腹水者限钠<2g/d（食盐<2g/d），尿少时限制液体入量约1000ml/d；禁用对乙酰氨基酚等肝毒性药物及一切非必需药物，慎用镇静催眠药；每日晨起空腹测体重、腹围并记录。\n\n【随诊要求】\n每1-3个月门诊复查血常规、肝功能、凝血功能、肾功能、电解质、甲胎蛋白及腹部超声，失代偿期缩短至2-4周；每6-12个月行胃镜筛查食管胃底静脉曲张（轻中度每1-2年复查，重度或有红色征每半年复查）；每6个月行肝脏弹性成像评估纤维化进展；定期检测HBV/HCV、铁蛋白等排除合并病因；出现呕血、黑便、腹胀明显加重、发热、意识行为异常时立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":848,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8c7ee4fe2df7a8fb47542f54758fee4ca7b33b99be5abe5ffbceea37502f3d2c","pinyin":"jiujingxingganyinghua","initials":"jjxgyh","setting":"out","caseName":"门诊病历716","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历716",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2632ebb1cf147fbc6036","key":"v1-c9ccc21dfe2a3058|templates-2632ebb1cf147fbc6036","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肝炎后肝硬化","category":"门诊病历模板","raw":{"name":"肝炎后肝硬化","category":"门诊病历模板","case":{"case_name":"门诊病历717","templates":{"主诉":"腹胀1天","现病史":"患者1周前无明显诱因出现肝炎后肝硬化相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒20年，约4两/日。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以腹胀1天为主诉，起病1周，伴轻度乏力，既往有肝炎病史，需评估肝功能储备及门静脉高压程度，明确有无肝硬化失代偿及并发症，入院即刻完善血常规，了解白细胞、血红蛋白及血小板水平，排除感染、贫血及脾功能亢进所致血细胞减少；查便常规+潜血，了解有无消化道出血及肠道炎症，排除肠道感染、炎症性肠病并明确有无隐匿性失血；完善肝功能检查，了解转氨酶、胆红素、白蛋白及凝血相关指标水平，明确有无肝细胞损伤及合成功能障碍；患者伴轻度乏力，为排除胰腺疾病所致消化道症状，完善淀粉酶与脂肪酶检查，明确有无急性胰腺炎；腹部超声检查了解肝、胆、胰、脾形态及有无腹水、门静脉增宽，鉴别胆道梗阻及占位性病变；上述检查仍不能明确者，完善胃镜/肠镜（必要时）检查，直接观察食管胃底静脉、胃十二指肠及结直肠黏膜情况，明确有无静脉曲张、溃疡、占位并留取活检；腹部CT检查进一步明确腹腔实质脏器、肠壁及腹膜后有无占位、积液及血管异常，评估病变范围；因本病常与幽门螺杆菌感染相关，完善幽门螺杆菌检测（C13/C14呼气试验），明确有无现症感染以指导治疗；患者存在潜在出血及凝血异常风险，完善凝血功能检查，评估凝血酶原时间及纤维蛋白原水平，为必要时的内镜或介入操作做准备；结合初步诊断，必要时完善肿瘤标志物检查，鉴别消化道恶性肿瘤，并定期复查上述指标动态评估病情变化。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 肝炎后肝硬化\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗病毒（病因治疗，乙肝后肝硬化）：恩替卡韦片0.5mg qd口服，长期服用，定期监测HBV-DNA及病毒学应答；或富马酸丙酚替诺福韦片25mg qd口服（肾功能不全者选用丙酚替诺福韦或调整恩替卡韦剂量），长期服用，期间监测肾功能、血磷。丙肝相关肝硬化：索磷布韦维帕他韦片400mg/100mg qd口服，疗程12周。\n2. 保肝降酶：甘草酸二铵肠溶胶囊150mg tid口服，疗程2~4周；或还原型谷胱甘肽片0.4g tid口服，疗程2~4周，复查肝功能后评估是否继续。\n3. 利尿（合并腹水时）：螺内酯片40mg qd口服起始，效果不佳每3~5天递增剂量，最大100mg qd，必要时联合呋塞米片20mg qd口服，维持体重下降0.5kg/d（无水肿者0.3kg/d），每周监测电解质、血肌酐及尿量调整剂量。\n4. 抗肝纤维化：扶正化瘀胶囊1.5g tid口服，疗程6个月，或安络化纤丸6g tid口服，疗程3个月，定期复查肝纤维化指标评估疗效。\n【一般治疗及生活指导】\n1. 休息：保证充足睡眠，避免熬夜及过劳；失代偿期（腹水、黄疸、乏力明显）以卧床休息为主，减少肝脏耗氧、促进肝细胞修复，代偿期可适度散步等温和活动，避免剧烈运动和突然屏气用力。\n2. 饮食：高蛋白（无肝性脑病时）、高维生素、低脂、易消化饮食；合并腹水者限盐（每日<2g）、限水（每日约1000~1500ml）；存在食管胃底静脉曲张者进温软食、细嚼慢咽，禁食粗糙、坚硬、过烫及带骨刺食物（如坚果、油炸食品、芹菜梗），以防曲张静脉破裂出血。\n3. 禁忌：严格终身禁酒及含酒精饮品；避免使用有肝损害药物（对乙酰氨基酚、非甾体抗炎药及成分不明的中草药偏方等），就诊时主动告知肝硬化病史；保持大便通畅，避免用力排便及剧烈咳嗽、搬重物等增加腹压行为。\n4. 自我监测：每日测体重、记尿量（腹水者），观察有无腹胀、黑便、呕血、皮肤瘀斑、嗜睡或性格改变，出现异常及时就诊。\n【随诊要求】\n1. 每1~3个月复查肝功能、血常规、凝血功能、甲胎蛋白（AFP）及腹部彩超（含门静脉内径、脾脏大小、腹水及有无肝占位）。\n2. 抗病毒治疗期间每3~6个月复查HBV-DNA、乙肝五项及肝纤维化指标（或肝脏弹性成像），评估病毒学应答及耐药情况，不可自行停药。\n3. 每6个月复查胃镜评估食管胃底静脉曲张程度，必要时行预防性套扎或硬化治疗；腹水者定期复查电解质、肾功能。\n4. 每6~12个月行肝脏弹性成像或无创肝纤维化检测评估肝纤维化进展；长期口服抗病毒药者每3~6个月监测肾功能、血磷、血钙及血乳酸。\n5. 出现呕血、黑便、腹围短期内明显增大、发热、意识模糊或行为异常等急症表现，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":849,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"935ae26f2aea1359c175d5e16f3d3803a04fc9f4dd87d54bf19046c10d9b995e","pinyin":"ganyanhouganyinghua","initials":"gyhgyh","setting":"out","caseName":"门诊病历717","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历717",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4ba9942acbec37f0bd6b","key":"v1-c9ccc21dfe2a3058|templates-4ba9942acbec37f0bd6b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"血吸虫性肝硬化","category":"门诊病历模板","raw":{"name":"血吸虫性肝硬化","category":"门诊病历模板","case":{"case_name":"门诊病历718","templates":{"主诉":"腹胀1天","现病史":"患者1周前无明显诱因出现血吸虫性肝硬化相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒15年，约4两/日。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以腹胀1天为主诉，起病1周，伴轻度乏力，考虑血吸虫卵沉积于门静脉系统致肝纤维化及门静脉高压，需评估肝功能及门静脉高压程度，明确有无肝硬化失代偿及并发症，入院即刻完善血常规，了解白细胞、血红蛋白及血小板水平，排除感染、贫血及脾功能亢进所致血细胞减少；查便常规+潜血，了解有无消化道出血及肠道炎症，排除肠道感染、炎症性肠病并明确有无隐匿性失血；完善肝功能检查，了解转氨酶、胆红素、白蛋白及凝血相关指标水平，明确有无肝细胞损伤及合成功能障碍；患者伴轻度乏力，为排除胰腺疾病所致消化道症状，完善淀粉酶与脂肪酶检查，明确有无急性胰腺炎；腹部超声检查了解肝、胆、胰、脾形态及有无腹水、门静脉增宽，鉴别胆道梗阻及占位性病变；上述检查仍不能明确者，完善胃镜/肠镜（必要时）检查，直接观察食管胃底静脉、胃十二指肠及结直肠黏膜情况，明确有无静脉曲张、溃疡、占位并留取活检；腹部CT检查进一步明确腹腔实质脏器、肠壁及腹膜后有无占位、积液及血管异常，评估病变范围；因本病常与幽门螺杆菌感染相关，完善幽门螺杆菌检测（C13/C14呼气试验），明确有无现症感染以指导治疗；患者存在潜在出血及凝血异常风险，完善凝血功能检查，评估凝血酶原时间及纤维蛋白原水平，为必要时的内镜或介入操作做准备；结合初步诊断，必要时完善肿瘤标志物检查，鉴别消化道恶性肿瘤，并定期复查上述指标动态评估病情变化。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 血吸虫性肝硬化\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗血吸虫病原治疗：吡喹酮片，慢性期总剂量60mg/kg，分2日4-6次口服（如体重60kg者每次600mg，每日3次，连服2日）；晚期肝硬化体质虚弱者减量至总剂量40mg/kg，分2日服用。疗程结束后第3、6个月复查粪便毛蚴孵化试验评价疗效。\n2. 门脉高压及食管胃底静脉曲张预防性治疗：普萘洛尔片10mg bid起始，每3-7日递增剂量，以静息心率降至55-60次/分为目标，维持量20-60mg bid，长期口服；静息心率低于55次/分或血压明显下降者减量或停药。\n3. 腹水治疗：螺内酯片40-80mg qd，可联合呋塞米片20-40mg qd口服，以每日尿量1000-2000ml、体重每日下降0.5kg（有水肿者）为度，阶梯调整剂量，注意监测血钾、肾功能。\n4. 保肝及抗肝纤维化：多烯磷脂酰胆碱胶囊456mg tid口服，或复方鳖甲软肝片2g tid口服，连用3-6个月。\n【一般治疗及生活指导】\n1. 休息与活动：肝功能代偿期可从事轻体力活动，避免劳累及熬夜；失代偿期（明显腹水、黄疸）应卧床休息为主，病情稳定后循序渐进恢复日常活动，避免剧烈运动。\n2. 饮食：高蛋白（无肝性脑病者）、高维生素、适量碳水化合物饮食，腹水者每日食盐<2g；食物宜细软易消化，禁食粗糙、坚硬、油炸及辛辣刺激食物（如坚果、带骨刺鱼、硬饼干等），以防食管胃底静脉曲张破裂出血。\n3. 禁忌：绝对禁酒，禁用对肝有损害的药物（如部分抗生素、非甾体抗炎药及中草药）；避免剧烈咳嗽、用力排便、提重物、屏气等增加腹压的动作。\n4. 个人防护：避免接触疫水、做好钉螺环境防护，防止血吸虫再感染；注意皮肤清洁，预防感染。\n【随诊要求】\n1. 每1-3个月门诊复查肝功能、血常规、凝血功能、甲胎蛋白及腹部超声（门静脉内径、脾脏大小、腹水量）。\n2. 每1-2年行胃镜复查食管胃底静脉曲张程度，已有中-重度曲张者每年复查1次。\n3. 服用普萘洛尔者定期监测静息心率、血压；服用利尿剂者每2-4周复查电解质、肾功能。\n4. 如出现呕血、黑便、腹胀迅速加重、发热、神志改变等，立即急诊就诊；脾功能亢进明显者评估外科切脾或TIPS指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":850,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5624300d8599ab1a3abd953eb00de964a2c0864c2362217a48a0886cf513e27e","pinyin":"xuexichongxingganyinghua","initials":"xxcxgyh","setting":"out","caseName":"门诊病历718","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历718",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-628dccada75b872edbb3","key":"v1-c9ccc21dfe2a3058|templates-628dccada75b872edbb3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"心源性肝硬化","category":"门诊病历模板","raw":{"name":"心源性肝硬化","category":"门诊病历模板","case":{"case_name":"门诊病历719","templates":{"主诉":"腹胀1天","现病史":"患者1周前无明显诱因出现心源性肝硬化相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒25年，约2两/日。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以腹胀1天为主诉，起病1周，伴轻度乏力，心源性肝硬化继发于右心功能不全及体循环淤血，故入院即刻完善血常规，了解血红蛋白及血小板水平，排除贫血、感染及脾功能亢进所致血细胞减少；完善生化全项（肝肾功能、电解质、血糖、血脂）检查，了解转氨酶、胆红素、白蛋白、肌酐及电解质水平，明确有无肝肾功能不全、电解质紊乱并指导利尿及营养支持方案；患者存在体循环淤血、心肌受累可能，完善心肌酶谱与肌钙蛋白检查，排除急性心肌损伤及心肌梗死；心电图检查了解心率、心律及有无心肌缺血、心律失常，明确心脏基础病变；心脏超声检查了解心脏各房室大小、室壁运动、射血分数及瓣膜情况，明确有无心功能不全及肺动脉高压，评估淤血性肝大的病因；胸部X线片检查了解心影大小、肺淤血及有无胸腔积液，评估心功能状态并鉴别肺部感染；患者病情可能阵发性加重，完善动态心电图检查，明确有无阵发性心律失常及心肌缺血发作；结合冠心病危险因素，完善冠脉CTA（必要时）检查，明确冠状动脉有无狭窄及狭窄程度以指导血运重建决策；完善BNP/NT-proBNP检查，明确有无心功能衰竭并评估其严重程度；同时监测体重、腹围及尿量，定期复查肝功能与电解质，动态评估淤血性肝损伤的转归以调整治疗方案。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 心源性肝硬化\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 利尿消肿：呋塞米片20mg qd口服（晨服，根据体重及尿量可渐增至20mg bid～tid），联合螺内酯片20mg qd～tid口服，维持每日尿量1500～2000ml，3天内体重下降以0.5～1kg/日为度；\n2. 改善心功能（针对原发心脏疾病）：地高辛片0.125mg qd口服（伴肾功能不全或电解质紊乱者减量并监测血药浓度），或联用血管紧张素转换酶抑制剂如培哚普利片4mg qd口服，动态监测血压、心率及BNP/NT-proBNP；\n3. 保肝治疗：多烯磷脂酰胆碱胶囊456mg tid口服×8～12周，或水飞蓟宾胶囊140mg tid口服，疗程1～3个月，定期复查肝功能评估疗效；\n4. 预防食管胃底静脉曲张出血（无低血压、休克及失代偿性心衰者）：普萘洛尔片10mg bid口服，以静息心率较基础下降25%、不低于55次/分（或55～60次/分）为靶目标逐步调整剂量。\n\n【一般治疗及生活指导】\n1. 休息：以卧床休息为主，避免劳累、负重及剧烈活动，减轻心脏前、后负荷，保证充足睡眠；\n2. 饮食：低盐低脂、适量优质蛋白、易消化饮食，每日钠盐摄入<2g，液体入量控制在1500ml/日以内（腹水明显者根据患者具体情况制定个体化方案进一步限制），少食多餐，忌坚硬粗糙食物以防食管静脉曲张破裂出血；\n3. 禁忌：绝对禁酒、戒烟，避免使用肝毒性及肾毒性药物（如对乙酰氨基酚、非甾体抗炎药等），慎用镇静催眠药，避免自行服用中草药及保健品；\n4. 自我监测：每日晨起空腹称体重并记录尿量，若3天内体重增加>2kg或尿量明显减少，提示心衰及肝淤血加重，应及时就诊。\n\n【随诊要求】\n1. 每1～2周门诊复诊，评估心功能分级（NYHA）及肝淤血、腹水改善情况；\n2. 每1～3个月复查肝功能、电解质、肾功能、凝血功能、血常规，每3～6个月复查心脏彩超、肝脏彩超（必要时肝脏弹性成像），监测食管胃底静脉曲张进展及肝脏占位性病变；\n3. 出现腹胀明显加重、尿量锐减、下肢水肿复现、皮肤巩膜黄染、呕血黑便、意识改变或行为异常等，立即急诊就诊；\n4. 长期随访原发心脏疾病，遵医嘱规律服用抗心衰药物，不可自行停药、减量或加量，并定期行心电图及血药浓度监测。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":851,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"31d3b3f08f8fb1f35c7d43e6e451adfbca64c32c0c577f46dd845b0888e4cf66","pinyin":"xinyuanxingganyinghua","initials":"xyxgyh","setting":"out","caseName":"门诊病历719","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历719",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f93c12c1424647617b56","key":"v1-c9ccc21dfe2a3058|templates-f93c12c1424647617b56","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"原发性肝癌","category":"门诊病历模板","raw":{"name":"原发性肝癌","category":"门诊病历模板","case":{"case_name":"门诊病历720","templates":{"主诉":"肝区疼痛、腹胀伴消瘦3个月","现病史":"患者存在以下危险因素（肝硬化基础，病因包括乙肝，我国最为常见，符合肝硬化、肝癌三部曲的规律；丙肝；酒精性肝病；非酒精性脂肪肝；血吸虫性肝病。HBsAg阳性携带者可不经过肝硬化阶段直接发生肝癌，尤其有肝癌家族史者；黄曲霉毒素暴露，与进食霉变食物有关；年龄在40岁以上，男性多见；饮水污染）。患者于筛查或出现症状时发现：早期可无症状，高危人群应定期筛查，行超声加甲胎蛋白检查，每6个月1次，肝硬化患者尤应如此，此为早期诊断的关键，早期小肝癌可治愈；肝区疼痛，呈胀痛或钝痛，系肿瘤牵拉肝包膜所致；腹胀，可由腹水或巨大肿瘤引起；食欲减退、消瘦、乏力；黄疸，多见于晚期，因肝功能衰竭或胆管受压所致；发热，与肿瘤坏死有关；腹水、脾大，与肝硬化门脉高压并存；上消化道出血，可因静脉曲张引起；肿瘤标志物方面，甲胎蛋白>400ng/ml且持续升高，高度提示肝癌，约30%患者甲胎蛋白正常，多见于丙肝相关或低分化肝癌；超声可见占位，呈低回声结节，并可见血流；增强CT或MRI显示快进快出，即动脉期强化、门脉期洗脱，为典型影像学诊断依据，可无需活检，此点重要；肝硬化背景下的再生结节需随访，结节增长为警示信号；门脉癌栓提示预后差；可出现肝外转移至肺、骨；并需进行Child-Pugh分期。今日来我院肝病科或肿瘤科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。吸烟30年，10支/日；不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P88次/分，R20次/分，BP116/72mmHg。肝脏增大，于右肋下可触及，质硬，表面可触及结节，多见于晚期；肝区有压痛及叩痛；腹水征阳性；脾大；黄疸；肝掌及蜘蛛痣，与肝硬化有关；消瘦，甚至呈恶病质；锁骨上淋巴结可肿大；下肢水肿；腹部血管杂音较少见。","辅助检查":"【必做】甲胎蛋白（为核心肿瘤标志物，>400ng/ml且持续4周以上支持诊断，但约30%患者可正常）、异常凝血酶原（PIVKA-Ⅱ，可用于甲胎蛋白阴性者的辅助诊断）、肝功能及Child-Pugh评分（用于分期及治疗决策）、血常规（脾功能亢进可致血小板降低）、凝血功能、乙肝及丙肝标志物与病毒载量、肾功能及电解质；【影像】腹部超声（用于筛查占位，可呈低回声或高回声，并观察血流）、增强CT或MRI（为核心检查，呈快进快出表现，即动脉期强化、静脉期或延迟期洗脱，为典型肝细胞癌影像学诊断依据，属金标准检查，肝硬化背景加典型增强表现者可直接诊断，无需活检；并可评估肿瘤数目、大小即BCLC分期、门脉侵犯即癌栓、肝静脉及胆管情况）、超声造影或普美显MRI（用于疑难病灶，与再生结节、血管瘤鉴别）、PET-CT（用于评估远处转移，即肝外转移）、肝活检（指征为影像不典型需组织学确诊者，可行针吸或活检；不能手术而行消融或化疗前并非必需，因影像典型者可直接诊断）；【分期】BCLC分期（0、A、B、C、D期，依据肿瘤负荷、肝功能及体能状态，为治疗决策标准）、门脉高压评估（可行肝静脉压力梯度测定）、肝功能储备评估。","初步诊断":"1. 原发性肝细胞癌（BCLC分期0~D期；Child-Pugh分级A~C级；需明确肿瘤大小、数目及血管侵犯情况；背景为乙肝、丙肝或酒精性肝硬化；甲胎蛋白待明确；评估肝功能及体能状态以制定治疗决策）\n（注：治疗依据BCLC分期及肝功能决定，多学科协作，早期可治愈，此点重要：①早期（0期、A期）：手术切除适用于单发肿瘤且肝功能良好者，即Child-A级，可达根治；射频或微波消融适用于肿瘤≤3cm者，微创且可原位灭活，可达治愈，适用于Child-A或B级、不能或不愿手术者；肝移植依据米兰标准，即单发肿瘤≤5cm或不超过3个且最大≤3cm，适用于肝硬化背景者，可同时治疗肝硬化与肝癌，为最佳选择，小肝癌行移植后5年生存率>70%，但供体有限；消融治疗对≤3cm者可达治愈。②中期（B期）：多发结节且肝功能良好者，行经动脉化疗栓塞（TACE），为标准治疗，采用碘油加化疗药栓塞，可多次进行；TACE联合系统治疗，如联合仑伐替尼或索拉非尼，近年证据显示可改善生存。③晚期（C期）：门脉侵犯或肝外转移者行系统治疗，靶向药物如仑伐替尼或索拉非尼为一线方案，免疫联合方案如阿替利珠单抗加贝伐珠单抗（T+A）为一线标准，优于索拉非尼，此点重要；亦可选信迪利单抗加贝伐珠单抗类似物，或卡瑞利珠单抗加阿帕替尼；二线可选瑞戈非尼、卡博替尼或雷莫西尤单抗。④对症及并发症处理：腹水、静脉曲张、肝性脑病按肝硬化管理；疼痛予止痛治疗；癌栓可考虑门脉放疗或粒子植入；肝功能衰竭予支持治疗。⑤随访：每3个月复查甲胎蛋白及超声，用于治疗后复发监测，肝癌复发率高，此点重要；监测Child-Pugh分级；抗病毒治疗方面，乙肝者予恩替卡韦或替诺福韦，需终身服用以抑制病毒、降低复发，无论病毒载量高低，此点重要；丙肝者予直接抗病毒药物治疗，但肝硬化患者肝癌风险仍存在，仍需筛查；高危人群即肝硬化或乙肝携带者应每6个月行超声加甲胎蛋白筛查，此为早期诊断关键，早期小肝癌可治愈；同时戒酒、避免进食霉变食物。肝病科、肿瘤科与介入科应多学科协作，重视早筛即超声加甲胎蛋白，依BCLC分期选择手术、消融、移植、TACE或靶免治疗，并坚持随访。","处理方案":"【药物治疗】\n1. 抗病毒治疗（HBsAg阳性者）：恩替卡韦片0.5mg qd 口服，长期维持（或富马酸丙酚替诺福韦片25mg qd 口服），治疗期间每3-6个月监测HBV-DNA。\n2. 保肝治疗（肝功能异常或介入/靶向治疗期间）：水飞蓟宾胶囊70mg tid 口服×4周；或多烯磷脂酰胆碱胶囊456mg tid 口服×4周，4周后复查肝功能调整用药。\n3. 靶向治疗（晚期一线，门诊口服）：仑伐替尼胶囊体重<60kg者8mg qd、体重≥60kg者12mg qd 口服，28天为1周期，持续至疾病进展或不可耐受；或索拉非尼片400mg bid 口服（餐前1小时或餐后2小时服用），28天为1周期，注意监测血压及手足皮肤反应。\n4. 免疫治疗（联合靶向，门诊输注）：信迪利单抗或卡瑞利珠单抗200mg ivdrip q3w，联合仑伐替尼使用，用药前筛查HBV/HCV及自身免疫性疾病，注意免疫相关性不良反应。\n\n【一般治疗及生活指导】\n1. 休息与活动：避免劳累及熬夜，保证充足睡眠；肝功能代偿期可进行散步等轻度有氧活动，避免剧烈运动及腹部挤压碰撞，防止肿瘤破裂出血。\n2. 饮食：高蛋白、高维生素、低脂饮食，适量优质蛋白（鱼肉、蛋、奶、瘦肉），多食新鲜蔬果；合并肝硬化腹水者每日限盐＜5g、限制饮水，合并食管胃底静脉曲张者进软食、细嚼慢咽，忌粗硬、辛辣、过烫食物。\n3. 禁忌：绝对戒烟戒酒，禁食发霉变质食物（含黄曲霉毒素），慎用或避免肝毒性药物（对乙酰氨基酚、部分中草药及偏方），用药需经医师评估。\n\n【随诊要求】\n1. 启动靶向/免疫治疗后2-4周复诊，复查血常规、肝肾功能、凝血功能、甲胎蛋白（AFP）及甲状腺功能，评估疗效及不良反应，必要时调整剂量。\n2. 治疗期间每2-3个月复查AFP、肝功能及上腹部增强CT/MRI（或超声造影），动态评估肿瘤大小、数目及有无血管侵犯、远处转移。\n3. 出现明显腹痛、腹胀、呕血、黑便、黄疸加深、发热或意识改变时，立即就近急诊就诊，不可延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":852,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"79c2b9e5e485729e600f91629dc127bfa0300fd0a85e898e1eda1aad8cc7afed","pinyin":"yuanfaxingganai","initials":"yfxga","setting":"out","caseName":"门诊病历720","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历720",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a3a5266fff0b8abb00e8","key":"v1-c9ccc21dfe2a3058|templates-a3a5266fff0b8abb00e8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"继发性肝癌","category":"门诊病历模板","raw":{"name":"继发性肝癌","category":"门诊病历模板","case":{"case_name":"门诊病历721","templates":{"主诉":"肝区疼痛1天","现病史":"患者1周前无明显诱因出现继发性肝癌相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。吸烟30年，30支/日；偶有饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以肝区疼痛1天为主诉，起病1周，伴轻度乏力，需警惕肝脏占位性病变，先评估有无贫血、感染及肝功能受损以支持诊断，入院即刻完善血常规，了解白细胞、血红蛋白及血小板水平，排除感染、贫血及脾功能亢进所致血细胞减少；查便常规+潜血，了解有无消化道出血及肠道炎症，排除肠道感染、炎症性肠病并明确有无隐匿性失血；完善肝功能检查，了解转氨酶、胆红素、白蛋白及凝血相关指标水平，明确有无肝细胞损伤及合成功能障碍；患者伴轻度乏力，为排除胰腺疾病所致消化道症状，完善淀粉酶与脂肪酶检查，明确有无急性胰腺炎；腹部超声检查了解肝、胆、胰、脾形态及有无腹水、门静脉增宽，鉴别胆道梗阻及占位性病变；上述检查仍不能明确者，完善胃镜/肠镜（必要时）检查，直接观察食管胃底静脉、胃十二指肠及结直肠黏膜情况，明确有无静脉曲张、溃疡、占位并留取活检；腹部CT检查进一步明确腹腔实质脏器、肠壁及腹膜后有无占位、积液及血管异常，评估病变范围；因本病常与幽门螺杆菌感染相关，完善幽门螺杆菌检测（C13/C14呼气试验），明确有无现症感染以指导治疗；患者存在潜在出血及凝血异常风险，完善凝血功能检查，评估凝血酶原时间及纤维蛋白原水平，为必要时的内镜或介入操作做准备；结合初步诊断，必要时完善肿瘤标志物检查，鉴别消化道恶性肿瘤，并定期复查上述指标动态评估病情变化。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 继发性肝癌\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 分子靶向治疗：对原发灶明确者规范行全身治疗，如结直肠癌肝转移者予瑞戈非尼片160mg 口服 qd，连用21天、停药7天，28天为一疗程；肝癌来源转移灶经专科评估可选用仑伐替尼胶囊8mg 口服 qd，持续服用至疾病进展或出现不可耐受毒性（靶向药均需专科医师评估后启用，用药期间监测血压及手足皮肤反应）。\n2. 保肝治疗：多烯磷脂酰胆碱胶囊456mg 口服 tid，疗程4周，复查肝功能后调整；或水飞蓟宾胶囊70mg 口服 tid，疗程4周。\n3. 对症支持：肝区疼痛者予羟考酮缓释片10mg 口服 q12h起始，按疼痛评分每24小时滴定调整；食欲减退、恶心者予甲氧氯普胺片10mg 口服 tid，餐前30分钟。\n4. 免疫调节：免疫功能低下者可予胸腺肽α1 1.6mg 皮下注射 每周2次，疗程8周。\n【一般治疗及生活指导】\n1. 休息：保证每日7-8小时睡眠，避免熬夜及重体力劳动；肝功能异常、乏力明显者以卧床休息为主，可室内缓步活动。\n2. 饮食：高蛋白、高维生素、低脂易消化软食，少食多餐；禁酒，避免粗糙、坚硬、过烫及辛辣刺激食物，预防食管胃底静脉曲张破裂出血；合并腹水者限制钠盐摄入（每日＜2g）。\n3. 活动：适度散步等有氧活动，避免剧烈运动、负重及腹部撞击，防止肝破裂及肿瘤出血。\n4. 禁忌：禁烟酒；避免自行服用肝毒性药物（对乙酰氨基酚、部分中草药及偏方）及非甾体抗炎药（出血风险）；避免接触肝毒性化学物质。\n【随诊要求】\n1. 每2-4周门诊复查血常规、肝肾功能、电解质、凝血功能及肿瘤标志物（CEA、CA19-9、AFP等）。\n2. 每8-12周复查腹部增强CT或MRI，评估肝内病灶大小、数目及治疗疗效；骨痛或怀疑骨转移者加做全身骨显像（ECT）。\n3. 靶向治疗期间每周监测血压，出现手足皮肤反应、腹泻、肝功能急剧升高等不良反应时及时就诊调整剂量。\n4. 出现黄疸加深、腹胀腹水加重、呕血黑便、剧烈腹痛或意识改变者，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":853,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b0a1f19f1d34e89cf883b423e3eddf824425968c80f50b992bf65b8030a19b95","pinyin":"jifaxingganai","initials":"jfxga","setting":"out","caseName":"门诊病历721","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历721",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5f4e6b4caab6f7fa6850","key":"v1-c9ccc21dfe2a3058|templates-5f4e6b4caab6f7fa6850","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肝脓肿","category":"门诊病历模板","raw":{"name":"肝脓肿","category":"门诊病历模板","case":{"case_name":"门诊病历722","templates":{"主诉":"发热、寒战伴肝区疼痛1周","现病史":"患者存在以下致病因素（细菌性肝脓肿最常见，感染途径包括胆道感染，如胆管炎、胆道梗阻、结石，为最常见来源；门脉途径，如腹腔感染、阑尾炎、憩室炎引起门脉菌血症；肝动脉途径，见于败血症、菌血症；邻近器官直接蔓延，如胆囊炎穿破；以及隐源性感染。糖尿病是重要危险因素，与肺炎克雷伯杆菌相关，该菌所致肝脓肿在我国较为常见；阿米巴性肝脓肿由肠阿米巴经门脉血行播散而来，我国较少见）。患者于1周前（急性或亚急性起病）出现以下表现：发热，呈弛张高热，伴寒战，多见于细菌性肝脓肿，阿米巴性者多为中低热；肝区疼痛，位于右上腹或右季肋部，呈持续性胀痛；肝大，伴压痛及叩痛；恶心、呕吐、食欲减退；乏力；黄疸较少见，多因胆道梗阻或脓肿压迫胆管所致；可有右肩放射痛；咳嗽，由膈肌受刺激引起；消瘦多见于慢性或阿米巴性肝脓肿。还需注意以下情况：脓肿可为单发或多发，细菌性者以多发常见；部位以右叶多见；糖尿病患者感染肺炎克雷伯杆菌者易发病，需重视血糖控制；可并发败血症或脓毒症，属重症；脓肿穿破可致脓胸、肺脓肿、腹膜炎，亦可致胆道出血。今日来我院感染科或消化科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T39.2℃，P104次/分，脉搏增快，R22次/分，BP108/68mmHg。发热，呈弛张高热；肝脏增大，于右肋下可触及，伴压痛及叩击痛，肝区压痛明显；右上腹压痛，可有肌紧张，若穿破可致腹膜炎；黄疸，多见于胆道梗阻；肺部可闻及右肺底啰音或胸膜摩擦音，由膈下刺激引起，右侧肩部有压痛点；腹水少见；注意有无糖尿病相关体征及营养状况。","辅助检查":"【必做】血常规（白细胞显著升高，伴核左移）、CRP、血沉、血培养（患者使用抗生素前采集，对细菌性肝脓肿的病原诊断重要，如肺炎克雷伯杆菌等）、肝功能（碱性磷酸酶升高，因胆道淤积所致，较为常见；胆红素可正常；转氨酶轻度升高）、白蛋白、血糖（糖尿病为重要危险因素）、阿米巴血清学（检测抗体，用于阿米巴性肝脓肿，适用于有疫区居住史或阿米巴痢疾病史者，采用酶联免疫吸附试验）；【影像】腹部超声（为核心检查，肝脓肿呈低回声液性区，壁厚，即脓腔；可判断单发或多发，并用于定位及引导穿刺或引流，可床旁进行）、腹部CT增强（脓肿呈低密度，可见环形强化即双靶征，若见气体提示产气菌感染，以肺炎克雷伯杆菌常见，可形成气性脓肿；有助于定位、判断多发、与肿瘤鉴别，并可观察胆道有无结石及扩张）、MRI（用于疑难病例的鉴别）；【确诊】肝脓肿穿刺（抽脓兼具诊断与治疗作用，可观察脓液性状，细菌性者多为黄绿色脓，阿米巴性者为巧克力色，具特征性；脓液培养可查细菌或阿米巴滋养体，必要时置管引流）；【随访】影像随访观察脓肿消退情况，并监测血糖控制情况。","初步诊断":"1. 肝脓肿（细菌性，可为肺炎克雷伯杆菌所致、与糖尿病相关，或大肠杆菌、厌氧菌所致，来源为胆道或门脉；或为阿米巴性；需明确单发或多发、大小及部位；行脓液引流及培养；评估败血症及穿破等并发症）\n（注：治疗以抗感染联合引流为核心，同时控制糖尿病：①抗生素：经验性选用广谱抗生素，覆盖肠源革兰阴性菌（大肠杆菌、克雷伯杆菌）及厌氧菌，如哌拉西林他唑巴坦或头孢曲松加甲硝唑，覆盖厌氧菌十分重要；考虑我国糖尿病相关肺炎克雷伯杆菌感染常见，可选用第三代头孢或碳青霉烯类；阿米巴性者予甲硝唑750mg tid共5~10天以杀灭滋养体，并加用肠内抗阿米巴药如双碘喹啉；疗程方面，静脉用药4~6周（细菌性者疗程宜长，至脓腔闭合），之后改口服，总疗程4~6周，此点重要。②引流：经皮穿刺引流，在超声或CT引导下穿刺抽脓或置管引流，为核心治疗，适用于直径>5cm或单发脓肿，穿刺引流后愈合较快；单纯抗生素治疗适用于较小脓肿（直径<3~5cm），可单用药物观察；多发脓肿以引流主要脓腔为主；脓液培养及药敏可指导调整用药。③手术：切开引流，指征为经皮引流失败、脓腔分隔致引流不畅、穿破引起腹膜炎（属急症）、胆道结石需在引流后处理（行ERCP或手术）、巨大或慢性脓肿囊壁已机化者。④对症及支持治疗：退热、营养支持、补液，并控制血糖，糖尿病者控制血糖是关键，因高血糖时感染难以控制，且克雷伯杆菌易感染，应使用胰岛素控制血糖。⑤并发症处理：败血症或脓毒症者行血培养，重症需ICU治疗；穿破至膈、腹腔或心包者需相应处理及手术；胆道出血或支气管胆瘘需相应处理。⑥随访：退热情况，引流加抗生素治疗后一般48~72小时体温下降；影像随访脓腔缩小及闭合，经超声或CT随访，闭合需2~4周；注意复发；监测血糖控制；阿米巴性者需治疗肠阿米巴病；处理来源病灶，如胆道结石，以及门脉或阑尾等原发灶。感染科或肝病科应重视引流联合足程抗生素，控制糖尿病血糖，并随访影像直至脓腔闭合。","处理方案":"【药物治疗】\n1. 抗感染治疗：肝脓肿病原菌以肠道革兰阴性菌（大肠埃希菌、肺炎克雷伯菌）及厌氧菌为主，门诊口服方案首选左氧氟沙星片0.5g po qd+甲硝唑片0.4g po tid，疗程4～6周（重症或脓肿较大者建议住院静脉予头孢曲松2g ivdrip qd+甲硝唑0.5g ivdrip q8h，症状好转后序贯口服至疗程满）。\n2. 对症退热：体温≥38.5℃伴明显不适者，予对乙酰氨基酚片0.5g po，必要时6小时重复，24小时不超过2g；避免长期使用退热药掩盖病情。\n3. 病因治疗：合并糖尿病者严格控糖（空腹血糖控制于7.8mmol/L以下，必要时内分泌科调整降糖方案）；有胆道感染、胆石症者同期处理原发灶。\n【一般治疗及生活指导】\n1. 急性期卧床休息，避免劳累及剧烈运动，待体温正常、乏力缓解后再逐步恢复日常活动。\n2. 饮食以高蛋白、高维生素、易消化为原则（鱼、蛋、瘦肉、新鲜蔬果），少食多餐，保证足够热量；禁饮酒，忌辛辣、油腻及生冷食物，减少肝脏负担。\n3. 注意肝区保护，避免右上腹受挤压碰撞，衣着宽松；保持大便通畅，必要时予乳果糖口服液15ml qd预防便秘。\n4. 体温监测每日3～4次，若出现寒战、高热不退、黄疸、呕血或黑便等，立即就医，不可自行加量或换用抗菌药物。\n【随诊要求】\n1. 治疗期间每1～2周门诊复查血常规、CRP、肝肾功能及血培养（发热期），动态评估感染控制情况。\n2. 每2周复查腹部B超（必要时CT）观察脓肿大小、液化及吸收情况；疗程结束时必须复查影像学，确认脓腔基本吸收方可停药。\n3. 总疗程4～6周，疗程结束后2周复查肝功能及影像学；如脓肿经皮穿刺引流者，须按引流量减少、引流液转清后根据患者具体情况制定个体化方案拔管并复诊评估。\n4. 停药后1个月复诊复查超声，观察有无复发；若再次出现发热、右上腹痛、恶心呕吐等，随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":854,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8fc427445c46c802000c04b6fa84c6595dc7e6a2a3ea231ca357742f5a901b04","pinyin":"gannongzhong","initials":"gnz","setting":"out","caseName":"门诊病历722","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历722",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-13dc04a16a7098d4bb4e","key":"v1-c9ccc21dfe2a3058|templates-13dc04a16a7098d4bb4e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肝囊肿","category":"门诊病历模板","raw":{"name":"肝囊肿","category":"门诊病历模板","case":{"case_name":"门诊病历723","templates":{"主诉":"体检发现肝区异常1年","现病史":"患者于体检行超声检查时发现肝囊肿：为单纯性肝囊肿，最为常见，系先天性胆管发育异常所致，即胆管囊肿，不与胆道相通，为浆液性囊肿；属良性病变，生长缓慢；多数无症状，常为体检偶然发现；可为单个或多个；大小自数毫米至数厘米不等，巨大者（>10cm）少见。需注意以下情况：症状方面，较大囊肿（>5~10cm）可引起上腹胀痛或不适，系压迫所致；压迫邻近器官可致胆管梗阻而出现黄疸（少见）；压迫门脉或下腔静脉者少见；压迫胃、肠可致早饱。并发症方面，囊内出血可致突发疼痛；囊内感染可致发热、疼痛，可继发细菌感染；破裂入腹腔少见。鉴别诊断方面，需与多囊肝鉴别，后者为多发、数目众多，常伴多囊肾，属遗传性疾病，需评估肾功能不全；与肝脓肿鉴别，后者有发热及脓液，囊壁较厚；与肝囊腺瘤或囊腺癌鉴别，后者少见，囊壁厚、有分隔或乳头状突起，有恶变可能，需手术及病理确诊；与包虫囊肿鉴别，多见于疫区、牧区，有犬羊接触史，囊内可见子囊及钙化，血清学检查可助诊断；还需与外伤后囊肿、Caroli病（胆管扩张）鉴别。此外应随访囊肿生长及变化情况，定期行超声检查。今日来我院消化科或肝胆外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P76次/分，R18次/分，BP118/74mmHg。腹部检查：肝脏增大，巨大囊肿者于右上腹可触及囊性、光滑、无压痛的包块；右上腹压痛，多见于合并感染或出血时；肝区叩痛；注意血压，多囊肾者可伴高血压；全身情况需评估有无多囊肾及肾功能损害。","辅助检查":"【必做】腹部超声（为核心检查，肝囊肿表现为无回声液性暗区，壁薄光滑，后方回声增强，为单纯性囊肿的典型表现，可参照类似Bosniak标准评估囊壁、分隔及实性成分，以判断是否为复杂囊肿；可明确大小、数目、部位及与胆道的关系）；【影像】CT或MRI（用于复杂囊肿或大囊肿的精确评估，可观察囊壁有无强化及分隔，以鉴别囊腺瘤；可判断囊内有无出血或感染所致密度改变；MRI用于疑难病例的鉴别；疑为包虫囊肿者可行CT检查，观察钙化及子囊，适用于疫区可疑病例）；【血液】肝功能（多正常，除非巨大或多发囊肿压迫肝组织）、肾功能（疑多囊肾者查肌酐）、包虫血清学（适用于疫区可疑者，行ELISA检测）、肿瘤标志物（疑囊腺癌者可查CA19-9，包括囊液及血清，较少用）、囊肿穿刺（用于诊断，可观察囊液性状，清亮浆液性者多为单纯性囊肿，浑浊者提示感染；行细胞学及肿瘤标志物检查，以排除囊腺瘤或囊腺癌，适用于可疑病例）；【随访】超声随访囊肿大小，囊肿生长缓慢，无症状的小囊肿无需治疗，定期随访即可；若囊肿增大或出现症状，则进一步评估。","初步诊断":"1. 肝囊肿（单纯性囊肿，单发或多发，需与多囊肝及复杂囊肿如囊腺瘤鉴别；评估大小、有无压迫症状及并发症如出血、感染、破裂；评估有无多囊肾及肾功能损害）\n（注：治疗上多数无需处理，以观察为主：①观察：无症状的单纯性小或中等大小囊肿无需处理，应告知患者属良性病变，避免过度紧张，此点重要；定期超声随访，每1~2年1次，观察大小变化。②有症状或较大囊肿：行超声或CT引导下穿刺抽液，并向囊内注入硬化剂，如无水乙醇或聚桂醇，以破坏囊壁、防止复发，单纯抽液复发率高，故需硬化治疗，此点重要；适应证为直径>5cm且伴压迫症状或胀痛者；操作时尽量抽尽囊液，注入硬化剂后留置15~20分钟再抽出；并发症如出血、感染较少见。③手术：腹腔镜囊肿开窗引流术，即去顶术，切除部分囊壁开窗，使囊液引流至腹腔并被吸收，可达到根治效果，适用于巨大囊肿、有症状、硬化治疗失败或复发者；肝叶切除适用于极大或局限的多囊肝等严重病例。④并发症处理：感染时予抗生素覆盖肠道菌群，并行穿刺引流置管；出血时卧床观察，出血量大者行穿刺或手术；破裂者观察或手术。⑤多囊肝及多囊肾：多囊肾者随访肾功能（肌酐），本病为遗传性，多属常染色体显性多囊肾，需处理高血压，肾功能衰竭者评估透析或移植；多囊肝巨大者严重时评估肝移植。⑥随访：超声随访囊肿大小，无症状者每1~2年复查，硬化治疗后评估有无复发及囊肿缩小情况；复杂囊肿需手术切除并送病理，术后随访。消化科或肝胆外科对无症状者观察，有症状或较大者行硬化或开窗治疗，复杂囊肿需鉴别后手术，合并多囊肾者需长期随访。","处理方案":"【药物治疗】\n1. 无症状单纯性肝囊肿一般无需药物干预，目前无循证证据支持药物可使囊肿缩小或消失，不建议常规服用消囊、保肝类\"偏方\"药物，以免加重肝脏负担。\n2. 囊肿合并感染（发热、右上腹持续性疼痛、血象升高）时：头孢呋辛酯片0.25g bid口服×7天，或左氧氟沙星片0.5g qd口服×7天（18岁以下、孕妇及哺乳期禁用喹诺酮类；头孢过敏者选用左氧氟沙星，疗程7~10天）。\n3. 合并肝功能异常（ALT/AST升高）者：复方甘草酸苷片75mg tid口服×2周，或水飞蓟宾胶囊105mg tid口服×2周，疗程结束后复查肝功能。\n【一般治疗及生活指导】\n1. 规律作息，避免熬夜和过度劳累，保证充足睡眠，保持情绪平稳，避免焦虑紧张。\n2. 饮食清淡、均衡，适量补充优质蛋白（鱼、蛋、奶、瘦肉），多食新鲜蔬菜水果；避免暴饮暴食及高脂油腻、辛辣刺激饮食，戒酒，不自行服用成分不明的中草药及保健品。\n3. 可进行散步、慢跑、游泳、太极拳等中等强度有氧运动，但应避免剧烈运动及腹部直接撞击（如对抗性运动、骑跨伤），防止囊肿破裂出血。\n【随诊要求】\n1. 无症状、直径<5cm的单纯性肝囊肿：每6~12个月门诊复查腹部超声1次，动态观察囊肿大小及形态变化。\n2. 囊肿直径≥5cm、短期内明显增大（1年增大>2cm）或出现腹胀、右上腹隐痛等压迫症状者，建议3~6个月内复查超声，必要时行上腹部CT/MRI进一步评估，并转肝胆外科专科评估介入（超声引导下穿刺抽液+硬化治疗）或手术（腹腔镜囊肿开窗引流术）治疗指征。\n3. 若出现突发右上腹剧痛、发热、黄疸等表现，提示囊肿破裂、出血或感染可能，应立即急诊就诊。\n4. 随访中发现囊壁增厚、囊内出现分隔或实性成分、血清CA19-9持续升高等异常时，应进一步检查以排除囊性肿瘤可能。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":855,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c1df3cf51e721a23ca3fa3496fc3c81455f30398cf91833467421ab161734910","pinyin":"gannangzhong","initials":"gnz","setting":"out","caseName":"门诊病历723","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历723",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-88d34586e836f5c34f43","key":"v1-c9ccc21dfe2a3058|templates-88d34586e836f5c34f43","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肝血管瘤","category":"门诊病历模板","raw":{"name":"肝血管瘤","category":"门诊病历模板","case":{"case_name":"门诊病历724","templates":{"主诉":"上腹隐痛1天","现病史":"患者1周前无明显诱因出现肝血管瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因上腹隐痛1天就诊，现病史提示1周前无明显诱因出现相关症状并逐渐加重，伴轻度乏力，为明确腹痛性质、排除腹腔急慢性感染及贫血所致乏力，门诊即刻完善血常规检查排除感染、贫血；患者上腹隐痛需与胃十二指肠及结直肠病变相鉴别，完善便常规+潜血检查了解有无消化道出血及肠道炎症。患者以右上腹隐痛为主要表现，完善腹部超声检查作为首选影像学筛查，了解肝内病灶的大小、边界、内部回声及血流情况，明确是否为肝血管瘤典型的高回声表现；肝血管瘤需与原发性肝癌、肝转移瘤、肝脓肿相鉴别，完善腹部CT检查（必要时行增强扫描）明确病灶的强化方式与血供特点，评估有无占位效应及周围组织关系；若CT仍不能明确性质，可进一步行上腹部MRI检查了解病灶在T2WI上的信号特征。因肝血管瘤为血供丰富病灶，且患者需评估肝脏合成功能与储备，完善肝功能检查了解转氨酶、胆红素及白蛋白水平，指导后续随访方案。患者上腹隐痛不能除外胰腺及胆道来源，完善淀粉酶、脂肪酶检查排除急性胰腺炎及胰胆管梗阻所致腹痛。为除外常见上消化道病因及幽门螺杆菌感染对腹痛的影响，完善幽门螺杆菌检测（C13/C14呼气试验），必要时完善胃镜/肠镜检查了解胃黏膜及结直肠有无溃疡、炎症或肿瘤性病变。患者肝内占位有出血及穿刺风险，完善凝血功能检查评估凝血状态，为必要时的介入或手术治疗提供依据。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 肝血管瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 无症状、瘤体较小（<5cm）且影像学稳定者：一般无需药物治疗，定期影像随访即可，勿自行服用\"消瘤\"类偏方。\n2. 有症状（右上腹不适、胀痛）或瘤体进行性增大者：盐酸普萘洛尔片 10mg po tid，初始可减半量逐日加量，服药期间监测心率（静息心率不低于55次/分）与血压，疗程3~6个月；属超说明书用药，需知情同意并排除哮喘、窦性心动过缓、房室传导阻滞等禁忌证。\n3. 疼痛明显需对症处理者：对乙酰氨基酚片 0.5g po，必要时每6小时1次，24小时总量不超过2g，连续使用不超过5天；避免长期服用NSAIDs及阿司匹林。\n4. 症状明显且瘤体持续增大（>5cm）影响生活者：可转介入科行超选择性动脉栓塞治疗（平阳霉素碘油乳剂栓塞），需专科评估后实施，不推荐自行用药。\n\n【一般治疗及生活指导】\n1. 休息：保证充足睡眠，避免熬夜、过度劳累，保持情绪平稳，避免长期精神紧张。\n2. 饮食：清淡、均衡饮食，适量优质蛋白及新鲜蔬果，避免长期大量饮酒及高脂油腻饮食；本病无需特殊忌口。\n3. 活动：可正常工作和进行散步等温和运动；避免剧烈运动、重体力劳动及腹部撞击挤压（如举重、拳击、患者度腹肌锻炼），瘤体>10cm者尤应注意，防止外伤诱发破裂出血。\n4. 禁忌：避免使用含雌激素类药物（口服避孕药、绝经期激素替代治疗），以免促进瘤体生长；慎用不明成分保健品及可能损伤肝脏的药物。\n\n【随诊要求】\n1. 无症状且瘤体<5cm者：每6~12个月复查腹部彩超1次，动态观察瘤体大小及形态变化。\n2. 瘤体5~10cm或首次确诊者：每3~6个月复查彩超；若出现右上腹胀痛、进食后饱胀、瘤体短期明显增大等，及时就诊并行增强CT或MRI评估。\n3. 瘤体>10cm（巨大血管瘤）或有明显症状者：建议转肝胆外科/介入科评估治疗；若突发剧烈腹痛、腹胀、面色苍白、休克等疑似破裂征象，立即急诊就诊；伴血小板减少、凝血异常者需警惕Kasabach-Merritt综合征。\n4. 随访期间瘤体年增长>1cm或新发症状者，应缩短随访间隔并转专科处理；育龄期女性妊娠期间每3个月复查彩超1次，产后复查确认瘤体变化。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":856,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3396f4e03547325dcd14cb8f47caf428699f02668cd107002cd635f25e7bfe0b","pinyin":"ganxueguanliu","initials":"gxgl","setting":"out","caseName":"门诊病历724","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历724",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-746899b1ded671aaf448","key":"v1-c9ccc21dfe2a3058|templates-746899b1ded671aaf448","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性胆囊炎","category":"门诊病历模板","raw":{"name":"慢性胆囊炎","category":"门诊病历模板","case":{"case_name":"门诊病历725","templates":{"主诉":"反复右上腹隐痛、胀痛10年","现病史":"患者于10年前开始反复出现右上腹或上腹隐痛、胀痛，多于进食油腻后加重，呈阵发性或持续性，偶向右肩背部放射，伴嗳气、腹胀，属消化不良表现，无特异性，可有恶心；对油腻食物不耐受，进食油腻后不适为重要线索。急性发作时可反复出现胆绞痛，表现为右上腹剧痛、阵发性，系结石嵌顿所致，参见胆石症相关内容；亦可出现急性胆囊炎，表现为发热及Murphy征阳性，参见急性胆囊炎相关内容。慢性胆囊炎多因胆囊结石长期刺激所致，结石性慢性胆囊炎占90%以上伴结石；非结石性者少见，与胆汁淤积或感染有关。超声检查可见胆囊壁增厚（≥4mm）、胆囊结石及胆囊收缩功能下降。需注意有无并发症：急性发作时可合并感染而发热；可继发胆总管结石并出现黄疸；慢性胆囊炎合并结石长期存在可增加胆囊癌风险，结石>3cm、胆囊壁钙化即瓷化胆囊者癌变率较高；胆囊腺肌症亦为胆囊癌高危因素，需考虑手术，此点重要。还需了解症状与进食油腻的关系及急性发作频率。今日来我院消化科或普外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.7℃，P76次/分，R18次/分，BP118/74mmHg。右上腹轻压痛，慢性期Murphy征阴性或弱阳性，急性发作时呈阳性；右上腹叩击痛可疑阳性；无肌紧张及反跳痛，提示无急性炎症；肝区叩痛可疑阳性；无黄疸，若胆总管梗阻则可出现黄疸。","辅助检查":"【必做】腹部超声（为确诊核心，可见胆囊结石及大小、数量，胆囊壁增厚≥4mm提示慢性炎症及纤维化，可观察胆囊大小有无萎缩或增大；脂餐试验可评估收缩功能，收缩率<50%提示功能低下；并可发现胆囊内泥沙样结石或胆汁淤积，用于常规随访）；【血液】急性发作或出现黄疸时查肝功能，包括胆红素、碱性磷酸酶及转氨酶，以评估胆道梗阻；血常规用于判断有无感染，多见于急性发作；血淀粉酶及脂肪酶用于排查胆源性急性胰腺炎；【影像】疑有胆囊癌或病情复杂者行增强CT、MRI或MRCP检查，以了解有无胆总管结石及黄疸；必要时行超声内镜检查；【其他】胆囊壁钙化即瓷化胆囊，可经X线或CT发现，提示胆囊癌风险，需评估手术指征。","初步诊断":"1. 慢性胆囊炎（结石性或非结石性；伴胆囊结石，大小待明确；有症状；需评估胆囊癌危险因素）\n（注：治疗方面，有症状的结石性慢性胆囊炎行胆囊切除可根治，无症状者需评估手术指征：①饮食管理：无症状或轻症者予低脂饮食，避免油腻以减少发作，并规律进食、少食多餐。②药物对症治疗：症状较轻者予解痉治疗，如山莨菪碱，用于胆绞痛；利胆治疗可选熊去氧胆酸，用于溶解胆固醇结石，但仅限小结石（<0.5cm）及非钙化结石，且需胆囊功能正常，疗程长（6~12个月），成功率有限，现已少用；消炎利胆片等中成药可作为辅助治疗以缓解症状；急性发作时予抗感染治疗，参见急性胆囊炎相关内容。③胆囊切除术：腹腔镜胆囊切除为首选及金标准；手术指征包括：有症状者，如反复胆绞痛、急性胆囊炎发作或消化不良影响生活，切除后症状可缓解；并发症高危者，如结石>2~3cm、胆囊壁钙化即瓷化胆囊（必须切除，因有癌变风险）、胆囊腺肌症、合并胆囊息肉>1cm、糖尿病（感染及并发症风险高，可择期切除）、胆囊癌高危者（年龄>50岁且合并结石长期存在，需评估）；无症状者通常观察，但合并高危因素者应手术；妊娠期症状发作者以保守治疗为主，必要时于孕中期手术。④并发症处理：急性胆囊炎、胆总管结石、胆囊癌均按相应方案处理，参见专项内容。⑤随访：未手术者，无症状者每年行超声检查，观察结石变化及胆囊壁有无增厚或钙化，以预警癌变；症状加重者重新评估手术；胆囊切除后多数症状缓解，少数可出现术后消化不良，与胆盐代谢有关，术后腹泻多可逐渐好转，需随访。普外科或消化科对有症状者以手术为根本治疗，腹腔镜手术微创，宜择期进行；急性期先保守治疗，待炎症消退后手术）。","处理方案":"【药物治疗】\n1. 利胆药：熊去氧胆酸胶囊（优思弗）250mg 口服 bid，或按10mg/kg/d分次服用，疗程3～6个月，用于慢性非急性期利胆、促进结石溶解。\n2. 解痉镇痛药：匹维溴铵片（得舒特）50mg 口服 tid 餐前，或山莨菪碱片10mg 口服 tid，用于缓解右上腹隐痛、胆绞痛发作。\n3. 助消化药：复方阿嗪米特肠溶片（泌特）2片 口服 tid 餐后，改善腹胀、消化不良症状。\n4. 抗菌药物：仅在急性发作合并感染（发热、右上腹剧痛、白细胞升高）时选用，如头孢呋辛酯片0.25g 口服 bid×5天，或左氧氟沙星片0.5g 口服 qd×5天，无感染征象者不常规使用抗生素。\n\n【一般治疗及生活指导】\n1. 低脂低胆固醇饮食：忌食油炸、肥腻食物（肥肉、动物内脏、蛋黄、奶油）、辛辣刺激食物，少食多餐，避免暴饮暴食。\n2. 规律进餐、坚持吃早餐，促进胆囊定时收缩排空，避免胆汁淤积；戒酒。\n3. 控制体重，适当运动（散步、慢跑等有氧运动），避免久坐、腹部受凉，防止诱发胆绞痛。\n4. 保持心情舒畅，避免精神紧张、过度劳累。\n\n【随诊要求】\n1. 每3～6个月门诊复查腹部超声，观察胆囊壁厚度及结石大小、数量变化；每年复查肝功能、血脂。\n2. 若出现右上腹持续性剧痛、发热、寒战、皮肤巩膜黄染，提示急性发作或胆总管梗阻，应立即急诊就诊。\n3. 症状反复发作影响生活、胆囊壁增厚≥4mm、结石增大或合并胆囊息肉者，建议肝胆外科评估，行腹腔镜胆囊切除术；术后仍应定期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":857,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"466c5f39137a246b0f1f5b7fb6a6bdb68a38bceb80e0bbab3df1402c43f51ccc","pinyin":"manxingdannangyan","initials":"mxdny","setting":"out","caseName":"门诊病历725","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历725",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ec506d1fb0e8d5398c6a","key":"v1-c9ccc21dfe2a3058|templates-ec506d1fb0e8d5398c6a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胆囊结石","category":"门诊病历模板","raw":{"name":"胆囊结石","category":"门诊病历模板","case":{"case_name":"门诊病历726","templates":{"主诉":"反复右上腹绞痛1年","现病史":"患者存在以下危险因素：女性，发病率约为男性的2~3倍；肥胖；妊娠，与雌激素致胆汁淤积有关；高脂饮食或快速减重；肝硬化或溶血，易形成色素性结石；家族史。患者于体检或发作时发现：无症状者约占70~80%，为体检超声发现的静止性结石；胆绞痛表现为右上腹或上腹阵发性绞痛、胀痛，多于油腻餐后或夜间发作，系结石嵌顿于胆囊管所致，持续30分钟至数小时可自行缓解，可向右肩背部放射，伴恶心、呕吐；并发症包括急性胆囊炎，表现为持续疼痛>6小时并伴发热及Murphy征阳性，属急症；胆总管结石，可出现黄疸、发热；胆源性胰腺炎，多因小结石排出所致，表现为上腹痛并向背部放射、淀粉酶升高；胆囊癌，长期结石>3cm者风险较高；瓷化胆囊癌变率高，需手术；以及Mirizzi综合征。还需记录发作频率及诱因、有无胆囊壁增厚（提示慢性胆囊炎）、结石大小及数目（可为泥沙样）。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.0℃，P80次/分，R18次/分，BP118/74mmHg。发作时右上腹压痛；Murphy征阳性，提示胆囊炎；无反跳痛及肌紧张，提示无穿孔；肝区叩痛；黄疸，提示胆总管结石梗阻；发热，提示胆囊炎或胆管炎。","辅助检查":"【必做】腹部超声（核心检查：胆囊结石呈强回声伴声影，可随体位移动，此点与息肉鉴别，息肉不移动；可判断结石数目及大小、胆囊壁有无增厚、胆总管有无扩张及结石）、肝功能（胆道梗阻时胆红素、碱性磷酸酶、γ-谷氨酰转移酶及转氨酶可升高，发作时可轻度升高）、淀粉酶及脂肪酶（排查胆源性胰腺炎）、血常规及CRP（判断有无胆囊炎）、血糖及血脂；【评估】MRCP（疑有胆总管结石，如出现黄疸或胰腺炎时）、CT（用于胆总管结石或胰腺炎的评估）、内镜超声（用于胆总管下端小结石的检出）、脂餐试验（评估胆囊收缩功能）；【随访】超声随访，监测结石大小及数目变化、胆囊壁有无增厚，以及癌变监测，需长期进行。","初步诊断":"1. 胆囊结石（单发或多发，可为泥沙样；需明确大小，>3cm者癌变风险增高；无症状即静止性结石，或有症状即胆绞痛，需记录发作频率；评估并发症如胆囊炎、胆总管结石、胰腺炎；了解有无胆囊壁增厚及钙化即瓷化胆囊；评估手术指征）\n（注：治疗方面，无症状者以观察随访为主，定期行超声检查；但存在高危因素者，如大结石>2~3cm、瓷化胆囊（必须手术）、合并息肉>1cm、糖尿病、免疫功能低下、长期肠外营养，应评估择期手术；有症状的胆绞痛者行腹腔镜胆囊切除，为金标准，微创且可根治，宜择期于发作间歇期进行；发作时予解痉止痛，如山莨菪碱或非甾体抗炎药，并予低脂饮食；急性胆囊炎者予急诊抗感染及手术，参见急性胆囊炎相关内容；妊娠期以保守治疗为主，必要时评估中孕期手术；熊去氧胆酸溶石仅适用于小结石<0.5~1cm、非钙化且胆囊功能良好者，疗效有限且复发率高，现已少用；胆总管结石者行ERCP取石；术后随访症状缓解情况，胆囊切除后腹泻多可逐渐缓解，并注意低脂饮食）。","处理方案":"【药物治疗】\n1. 解痉止痛（胆绞痛发作时）：间苯三酚注射液80mg 肌注 必要时；或屈他维林片40mg tid po。\n2. 利胆溶石（胆固醇结石、胆囊功能正常且无急性炎症者）：熊去氧胆酸胶囊250mg bid po（按10mg/kg/d分2次服），疗程6～24个月。\n3. 抗感染（合并急性胆囊炎，发热、血象升高或影像提示感染时）：头孢呋辛酯片0.25g bid po×5～7天；或左氧氟沙星片0.5g qd po×5～7天。\n4. 助消化（腹胀、脂肪泻者）：复方阿嗪米特肠溶片2片 tid po，餐后服。\n【一般治疗及生活指导】\n1. 低脂低胆固醇饮食：忌油炸、肥腻食物、动物内脏、蛋黄及浓肉汤，每日脂肪摄入＜50g；规律三餐，避免暴饮暴食及长期素食或过度节食。\n2. 控制体重、避免快速减肥；缓解期适当活动（散步等），急性发作期卧床休息。\n3. 忌饮酒及辛辣刺激性食物；避免空腹时间过长（如不吃早餐），多饮水，每日2000ml以上。\n4. 合并糖尿病、高脂血症者积极治疗原发病；妊娠期及服用雌激素者注意结石诱发风险。\n【随诊要求】\n1. 每3～6个月复查腹部超声，动态观察结石大小、数量及胆囊壁厚度变化。\n2. 溶石治疗者每6个月复查超声评估疗效；结石无缩小或胆囊功能减退者停用熊去氧胆酸并外科评估。\n3. 出现右上腹持续性剧痛、发热、黄疸或Murphy征阳性，提示急性胆囊炎或胆总管结石，立即急诊就诊。\n4. 结石＞2cm、胆囊壁增厚＞4mm、胆囊息肉合并结石或反复发作胆绞痛者，建议外科会诊评估胆囊切除手术指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":858,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bd5834dbb69c56c7c07522fe2bbc3610c021b60f89a58be23bc33139c6a3956c","pinyin":"dannangjieshi","initials":"dnjs","setting":"out","caseName":"门诊病历726","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历726",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-225ecd4582f6a5de67f7","key":"v1-c9ccc21dfe2a3058|templates-225ecd4582f6a5de67f7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胆管结石","category":"门诊病历模板","raw":{"name":"胆管结石","category":"门诊病历模板","case":{"case_name":"门诊病历727","templates":{"主诉":"右上腹绞痛伴黄疸、发热1周","现病史":"患者存在以下病因（胆总管结石可分为继发性，即胆囊结石排入胆总管，最为常见；原发性，即胆总管原发泥沙样结石，与胆道感染或狭窄有关，我国多见东方色素性结石；有胆道手术史者，可因胆肠吻合口狭窄而形成结石；肝内胆管结石，我国西南地区多见，易复发并引起胆管炎）。患者于1周前出现以下表现：无症状者，多见于小结石未造成梗阻，可经体检超声或MRCP发现；胆绞痛，位于右上腹，呈阵发性，多于进食油腻后发作；梗阻表现包括黄疸，为梗阻性，可见皮肤巩膜黄染、尿色加深、陶土样便及皮肤瘙痒；黄疸可呈间歇性，因结石嵌顿后又漂浮移位所致，黄疸波动为胆总管结石的特征；Charcot三联征，即腹痛加黄疸加发热寒战，提示胆管炎，属急症，参见急性胆管炎相关内容；Reynolds五联征，即三联征加休克及意识障碍，提示急性梗阻性化脓性胆管炎，属急症；胰腺炎，因结石堵塞共同通道所致，为胆源性胰腺炎，表现为上腹痛及血淀粉酶升高，此点重要，胆总管小结石可致一过性胰腺炎，有时以胰腺炎为首发表现；肝功能异常，呈淤胆型，碱性磷酸酶及γ-谷氨酰转移酶升高，转氨酶轻中度升高，多于结石发作时出现。还需了解有无胆囊结石同时存在及胆囊炎、黄疸是否呈间歇性、有无发热及胆管炎、有无胰腺炎及淀粉酶升高、有无ERCP史或手术史；超声可见胆总管扩张（>8mm，胆囊切除后>10mm）及下端结石，但超声可漏诊，因受气体干扰。今日来我院消化科或肝胆外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.2℃，P96次/分，R20次/分，BP112/70mmHg。黄疸，可见皮肤巩膜黄染，需注意程度；右上腹或上腹压痛，合并胆囊炎时Murphy征阳性；肝区叩痛；肝大，与淤胆有关；腹部无肌紧张，提示无穿孔；发热伴寒战，提示胆管炎；休克者血压降低，提示化脓性胆管炎，属急症，需评估；皮肤可见抓痕，与瘙痒有关；合并胰腺炎者上腹压痛，可有反跳痛，血淀粉酶升高。","辅助检查":"【必做】肝功能（呈梗阻性黄疸表现，总胆红素及直接胆红素升高，碱性磷酸酶及γ-谷氨酰转移酶显著升高，转氨酶轻中度升高，多于发作时升高、缓解后下降，呈波动性，为其特征）、血淀粉酶及脂肪酶（了解有无合并胰腺炎，此点重要）、血常规及CRP（判断有无胆管炎及感染）、凝血功能（胆道梗阻可致维生素K吸收减少）；【影像】腹部超声（为首选，可见胆总管扩张>8mm、结石，但下端结石显示率较低，约50~70%，因受气体干扰，并可观察肝内外胆管扩张、胆囊结石及胰腺）；磁共振胰胆管成像（MRCP，为核心无创检查，对胆总管结石敏感性和特异性均高，可显示结石大小及位置以及肝内胆管情况，为非急诊时的诊断首选）、内镜超声（对小结石及壶腹部病变敏感，适用于MRCP阴性但仍疑有结石者，或ERCP前评估）；【确诊】ERCP（兼具诊断与治疗作用，可经造影显示结石，并行括约肌切开取石，参见治疗部分，属治疗性内镜，可确诊）；【其他】CT（部分结石可显影，尤其钙化结石，并可用于评估合并胰腺炎或并发症）、疑有肿瘤者，如胆总管下段癌致梗阻而无结石，需行MRCP鉴别，此点重要。","初步诊断":"1. 胆总管结石（继发性即胆囊结石排入，或原发性，或肝内胆管结石；无症状，或有胆绞痛、梗阻性黄疸、胆管炎、胆源性胰腺炎；胆总管扩张，直径待明确；需评估ERCP或手术指征）\n（注：治疗依据症状及并发症决定，以取出结石、解除梗阻为目标：①无症状者：若为小结石且无梗阻，可与患者讨论后决定，多数主张处理，因将来有发生胆管炎等并发症的风险，尤其合并胆囊结石者，可行胆囊切除加胆总管探查，或行ERCP；具体依就诊单位条件评估；年轻患者倾向积极处理。②胆绞痛或梗阻但无感染者：行ERCP，即内镜逆行胰胆管造影，行括约肌切开加取石，采用网篮或碎石取石，成功率高，可达90%以上，为胆总管结石的标准首选治疗；取石失败或结石巨大者，可行机械碎石、体外震波碎石或激光碎石，或改行手术；可置鼻胆管引流，用于梗阻未取尽者，以引流减压；内镜治疗后并发症包括ERCP后胰腺炎，较为常见，需重视，应观察血淀粉酶，轻者对症处理；出血，多因切开所致，需止血；穿孔少见，若出现腹痛属急症。③胆管炎：属急症，治疗为抗感染加胆道引流，行急诊ERCP减压引流，参见急性胆管炎相关内容，化脓性者需紧急处理，宜于24~48小时内完成；抗生素需覆盖革兰阴性菌、厌氧菌及肠球菌，如哌拉西林他唑巴坦，或头孢曲松加甲硝唑。④胆源性胰腺炎：轻型者可先行保守治疗，待胰腺炎缓解后行ERCP；重症或合并胆管炎者需急诊ERCP，此点重要；合并胆囊结石者患者胰腺炎恢复后行胆囊切除，以防再发，此点重要。⑤合并胆囊结石：ERCP取石后应行腹腔镜胆囊切除，择期进行，以防结石再次排入导致胆总管结石复发，此点重要。⑥手术：腹腔镜胆总管探查取石，可同期行胆囊切除；或行开腹手术，适用于失败或复杂病例；胆肠吻合术，如Roux-en-Y吻合，适用于原发性或复发性及肝内胆管结石者，需评估。⑦随访：取石后症状消失，肝功能恢复；ERCP后需观察有无胰腺炎；胆总管结石复发率约10~20%，需随访超声或MRCP，再发者再次处理；术后或取石后应复查影像，了解有无残余结石。消化内镜或肝胆外科应重视ERCP取石这一标准治疗，胆管炎需急诊引流，胆囊切除可防复发，此点重要。","处理方案":"【药物治疗】\n1. 抗感染治疗（合并胆道感染时）：头孢克肟胶囊0.1g bid po，联合甲硝唑片0.4g tid po，疗程7天；若出现寒战、高热或黄疸，提示急性胆管炎，应停用口服药改为静脉抗感染（如头孢哌酮/舒巴坦3.0g ivgtt q12h + 甲硝唑0.5g ivgtt bid，疗程7～10天）并转住院治疗。\n2. 解痉镇痛：山莨菪碱片10mg tid po，胆绞痛发作时临时加服10mg；青光眼、前列腺增生者禁用，可改用间苯三酚片80mg tid po。\n3. 利胆治疗：熊去氧胆酸胶囊250mg tid po，餐后服用，疗程3～6个月；仅适用于胆固醇性结石且胆总管无完全梗阻者，结石较大或嵌顿者利胆治疗无效，应首选ERCP取石或手术治疗。\n4. 补充维生素K：反复梗阻、黄疸较深者，予维生素K1片10mg qd po，连用3天，改善凝血功能、降低出血风险。\n\n【一般治疗及生活指导】\n1. 饮食：严格低脂、低胆固醇饮食，忌油炸、肥腻食物及动物内脏、蛋黄等高脂高胆固醇食物，少食多餐，避免暴饮暴食；急性发作期暂禁食或进清淡流质饮食。\n2. 休息与活动：急性期卧床休息，减少活动；缓解期适当散步等轻度活动，控制体重，避免剧烈运动和腹部撞击。\n3. 禁忌：戒烟、限酒，避免浓茶、咖啡及高糖饮料；勿滥用泻药及成分不明的保健品、中药补剂，以免诱发胆绞痛；合并胆道感染期间避免使用阿司匹林等影响凝血的药物。\n4. 病情观察：若出现右上腹绞痛进行性加重、寒战高热、黄疸（Charcot三联征），或伴意识障碍、血压下降（Reynolds五联征），提示急性梗阻性化脓性胆管炎，须立即急诊就诊。\n\n【随诊要求】\n1. 用药2周后复诊，复查血常规、肝功能（ALT、AST、TBIL、DBIL、ALP、GGT）及腹部超声，评估感染与梗阻缓解情况。\n2. 确诊胆管结石者应尽快完善MRCP，明确结石部位、大小及胆管扩张程度，预约ERCP取石或择期手术治疗，去除结石、解除梗阻为根治手段。\n3. 未手术者每3～6个月复查腹部超声1次；行ERCP或手术者术后1、3、6个月各复查肝功能及超声1次。若再次出现腹痛、发热或黄疸，随时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":859,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"28a04533b9634f453cd7b6ccd32346f3820921dfe4e4c2da66239a3429d96359","pinyin":"danguanjieshi","initials":"dgjs","setting":"out","caseName":"门诊病历727","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历727",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e064dc6c17b638979942","key":"v1-c9ccc21dfe2a3058|templates-e064dc6c17b638979942","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性胆管炎","category":"门诊病历模板","raw":{"name":"急性胆管炎","category":"门诊病历模板","case":{"case_name":"门诊病历728","templates":{"主诉":"腹痛伴黄疸、发热寒战2天","现病史":"患者有胆石症基础（胆总管结石为最常见病因，结石嵌顿于胆总管可致胆汁淤积并继发细菌感染，从而引起胆管炎；ERCP或胆道支架术后可发生术后胆管炎；胆道肿瘤所致恶性梗阻亦可合并感染）。患者于2天前出现以下表现：腹痛，位于右上腹或上腹，呈持续性疼痛，可阵发性加重；黄疸，呈进行性，可见皮肤巩膜黄染、尿色加深、陶土样便，与胆汁淤积有关；发热寒战，体温可达39℃以上，呈弛张热，伴寒战，系菌血症及胆道感染所致，病原以革兰阴性菌如大肠杆菌为主，内毒素参与致病；Charcot三联征，即腹痛加黄疸加发热，为急性胆管炎的经典三联征，有诊断意义；重症者出现Reynolds五联征，即三联征加休克（低血压、感染性休克）及意识障碍（嗜睡或昏迷，为脓毒症脑病），提示急性梗阻性化脓性胆管炎，为最严重类型，属急症，死亡率高；全身表现包括感染中毒症状，如乏力、恶心呕吐、烦躁，为休克前兆。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T39.1℃，P112次/分，脉搏增快，R24次/分，BP88/56mmHg，血压降低，提示重症及休克。神志清楚、嗜睡或淡漠，出现意识障碍提示重症，符合五联征；皮肤巩膜黄染明显；右上腹压痛阳性；Murphy征可疑阳性，提示合并胆囊炎；肝大，因胆道梗阻致淤胆性肝大，伴压痛；肝区叩击痛阳性；腹膜炎体征如肌紧张少见，若出现需考虑坏疽或穿孔；休克表现包括皮肤湿冷、尿量减少，提示重症。","辅助检查":"【必做】血常规（白细胞显著升高，伴核左移）、CRP及降钙素原（感染及脓毒症时升高，用于评估）、肝功能（呈梗阻性黄疸，胆红素升高且以结合胆红素为主，碱性磷酸酶及γ-谷氨酰转移酶显著升高，提示胆汁淤积，转氨酶轻中度升高，与胆管炎有关）、血培养（患者使用抗生素前采集2~3套，以明确病原，如大肠杆菌、克雷伯杆菌、肠球菌，以革兰阴性菌为主，并行药敏试验，此点重要）、凝血功能（胆道梗阻致维生素K吸收减少，凝血酶原时间延长，手术或介入前需纠正）；【影像】腹部超声（为首选，可见胆总管扩张>8mm，胆囊切除后>10mm，可见胆总管下端结石，超声有时漏诊，可观察肝内外胆管扩张，用于快速床旁评估梗阻）、MRCP（磁共振胰胆管成像，可敏感显示胆总管结石及狭窄，适用于病情稳定后的非急诊检查）、CT（用于评估胆总管结石、肿瘤及并发症如腹膜炎，必要时进行）；【介入】ERCP（内镜逆行胰胆管造影，兼具诊断与治疗作用，可行EST括约肌切开取石或支架置入引流，为核心治疗，参见治疗部分）。","初步诊断":"1. 急性胆管炎（轻中度，符合Charcot三联征；或为重症即急性梗阻性化脓性胆管炎，符合Reynolds五联征，伴休克及意识障碍；病因可为胆总管结石、支架或肿瘤）\n（注：急性胆管炎属急症，胆道梗阻合并感染可致脓毒症，甚至死亡，治疗原则为抗感染加胆道引流，其中解除梗阻为核心，并需把握手术时机：①抗感染：立即予经验性广谱抗生素，覆盖革兰阴性肠杆菌（大肠杆菌、克雷伯杆菌常见）及肠球菌、厌氧菌，可选哌拉西林他唑巴坦4.5g q6h，或头孢曲松2g q24h加甲硝唑0.5g q8h，重症可用美罗培南；待血培养结果回报后调整；疗程方面，引流后抗生素使用7~10天，无并发症者可缩短。②胆道引流及解除梗阻：为核心治疗，确定存在胆道梗阻后应尽快引流；内镜治疗为首选，可行内镜下括约肌切开加取石，或置鼻胆管引流（ENBD，不取石仅引流，适用于重症以快速减压），或置入支架，宜在72小时内完成，重症者患者24~48小时内紧急进行，时间窗很重要；经皮肝穿刺胆道引流（PTCD）适用于ERCP失败或无法实施者，如解剖改变或胃肠吻合术后；外科手术适用于内镜或介入失败，或合并穿孔、坏疽者，行急诊手术，即胆总管切开引流加T管引流，开放手术现已少用，多用于介入失败时。③支持治疗：补液，脓毒症者行液体复苏；休克者使用血管活性药，如去甲肾上腺素；监测生命体征、尿量及乳酸，按脓毒症原则管理；凝血酶原时间延长者予维生素K纠正；并予退热治疗。④重症即急性梗阻性化脓性胆管炎者应收治ICU，行急诊引流，时间就是生命，减压后症状可迅速改善，血压回升、意识转清是判断引流有效的标志。⑤病因处理：引流后择期处理病因，胆总管结石者行ERCP取石以达到彻底治疗；支架者择期更换或取出；肿瘤者评估根治治疗，参见相关章节。⑥随访：引流后监测黄疸消退及胆红素下降情况，评估感染控制；行胆道影像检查，了解有无结石残留或复发，ERCP后尤应注意；预防复发，胆总管结石术后应低脂饮食并随访超声。急诊、肝胆外科与消化内镜应多学科协作，早期引流是核心，不可延误，因死亡率与引流延迟相关）。","处理方案":"【药物治疗】\n1．抗感染（覆盖革兰阴性肠道杆菌及厌氧菌，门诊轻症口服方案）：左氧氟沙星片0.5g qd×5～7天，联合甲硝唑片0.4g tid×5～7天；或阿莫西林克拉维酸钾片0.625g tid×5～7天。\n2．利胆：熊去氧胆酸胶囊0.25g bid～tid×2～4周（梗阻未解除者暂缓，以免胆压升高）。\n3．解痉止痛：山莨菪碱片5～10mg tid（青光眼、前列腺肥大者禁用）；疼痛剧烈时临时予山莨菪碱注射液10mg肌注。\n【一般治疗及生活指导】\n1．急性期卧床休息、清淡流质或半流质饮食，必要时静脉补液维持水、电解质平衡；退热后逐渐过渡至低脂普食。\n2．严格低脂饮食：少食多餐，忌油腻、油炸、高胆固醇食物（蛋黄、动物内脏、肥肉）及暴饮暴食，绝对戒酒。\n3．监测体温、皮肤巩膜黄染及腹痛变化：若出现寒战高热、黄疸加深、右上腹绞痛加剧，提示病情加重，须立即急诊就诊。\n4．保持大便通畅，避免便秘、用力屏气诱发胆绞痛；胆道术后或带T管者注意引流通畅。\n【随诊要求】\n1．用药后3天内复诊复查血常规、CRP、肝功能、血淀粉酶；体温持续不退或黄疸进行性加重者立即返院，警惕重症胆管炎（Charcot三联征/雷诺五联征）。\n2．症状缓解后1～2周复查肝胆胰超声或CT，评估胆管扩张、结石位置及有无胆道狭窄。\n3．影像学证实胆总管结石或胆道梗阻者，建议限期行ERCP+EST取石或外科手术解除梗阻，切勿仅依赖药物缓解。\n4．反复发作胆管炎、胆肠吻合术后患者需长期随访（每3～6个月复查肝功能和影像学）。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":860,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9ba72b42c2ca0f5f5b57748db9f2ccb2dd4c8acb0ee35b7102b41ef0ac51b532","pinyin":"jixingdanguanyan","initials":"jxdgy","setting":"out","caseName":"门诊病历728","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历728",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1a1c8ed8c0d112e73d8a","key":"v1-c9ccc21dfe2a3058|templates-1a1c8ed8c0d112e73d8a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性胰腺炎","category":"门诊病历模板","raw":{"name":"慢性胰腺炎","category":"门诊病历模板","case":{"case_name":"门诊病历729","templates":{"主诉":"反复上腹疼痛伴脂肪泻3年","现病史":"患者存在以下病因（酒精性最为常见，我国长期大量饮酒为慢性胰腺炎的主要病因；特发性，病因不明；胆源性，胆石可致反复胰腺炎而慢性化；遗传性，与家族性阳离子胰蛋白酶原基因突变有关；自身免疫性，属IgG4相关疾病，可呈肿块型，激素治疗有效，此点重要，属可治性疾病，需注意鉴别；热带性；以及高钙、高脂血症等。复发性急性胰腺炎反复发作亦可慢性化）。患者于3年前（慢性、渐进性起病，病程数年）出现以下表现：腹痛，位于上腹或中腹，呈阵发性或持续性，多于进食后或饮酒后加重，可向前放射至腰背部，符合胰腺疼痛特点；反复发作，急性加重时类似急性胰腺炎；脂肪泻，因胰酶不足致脂肪消化吸收障碍，表现为大便油腻、恶臭、漂浮、量多，呈陶土样，为胰源性腹泻，是慢性胰腺炎晚期的特征性表现；体重下降，与吸收不良及食欲减退有关；糖尿病，因胰岛破坏致胰岛素分泌减少，为慢性胰腺炎继发的糖尿病，多出现于晚期，约占50%；黄疸少见，可因胰头纤维化压迫胆总管所致；腹部包块，可为假性囊肿，属胰腺囊性病变，为慢性胰腺炎的并发症，参见胰腺囊肿相关内容；消瘦，与营养不良有关。还需了解有无急性发作（剧烈腹痛，但血淀粉酶可不高，因胰腺纤维化萎缩所致，淀粉酶可不升高，此点重要，慢性胰腺炎急性发作时淀粉酶正常亦有可能）、饮酒史（饮酒量及年限）、胆石史、家族史（遗传性）、自身免疫相关表现（IgG4、肿块型）、假性囊肿（腹痛、腹块、压迫）、胰管结石（胰管钙化，可经X线或CT发现，为特征性表现）、脂肪泻（大便性状及频率）、糖尿病（血糖及病程）。今日来我院消化科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒20年，约2两/日。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P78次/分，R18次/分，BP114/72mmHg。上腹或中腹压痛，程度较轻，符合慢性期表现；急性发作时可剧痛并出现反跳痛；消瘦，体重下降，提示营养不良；皮肤黄疸少见；腹部可触及包块，多位于上腹，提示假性囊肿；可见糖尿病相关体征，血糖升高；营养不良表现为皮肤干燥、肌肉减少；腹部血管杂音罕见，可见于胰大或脾动脉病变；腹水少见。","辅助检查":"【必做】血淀粉酶及脂肪酶（急性发作时可升高，但慢性期因胰腺纤维化可不高，此点重要，勿因淀粉酶正常而排除诊断）、血糖（了解有无合并糖尿病）、肝功能（黄疸时提示梗阻）、粪弹力蛋白酶（无创检查，反映胰腺外分泌功能，降低支持胰腺外分泌功能不足）、粪脂肪定量（用于脂肪泻，72小时粪脂肪>7g/日）、白蛋白及前白蛋白（评估营养状况）、脂溶性维生素（A、D、E、K，吸收不良时可缺乏）、血钙、自身免疫指标（IgG4，自身免疫性胰腺炎时可升高，支持诊断，此点重要，尤其肿块型）、肿瘤标志物（CA19-9可升高，但慢性胰腺炎亦可轻度升高，与胰头癌鉴别困难）；【影像】腹部CT（为核心检查，可见胰腺钙化，包括胰管或实质点状钙化，为慢性胰腺炎的特征性表现；胰管扩张，呈串珠样，可伴结石；胰腺萎缩；假性囊肿；胰头肿块，需与自身免疫性胰腺炎及肿瘤鉴别）、磁共振胰胆管成像或胰管成像（MRCP或MRCP加胰泌素，可显示胰管扩张、狭窄及结石，评估胰管形态）、ERCP（可显示胰管，兼具诊断与治疗作用，如取石或置支架，现已少用，因属有创检查）、超声内镜（用于胰头肿块的鉴别，可鉴别肿瘤，必要时行细针穿刺细胞学检查，此点重要；并可评估胰管结石）；【其他】急性发作时查血常规及CRP以评估严重程度；年轻或有家族史者行遗传学基因检测；骨密度检查，了解有无骨质疏松，与吸收不良有关。","初步诊断":"1. 慢性胰腺炎（病因为酒精性、特发性、胆源性或自身免疫性等；胰腺形态可见钙化、胰管扩张或萎缩；合并内外分泌功能不全，表现为脂肪泻及糖尿病；需评估有无假性囊肿及胰头肿块）\n（注：治疗以止痛、胰酶替代及处理并发症为主，并防止病情进展：①病因治疗：戒酒为核心，必须绝对执行，酒精是病情进展及疼痛的关键因素，戒酒后部分患者疼痛可缓解，并可防止进一步损伤；戒烟，吸烟可加重病情，应戒除；合并胆石者予相应处理；控制高脂、高钙；自身免疫性者予激素治疗，如泼尼松，对IgG4相关胰腺炎有效，可显著缩小肿块、改善功能，早期治疗重要。②疼痛治疗：慢性疼痛较为棘手，措施包括戒酒、胰酶替代（部分患者疼痛可缓解，与反馈抑制有关）、按阶梯使用止痛药（轻者用对乙酰氨基酚或非甾体抗炎药，重者用曲马多或阿片类，长期使用有依赖风险，须慎用，可多学科疼痛门诊协作）、腹腔神经丛阻滞（用于顽固性疼痛，属介入治疗，可缓解症状）、内镜治疗（胰管减压，适用于胰管结石或狭窄者，行ERCP取石或置支架以减压，可缓解疼痛）、体外震波碎石（用于胰管大结石，碎石后行ERCP取石）、手术（用于顽固性疼痛，胰管扩张者可行胰管空肠吻合即Puestow手术以减压；胰头肿块者行胰头切除或胰十二指肠切除，因与肿瘤难以鉴别，必要时手术；胰尾病变可行远端切除）。③胰酶替代：为脂肪泻的核心治疗，予胰酶肠溶胶囊，每餐脂肪酶2.5万~4万U，随餐口服，采用大剂量肠溶微球制剂效果好，可改善腹泻、增加体重及营养，此点重要；饮食方面可予低脂或适量脂肪饮食，胰酶替代充分时不必严格限制脂肪，中链甘油三酯可不需胰酶即可吸收，可作为热量补充；补充脂溶性维生素（A、D、E、K），缺乏时补充，此点重要；严重营养不良者予肠内或肠外营养支持。④糖尿病：属胰腺性糖尿病，多需胰岛素治疗，口服降糖药如磺脲类可刺激残余β细胞分泌，亦可选用；因胰高血糖素降低，血糖脆性大，易发生低血糖，需监测，建议内分泌科管理，处理原则类似1型糖尿病，以胰岛素为主。⑤并发症处理：假性囊肿直径>6cm、有症状、压迫或感染者行引流，可经内镜经胃引流或手术；胆总管狭窄致黄疸者置支架或手术；胰管破裂可致腹水；胰源性腹水少见；慢性胰腺炎患者胰腺癌风险增加5~8倍，长期随访，若出现新发肿块或症状加重，应警惕，查CA19-9及CT，此点重要。⑥随访：观察症状，包括疼痛、腹泻及体重；评估胰酶替代对脂肪泻的控制情况；管理血糖；每年行CT以监测钙化、囊肿及肿块，警惕胰腺癌风险；评估营养状况，包括体重、白蛋白及维生素；强调长期戒酒的依从性，以防止进展，此点重要。消化科与胰腺专科应重视戒酒、胰酶替代及营养支持，疼痛需多学科管理，自身免疫性者予激素，并监测癌变，此点重要。","处理方案":"【药物治疗】\n1. 胰酶替代治疗：胰酶肠溶胶囊（得每通）0.3g tid，餐中或餐后即刻整粒吞服（勿嚼碎），疗程：长期维持，根据脂肪泻改善情况调整剂量，最大可增至0.9g tid。\n2. 抑酸辅助：奥美拉唑肠溶胶囊20mg qd，晨起空腹口服，疗程4-8周，以减少胃酸对胰酶的破坏、提高胰酶在小肠的活性。\n3. 疼痛控制：轻中度疼痛予对乙酰氨基酚片0.5g prn，每日总量不超过2g；控制不佳时换用曲马多缓释片50mg bid，疼痛缓解后逐渐减量，避免长期连续使用阿片类药物；腹痛性质改变或加重时及时就诊。\n4. 脂肪泻明显者补充脂溶性维生素：维生素AD软胶囊1粒 qd、维生素E软胶囊0.1g qd；合并糖尿病者按血糖水平加用相应降糖方案。\n\n【一般治疗及生活指导】\n1. 严格戒酒、戒烟：酒精与吸烟是慢性胰腺炎进展最重要的可干预因素，须彻底戒除，家属监督执行，避免一切含酒精饮品及食品。\n2. 低脂饮食：每日脂肪摄入控制在40-60g以内，少量多餐（每日5-6餐），忌油炸、肥腻食物及暴饮暴食，以优质蛋白（鱼、瘦肉、蛋清）和碳水化合物为主，保证充足热量。\n3. 活动与休息：急性疼痛发作期卧床休息，缓解期适度活动（如散步），避免剧烈运动、重体力劳动及腹部挤压外伤。\n4. 规律作息、情绪稳定，控制体重；合并糖尿病者按低盐低脂饮食管理并规律监测血糖。\n\n【随诊要求】\n1. 复诊周期：治疗方案调整后2-4周复诊，病情稳定后每3个月门诊复诊一次；每年复查腹部CT或MRI评估胰腺形态及有无假性囊肿、胆道梗阻、胰源性门脉高压等并发症。\n2. 复查项目：每次复诊查血淀粉酶、脂肪酶、肝功能、血糖、糖化血红蛋白，定期行大便脂肪定性定量检测评估胰腺外分泌功能。\n3. 出现腹痛加重、发热、黄疸、恶心呕吐、明显消瘦或黑便时，立即就近就诊。\n4. 长期随访监测胰腺内外分泌功能，预防及筛查糖尿病、骨质疏松与营养不良，必要时转内分泌科、营养科协作管理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":861,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b1116271f10b68db3b3d04c9b710bebb170a932c5f75543e81bc438f0b3ad9ea","pinyin":"manxingyixianyan","initials":"mxyxy","setting":"out","caseName":"门诊病历729","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历729",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ac72492ce4029c3178d8","key":"v1-c9ccc21dfe2a3058|templates-ac72492ce4029c3178d8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胰腺囊肿","category":"门诊病历模板","raw":{"name":"胰腺囊肿","category":"门诊病历模板","case":{"case_name":"门诊病历730","templates":{"主诉":"上腹隐痛1天","现病史":"患者1周前无明显诱因出现胰腺囊肿相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因上腹隐痛1天就诊，现病史提示1周前无明显诱因出现相关症状并逐渐加重，伴轻度乏力，无明显发热及恶心呕吐，为明确腹痛性质、排除感染及贫血所致乏力，门诊即刻完善血常规检查排除感染、贫血；患者上腹隐痛伴消化系统症状，完善便常规+潜血检查了解有无消化道出血、肠道炎症或寄生虫感染；患者以胰腺囊肿为主要诊断且囊肿可随病程变化，需动态了解囊肿有无增大、囊壁情况及其与胰管的关系，完善腹部超声检查评估囊肿大小、形态、内部分隔及有无胆道梗阻；囊肿需与胰腺假性囊肿、黏液性囊腺瘤、导管内乳头状黏液性肿瘤及囊性神经内分泌肿瘤相鉴别，完善腹部CT检查（必要时增强及薄层扫描）明确囊壁强化、分隔及胰周浸润情况，评估有无恶变征象。患者上腹隐痛需排除胰腺自身炎症性病变，完善淀粉酶、脂肪酶检查排除急性胰腺炎及慢性胰腺炎急性发作，评估胰管通畅情况。囊肿可压迫胆总管导致胆汁淤积，且需了解肝脏代谢与合成功能以指导后续用药及手术耐受性，完善肝功能检查了解胆红素、转氨酶及白蛋白水平。为排除幽门螺杆菌感染及胃十二指肠病变所致上腹痛，完善幽门螺杆菌检测（C13/C14呼气试验），必要时完善胃镜/肠镜检查了解胃黏膜及十二指肠乳头情况。若考虑囊肿与胰管相通或需明确胰管解剖，可进一步行MRCP检查。患者存在囊肿合并出血、感染及潜在手术可能，完善凝血功能检查评估凝血状态，为必要时穿刺引流或手术提供依据。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胰腺囊肿\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 胰酶替代治疗：复方胰酶肠溶胶囊（如得每通）0.3g，进餐时整粒吞服，tid，疗程2-4周；合并脂肪泻、腹胀等外分泌功能不全表现者根据患者具体情况制定个体化方案延长。\n2. 抑酸治疗：奥美拉唑肠溶胶囊20mg，早餐前30分钟口服，qd，疗程2-4周；抑制胃酸、减少促胰液素分泌，减轻胰液分泌刺激。\n3. 止痛治疗（腹痛明显时）：间苯三酚片80mg口服，tid，症状缓解即停，不超过3-5天；疼痛较重者可用曲马多缓释片50mg口服，bid，疗程3-5天。禁用吗啡（可诱发Oddi括约肌痉挛、加重胰管内压力）。\n4. 若合并囊肿继发感染（发热、囊肿内脓液征象），在影像学引导穿刺引流基础上予头孢哌酮舒巴坦钠3.0g静滴q12h，疗程7-14天（需住院治疗，门诊仅限轻症口服替代：左氧氟沙星片0.5g口服qd，疗程7天，并密切随访）。\n\n【一般治疗及生活指导】\n1. 饮食：低脂饮食，每日脂肪摄入<50g，忌油炸、肥腻、高胆固醇食物，少食多餐（每日4-6餐），避免暴饮暴食；戒烟、严格戒酒。\n2. 活动：囊肿直径<4cm且无症状者可正常生活工作，但避免剧烈运动、重体力劳动及腹部挤压撞击，防止囊肿破裂、出血或继发感染。\n3. 禁忌：禁用吗啡及阿片类镇痛药；不宜自行服用泻药或强力通便药物；避免腹部按摩、热敷等物理刺激。\n4. 监测：囊肿较大（≥5cm）或近期增大者，避免驾驶、高空作业等，防止突发破裂所致急腹症影响安全。\n\n【随诊要求】\n1. 每3-6个月复查腹部彩超或CT/MRI，动态对比囊肿大小、形态及囊壁改变；囊肿稳定且直径<5cm者可延长至6-12个月复查。\n2. 囊肿直径≥5cm、有压迫症状（腹痛、腹胀、黄疸、恶心呕吐）或随访中明显增大者，建议转消化内科/肝胆外科评估内镜下引流或外科手术。\n3. 疑为黏液性囊性肿瘤或IPMN等囊性肿瘤者，行超声内镜（EUS）及囊液分析（CEA、淀粉酶、细胞学）明确性质，并每6个月随访。\n4. 出现剧烈腹痛、发热、黄疸、囊肿短期内迅速增大或外伤后腹痛加剧，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":862,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e9057604fc00a83ad3956822e54eb16dd656b32f4b1332baa594874cf343d8b9","pinyin":"yixiannangzhong","initials":"yxnz","setting":"out","caseName":"门诊病历730","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历730",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-503218970820e19a0ecd","key":"v1-c9ccc21dfe2a3058|templates-503218970820e19a0ecd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"胰腺内分泌肿瘤","category":"门诊病历模板","raw":{"name":"胰腺内分泌肿瘤","category":"门诊病历模板","case":{"case_name":"门诊病历731","templates":{"主诉":"上腹隐痛1天","现病史":"患者1周前无明显诱因出现胰腺内分泌肿瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因上腹隐痛1天就诊，现病史提示1周前无明显诱因出现相关症状并逐渐加重，伴轻度乏力，无明显发热及恶心呕吐，为明确腹痛原因、排除感染及贫血所致乏力，门诊即刻完善血常规检查排除感染、贫血；患者上腹隐痛伴消化功能异常，完善便常规+潜血检查了解有无消化道出血及脂肪泻、慢性腹泻所致肠道改变；胰腺内分泌肿瘤多血供丰富且体积较小，常规检查易漏诊，完善腹部超声检查作为初筛，了解胰腺实质回声及有无占位；进一步完善腹部CT检查（建议增强、动脉期薄层扫描）明确肿瘤位置、大小、血供特点及有无肝转移，评估手术切除可能性。患者上腹隐痛需与胰腺炎性病变相鉴别，完善淀粉酶、脂肪酶检查排除急性或慢性胰腺炎所致腹痛。胰腺内分泌肿瘤可分泌多种激素并影响肝脏代谢，且需评估肝功能储备以指导治疗，完善肝功能检查了解转氨酶、胆红素及白蛋白水平。患者存在激素分泌异常所致消化道症状可能，完善幽门螺杆菌检测（C13/C14呼气试验），必要时完善胃镜/肠镜检查排除胃十二指肠溃疡、炎症及其他肿瘤性病变所致腹痛。考虑该病需与胰腺癌及胰腺囊性肿瘤相鉴别，必要时行上腹部MRI及MRCP检查了解胰管及胰周情况，并行生长抑素受体显像等特殊检查以明确肿瘤功能状态。因肿瘤有出血倾向及潜在手术、活检需求，完善凝血功能检查评估凝血状态，为介入或手术提供安全保障。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 胰腺内分泌肿瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 生长抑素类似物（控制功能性肿瘤激素高分泌及类癌综合征症状，首选）：醋酸奥曲肽注射液0.1mg 皮下注射 q8h；症状控制后可换用长效奥曲肽微球20mg 深部肌注 q4w。\n2. 质子泵抑制剂（胃泌素瘤抑酸治疗）：奥美拉唑肠溶胶囊20mg bid，口服，长期维持，据症状及胃酸分泌调整剂量。\n3. 二氮嗪（胰岛素瘤低血糖控制）：二氮嗪片50mg tid，口服起始，据血糖监测调整，最大可至150mg tid。\n4. 进展期或转移性肿瘤靶向治疗（可选用）：依维莫司片10mg qd，口服；或舒尼替尼胶囊37.5mg qd，口服，连续服用4周休2周，注意监测血糖、血常规及肝功能。\n\n【一般治疗及生活指导】\n1. 胰岛素瘤患者随身携带糖果、饼干或含糖饮料，出现心慌、出汗、手抖、乏力等低血糖症状时立即进食含糖食品，避免长时间空腹，必要时两餐间加餐。\n2. 饮食以少食多餐、均衡营养为原则，戒烟限酒，避免暴饮暴食及高脂餐后剧烈活动。\n3. 规律作息，保证充足睡眠，避免过度劳累；每日监测空腹及餐前血糖并记录，复诊时携带血糖记录。\n4. 胃泌素瘤患者如出现反复上腹痛、腹泻、反酸烧心加重或黑便，及时就诊，勿自行停用抑酸药。\n\n【随诊要求】\n1. 每3个月门诊复查血清嗜铬粒蛋白A、胰多肽等肿瘤标志物及血糖、肝肾功能、电解质，功能性肿瘤同时复查相应激素水平（胰岛素、胃泌素等）。\n2. 每6-12个月复查腹部增强CT/MRI或超声内镜，评估原发灶大小及有无肝转移、淋巴结转移。\n3. 使用生长抑素类似物或靶向药物期间，定期监测空腹血糖、甲状腺功能、血常规及肝功能，警惕相关不良反应。\n4. 出现顽固性低血糖、剧烈腹痛、黄疸、消化道出血或短期内体重明显下降等新发症状时，随时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":863,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dcdce867940a46ede7af026f27fb75c05b638aa46b5097a4d1df7da9149ac36f","pinyin":"yixianneifenmizhongliu","initials":"yxnfmzl","setting":"out","caseName":"门诊病历731","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历731",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-fda853bc584263c30bb4","key":"v1-c9ccc21dfe2a3058|templates-fda853bc584263c30bb4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性阑尾炎","category":"门诊病历模板","raw":{"name":"急性阑尾炎","category":"门诊病历模板","case":{"case_name":"门诊病历732","templates":{"主诉":"转移性右下腹痛伴恶心呕吐10小时","现病史":"患者于10小时前开始腹痛，表现如下：典型的转移性右下腹痛，最初为上腹或脐周疼痛，系内脏神经受阑尾扩张牵拉所致，定位模糊，数小时后疼痛转移并固定于右下腹，因炎症波及壁层腹膜，定位明确，压痛点位于麦氏点，为其特征，约70~80%的患者有转移性疼痛史；右下腹呈持续性疼痛，以麦氏点压痛最明显，咳嗽或活动时加重，出现腹膜炎时更为明显；恶心、呕吐，早期为反射性，呕吐1~2次，为胃内容物；食欲减退，早期常见；发热，早期多为低中度，与炎症有关，穿孔后可出现高热（39℃以上），提示腹膜炎或脓肿；腹泻或便秘，多见于盆腔位阑尾，可刺激直肠引起里急后重或腹泻；尿频，多见于盲肠后位或盆腔位阑尾，可刺激输尿管而出现泌尿系症状，有误诊可能。需注意有无穿孔，表现为腹痛突然加剧、弥漫性腹膜炎（全腹痛、腹肌紧张呈板状、发热升高），此为最严重的并发症，儿童及老年人穿孔率高，此点重要；阑尾周围脓肿表现为右下腹包块，系穿孔后包裹所致，发热持续；化脓性门静脉炎罕见，可有寒战、高热及黄疸。还需了解既往有无类似发作史，慢性阑尾炎可表现为反复右下腹痛或亚急性发作；育龄女性需询问月经史，以鉴别异位妊娠、黄体破裂及附件炎，此点重要，应查hCG并行妇科超声，并了解孕周，孕期阑尾炎症状不典型，因子宫增大压痛点外移，穿孔率升高，孕妇出现腹痛时应考虑本病。今日来我院急诊或普外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.1℃，P96次/分，R20次/分，BP118/72mmHg。右下腹麦氏点（脐与髂前上棘连线中外1/3处）压痛阳性，且较局限；反跳痛及肌紧张阳性，穿孔致腹膜炎时右下腹尤为明显；结肠充气试验（Rovsing征）阳性，即按压左下腹引起右下腹痛；腰大肌试验阳性，见于盲肠后位阑尾，伸髋或屈髋内旋时出现右下腹痛；闭孔内肌试验阳性，见于盆腔位阑尾，屈髋内旋时出现疼痛；右下腹可触及包块，提示脓肿，系穿孔后包裹所致；体温升高；育龄女性应行妇科检查及妊娠试验以助鉴别；穿孔致弥漫性腹膜炎时全腹压痛及反跳痛，呈板状腹，肠鸣音消失。","辅助检查":"【必做】血常规（白细胞及中性粒细胞升高，提示炎症，伴核左移）、CRP（升高较敏感，阴性有助于排除诊断，低度疑似而CRP正常者阑尾炎可能性小）、尿常规（排除泌尿系结石及感染，观察有无血尿或白细胞）、妊娠试验（育龄女性必须检查，以排除异位妊娠，此点重要）；【影像】腹部超声（可见阑尾肿大，直径>6mm，不可压缩，可伴粪石及周围积液、炎症脂肪；适用于儿童及孕妇，为首选且无辐射，但正常阑尾可不显示，故阴性不能排除，超声对阑尾炎的敏感性有限；并可发现右下腹脓肿或积液）、腹部CT（为诊断金标准之一，敏感性和特异性均高，可见阑尾增粗、周围脂肪条纹征及脓肿，适用于成人诊断不明、老年及肥胖者，为首选，但有辐射，孕妇慎用）、阑尾炎评分（Alvarado评分，可辅助临床决策）；【其他】诊断困难者可行腹腔镜探查，兼具诊断与治疗作用，属金标准，可同时行阑尾切除；高热或穿孔后疑脓毒症者，必要时行血培养。","初步诊断":"1. 急性阑尾炎（单纯性、化脓性、坏疽性或穿孔，类型待明确；是否伴阑尾周围脓肿待明确；已完成妊娠、妇科及泌尿系相关鉴别）\n（注：治疗方面，诊断明确后行手术切除，为金标准，属急症，以防穿孔：①阑尾切除术：为首选，可行腹腔镜阑尾切除，微创、恢复快、切口小、术后疼痛轻，为近年标准术式；亦可开腹手术，适用于穿孔致弥漫性腹膜炎或经济条件受限者；术前需禁食，并予抗生素预防，如头孢类加甲硝唑，于术前30分钟给药，以防切口感染，此点重要；诊断明确后应尽快手术，在穿孔前进行，儿童、老年人及孕妇穿孔风险高，不可拖延。②保守治疗：适用于单纯性早期、无穿孔且经影像确认者，予抗生素，如阿莫西林克拉维酸或头孢类加甲硝唑，疗程为静脉用药2~3天后改口服，总疗程5~7天，并观察病情；但复发率高，1年内约30%，多数最终仍需手术，现已少用，仅限手术禁忌或麻醉高风险者，多数仍建议手术，此点重要。③阑尾周围脓肿：因穿孔后包裹所致，先予保守治疗，即抗生素加超声或CT引导下穿刺引流，待脓肿消退后6~8周择期行阑尾切除，即间期阑尾切除，以防复发，此点重要。④穿孔致腹膜炎：行急诊手术，予冲洗引流，并延长抗生素疗程，疑脓毒症者行血培养，严重者收治ICU。⑤并发症处理：切口感染多见于穿孔后，应换药引流；腹腔脓肿表现为术后持续发热，可经超声或CT引导穿刺引流；肠梗阻多因粘连所致，术后可发生，以保守治疗为主。⑥随访：术后恢复一般需1~2周，腹腔镜手术恢复较快；监测切口有无感染；阑尾标本应送病理，以确认诊断，并排除罕见的阑尾肿瘤，如类癌或腺癌，病理检查重要。急诊与普外科应重视转移性右下腹痛这一典型表现，经影像确认后及时手术，于穿孔前干预，以减少并发症。","处理方案":"【药物治疗】\n1. 抗感染治疗（首选方案，适用于症状轻、同意保守治疗的门诊患者）：左氧氟沙星片0.5g qd口服＋甲硝唑片0.4g tid口服，疗程5～7天；或阿莫西林克拉维酸钾片0.625g bid口服＋甲硝唑片0.4g tid口服，疗程5～7天，以覆盖大肠埃希菌等肠道需氧菌及脆弱拟杆菌等厌氧菌。\n2. 解痉对症：右下腹痛明显者予山莨菪碱片10mg tid口服解痉止痛；恶心、呕吐明显者予甲氧氯普胺片5mg tid口服（连用不超过5天）；体温≥38.5℃时可临时加用对乙酰氨基酚片0.5g口服（间隔≥6小时）。禁用吗啡、哌替啶等强效镇痛药，以免掩盖病情延误手术。\n3. 用药期间若腹痛进行性加重、出现高热寒战或腹膜炎体征，须立即停用口服抗生素并转急诊外科评估手术，不可继续居家用药；明确诊断的急性阑尾炎首选治疗为急诊阑尾切除术，保守治疗仅适用于轻型单纯性阑尾炎且患者知情同意拒绝手术者。\n\n【一般治疗及生活指导】\n1. 休息：急性期绝对卧床休息，以屈膝半卧位为佳，减少活动及腹压增高的动作（用力排便、剧烈咳嗽、搬重物），防止炎症扩散。\n2. 饮食：腹痛明显时暂禁食或仅进少量流质（米汤、藕粉），症状缓解后逐步过渡至半流质、软食；1周内忌油腻、生冷、辛辣及产气食物（豆制品、碳酸饮料），避免暴饮暴食。\n3. 观察与就医：每日监测体温及右下腹疼痛变化，若疼痛转移、加剧或伴寒战、频繁呕吐、腹胀，提示病情进展，须立即急诊就医。\n\n【随诊要求】\n1. 用药48～72小时复诊，复查血常规、C反应蛋白并评估腹痛及体温变化；症状缓解者按疗程完成抗生素治疗后1周内复查血常规，评估炎症消退情况。\n2. 治疗期间或停药后腹痛复发、发热不退者随时复诊；保守治疗治愈者建议1～3个月内行阑尾超声或CT复查，排除阑尾脓肿、阑尾周围炎及慢性阑尾炎，并与普外科会诊评估是否择期行阑尾切除术以预防复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":864,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f2b0ec1a1cd46584524579f8d41115acf0324d62fae83f0146cfabb9b27ec773","pinyin":"jixinglanweiyan","initials":"jxlwy","setting":"out","caseName":"门诊病历732","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历732",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f41472abc978c043811d","key":"v1-c9ccc21dfe2a3058|templates-f41472abc978c043811d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性阑尾炎","category":"门诊病历模板","raw":{"name":"慢性阑尾炎","category":"门诊病历模板","case":{"case_name":"门诊病历733","templates":{"主诉":"右下腹隐痛1天","现病史":"患者1周前无明显诱因出现慢性阑尾炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因右下腹隐痛1天就诊，现病史提示1周前无明显诱因出现相关症状并逐渐加重，伴轻度乏力，无明显发热及恶心呕吐，为明确有无阑尾急性化脓性感染及贫血所致乏力，急诊完成血常规检查排除感染、贫血；患者右下腹痛需与右侧输尿管结石、妇科疾病及肠道肿瘤相鉴别，完善超声检查了解阑尾区有无肿大、粪石、周围积液及腹腔淋巴结情况，并了解泌尿系与盆腔器官形态。慢性阑尾炎反复发作可致阑尾周围粘连及穿孔风险，完善腹部CT检查明确阑尾形态、位置、壁厚及与周围组织关系，评估有无脓肿、粪石及穿孔；若CT征象不典型、需与其他右下腹占位相鉴别，必要时完善腹部MRI检查明确病变性质。患者右下腹痛需排除肠结核、炎症性肠病及其他消化道病变，完善X线片检查了解有无肠梗阻、气液平面等表现。患者若考虑手术治疗，需评估麻醉与手术耐受性，完善心电图检查排除心律失常及心肌缺血，完善胸部X线片检查排除肺部感染及结核；完善肝肾功能、电解质、血糖检查了解重要脏器功能及有无水电解质紊乱、糖代谢异常，为术前评估及补液纠治提供依据；完善凝血功能检查评估凝血状态，避免术中术后出血风险；完善血型检查为术中备血输血做好准备。患者右下腹痛不能完全除外结肠肿瘤及泌尿系肿瘤，必要时完善肿瘤标志物检查以助鉴别诊断。\n\n（检查清单）\n【必做检查】\n血常规、凝血功能、肝肾功能、电解质、血糖、血型\n\n【影像学检查】\nX线片、CT、MRI、超声\n\n【其他检查】\n心电图、胸部X线片、肿瘤标志物（必要时）","初步诊断":"1. 慢性阑尾炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗菌药物（急性发作期抗感染）：头孢克肟胶囊 0.1g bid po ×5天；或阿莫西林克拉维酸钾片 0.457g tid po ×5天，同时联合甲硝唑片 0.4g tid po ×5天（覆盖厌氧菌），餐后服用。\n2. 解痉止痛：匹维溴铵片 50mg tid po，餐前服用，缓解右下腹痉挛性疼痛；疼痛明显时亦可选用山莨菪碱片 5-10mg tid po。\n3. 调节肠道菌群：双歧杆菌三联活菌胶囊 0.42g tid po ×7天，与抗菌药物间隔2小时以上服用，减少抗生素相关性腹泻。\n【一般治疗及生活指导】\n1. 急性发作期注意休息，避免剧烈运动、腹部挤压及负重，防止诱发或加重腹痛。\n2. 清淡易消化饮食，少食多餐，忌生冷、油腻、辛辣刺激食物及暴饮暴食，避免进食后立即活动。\n3. 保持大便通畅，多饮水、适量进食富含膳食纤维食物，防治便秘，避免用力排便。\n4. 慢性阑尾炎反复发作易致阑尾粘连、形成粪石，确诊后建议择期行腹腔镜阑尾切除术以根治，去除潜在急性发作及穿孔风险。\n【随诊要求】\n1. 药物治疗后2周复诊，评估腹痛缓解情况及药物耐受性；症状未缓解或右下腹痛反复发作时及时复诊。\n2. 若出现转移性右下腹痛、持续加重疼痛、发热、恶心呕吐、腹肌紧张等，立即急诊就诊，排除急性阑尾炎或穿孔。\n3. 暂未手术者建议每3-6个月行腹部超声随访，监测阑尾及周围情况；拟行手术者按普外科门诊预约，完善血常规、凝血、腹部超声等术前评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":865,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"dd562f2602744283bc330e1e886f267ec3bfae156763ae33df811d6b867773d2","pinyin":"manxinglanweiyan","initials":"mxlwy","setting":"out","caseName":"门诊病历733","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历733",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e995e468fa516164a1fb","key":"v1-c9ccc21dfe2a3058|templates-e995e468fa516164a1fb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肠扭转","category":"门诊病历模板","raw":{"name":"肠扭转","category":"门诊病历模板","case":{"case_name":"门诊病历734","templates":{"主诉":"突发腹部绞痛伴腹胀、呕吐8小时","现病史":"患者存在以下发病基础（乙状结肠扭转多见于老年人，常伴慢性便秘及乙状结肠冗长，为最常见的类型，我国以老年男性多见；小肠扭转多见于儿童及青壮年，与肠系膜过长、旋转不良或手术后粘连有关，可因餐后剧烈运动或体位突变诱发；盲肠扭转少见）。患者于8小时前（多于饱餐后、剧烈活动、体位改变或用力排便后发病，乙状结肠扭转尤为典型）突发以下表现：剧烈腹部绞痛，位于脐周或下腹，呈持续性剧痛并阵发性加剧，因肠绞窄所致，难以忍受；进行性腹胀，乙状结肠扭转时腹部高度膨隆，且不对称，可见局部隆起；停止排气排便，提示完全性肠梗阻；呕吐，小肠扭转者呕吐频繁且出现较早，乙状结肠扭转者出现较晚，可呕吐粪样物；伴恶心。随肠绞窄进展，可出现腹痛持续加剧、腹膜炎体征（压痛、反跳痛及肌紧张）、血性腹水及休克，系肠坏死穿孔致全身中毒所致，表现为发热、心率增快、血压下降，属急症，延误可致死，绞窄性肠梗阻死亡率高。还需了解既往有无慢性便秘史（乙状结肠冗长的基础）、腹部手术史（粘连可成为扭转的基础）以及发病诱因，如发病前餐后运动或体位改变。今日来我院急诊或普外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.9℃，P108次/分，脉搏增快，R22次/分，BP96/60mmHg，血压降低，晚期提示休克。神志清楚、烦躁或淡漠，出现淡漠提示休克；腹部高度膨隆，乙状结肠扭转时呈不对称性，可见局部巨大隆起；早期压痛较轻，晚期呈弥漫性压痛，伴反跳痛及肌紧张，提示绞窄穿孔；叩诊呈鼓音，提示肠管气胀；移动性浊音阳性，提示血性腹水，多见于晚期；肠鸣音早期亢进，可闻及气过水声及金属音，随绞窄进展转为减弱或消失，提示麻痹性肠梗阻；直肠指诊可见直肠空虚，为乙状结肠扭转的特征性表现，即壶腹空虚，指套可染血，提示肠坏死。","辅助检查":"【必做】腹部立位X线平片（可见肠梗阻所致气液平；乙状结肠扭转的特征为巨大扩张的乙状结肠袢，呈马蹄形，即咖啡豆征，可见双袢肠管；小肠扭转可见阶梯状气液平）、血常规（白细胞升高，绞窄时伴核左移）、CRP、电解质（呕吐及肠梗阻可致电解质紊乱）、血气分析及乳酸（绞窄或肠坏死时出现代谢性酸中毒及乳酸升高，此点重要，为缺血指标）、肝肾功能、血型及交叉配血（为手术做准备）；【影像】腹部CT（为首选确诊手段，敏感性高，可见肠系膜血管扭转即漩涡征，为肠系膜血管呈漩涡状排列的特征性表现；肠壁增厚或肠壁积气，提示坏死，属急症；并可发现腹水及肠系膜水肿，有助于与其他肠梗阻鉴别，并评估绞窄程度，CT增强检查重要，属急诊检查）、肠系膜血管成像（CTA，用于评估血供）；【其他】诊断已明确为绞窄者，可直接手术，不必过度进行影像检查，因时间窗重要。","初步诊断":"1. 肠扭转（乙状结肠扭转、小肠扭转或盲肠扭转，类型待明确；合并绞窄性肠梗阻；需评估有无坏死及穿孔，属急症）\n（注：肠扭转属绞窄性肠梗阻，肠坏死的时间窗很短，数小时内血供中断即可导致坏死、穿孔及休克，甚至致死，急诊处理核心如下：①紧急评估及复苏：疑为肠扭转者按急症处理，禁食并予胃肠减压；补液，肠梗阻时体液丢失明显，需积极补充并纠正电解质紊乱；抗感染，予广谱抗生素覆盖肠源性菌群，如哌拉西林他唑巴坦或头孢类加甲硝唑；监测生命体征、乳酸及尿量，以评估绞窄程度；备血，为手术做准备。②乙状结肠扭转：可行内镜复位，经乙状结肠镜或结肠镜直视下通过扭转处，排气减压并复位，复位成功可见排气、腹胀缓解及肛门排气，随后留置肛管减压以防早期复发；但复位后仍需择期手术，行乙状结肠切除以防复发，因复发率高，可达40%以上，尤其未处理病因者；复位失败或疑有坏死者，如出现血便、腹膜炎或CT示坏死征象，应行急诊手术。③手术：适应证包括小肠扭转（无法内镜复位，需急诊手术）、乙状结肠复位失败或坏死、穿孔、盲肠扭转（需手术）以及出现绞窄征象者（CT示坏死、腹膜炎、乳酸升高或血便，应立即手术，不可尝试内镜，以免延误导致坏死）；手术方式为开腹或腹腔镜探查，扭转复位，无坏死者复位后固定，乙状结肠扭转复位后需评估肠管活力；肠坏死者行肠切除，乙状结肠坏死可行Hartmann手术，即切除加结肠造口，二期吻合，适用于污染重或病情不稳定者，条件好且污染轻者可一期吻合；小肠坏死者行肠切除吻合，大范围坏死有短肠综合征风险，需评估。④术后管理：收治ICU或加强监护，绞窄坏死术后注意脓毒症，予液体复苏及抗感染；营养方面，术后早期予肠外营养，逐步恢复肠内营养；并发症包括吻合口漏，坏死切除吻合后需观察，可留置腹腔引流；广泛小肠切除可致短肠综合征，需营养支持，参见短肠综合征相关内容。⑤随访：术后观察恢复情况；造口者可行二期还纳，一般于3~6个月后进行；处理病因，如慢性便秘为乙状结肠扭转的基础，应予通便及纤维饮食以防复发；术后注意预防粘连所致再次扭转，并适当活动。急诊与普外科应分秒必争，肠扭转存在绞窄时间窗，出现乳酸升高或腹膜炎时应立即手术，不可延误）。","处理方案":"【药物治疗】\n1. 解痉止痛：山莨菪碱片（654-2）5mg po tid（腹痛明显时可临时10mg），症状缓解后停用；青光眼、前列腺肥大、肠麻痹者禁用。\n2. 通便治疗（乙状结肠扭转内镜复位成功后）：乳果糖口服溶液15ml po bid，或聚乙二醇4000散10g po bid，连用至排便规律后渐减。\n3. 肠道微生态调节：双歧杆菌三联活菌胶囊420mg po tid，连用7-14天，与抗菌药物间隔2小时服用。\n4. 抗感染（有发热、腹胀压痛明显或复位后预防感染时）：头孢呋辛酯片0.25g po bid＋甲硝唑片0.4g po tid，共5天；青霉素过敏者改用左氧氟沙星片0.5g po qd×5天。\n【一般治疗及生活指导】\n1. 急性期卧床休息、暂禁食水，必要时静脉补液维持水电解质平衡；待肛门排气、排便恢复后再逐步进食，避免饱餐及餐后立即剧烈活动。\n2. 饮食从流质（米汤、藕粉、清汤）→半流质（粥、烂面条）→软食过渡，少量多餐；忌暴饮暴食及产气食物（豆类、红薯、碳酸饮料、牛奶等），忌辛辣油腻、粗糙高纤维食物，逐步增加膳食纤维。\n3. 保持大便通畅：每日饮水1500-2000ml，养成定时排便习惯，避免用力屏气排便；便秘者按医嘱规律服用通便药，切勿滥用泻药。\n4. 复位后1周内避免剧烈运动、弯腰负重及长时间站立；肠扭转为急腹症，严禁自行服用止痛药掩盖病情，出现腹痛复发或加重应立即就医。\n【随诊要求】\n1. 复位或保守治疗成功后24-48小时门诊复诊，复查立位腹部平片或腹部CT，评估肠管复位及血运恢复情况。\n2. 症状缓解后1周内复诊，评估进食恢复及排便情况；病情平稳后建议1-3个月门诊随访一次。\n3. 随诊期间若出现剧烈腹痛、呕吐、腹胀进行性加重、停止排气排便或便血，立即禁食并急诊就医，必要时转外科手术治疗。\n4. 反复发作（≥2次）的乙状结肠扭转，或影像学提示肠壁缺血、坏死征象者，建议转普外科住院行乙状结肠切除或固定术等确定性治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":866,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e511a8fc47819c5a8e81da1940dfe2e106ea19180bee12f6dacb10c26b72ac8e","pinyin":"changniuzhuan","initials":"cnz","setting":"out","caseName":"门诊病历734","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历734",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c49e2bd1e8834f1c3240","key":"v1-c9ccc21dfe2a3058|templates-c49e2bd1e8834f1c3240","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肠套叠","category":"门诊病历模板","raw":{"name":"肠套叠","category":"门诊病历模板","case":{"case_name":"门诊病历735","templates":{"主诉":"阵发性哭闹伴呕吐、果酱样便6小时","现病史":"患儿处于好发年龄6个月~2岁（为婴儿最常见的急腹症，2岁以下者占80%）。病因方面：特发性者占大多数，多发生于病毒感染后，因回肠末端淋巴组织增生（Peyer结）成为肠套叠的诱发点，病毒感染或疫苗接种后常见；器质性者多见于2岁以上儿童，套叠点可为麦克尔憩室、息肉、肿瘤或肠重复畸形，需注意寻找，年长儿器质性病因比例较高；成人肠套叠少见，多为器质性，如肿瘤或息肉所致，为手术指征。患儿于6小时前突发阵发性哭闹，程度剧烈，双腿蜷曲，面色苍白，呈阵发性发作，每次持续数分钟，间歇期安静如常，可玩耍，随后再次发作，反复出现，此为婴幼儿腹痛及阵发哭闹的特征；呕吐，早期为胃内容物，之后可为胆汁样，提示肠梗阻；于2小时前排果酱样便，为血便，呈暗红果酱样，系肠黏膜出血坏死所致，多见于套叠晚期，为诊断的重要线索，但并非必有，早期可无血便或仅隐血阳性；腹部可触及腊肠样包块，多位于右上腹，系套叠肠管所致，右下腹可有空虚感，为回盲部套叠的特征，即Dance征。还需了解有无精神萎靡、嗜睡，提示晚期休克或肠坏死，属急症；有无发热，肠坏死或穿孔后可出现高热及腹膜炎；有无腹膨隆，提示晚期肠梗阻。若延误诊治，可致肠坏死、穿孔，危及生命。今日来我院急诊或小儿外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.5℃，P132次/分，R28次/分，BP86/54mmHg。神志方面可为阵发哭闹、间歇期安静或萎靡嗜睡，后者提示晚期；腹部于右上腹或中腹可触及腊肠样包块，质软，轻压痛，可活动，为早期套叠包块；右下腹空虚感，即Dance征，多见于回盲型套叠；腹胀，见于晚期肠梗阻；压痛、反跳痛及肌紧张，提示穿孔，属晚期；肠鸣音早期亢进，呈阵发性，与肠痉挛有关，肠坏死时转为减弱或消失；肛诊可见指套染血，提示果酱样便，对早期识别重要，无肉眼血便者亦应行肛诊，以查隐血或血性黏液。","辅助检查":"【必做】腹部超声（为首选，属诊断金标准之一，无创且快速，横断面可见靶环征或同心圆征，纵断面可见套筒征或假肾征，为典型超声表现，是确诊的核心，同时可评估肠壁水肿及血流情况，彩色多普勒示血流减少提示缺血，为坏死的预警指标）；【影像】空气或钡剂灌肠（兼具诊断与治疗作用，在X线监视下行空气灌肠，通过压力复位，可同时确认诊断并完成治疗，复位成功表现为套叠退回、空气进入小肠、压力下降、患儿安静、排气排便，符合复位标准，参见治疗部分）；【其他】腹部X线平片（可见肠梗阻所致气液平，穿孔时可见膈下游离气，现已少用，多用于出现并发症时）、血常规（白细胞升高，提示炎症或坏死）、电解质（呕吐可致电解质紊乱）、血气分析（晚期脱水或休克时可出现异常）。","初步诊断":"1. 肠套叠（婴幼儿特发性或器质性，年长儿及成人需查找套叠点；部位以回结型最常见，回盲型次之；发病已6小时，需评估有无穿孔及坏死）\n（注：治疗方面，婴幼儿肠套叠早期行空气灌肠复位，为首选的非手术治疗，成功率80~90%，时间窗重要：①空气灌肠复位：适应证为发病24~48小时内、无穿孔及腹膜炎表现、一般情况可者；在X线监视下经气囊肛管注气，压力80~120mmHg，使套叠退回；复位成功的标志为气体进入小肠、包块消失、患儿安静入睡、排气排便，果酱样便后转为正常；复位后需住院观察24小时，注意复发，复发率约5~10%，再套叠者可再次灌肠，可重复2~3次，反复复发者应查找器质性病因；禁忌证包括穿孔，如腹膜炎或气腹，禁行灌肠；发病时间过长，超过48小时者肠坏死风险高，灌肠失败率高，应改行手术。②手术治疗：适用于灌肠失败、有禁忌、穿孔、肠坏死或存在器质性套叠点者；手术方式包括手法复位，无坏死者轻轻挤退，不可牵拉；肠切除，坏死者行切除吻合；器质性套叠点者，年长儿及成人应切除套叠点，如肿瘤、息肉或麦克尔憩室，以防再发，并同时送病理。③支持治疗：补液，予禁食并纠正脱水及电解质紊乱；抗生素，复位后或手术者患者，以防感染，因肠屏障受损；监测复位后的生命体征、腹部情况、肠鸣音及大便。④随访：复位后观察排气排便情况，并从流质开始逐步恢复饮食，一般需24~48小时；监测复发，早期指出院后1~2周内再次出现哭闹、腹痛时应及时就诊；成人患者应关注病理结果，确认器质性病因。小儿外科与急诊应重视早期识别，阵发哭闹加果酱样便加腹部包块构成三联征，超声可确诊，发病24小时内行空气灌肠成功率较高，延误可致肠坏死，需手术甚至危及生命，时间窗是关键）。","处理方案":"【药物治疗】\n1.解痉镇痛：山莨菪碱片（654-2）10mg po tid×3~5天，餐后服用，缓解肠痉挛性阵发腹痛；若用药后腹痛持续不缓解或加重，须立即停药并急诊就医，不可自行加量或延长疗程。\n2.抗感染：头孢呋辛酯片0.25g po bid×5天，防治肠壁缺血水肿后继发感染及肠道菌群移位；对头孢菌素类过敏者改用左氧氟沙星片0.5g po qd×5天（注意光敏反应及避免与含铝、镁制剂同服）。\n3.维持水电解质平衡：口服补液盐Ⅲ（博叶）1袋溶于250ml温水中，少量多次分次服用，每日1~2袋；呕吐、腹泻明显者按需增加，尿量减少或口渴明显时及时就医静脉补液。\n【一般治疗及生活指导】\n1.休息：急性期卧床休息，避免剧烈活动、用力排便及腹部受压，减少肠蠕动刺激，防止套叠加重或复发。\n2.饮食：腹痛明显时暂禁食6~12小时或仅进流质（米汤、藕粉），症状缓解后逐渐过渡为少渣半流质→软食，少量多餐；忌油腻、辛辣刺激、生冷及粗纤维食物（韭菜、芹菜、竹笋），忌产气食物（豆类、碳酸饮料、红薯、牛奶），多饮水。\n3.禁忌：严禁腹部按摩、热敷及自行灌肠、服用泻药，以免加重套叠或诱发肠穿孔；密切观察大便性状，一旦出现果酱样血便、频繁呕吐、腹胀进行性加重或发热，立即急诊就诊，不可延误。\n【随诊要求】\n1.经空气或钡剂灌肠复位成功者，24小时内返院复查（首选床旁超声）确认复位效果，观察套叠有无复发。\n2.3~5天后门诊复诊评估腹痛缓解及肠功能恢复情况；成人肠套叠多继发于息肉、肿瘤等器质性病变，症状缓解后建议行全结肠镜检查及腹部CT小肠成像（CTE）寻找并处理病因。\n3.随访期间若再现剧烈阵发腹痛、呕吐、血便或出现腹膜炎体征，随时急诊就诊，必要时外科手术探查；合并肠缺血坏死、术后患者遵医嘱定期复查血常规、CRP及腹部影像学。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":867,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5c3bd75cecbecc62d54329fd9aacc89fd74b62afcd08ab6d0f8453519204e03e","pinyin":"changtaodie","initials":"ctd","setting":"out","caseName":"门诊病历735","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历735",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2fd578285dedef9e4bc4","key":"v1-c9ccc21dfe2a3058|templates-2fd578285dedef9e4bc4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹外疝","category":"门诊病历模板","raw":{"name":"腹外疝","category":"门诊病历模板","case":{"case_name":"门诊病历736","templates":{"主诉":"腹部包块1天","现病史":"患者1周前无明显诱因出现腹外疝相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因腹部包块1天就诊，现病史提示1周前无明显诱因出现相关症状并逐渐加重，伴轻度乏力，无明显发热及恶心呕吐，为明确有无嵌顿疝继发感染、肠管缺血及贫血所致乏力，急诊完成血常规检查排除感染、贫血；腹外疝需与腹壁脂肪瘤、腹壁子宫内膜异位症及腹腔内占位相鉴别，完善超声检查明确疝囊位置、大小、疝内容物性质及疝环口径，并评估腹壁各层结构。为明确疝与腹壁缺损的解剖关系、有无嵌顿及肠管血运障碍，完善腹部CT检查评估疝内容物、疝颈宽窄及有无肠梗阻征象；若需进一步鉴别腹壁软组织病变性质，必要时完善MRI检查明确病变范围及与腹壁肌肉筋膜的关系。若患者存在腹痛、腹胀、呕吐等肠梗阻表现，完善X线片检查了解有无肠管扩张、气液平面及膈下游离气体。患者若拟行疝修补术，需评估手术与麻醉耐受性，完善心电图检查排除心律失常及心肌缺血，完善胸部X线片检查排除肺部感染、结核及膈疝可能；完善肝肾功能、电解质、血糖检查了解重要脏器功能及有无水电解质紊乱与糖代谢异常，为术前准备提供依据；完善凝血功能检查评估凝血状态，降低术中术后出血风险；完善血型检查为术中备血输血做好准备。患者腹部包块需排除腹腔肿瘤性病变所致腹压增高，必要时完善肿瘤标志物检查协助鉴别诊断。\n\n（检查清单）\n【必做检查】\n血常规、凝血功能、肝肾功能、电解质、血糖、血型\n\n【影像学检查】\nX线片、CT、MRI、超声\n\n【其他检查】\n心电图、胸部X线片、肿瘤标志物（必要时）","初步诊断":"1. 腹外疝\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 缓泻剂（防治便秘、降低腹内压）：乳果糖口服溶液15ml，晨起顿服，每日1次，连用1～2周，排便通畅后减为10ml每日1次维持；或聚乙二醇4000散10g，每日2次，温水溶解后口服，便软后减为每日1次。\n2. 合并前列腺增生、排尿困难者（男性腹外疝常见诱因）：坦索罗辛缓释胶囊0.4mg，每晚1次，口服，疗程2～4周，改善排尿以减轻腹压增高。\n3. 疝区坠胀、疼痛明显时短期对症：布洛芬缓释胶囊0.3g，每日2次，餐后口服，疼痛缓解即停用，总疗程不超过3～5天；消化性溃疡活动期、严重肝肾功能不全者禁用。\n\n【一般治疗及生活指导】\n1. 避免一切增加腹内压的因素：防治便秘、慢性咳嗽，避免重体力劳动、提举重物、剧烈运动及久站久坐；咳嗽、打喷嚏时用手掌按压疝区。\n2. 饮食：多饮水，多食富含膳食纤维食物（新鲜蔬菜、水果、粗粮），少食产气食物（豆类、碳酸饮料），控制体重，戒烟限酒。\n3. 活动与休息：可从事日常轻度活动，但避免屏气用力动作；手法复位嵌顿疝后卧床休息24～48小时，密切观察有无腹痛、腹胀、发热及腹膜炎征象。\n4. 暂不宜手术者患者戴疝带，先将疝内容物完全还纳再以疝带压住疝环，夜间睡眠时取下，注意局部皮肤保护，防止压疮。\n\n【随诊要求】\n1. 确诊后应尽快至普外科疝专科门诊就诊，完善术前评估，限期择期手术；嵌顿或绞窄疝须急诊手术。\n2. 保守观察者每3～6个月门诊复查1次，评估疝块大小、症状变化及有无嵌顿风险；术后按医嘱于术后1个月、3个月复查，观察切口愈合及有无复发。\n3. 若疝块突然增大、变硬、疼痛加剧、不能回纳，或伴恶心呕吐、腹痛腹胀、停止排气排便、发热等表现，提示嵌顿或绞窄可能，须立即急诊就诊，切勿自行强行复位延误病情。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":868,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3c75770647c8a0b3e88b0eac45a4bac55a34f50bab0c8f25bf659ec1582c5292","pinyin":"fuwaishan","initials":"fws","setting":"out","caseName":"门诊病历736","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历736",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a3157c4478d531ac67c1","key":"v1-c9ccc21dfe2a3058|templates-a3157c4478d531ac67c1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"腹股沟疝","category":"门诊病历模板","raw":{"name":"腹股沟疝","category":"门诊病历模板","case":{"case_name":"门诊病历737","templates":{"主诉":"可复性包块2年","现病史":"患者为老年男性，腹股沟疝以男性多见，男女比例约为15:1；右侧多于左侧，此点以斜疝最为典型。本病可发生于各年龄段：婴幼儿多为先天性鞘状突未闭所致斜疝；成人多为后天性腹壁薄弱所致；老年人以直疝多见，与腹壁肌肉薄弱有关。常见腹压增高因素包括：慢性咳嗽（如慢阻肺）、便秘（长期用力排便）、前列腺增生所致排尿困难（老年男性用力排尿为重要诱因）、重体力劳动、肥胖、妊娠及腹水等，另有家族疝史者亦不少见。患者于3年前在渐进用力或突发用力（如搬重物、用力后）时发现右侧腹股沟区包块，现病史如下：腹股沟区包块于站立、咳嗽、用力（即增加腹压）时出现，并可突出于腹股沟区或降入阴囊（斜疝可降入阴囊，直疝一般不入阴囊，借此可资鉴别），平卧或用手推送后可还纳，属可复性，还纳后包块消失。还纳后行咳嗽冲击感试验：手指压迫内环口后嘱患者咳嗽，斜疝可阻止疝块突出，直疝则不能，此为二者鉴别要点之一。患者疝出时有胀痛及坠胀不适，久站或劳累后加重。若疝内容物不能还纳，可突然出现剧痛，包块变硬、压痛明显，即为嵌顿；嵌顿后可出现肠梗阻表现，如恶心、呕吐、停止排气排便，属嵌顿疝急症；若嵌顿进一步导致肠管血供中断、坏死，即为绞窄，可出现发热及腹膜炎表现，属急症，手术时机极为重要，嵌顿与绞窄均可危及生命，需急诊手术。疝内容物多为肠管（其中小肠最多见）或大网膜，还纳时可有咕噜声，为肠管气过水声；女性患者若嵌顿内容物为卵巢或输卵管，则更为危险。本病分型包括：斜疝，经腹股沟管、内环至外环，可降入阴囊，多见于儿童及青年，可为先天性或后天性；直疝，经直疝三角（海氏三角）突出，一般不降入阴囊，多见于老年腹壁肌肉薄弱者，基底宽、易还纳；股疝，位于腹股沟韧带下方卵圆窝处，多见于女性，嵌顿率高，属急症，须高度重视。今日来我院普外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.6℃，P 84次/分，R 18次/分，BP 142/86mmHg。站立位检查：嘱患者站立并咳嗽、用力，观察腹股沟区包块出现及其位置，位于腹股沟区、内环上方者提示斜疝，位于直疝三角者提示直疝；同时评估包块大小及还纳情况。仰卧后以手法还纳，包块可复位；行指压内环试验，嘱患者咳嗽，若包块仍突出则为直疝，若可阻止包块突出则为斜疝，此试验用于二者鉴别，为重要鉴别手段。包块透光试验阴性：阴性者为疝，阳性者为鞘膜积液，可用于鉴别。触诊阴囊，了解疝内容物是否降入。检查有无嵌顿征象：包块紧张、压痛、不可还纳，皮肤红肿者属急症，须及时处理。咳嗽冲击感检查：还纳后以指尖压于内环处嘱患者咳嗽，斜疝可有冲动感，此为斜疝的体征特点。同时检查对侧有无疝；对女性患者检查腹股沟韧带下方卵圆窝处，以除外股疝。检查腹部，注意有无嵌顿所致肠梗阻表现，如腹胀。全身检查注意有无腹压增高因素，如咳嗽、前列腺增生等。","辅助检查":"【必做】以临床检查为主，典型者站立咳嗽时可见包块即可诊断。【影像】超声检查腹股沟区，明确疝及其内容物（肠管或大网膜），并与鞘膜积液、隐睾、淋巴结肿大等相鉴别；诊断不明者、女性、肥胖及小儿患者尤为重要，可作为首选；同时可行 Valsalva 动态观察。【其他】腹部X线或CT检查，用于嵌顿或绞窄者，可显示肠梗阻（气液平）或内容物坏死，CT有助于评估、疑有绞窄者应行此项检查；疝气特殊检查用于难复性疝或滑动疝的鉴别。","初步诊断":"1. 腹股沟疝（右侧：斜疝，可降入阴囊，属可复性，平卧或手法推送后可还纳；尚需与直疝、股疝相鉴别，并评估有无嵌顿、绞窄及诱发因素（慢性咳嗽、便秘、前列腺增生）；若发生绞窄坏死可危及生命，须及早识别与处理）。\n（注：治疗以手术根治为主，嵌顿者需急诊处理，此点极为重要）：①可复性疝：可行择期手术，手术为根治的唯一有效手段，成人患者均应手术，以防嵌顿、绞窄等并发症，且并发症风险随时间延长而增加，此点重要。手术方式包括：开放手术，即疝修补术，传统张力修补以 Bassini 法为代表，复发率高，现已少用；无张力修补术，使用补片即聚丙烯网片，以加强腹股沟管后壁，复发率低（<1%~3%），为开放手术的标准术式；腹腔镜疝修补术，包括经腹腹膜前修补与全腹膜外修补，属微创方式，对双侧疝可同时处理，具有优势，亦适用于复发疝，术后恢复快，可酌情选择。小儿患者行疝囊高位结扎术，仅结扎鞘状突，不需放置补片，因儿童腹壁仍在发育，此种修复方式简单而有效。②嵌顿疝：属急症，嵌顿时间过长可致绞窄、坏死，须急诊手术，此点重要。早期嵌顿者，若嵌顿时间短（<3~4小时）、无绞窄征象（无剧痛、红肿、发热、腹膜炎表现），可试行手法还纳，采用头低脚高位、适当镇静、动作轻柔，复位成功后须观察有无腹膜炎（观察24小时）；但复位后仍应择期手术，以防复发，此点重要；若手法复位失败或疑有绞窄，则行急诊手术。绞窄者属急症，须急诊手术，打开疝囊后检查肠管活力，肠管坏死者予以切除（肠切除加吻合），还纳后行修补；因存在感染、污染，疝修补时放置补片属禁忌，感染情况下只用组织修补，或暂不修补，留待二期处理，此点重要。③保守治疗：仅适用于不适合手术者，如高龄、严重基础病、存在手术禁忌者，此类患者可使用疝带压迫内环，以防止疝块突出，但不能根治，且仍有嵌顿风险，应评估后使用，属姑息性措施；多数患者仍应全面评估并争取手术治疗。④诱发因素处理：应积极治疗慢性咳嗽（控制慢阻肺）、便秘（通便）、前列腺增生（改善排尿），以防术后复发，此点重要。⑤随访：术后恢复方面，1~2周可从事轻体力活动，重体力活动需4~6周；无张力修补术后复发率低，若复发则需再次手术评估；阴囊血肿或鞘膜积液为术后常见情况，多可自行吸收，可予观察，积液量大者可行穿刺抽液；慢性疼痛少见，多与补片或神经有关，需相应处理；感染少见，但补片感染后果严重，处理较为困难，须重视。本病属普外科常见疾病范畴，成人以无张力修补术为主要术式，嵌顿者行急诊手术以防肠坏死，并重视诱发因素的治疗与术后随访，此点重要。","处理方案":"【药物治疗】\n1. 聚乙二醇4000散10g po qd，或乳果糖口服溶液15ml po qd，连用3-5天，软化大便、保持排便通畅，避免用力排便致腹压骤增诱发或加重疝。\n2. 坦索罗辛缓释胶囊0.4mg po qd（男性合并前列腺增生排尿费力者），改善排尿、减少腹压增高，用药期间注意体位性低血压。\n3. 氢溴酸右美沙芬片15mg po tid（伴咳嗽者），镇咳减少腹压骤增；咳嗽超过2周且伴痰血者需进一步排查。\n4. 本病根治手段为外科手术，药物仅用于控制加重因素及围手术期对症处理，不建议长期依赖药物治疗。\n\n【一般治疗及生活指导】\n1. 避免重体力劳动及提举重物、剧烈咳嗽、用力排便等一切增加腹压的动作；咳嗽、便秘、前列腺增生所致排尿困难等原发因素应积极治疗。\n2. 戒烟、控制体重、清淡饮食并增加膳食纤维摄入，多饮水，保持大便松软通畅。\n3. 暂不宜手术者可在平卧还纳疝内容物后用疝气带压迫内环口，白天佩戴、平卧睡眠时取下，避免压迫过久引起局部皮肤破损或内容物嵌顿。\n4. 密切观察疝块变化，若出现疝块突然增大、变硬、伴明显疼痛且不能还纳，或出现腹痛、恶心呕吐、停止排气排便，须立即急诊就诊，不可强行还纳。\n\n【随诊要求】\n1. 成人腹股沟疝原则上建议择期行疝修补术以获根治；暂不行手术者每3-6个月门诊复查一次，评估疝块大小及有无嵌顿风险。\n2. 出现嵌顿或绞窄征象（疝块不能还纳、明显触痛、伴恶心呕吐或肠梗阻表现）时立即急诊就医。\n3. 行手术治疗者术后1周、1个月门诊复查切口愈合及有无复发、阴囊水肿等情况，此后每年随访1次；术后3个月内避免重体力劳动及剧烈运动。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":869,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5474869b61c99a36fd5b90200ff2b762b503f677540c4e119e5ffb345b788b55","pinyin":"fugugoushan","initials":"fggs","setting":"out","caseName":"门诊病历737","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历737",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-091255e19de3ad360d41","key":"v1-c9ccc21dfe2a3058|templates-091255e19de3ad360d41","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"股疝","category":"门诊病历模板","raw":{"name":"股疝","category":"门诊病历模板","case":{"case_name":"门诊病历738","templates":{"主诉":"反复股疝相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现股疝相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因反复股疝相关不适1周、加重1天就诊，现病史提示症状逐渐加重并伴轻度乏力，无明显发热及恶心呕吐，为明确有无嵌顿继发感染及贫血所致乏力，急诊完成血常规检查排除感染、贫血；股疝经股环突出，极易嵌顿并压迫股静脉，完善超声检查明确疝囊位于腹股沟韧带下方股静脉内侧的位置特点、疝内容物性质及疝环大小，并评估有无股静脉受压及下肢静脉回流障碍。股疝嵌顿后易发生肠管绞窄坏死，需及早评估，完善腹部CT检查明确疝内容物、疝颈宽窄、有无肠梗阻及肠壁缺血征象；若需进一步鉴别腹股沟区软组织病变及淋巴结性质，必要时完善MRI检查明确病变与股血管、耻骨梳韧带的关系。若患者出现腹痛、腹胀、呕吐等肠梗阻表现，完善X线片检查了解有无肠管扩张、气液平面及膈下游离气体。患者若拟行股疝修补术，需评估手术与麻醉耐受性，完善心电图检查排除心律失常及心肌缺血，完善胸部X线片检查排除肺部感染及结核；完善肝肾功能、电解质、血糖检查了解重要脏器功能及有无水电解质紊乱与糖代谢异常，为术前纠正提供依据；完善凝血功能检查评估凝血状态，降低术中术后出血风险；完善血型检查为术中备血输血做好准备。患者腹股沟区包块需排除淋巴结转移性病变及股血管来源肿瘤，必要时完善肿瘤标志物检查协助鉴别诊断。\n\n（检查清单）\n【必做检查】\n血常规、凝血功能、肝肾功能、电解质、血糖、血型\n\n【影像学检查】\nX线片、CT、MRI、超声\n\n【其他检查】\n心电图、胸部X线片、肿瘤标志物（必要时）","初步诊断":"1. 股疝\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 通便药物：乳果糖口服溶液（杜密克）15ml qd，晨起空腹口服，保持大便通畅，避免用力排便增加腹压诱发或加重嵌顿；大便仍干结者可增至bid或加用开塞露20ml纳肛（prn），疗程至择期手术前。\n2. 预防性抗感染（适用于嵌顿或绞窄高危患者，如疝块张力增高、伴局部压痛）：头孢呋辛酯片0.25g bid po，疗程3-5天；对青霉素过敏者改用左氧氟沙星片0.5g qd po。用药期间需同时转外科急诊评估手术时机。\n3. 止痛对症（明确排除嵌顿、绞窄后方可使用）：布洛芬缓释胶囊0.3g bid po，疗程≤3天；或对乙酰氨基酚片0.5g prn（每日不超过2g），缓解腹股沟区坠胀不适。\n\n【一般治疗及生活指导】\n1. 休息与体位：减少久站、久蹲、长时间行走及剧烈运动，适当卧床休息；提重物、屏气、用力咳嗽、用力排便等增加腹压的动作应严格避免。\n2. 饮食指导：清淡、高纤维素饮食，多饮水，多吃蔬菜水果，保持大便通畅；避免暴饮暴食及辛辣刺激食物，肥胖者应控制体重，吸烟者建议戒烟以减少慢性咳嗽。\n3. 活动与手术建议：股疝颈口狭小、极易嵌顿绞窄，确诊后应尽快（1个月内）行择期股疝修补术；术前可佩戴疝带临时托举，但不可长期依赖。\n4. 病情观察：每日自查腹股沟韧带下方包块，若包块突然增大、变硬、触痛明显，伴恶心呕吐、腹胀、停止排气排便，提示嵌顿或绞窄，须立即急诊外科就诊，切勿自行手法还纳。\n\n【随诊要求】\n1. 择期手术前：每1-2周门诊复诊1次，评估疝块大小、张力及有无嵌顿先兆，完善术前检查（血常规、凝血、心电图、胸片等），尽早安排手术。\n2. 术后患者：术后2周复诊查看切口愈合情况，术后1个月、3个月复查评估有无切口感染、血清肿及疝复发；出现切口红肿渗液、发热或腹股沟区包块再发时随时就诊。\n3. 嵌顿/绞窄风险者：若出现腹痛、呕吐、疝块不可还纳等急腹症表现，无需等待预约，随时急诊复诊并行急诊手术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":870,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ebc8b384ae27139cd11c33b2f9aff519817f666fa94ef45caebd5cc477ced107","pinyin":"gushan","initials":"gs","setting":"out","caseName":"门诊病历738","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历738",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b85cb8d41e8e1b5630f8","key":"v1-c9ccc21dfe2a3058|templates-b85cb8d41e8e1b5630f8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"切口疝","category":"门诊病历模板","raw":{"name":"切口疝","category":"门诊病历模板","case":{"case_name":"门诊病历739","templates":{"主诉":"腹部包块1天","现病史":"患者1周前无明显诱因出现切口疝相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因腹部包块1天就诊，现病史提示1周前无明显诱因出现相关症状并逐渐加重，伴轻度乏力，无明显发热及恶心呕吐，为明确有无切口疝嵌顿继发感染及贫血所致乏力，急诊完成血常规检查排除感染、贫血；患者既往有腹部手术史（现病史及既往史未详述，需重点追问），切口疝本质为切口筋膜层愈合不良所致腹壁缺损，完善超声检查明确疝囊位置、大小、疝内容物性质及筋膜缺损口径，了解腹壁各层结构及有无积液。为明确筋膜缺损范围、疝内容物有无嵌顿及肠管血运障碍，完善腹部CT检查评估疝环大小、疝内容物及有无肠梗阻征象，为修补术式选择提供依据；若需鉴别腹壁肿瘤、血肿及脓肿等包块性质，必要时完善MRI检查明确病变范围及其与腹壁肌层的关系。若患者伴腹痛、腹胀、呕吐等肠梗阻表现，完善X线片检查了解有无肠管扩张、气液平面及膈下游离气体。患者若拟行切口疝修补术，需评估手术与麻醉耐受性，完善心电图检查排除心律失常及心肌缺血，完善胸部X线片检查排除肺部感染及结核；完善肝肾功能、电解质、血糖检查了解重要脏器功能及有无水电解质紊乱与糖代谢异常，为术前准备提供依据；完善凝血功能检查评估凝血状态，降低术中术后出血风险；完善血型检查为术中备血输血做好准备。患者切口区包块需排除切口种植转移及腹腔肿瘤，必要时完善肿瘤标志物检查协助鉴别诊断。\n\n（检查清单）\n【必做检查】\n血常规、凝血功能、肝肾功能、电解质、血糖、血型\n\n【影像学检查】\nX线片、CT、MRI、超声\n\n【其他检查】\n心电图、胸部X线片、肿瘤标志物（必要时）","初步诊断":"1. 切口疝\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 预防便秘、降低腹压（合并便秘或排便费力者）：乳果糖口服溶液（如杜密克）15ml qd，晨起空腹口服，疗程1～2周，大便软化后可减量或按需服用，避免排便用力增加腹压诱发嵌顿。\n2. 控制慢性咳嗽（合并咳嗽者）：复方甲氧那明胶囊1粒 tid，或氢溴酸右美沙芬片15mg tid，疗程3～7天，减轻咳嗽时腹压骤增；咳嗽持续不缓解者建议呼吸科进一步诊治。\n3. 改善排尿困难（合并前列腺增生、排尿费力者）：坦索罗辛缓释胶囊0.4mg qd，口服，疗程4周，以减少用力屏气排尿对疝的冲击。\n【一般治疗及生活指导】\n1. 佩戴腹带：白天佩戴，松紧以能托住疝块、无压迫不适为度，先将可回纳的疝内容物还纳后再佩戴，夜间睡眠时可取下；疝块不能回纳或局部红肿疼痛时禁用腹带，及时就医。\n2. 避免一切增加腹压的行为：3个月内避免提重物及重体力劳动，避免剧烈咳嗽、用力排便、长时间站立或屏气用力，控制体重并戒烟（吸烟影响胶原代谢、增加复发风险）。\n3. 饮食：高纤维素饮食（新鲜蔬菜、水果、粗粮），每日饮水1500～2000ml，少量多餐，避免暴饮暴食及易产气食物（豆类、碳酸饮料等）引起腹胀。\n【随诊要求】\n1. 无症状或疝块小者每3～6个月门诊复诊1次，复查腹部查体，必要时行腹壁超声评估疝环大小及疝内容物情况。\n2. 如出现疝块明显增大、胀痛、不能回纳，或伴恶心呕吐、腹胀、停止排气排便等表现，提示嵌顿或肠梗阻可能，须立即急诊就诊。\n3. 具备手术指征者建议尽早至普外科/疝外科评估择期无张力修补术，术前戒烟至少4周，并控制便秘、慢性咳嗽、前列腺增生等基础疾病后再行手术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":871,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4b17dc8c20e44a755d30b940634f9e2d0e9a2448f2a5e09d41686076303c2bca","pinyin":"qiekoushan","initials":"qks","setting":"out","caseName":"门诊病历739","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历739",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-f9abd570f5d797f6122d","key":"v1-c9ccc21dfe2a3058|templates-f9abd570f5d797f6122d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脐疝","category":"门诊病历模板","raw":{"name":"脐疝","category":"门诊病历模板","case":{"case_name":"门诊病历740","templates":{"主诉":"反复脐疝相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现脐疝相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因反复脐疝相关不适1周、加重1天就诊，现病史提示症状逐渐加重并伴轻度乏力，无明显发热及恶心呕吐，为明确有无嵌顿继发感染及贫血所致乏力，急诊完成血常规检查排除感染、贫血；脐疝多与腹壁先天薄弱或腹内压增高有关，完善超声检查明确脐部疝囊大小、疝内容物性质及疝环口径，了解腹壁缺损情况及有无腹腔积液。为明确脐部筋膜缺损范围、疝内容物有无嵌顿及肠管血运障碍，完善腹部CT检查评估疝环大小、疝内容物、有无肠梗阻及腹水征象，为修补术式选择提供依据；若需鉴别脐部炎性肿块、脐尿管残余及腹壁肿瘤，必要时完善MRI检查明确病变范围与腹壁肌层的关系。若患者伴腹痛、腹胀、呕吐等肠梗阻表现，完善X线片检查了解有无肠管扩张、气液平面及膈下游离气体。脐疝常继发于腹内压增高，需同时评估心肺基础疾病，完善心电图检查排除心律失常及心肌缺血，完善胸部X线片检查排除肺部感染及结核；完善肝肾功能、电解质、血糖检查了解重要脏器功能及有无水电解质紊乱与糖代谢异常，为术前准备提供依据；完善凝血功能检查评估凝血状态，降低术中术后出血风险；完善血型检查为术中备血输血做好准备。患者脐部包块需排除腹腔肿瘤及脐部转移性结节，必要时完善肿瘤标志物检查协助鉴别诊断。\n\n（检查清单）\n【必做检查】\n血常规、凝血功能、肝肾功能、电解质、血糖、血型\n\n【影像学检查】\nX线片、CT、MRI、超声\n\n【其他检查】\n心电图、胸部X线片、肿瘤标志物（必要时）","初步诊断":"1. 脐疝\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 对症止痛：布洛芬缓释胶囊0.3g bid，餐后口服，疼痛明显时服用，疗程3～5天；不耐受者可改对乙酰氨基酚片0.5g tid，必要时服用。\n2. 通便治疗：乳果糖口服溶液15ml qd～bid，晨起口服，以每日1～2次成形软便为宜，可连续使用至排便规律。\n3. 胃黏膜保护（与NSAIDs联用期间）：奥美拉唑肠溶胶囊20mg qd，晨起空腹口服，共7天。\n\n【一般治疗及生活指导】\n1. 避免一切增加腹压的因素：勿提举重物、勿剧烈咳嗽、勿用力排便，避免久蹲、久站；咳嗽或打喷嚏时用手掌按压脐疝部位以减轻腹压冲击。\n2. 饮食：多进食富含膳食纤维的食物（绿叶蔬菜、水果、粗粮），每日饮水1500～2000ml，保持大便通畅，避免便秘及过饱腹胀。\n3. 体重管理：肥胖者应控制体重，减轻腹壁张力；避免腰带、裤腰过紧压迫脐部。\n4. 疝块护理：疝块脱出时可平卧自行还纳，严禁强行按压或揉搓还纳；疝气带仅作为术前临时压迫措施，不宜长期依赖。\n\n【随诊要求】\n1. 成人脐疝不能自愈，且随病程延长嵌顿风险增加，建议择期行疝修补术，具体术式请至普外科（疝外科）门诊评估后决定。\n2. 保守观察期间每3～6个月门诊复查1次；若疝块突然增大、变硬、疼痛加剧、不可还纳，或伴腹痛、恶心呕吐、停止排气排便等嵌顿或绞窄征象，须立即急诊就诊，切勿自行服用止痛药掩盖症状。\n3. 若行手术治疗，术后1个月返院复查切口愈合情况，术后3个月内避免重体力劳动和剧烈运动，出现切口红肿渗液、发热等及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":872,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"549df92e320ae07b30a3110d789747c54742fc10ab7a5430839df9aaf9974a49","pinyin":"qishan","initials":"qs","setting":"out","caseName":"门诊病历740","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历740",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7f23f692378feb158746","key":"v1-c9ccc21dfe2a3058|templates-7f23f692378feb158746","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性腹膜炎","category":"门诊病历模板","raw":{"name":"急性腹膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历741","templates":{"主诉":"突发全腹剧痛伴腹肌紧张、恶心呕吐6小时","现病史":"患者因继发性腹膜炎就诊，其最常见病因为腹腔内脏器穿孔、炎症或损伤，具体包括：消化道穿孔，如胃十二指肠溃疡穿孔（突发上腹痛、板状腹为特征）、阑尾炎穿孔（疼痛由右下腹扩散）、胆囊炎或胆管炎穿孔、肠梗阻所致坏死、绞窄疝、肠系膜缺血所致肠坏死、胰腺炎重症渗出、创伤所致腹部外伤空腔脏器破裂、术后吻合口漏或胆漏、肠漏；原发性腹膜炎较少见，多为血行感染，可见于肝硬化腹水患者（即自发性细菌性腹膜炎），儿童则可见链球菌感染；此外还可继发于妇科疾病，如盆腔炎、输卵管炎、盆腔腹膜炎。患者于突发起病（如穿孔、溃疡穿孔时突发剧烈疼痛）或渐进起病（如阑尾炎炎症扩散）后出现下列表现：腹痛，多为剧烈持续性全腹痛，或由原发病灶开始并扩散至全腹；腹肌紧张，呈板状腹，穿孔时全腹明显，伴肌卫及反跳痛，为腹膜炎特征；恶心呕吐，为反射性，可伴肠麻痹；发热，由炎症或感染所致，可伴寒战；腹胀，因肠麻痹可出现停止排气排便；全身表现，可见脱水、中毒及休克，为感染性休克，晚期可血压低、心率快、尿少、意识改变，属急症；膈肌受刺激时可出现肩痛；体位方面，患者常屈膝蜷曲，以减少腹肌张力，为腹膜炎的强迫体位。今日来我院急诊或普外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.5℃，P110次/分（增快），R24次/分（浅快，腹式呼吸受限），BP100/65mmHg（偏低，警惕休克）。神志清楚或淡漠（休克时淡漠）、强迫体位（屈膝不动）、腹部压痛（全腹均有，以原发灶处最重）、反跳痛（为腹膜炎特征）、腹肌紧张（板状腹，穿孔时明显，伴肌卫）、肝浊音界消失（穿孔致气腹的重要体征）、移动性浊音（提示腹水或渗出）、肠鸣音减弱或消失（提示肠麻痹）、腹部伤口或手术史、直肠指诊（盆腔压痛或有波动感，提示脓肿）、体温发热、心率增快（提示感染或脱水）、全身情况（注意休克、皮肤灌注）。","辅助检查":"【必做】血常规（白细胞显著升高或降低）、CRP及降钙素原、血培养（用于脓毒症）、电解质（注意紊乱）、血气（注意酸中毒，见于休克或坏死）、肝肾功能、血糖、血淀粉酶及脂肪酶（排查胰腺炎）、凝血功能；【影像】立位腹部X线（观察膈下游离气体，为穿孔特征及气腹的重要征象，并观察肠梗阻所致气液平）、腹部CT增强（为核心检查，可见腹腔积液、积气及原发病灶，如穿孔时造影剂外漏、阑尾炎、胰腺炎、肠梗阻伴坏死、肠壁积气提示缺血、脓肿定位，为腹腔诊断急症的首选）、超声（床旁检查腹腔积液或脓肿，快速并可引导穿刺）；【诊断性穿刺】腹腔穿刺（抽出脓性、血性或肠内容物可确诊腹膜炎并判断病原，依据抽出液判断原发病灶，胆汁提示胆道、粪臭提示肠道、血性提示坏死或出血，为重要检查，穿刺液应送培养）；【其他】妊娠试验（育龄女性需排查异位妊娠破裂，为急腹症鉴别的重要项目）、尿常规（排查泌尿系疾病）、心电图（排查心肌梗死，心梗可表现为上腹痛，为少见但需鉴别的项目）。","初步诊断":"1. 急性腹膜炎（继发性：原发性/继发性，由原发病灶所致（穿孔/阑尾炎/胰腺炎等）；弥漫性：局限性/弥漫性；需行脓毒症及休克评估，属急症）\n（注：治疗要点，本病为外科急症，多数需急诊手术以控制感染源）：①术前准备：禁食、胃肠减压（以减轻腹胀）、补液（积极纠正脱水及电解质紊乱）、抗感染（选用广谱抗生素，覆盖革兰阴性菌加厌氧菌，因肠源性感染厌氧菌重要，可用哌拉西林他唑巴坦或头孢曲松加甲硝唑，重症可用碳青霉烯类如美罗培南；合并脓毒症、休克者予液体复苏、血管活性药，并转入ICU监测）；②手术：剖腹探查，找到原发病灶后处理，穿孔予修补或切除，溃疡穿孔可修补或行胃大部切除术，具体依情况而定；阑尾炎行阑尾切除；胆囊炎或胆管炎行胆囊切除或引流；肠坏死行切除后吻合或造口，污染重者造口并二期处理；吻合口漏予修补或引流回肠袢；并行腹腔冲洗（用大量生理盐水冲洗以清除脓液）、引流（放置腹腔引流管，用于脓腔或吻合口，术后引流重要）；③原发性腹膜炎（即自发性细菌性腹膜炎）采取非手术治疗，以抗生素为主，如三代头孢中的头孢噻肟，参照自发性腹膜炎抗感染治疗，不需手术，此点区别重要；④术后处理：转入ICU监测脓毒症；抗生素疗程依培养结果而定，腹腔感染一般7~14天；观察引流并据脓液情况拔管；营养支持先肠外，早期后可过渡至肠内；注意并发症，包括腹腔脓肿（多有残留，可用超声或CT引导穿刺引流）、肠梗阻（多因术后粘连，较多见，多数经保守治疗）、切口感染或裂开、脓毒症可致多器官衰竭甚至死亡；⑤随访：观察恢复情况（肠鸣音恢复、排气后进食）、引流管拔除、原发病随访（溃疡愈合后随访并根除幽门螺杆菌以防再穿孔，此点重要）；急诊或普外科处理，本病为急症，应早期手术、控制感染源、抗感染及支持治疗，原发性腹膜炎则以抗生素治疗为主，鉴别很重要。","处理方案":"【药物治疗】\n1. 抗感染治疗（覆盖肠道需氧革兰阴性菌及厌氧菌，疗程5～7天）：左氧氟沙星片 0.5g 口服 每日1次；联合甲硝唑片 0.4g 口服 每日3次，餐后服。若青霉素过敏或喹诺酮不耐受，可改用头孢呋辛酯片 0.5g 口服 每日2次联合甲硝唑片 0.4g 口服 每日3次。\n2. 解痉止痛：山莨菪碱片 10mg 口服 每6～8小时1次，腹痛缓解即停；腹痛剧烈时可予山莨菪碱注射液 10mg 肌注 临时1次，忌用强效镇痛药以免掩盖体征。\n3. 补液及纠正水电解质紊乱：呕吐明显者予静脉补液，5%葡萄糖氯化钠注射液 500ml 加入 10%氯化钾注射液 10ml 静脉滴注 每日1次，同时监测尿量、电解质；轻症可口服补液盐III 500ml 分次口服。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息，取半卧位（床头抬高30°左右），以利腹腔渗液向盆腔引流、减轻膈肌刺激；避免剧烈活动及重体力劳动，症状缓解后1周内仍应减少活动量。\n2. 急性期禁食禁水6～12小时，必要时行胃肠减压；待腹痛缓解、肠鸣音恢复、肛门排气后逐步恢复饮食：先流质（米汤、藕粉）→半流质（稀粥、烂面条），少量多餐，忌油腻、辛辣刺激及产气食物（豆类、碳酸饮料、牛奶等）。\n3. 禁忌：禁用泻药、灌肠及腹部热敷，以免炎症扩散或肠穿孔加重病情；疼痛原因未明确前禁用吗啡类强效镇痛药，以免掩盖腹膜炎体征延误诊治。\n4. 注意保暖、避免受凉，保持情绪平稳；如出现寒战高热、血压下降、烦躁或意识淡漠，立即急诊就诊。\n\n【随诊要求】\n1. 用药后24～48小时复诊，复查血常规、C反应蛋白，评估腹痛程度、腹部压痛反跳痛及腹肌紧张等体征变化，依据疗效调整抗感染方案。\n2. 若腹痛持续加重、疼痛由局部蔓延至全腹、呕吐频繁不能进食、或出现高热不退、心率增快、血压下降等感染性休克表现，立即急诊就诊，警惕腹腔脓肿、肠梗阻及弥漫性腹膜炎等并发症，必要时转外科住院手术治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":873,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"340bcaeca354ab096a3e9089e162eb90f895f564e45932c78fc42a0c9f3557f9","pinyin":"jixingfumoyan","initials":"jxfmy","setting":"out","caseName":"门诊病历741","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历741",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d7944891da0775261f91","key":"v1-c9ccc21dfe2a3058|templates-d7944891da0775261f91","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性腹膜炎","category":"门诊病历模板","raw":{"name":"慢性腹膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历742","templates":{"主诉":"腹胀1天","现病史":"患者1周前无明显诱因出现慢性腹膜炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以腹胀1天为主诉，1周来症状逐渐加重并伴轻度乏力，虽无明显发热、无恶心呕吐，仍需先完善血常规检查明确有无感染及贫血；查尿常规、便常规以了解有无泌尿系感染、尿糖及肠道炎症、消化道出血等腹部症状的常见诱因；本次拟长期用药，药物多经肝肾代谢，完善肝肾功能、血糖、血脂检查以评估肝肾功能与糖脂代谢状态，指导后续用药及营养支持方案；患者腹胀伴乏力，完善电解质检查排除低钾、低钠等电解质紊乱所致胃肠动力减退；查心电图排除心肌缺血、心律失常等以腹胀为首发表现的心源性疾病；查胸部X线片排除肺部感染、胸腔积液及膈下游离气体；完善腹部超声检查以了解有无腹腔积液及其量、腹膜增厚、肠管扩张及肝胆胰脾情况，明确慢性腹膜炎的病因与范围；因腹膜病变性质单凭影像难以判定，必要时行诊断性腹腔穿刺送腹水常规、生化、细胞学及细菌培养，以鉴别结核性、细菌性与肿瘤性腹膜炎；病情稳定后定期复查血常规、肝肾功能与腹部超声，评估抗感染或抗结核治疗效果，必要时请消化内科、感染科会诊协同诊治。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 慢性腹膜炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗结核治疗（首选方案，针对最常见病因结核性腹膜炎）：异烟肼片0.3g qd＋利福平胶囊0.45g qd＋吡嗪酰胺片0.5g tid＋乙胺丁醇片0.75g qd，晨起空腹顿服，强化期2个月；继以异烟肼0.3g qd＋利福平0.45g qd巩固期，总疗程9～12个月，全程规范督导、不得中断。\n2. 糖皮质激素（患者足量有效抗结核基础上）：泼尼松片30～40mg qd晨起顿服，连用2～4周后每1～2周递减5mg，用于渗出型、粘连型患者，减轻渗出、防止腹膜粘连，疗程一般6～8周。\n3. 大量腹水者：腹腔穿刺适量放液（首次≤1000ml，以后每次≤3000ml，缓慢引流），可腹腔内注入异烟肼0.3g＋地塞米松5mg，每周1～2次，至腹水基本消退。\n4. 对症及辅助：腹痛明显者予山莨菪碱片10mg tid口服解痉；防治异烟肼神经毒性加用维生素B6片20mg tid；食欲差、低蛋白者加强营养支持并适当补充白蛋白。\n【一般治疗及生活指导】\n1. 休息：渗出活动期卧床休息、减少活动量，病情稳定后循序渐进恢复日常活动，避免劳累、熬夜及精神紧张。\n2. 饮食：高蛋白、高维生素、易消化软食，少量多餐（每日4～6餐），保证鱼、蛋、奶、瘦肉等优质蛋白摄入，忌生冷、辛辣刺激、油腻及粗硬食物，戒烟戒酒。\n3. 活动与禁忌：避免剧烈运动、腹部挤压及负重，避免受凉感冒；注意个人卫生，开放性肺结核者痰液等分泌物规范消毒处理，防止交叉感染。\n4. 用药依从：抗结核药晨起空腹顿服，不得自行停药、减量或改药；服利福平后尿液、汗液呈橘红色属正常现象，不必紧张。\n【随诊要求】\n1. 抗结核治疗期间每月复查肝功能、肾功能、血常规，警惕异烟肼、利福平所致肝损害；出现黄疸、恶心呕吐、乏力、尿色加深等立即复诊。\n2. 每1～3个月复查腹部B超或CT，动态观察腹水吸收及腹膜粘连情况；腹水明显者每周监测腹围、体重变化。\n3. 用药期间出现视力下降、视物模糊（乙胺丁醇）、皮疹、发热、关节痛、耳鸣等药物不良反应，应及时复诊调整方案。\n4. 疗程结束后停药，每3～6个月门诊复查1次，随访1～2年观察有无复发；育龄期女性治疗期间注意避孕。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":874,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1095a60201b0736f38daeeb99e026b0ad66eed23ebb3b4cd8cc63be1712e7929","pinyin":"manxingfumoyan","initials":"mxfmy","setting":"out","caseName":"门诊病历742","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历742",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4287dee682566fa6c619","key":"v1-c9ccc21dfe2a3058|templates-4287dee682566fa6c619","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"原发性腹膜炎","category":"门诊病历模板","raw":{"name":"原发性腹膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历743","templates":{"主诉":"腹胀1天","现病史":"患者1周前无明显诱因出现原发性腹膜炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者腹胀1天、1周来逐渐加重并伴轻度乏力，原发性腹膜炎多无明确腹腔内原发病灶，须先完善血常规检查明确有无感染及贫血；查尿常规、便常规以了解有无泌尿系感染及肠道炎症、消化道出血等诱因；本次需抗感染治疗，药物多经肝肾代谢，完善肝肾功能、血糖、血脂检查以评估肝肾功能与糖脂代谢状态，指导抗菌药物选择与剂量调整；患者腹胀、乏力明显，完善电解质检查排除低钾、低钠等电解质紊乱所致胃肠功能减退；查心电图排除心肌缺血与心律失常；查胸部X线片排除肺部感染、胸腔积液，并了解有无膈下游离气体以排除消化道穿孔；完善腹部超声检查了解腹腔积液量、腹膜情况，同时明确有无肝硬化、门脉高压、脾大等原发性腹膜炎的常见基础病变；原发性腹膜炎常继发于肝硬化腹水，故建议行诊断性腹腔穿刺，送腹水常规、生化、细胞学及细菌培养，明确腹水性质并排除继发性腹膜炎；病情稳定后定期复查血常规、肝肾功能、电解质及腹部超声，评估抗感染疗效，必要时请消化内科、感染科会诊。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 原发性腹膜炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 第三代头孢菌素（首选）：头孢克肟胶囊0.1g bid po×7天；疗效不佳或中重度感染改头孢曲松2g iv qd×7天，或头孢噻肟2g iv q8h×7天。\n2. 氟喹诺酮类（对β-内酰胺类过敏或院外轻症者）：左氧氟沙星片0.5g qd po×7天；用药期间多饮水，避免日晒，肝功能不全者慎用。\n3. 青霉素类复方制剂（备选）：阿莫西林克拉维酸钾片0.457g（阿莫西林0.4g/克拉维酸57mg）tid po×7天；青霉素过敏者禁用。\n4. 对症处理：腹痛明显予山莨菪碱片5mg tid po解痉（青光眼、前列腺肥大者禁用）；高热＞38.5℃予物理降温，必要时布洛芬缓释胶囊0.3g bid po，退热药疗程≤3天。\n\n【一般治疗及生活指导】\n1. 休息：急性期卧床休息为主，取半卧位以利腹腔渗液局限与吸收；症状缓解后逐步下床活动，避免劳累、熬夜及剧烈运动。\n2. 饮食：急性期予流质或半流质易消化饮食，少量多餐；肝硬化腹水者严格低盐饮食（每日食盐＜2g）并限制液体入量（每日约1000ml），无肝性脑病者予高蛋白、高维生素软食，禁食粗糙、坚硬、油炸及辛辣刺激性食物，以防食管胃底静脉曲张破裂出血。\n3. 禁忌：绝对禁烟戒酒，禁用非甾体抗炎药（吲哚美辛、阿司匹林等）、氨基糖苷类等肾毒性药物，慎用利尿剂防过度利尿诱发氮质血症；注意保暖，预防呼吸道感染。\n4. 病情观察：每日监测体温、腹痛部位及性质、腹围、体重与尿量，观察大便颜色，警惕呕血、黑便、神志改变（肝性脑病）、少尿等，异常及时就诊。\n\n【随诊要求】\n1. 用药48～72小时复诊，复查血常规、腹水常规（细胞计数、多形核细胞百分比及蛋白），评估抗感染疗效，无效及时调整抗生素方案。\n2. 完成7天疗程后复诊，复查腹水常规、肝肾功能及电解质，确认腹水多形核细胞＜250×10⁶/L、腹水培养阴性后方可停药。\n3. 肝硬化腹水患者每1～3个月门诊随访一次，定期复查肝功能、凝血功能、甲胎蛋白及腹水常规；曾患原发性腹膜炎者遵医嘱长期口服诺氟沙星0.4g qd（或复方磺胺甲噁唑）预防复发。\n4. 若出现持续高热不退、腹痛进行性加重、血压下降、意识障碍或消化道出血，应立即急诊就医，不得延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":875,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7b753b335e3740f735a04f907c1f282e047578c7c359373efa7ea923bc944b42","pinyin":"yuanfaxingfumoyan","initials":"yfxfmy","setting":"out","caseName":"门诊病历743","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历743",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-809dc24f1c9b0fdfcace","key":"v1-c9ccc21dfe2a3058|templates-809dc24f1c9b0fdfcace","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"继发性腹膜炎","category":"门诊病历模板","raw":{"name":"继发性腹膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历744","templates":{"主诉":"腹胀1天","现病史":"患者1周前无明显诱因出现继发性腹膜炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者腹胀1天、1周来逐渐加重并伴轻度乏力，继发性腹膜炎多由腹腔内脏器穿孔、坏死或炎症蔓延所致，病情可迅速恶化，须急诊完善血常规检查明确感染程度及有无贫血；查尿常规、便常规以了解有无泌尿系感染、肠道炎症及消化道出血；完善肝肾功能、血糖、血脂检查以评估肝肾代谢功能，为抗感染及可能的手术治疗提供依据；患者腹胀、乏力，完善电解质检查排除电解质紊乱所致肠麻痹与乏力；查心电图、胸部X线片排除心肌缺血、心律失常及肺部感染，胸部X线片并需注意有无膈下游离气体以提示消化道穿孔；完善腹部超声检查了解腹腔积液、肠管扩张及肝胆胰脾情况，明确感染来源；如拟行急诊手术，需补充凝血功能、血型、感染筛查等术前必查项目，评估手术耐受性；为鉴别急性胰腺炎这一常见继发因素，可查血、尿淀粉酶及脂肪酶；高度怀疑消化道穿孔、肠坏死或腹腔脓肿而超声难以明确时，急诊行腹部CT检查以明确病变部位与范围；定期复查血常规、CRP及腹部超声评估病情演变，必要时请普外科、消化内科急诊会诊。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 继发性腹膜炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗感染治疗（覆盖肠道需氧革兰阴性杆菌及厌氧菌，疗程5-7天）：①头孢呋辛酯片0.25g bid+甲硝唑片0.4g tid，口服，×5-7天；②莫西沙星片0.4g qd，口服，×5-7天（对厌氧菌亦有覆盖，可单用）；③阿莫西林克拉维酸钾片0.625g tid，口服，×5-7天。体温正常、腹部体征缓解后巩固治疗3天，总疗程一般7-10天。\n2. 对症支持治疗：甲氧氯普胺片5mg tid，口服，×3-5天（恶心、呕吐或腹胀明显时）；腹痛明显者必要时予山莨菪碱片5mg tid（青光眼、前列腺肥大者禁用），症状缓解即停用。\n3. 胃肠道休息与补液：禁食或清淡流质期间口服补液盐（ORSⅢ）500-1000ml/d分次口服，尿量不足或脱水明显者需静脉补液纠正水电解质紊乱；腹胀明显者可加用双歧杆菌三联活菌胶囊0.42g tid，口服，×7天调节肠道菌群。\n【一般治疗及生活指导】\n1. 休息：急性期卧床休息为主，腹痛腹胀明显时取半卧位以减轻腹肌紧张、利于炎性渗出局限；症状缓解后1-2周内避免剧烈运动及重体力劳动。\n2. 饮食：腹痛缓解、肠鸣音恢复后由流质（米汤、藕粉）→半流质（烂面条、粥）逐渐过渡至低脂、易消化少渣饮食，少量多餐，忌暴饮暴食，忌辛辣刺激、生冷油腻及产气食物（豆类、碳酸饮料）。\n3. 禁忌：严格禁烟禁酒，禁用泻药及强痛剂（以免掩盖病情）；警惕病因未除者（胆石症、消化道穿孔、阑尾炎等）需按外科意见尽早处理原发病灶。\n4. 病情监测：每日自测体温并观察腹痛部位、性质变化，如出现腹痛突然加剧、持续高热不退、恶心呕吐加重、腹胀进行性加重、面色苍白或四肢湿冷，立即急诊就医，不可延误。\n【随诊要求】\n1. 用药3天后复诊，评估腹痛、发热及腹部体征改善情况，必要时调整抗菌药物；若3天内症状无缓解或加重，应立即急诊就诊，排除脓肿形成、穿孔扩大等需外科干预的情况。\n2. 疗程结束后1-2周复查血常规、CRP、肝肾功能，评估感染控制及药物不良反应；胆道、阑尾等原发病因者遵相关专科（普外科/肝胆外科）随访计划定期复查。\n3. 治疗期间如出现皮疹、腹泻（尤其水样便）、双硫仑样反应（患者头孢类期间及停药1周内禁酒）等药物不良反应，及时复诊处理。\n4. 经治好转者建议随访至症状消失、实验室指标恢复正常，术后继发腹膜炎者按手术科室要求定期复查，警惕腹腔残余脓肿、粘连性肠梗阻等远期并发症。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":876,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6e1a54ae0e8ad3196380abdd1dff1fe3e5c12c1afaec521873b1ce40344ca8a0","pinyin":"jifaxingfumoyan","initials":"jfxfmy","setting":"out","caseName":"门诊病历744","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历744",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d69fd9a60cb5367bf6f4","key":"v1-c9ccc21dfe2a3058|templates-d69fd9a60cb5367bf6f4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"结核性腹膜炎","category":"门诊病历模板","raw":{"name":"结核性腹膜炎","category":"门诊病历模板","case":{"case_name":"门诊病历745","templates":{"主诉":"低热、盗汗伴腹痛、腹胀3个月","现病史":"患者因结核感染（肺结核经血行播散，或腹腔结核如肠结核、肠系膜淋巴结结核直接蔓延；青年女性多见，亦见于免疫低下者（HIV感染、激素治疗、透析）、营养不良、有结核接触史者）于1月余（起病隐匿、渐进，病程数周至数月）出现：发热（午后低热，37.5~38℃，为典型表现）、盗汗（夜间为著）、乏力、消瘦（呈进行性）、食欲减退、腹痛（持续性隐痛或胀痛，位于脐周或全腹，系粘连牵拉所致）、腹泻或便秘（肠功能紊乱所致，以腹泻常见）、腹胀（因腹水（渗出性、结核性多见）或肠胀气、肠粘连所致）、腹部包块（由粘连、网膜增厚形成，触诊有揉面感，即腹部柔韧感，为结核性腹膜炎的特征性重要体征）、腹水（移动性浊音，中至大量）、分型（腹水型（渗出性腹水，最常见）、粘连型（肠粘连、包块、肠梗阻）、干酪型（干酪样坏死、结节）、混合型）、并发症（肠梗阻（粘连所致最多见）、肠穿孔（少见，属急症）、肠瘘、腹水感染、肺结核并存（咳嗽、咳痰，胸片可查）、肠结核（腹痛、腹泻，可与肠外结核并存，参见肠结核）、肝脾结核播散）；另有结核接触史、既往结核史、卡介苗接种史。今日来我院消化科或感染科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P92次/分，R20次/分，BP110/70mmHg。腹部：腹水征（移动性浊音（+），液波震颤提示大量腹水）、腹部柔韧感（揉面感，为结核性特征，系腹膜增厚、粘连所致）、压痛（轻，位于脐周或全腹）、腹部包块（由粘连肠管、网膜形成，质韧，不活动）、肠鸣音（亢进或减弱，粘连性肠梗阻时可出现）、叩诊（鼓音，提示气胀）、腹围（用于腹水测量）；全身：消瘦、低热、盗汗、慢性病容、营养不良、浅表淋巴结（肿大，提示淋巴结核并存）、肺（听诊，注意肺结核啰音）、杵状指（少见）。","辅助检查":"【必做】血常规（贫血，白细胞正常/不高，区别于化脓性）、血沉（增快明显）、CRP、结核菌素试验/γ-干扰素释放试验（感染证据支持阳性，但不能区分活动）、胸片/胸部CT（肺结核（并存，约1/3发现原发灶，重要）、腹水检查（核心：渗出液（Light标准：蛋白>30g/L，白细胞↑，淋巴细胞为主，多）、腺苷脱氨酶（腹水腺苷脱氨酶>40~50U/L，结核性诊断价值大，重要鉴别恶性腹水）、抗酸染色（阳性率低）、结核分枝杆菌培养（腹水阳性率低）、腹水聚合酶链反应（Xpert，结核患者可检，重要，但腹水灵敏度受限）、细胞学（排除恶性腹膜转移，鉴别重要））；【影像】腹部超声（腹水（量）、腹膜（增厚）、肠系膜淋巴结（肿大）、粘连评估）、腹部CT（腹膜增厚，大网膜（饼状，结核性特征）、肠系膜淋巴结（肿大，钙化）、肠壁增厚（肠结核）、腹水）、全消化道造影（肠结核，肠粘连少见，已少用）；【确诊】腹膜活检（腹膜穿刺活检（超声引导或腹腔镜（直视腹膜粟粒样结节，活检，病理（干酪样肉芽肿，确诊金标准，重要，诊断不明，腹腔镜））；【其他】（血培养除外、HIV检测（免疫低下评估）、肝肾功能。","初步诊断":"1. 结核性腹膜炎（腹水型：腹水型或粘连型或干酪型；腹水腺苷脱氨酶45U/L；需评估肺结核或肠结核并存；确诊依据腹水检查或活检）\n（注：治疗（抗结核为核心，长程用药，腹水消退，注意粘连并发症）：①抗结核化疗（标准四联方案：异烟肼+利福平+吡嗪酰胺+乙胺丁醇，2个月强化期后改为异烟肼+利福平巩固，总疗程10~12个月（肺外结核需长程，较为重要），规则服药、全程督导（防耐药、防复发，较为重要）；激素：糖皮质激素（泼尼松30~40mg/d），在抗结核同时用于腹水型，可促进腹水吸收、减少粘连与瘢痕，较为重要（结核性腹膜炎用激素辅助可降低粘连、梗阻等并发症），逐渐减量，疗程4~6周；疗效：抗结核后2~4周发热、盗汗缓解，腹水渐消，1~3个月明显改善，无效者需再评估（耐药、诊断错误或并发脓肿））；②腹水处理（大量腹水致腹胀者行穿刺放液（减压缓解症状，防止持续大量腹水，但反复穿刺致蛋白丢失，需补充白蛋白及营养）、利尿（适量使用螺内酯辅助，腹水多时抗结核有效后即可吸收，不必强利尿）、营养（高蛋白饮食，因结核消耗大，支持治疗较为重要））；③并发症（肠梗阻（粘连型多见，多为慢性不全梗阻，保守治疗（禁食、胃肠减压、抗结核，粘连缓解多可部分好转），完全梗阻者手术（松解粘连，但术后易再粘连，须严格掌握指征）、肠穿孔或肠瘘（手术切除或修补）、脓肿（腹腔脓肿抗结核无效者行引流））；④随访（疗程（10~12个月全程，不可自行停药）、复查（腹水消退情况（超声）、症状（发热、腹痛缓解情况）、体重（增加提示营养恢复）、粘连并发症（长期监测肠梗阻）、肝功能（监测抗结核药，异烟肼、利福平较为重要）、疗程结束后随访（复发，1~2年））；由感染科或消化科规范抗结核，腹水型加用激素，注意营养，粘连并发症及手术指征较为重要。","处理方案":"【药物治疗】\n1. 抗结核化疗（初治首选方案2HRZE/4HR，总疗程6个月）：强化期2个月：异烟肼片0.3g qd+利福平胶囊0.45g qd（体重≥50kg者0.6g qd）+吡嗪酰胺片0.5g tid+乙胺丁醇片0.75g qd，均为晨起空腹顿服；继续期4个月：异烟肼片0.3g qd+利福平胶囊0.45g qd，晨起空腹顿服。\n2. 保肝辅助：水飞蓟宾胶囊70mg tid（或双环醇片25mg tid），与抗结核药同服，全程常规服用以预防药物性肝损伤。\n3. 营养神经辅助：维生素B6片10mg tid，预防异烟肼引起的周围神经炎；腹胀明显者可加用多酶片2片 tid促进消化。\n【一般治疗及生活指导】\n1. 充分休息，发热、腹水及腹痛明显期应卧床休息，避免劳累及熬夜，保证充足睡眠。\n2. 饮食宜高蛋白、高热量、高维生素、易消化（如鱼、蛋、瘦肉、奶、豆制品、新鲜蔬果），少量多餐，忌生冷、油腻及刺激性食物，戒烟酒。\n3. 病情缓解后可循序渐进进行散步等轻体力活动，注意保暖，预防呼吸道感染，避免与活动性肺结核患者密切接触。\n4. 严格遵医嘱规律服药，严禁自行停药、减量或改药，注意观察有无恶心、呕吐、皮肤巩膜黄染等药物不良反应。\n【随诊要求】\n1. 治疗期间每2～4周门诊复诊1次，强化期每月复查肝功能、血常规、肾功能，如出现转氨酶明显升高需及时调整方案。\n2. 每月复查腹部超声观察腹水消退及腹膜增厚、粘连变化，必要时复查胸片除外肺结核。\n3. 若出现发热不退、腹痛加重、呕吐、黄疸、尿少或腹胀进行性加重，应立即就诊；全程规律服药满6个月后门诊复查评估疗效并决定是否停药。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":877,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0a5b8e9f067a7e1ba607731c1138980aef78fe8584d46f0e3f6b77bfb94e8ce2","pinyin":"jiehexingfumoyan","initials":"jhxfmy","setting":"out","caseName":"门诊病历745","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历745",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-57906dc06da2ac198cc0","key":"v1-c9ccc21dfe2a3058|templates-57906dc06da2ac198cc0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急进性肾炎","category":"门诊病历模板","raw":{"name":"急进性肾炎","category":"门诊病历模板","case":{"case_name":"门诊病历746","templates":{"主诉":"水肿1天","现病史":"患者1周前无明显诱因出现急进性肾炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以水肿1天为主诉、1周来逐渐加重并伴轻度乏力，急进性肾炎肾功能可在数周内急剧恶化，须尽快完善尿常规检查明确有无血尿、蛋白尿及管型，评估肾小球损伤；查尿微量白蛋白与24小时尿蛋白定量以精确了解蛋白尿程度，判断肾损伤轻重及疗效；完善肾功能、电解质检查明确有无肾功能急剧减退及高钾血症等危险情况，指导治疗与透析时机评估；查泌尿系超声了解双肾大小、皮质厚度、有无积水及占位，鉴别梗阻性与慢性肾脏病；查血常规、肝功能、凝血功能以评估贫血、基础肝病及出血风险，并作为肾脏穿刺的术前必查项目；因急进性肾炎常继发于系统性红斑狼疮、血管炎等免疫性疾病，完善自身抗体检查以明确病因并指导激素及免疫抑制治疗；若病因仍不明确、肾功能持续恶化，病情稳定后行肾脏穿刺活检以明确病理类型，指导免疫抑制方案；治疗期间定期复查尿常规、肾功能、电解质与24小时尿蛋白定量，动态评估疗效。\n\n（检查清单）\n【必做检查】\n尿常规、尿微量白蛋白、24小时尿蛋白定量、肾功能、电解质\n\n【影像学检查】\n泌尿系超声、肾脏穿刺（必要时）\n\n【其他检查】\n血常规、肝功能、凝血功能、自身抗体（必要时）","初步诊断":"1. 急进性肾炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 糖皮质激素（基础免疫抑制）：泼尼松片 1mg/(kg·d) 晨顿服（成人常规 50～60mg/d），病情缓解（尿量增多、血肌酐趋稳）后每 2～4 周减量 5～10mg/d，至维持量 10～15mg/d 继续 6～12 个月，总疗程不少于 6 个月；急性期（新月体广泛形成或快速进展）需住院行甲泼尼龙冲击 500～1000mg/d 静脉滴注×3 天，冲击后序贯口服维持。\n2. 免疫抑制剂（与激素联用）：环磷酰胺 0.75g/m² 静脉冲击每月 1 次，或口服 50～100mg/d，连用 3～6 个月，累积总量不超过 150mg/kg；用药期间注意充分水化，警惕出血性膀胱炎。\n3. 免疫抑制剂替代方案：吗替麦考酚酯胶囊 0.5～1.0g bid 口服，用于不能耐受环磷酰胺者，疗程 6～12 个月，根据患者具体情况制定个体化方案与激素联用。\n4. 对症支持治疗：缬沙坦胶囊 80mg qd（血压控制目标 <130/80mmHg，据血压渐增至 160mg qd，监测血钾及血肌酐）；水肿明显者加呋塞米片 20～40mg qd 口服，尿量增多后根据患者具体情况制定个体化方案减停。\n\n【一般治疗及生活指导】\n1. 急性期绝对卧床休息，至肉眼血尿消失、水肿消退、血压及肾功能稳定后逐步恢复日常活动，半年内避免剧烈运动和重体力劳动。\n2. 低盐低优质蛋白饮食：食盐 <3g/d，蛋白质 0.6～0.8g/(kg·d)（以蛋、奶、瘦肉等优质蛋白为主）；水肿明显者限制液体入量于\"前一日尿量+500ml\"，避免香蕉、橘子、土豆等高钾食物及含钾代盐。\n3. 严格预防感染（尤其上呼吸道感染），避免劳累、受凉、妊娠；禁用非甾体抗炎药、氨基糖苷类抗生素及含碘造影剂等肾毒性药物，停用一切可疑诱发药物。\n4. 每日自测血压、体重并记录尿量，观察有无肉眼血尿加重或泡沫尿增多，发现异常及时就诊。\n\n【随诊要求】\n1. 治疗初期每周复诊 1 次，复查尿常规、24h 尿蛋白定量、血肌酐/尿素氮、电解质及血钾；病情缓解后每 2～4 周复诊 1 次。\n2. 每月复查血清抗 GBM 抗体、ANCA、ANA 谱、补体及血清白蛋白评估疾病活动度；激素减量期监测血糖、血脂、骨密度，必要时行胸部 CT 排除结核及机会性感染。\n3. 使用环磷酰胺或吗替麦考酚酯者每 2～4 周查血常规、肝功能，长期用药者每 3～6 个月复查尿常规，警惕骨髓抑制、肝损伤及出血性膀胱炎。\n4. 出现少尿（<400ml/d）、无尿、肉眼血尿加重、血压≥160/100mmHg、气促不能平卧或发热等病情恶化征象，应立即就近就医，不可等待常规复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":878,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1e3f7cd7eaa18f1c4075e37a789993dcb5a4370ba5fad7a1955d533e4550473c","pinyin":"jijinxingshenyan","initials":"jjxsy","setting":"out","caseName":"门诊病历746","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历746",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-894e89007c3e1569190b","key":"v1-c9ccc21dfe2a3058|templates-894e89007c3e1569190b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"隐匿性肾炎","category":"门诊病历模板","raw":{"name":"隐匿性肾炎","category":"门诊病历模板","case":{"case_name":"门诊病历747","templates":{"主诉":"泡沫尿1天","现病史":"患者1周前无明显诱因出现隐匿性肾炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以泡沫尿1天为主诉、1周来逐渐加重并伴轻度乏力，隐匿性肾炎多无水肿、高血压等自觉症状，须完善尿常规检查明确有无镜下血尿、蛋白尿及管型，这是发现肾小球损伤最基础的筛查；查尿微量白蛋白与24小时尿蛋白定量，了解蛋白尿的确切程度并作为随访基线，指导后续是否需干预；完善肾功能、电解质检查了解肾小球滤过功能与电解质状态，明确有无肾功能受损；查泌尿系超声了解双肾大小、形态、皮质厚度及有无积水、结石、占位，排除其他原因所致的尿检异常；查血常规、肝功能、凝血功能以评估有无贫血、基础肝病及出血风险，并作为肾脏穿刺的术前必查项目；隐匿性肾炎可为系统性红斑狼疮、IgA肾病等疾病的早期表现，完善自身抗体检查以明确有无免疫系统疾病；若随访中蛋白尿加重或出现肾功能减退而病因不明，病情稳定后行肾脏穿刺活检明确病理类型；因本病常病情隐匿、进展缓慢，需长期定期复查尿常规、尿蛋白定量、肾功能与血压，动态评估病情变化。\n\n（检查清单）\n【必做检查】\n尿常规、尿微量白蛋白、24小时尿蛋白定量、肾功能、电解质\n\n【影像学检查】\n泌尿系超声、肾脏穿刺（必要时）\n\n【其他检查】\n血常规、肝功能、凝血功能、自身抗体（必要时）","初步诊断":"1. 隐匿性肾炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 本病多数患者无需特殊药物治疗，以定期随访监测为主；切忌滥用药物，避免使用肾毒性药物（如氨基糖苷类抗生素、非甾体抗炎药、含马兜铃酸的中草药及保健品）。\n2. 尿蛋白定量持续＞0.5g/24h 或合并高血压者，首选 ACEI/ARB 类药物：贝那普利片 10mg qd 口服，或氯沙坦钾片 50mg qd 口服，长期维持，据血压及血肌酐调整剂量，用药期间定期监测血压、血钾及肾功能。\n3. 反复上呼吸道感染诱发血尿加重或尿蛋白增多者，予抗感染对症治疗：阿莫西林胶囊 0.5g tid×5～7天（青霉素过敏者改用头孢呋辛酯片 0.25g bid×5～7天）。\n【一般治疗及生活指导】\n1. 注意休息，避免劳累、熬夜、剧烈运动及精神紧张，保证充足睡眠，生活规律。\n2. 低盐饮食（每日食盐＜6g），蛋白质适量摄入（每日0.8～1.0g/kg），忌高蛋白、高嘌呤饮食，避免暴饮暴食及进食辛辣刺激食物。\n3. 预防感染：注意保暖，防治上呼吸道感染、扁桃体炎、皮肤感染等，感染为血尿及蛋白尿加重最常见诱因，出现感染应及时就诊处理。\n4. 慎用造影剂，避免乱用保健品及\"偏方\"中药，日常饮水适量（每日1500～2000ml），不宜过度憋尿。\n【随诊要求】\n1. 每3～6个月复查尿常规、尿沉渣镜检、24小时尿蛋白定量、血压、血肌酐，并记录尿检结果动态变化。\n2. 每年至少复查1次肾功能及尿微量白蛋白/肌酐比值；若24小时尿蛋白持续＞1g、血压升高或出现水肿、肉眼血尿，应及时至肾内科复诊，必要时行肾穿刺活检明确病理类型及指导治疗。\n3. 反复扁桃体炎诱发血尿加重者，可至耳鼻喉科评估行扁桃体摘除术；育龄期女性妊娠前应行肾脏专科评估，妊娠期加强监测。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":879,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8fde9869b9e13f887b4ff0217021fba04bbe0eb822435c7384d2b55e126f47ae","pinyin":"yinnixingshenyan","initials":"ynxsy","setting":"out","caseName":"门诊病历747","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历747",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e6c27d9745899cdf969e","key":"v1-c9ccc21dfe2a3058|templates-e6c27d9745899cdf969e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"急性肾衰竭","category":"门诊病历模板","raw":{"name":"急性肾衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历748","templates":{"主诉":"尿量减少伴水肿、乏力恶心3天","现病史":"患者因急性肾损伤（AKI）就诊，既往按肾前性、肾性、肾后性分类，分类是处理关键。诱因包括：肾前性因素，如血容量不足（出血、脱水、呕吐腹泻、烧伤，为最常见）、心力衰竭或低血压（休克、脓毒症、心源性）、肝肾综合征、非甾体抗炎药或血管紧张素转换酶抑制剂，上述因素导致肾灌注下降、肾血流下降，属功能性改变，多可逆；肾性因素，如急性肾小管坏死，可由缺血（休克、脓毒症，肾前性状态延长未纠正即进展）或肾毒性（药物如氨基糖苷类、造影剂（造影剂肾病，重要）、非甾体抗炎药、两性霉素、顺铂，毒素如肌红蛋白（挤压伤、横纹肌溶解，可见酱油色尿，重要）、血红蛋白（溶血））引起，还包括急性间质性肾炎（药物过敏，可见发热、皮疹、嗜酸细胞增多，参见间质性肾炎）、肾小球肾炎（急进性，血尿、蛋白尿，免疫相关）、血管病变（血管炎、血栓）；肾后性因素，即梗阻，如前列腺增生（老年男性常见）、结石或肿瘤，可位于双侧或独肾、膀胱（尿潴留，前列腺）、输尿管（双侧结石或肿瘤压迫）。患者于诱因后数小时至数日出现：少尿（尿量<400ml/日，或无尿<100ml/日，见于肾小管坏死或梗阻，提示程度）、水肿（眼睑、下肢，水钠潴留、尿少所致，可遍及全身，严重者肺水肿、呼吸困难、端坐呼吸，属急症）、乏力、恶心呕吐（尿毒症毒素潴留）、食欲减退、意识改变（尿毒症脑病，嗜睡、抽搐）、呼吸困难（肺水肿或容量过负荷、心衰）、高血压、心律失常（高钾所致，可致猝死，属急症，最为重要，血钾>6.5mmol/L时危及生命）、出血（尿毒症致血小板功能下降，可见消化道出血）、瘙痒、酱油色尿（横纹肌溶解、肌红蛋白尿）、血尿（肾小球肾炎）、发热皮疹（间质性肾炎）、腰痛、排尿困难或无尿（梗阻、肾后性）。分期按KDIGO标准：血肌酐升高（48小时内升高≥26.5μmol/L或升高≥1.5倍基线）、尿量<0.5ml/kg/h持续6小时；分期为1~3期，按肌酐及尿量评估。今日来我院肾内科或急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P88次/分，R18次/分，BP150/90mmHg（血压偏高提示容量过负荷，偏低提示休克）、体重（增加提示水潴留）。神志（清楚或嗜睡，嗜睡提示尿毒症脑病）、水肿（眼睑、下肢或全身，呈凹陷性）、肺部（湿啰音提示肺水肿、容量过负荷）、心脏（心率增快，高钾可致心律失常）、腹部（膀胱充盈提示尿潴留、肾后性，肾区叩痛）、皮肤（瘀斑、皮疹提示间质性病变）、血压（高血压见于肾小球肾炎或容量过负荷）、尿量（记录，必要时导尿评估）、神经（扑翼样震颤提示尿毒症）。","辅助检查":"【必做】肾功能（血肌酐，急性升高，为核心指标，需动态监测以行KDIGO分期；尿素氮）、电解质（血钾，高钾最为重要，属急症，需查心电图；钠、钙、磷）、血气（代谢性酸中毒）、尿常规（尿比重：肾前性者高（>1.020）、浓缩；肾小管坏死者低、等渗。尿蛋白、血尿提示肾小球肾炎；尿糖）、尿沉渣（红细胞管型提示肾炎、颗粒管型提示肾小管坏死、嗜酸性粒细胞提示间质性肾炎）、尿钠及钠排泄分数（肾前性者尿钠<20、排泄分数<1%，属功能性改变、可逆；肾小管坏死者尿钠>40、排泄分数>2%；用于鉴别，重要）、肝肾功能、血常规（贫血提示肾衰或溶血）、肌酸激酶（横纹肌溶解时升高，伴肌红蛋白尿）、血培养（脓毒症）、尿酸、血糖；【影像】肾脏超声（排除梗阻（肾后性，可见肾盂积水、双肾）、观察肾脏大小（急性者正常或增大，慢性者缩小，用于鉴别）、血流（彩色多普勒）、膀胱（残余尿，提示梗阻））；【其他】疑肾小球肾炎或血管炎者查自身抗体（抗核抗体、抗中性粒细胞胞浆抗体、抗基底膜抗体）、补体、肾活检（指征为病因不明、急进性肾炎、疑血管炎，可确诊并指导治疗，重要）、心电图（高钾时T波高尖，可致心律失常）、胸片（肺水肿）、尿渗透压。","初步诊断":"1. 急性肾损伤（AKI，KDIGO分期1~3期；分型：肾前性、肾性（急性肾小管坏死、间质性肾炎、肾小球肾炎）、肾后性（梗阻）；需评估高钾及容量过负荷，属急症）\n（注：治疗原则为去除病因加支持治疗、防治并发症，为核心，部分可逆：①去除病因、纠正诱因：肾前性者补液（纠正低血容量：出血者输血，脱水者补液，但心衰者需利尿，应评估容量，可参考中心静脉压，谨慎补液）、停用肾毒性药物（非甾体抗炎药、氨基糖苷类、血管紧张素转换酶抑制剂，此类药物在肾前性状态下可加重病情，须停用，重要；造影剂，予水化预防）、脓毒症者抗感染加液体复苏加血管活性药（改善灌注）、梗阻者解除梗阻（导尿（前列腺、膀胱）、双J管或经皮肾造瘘（输尿管梗阻））；②高钾血症处理（属急症，血钾>6.5mmol/L或心电图改变时：葡萄糖酸钙拮抗心肌毒性，最为重要，立即使用；胰岛素加葡萄糖促钾内移；碳酸氢钠纠正酸中毒；排钾利尿（呋塞米）；树脂口服降钾；透析用于顽固病例，紧急措施，重要）；③容量管理（少尿者限制液量，量出为入，按500ml加尿量计算，防止容量过负荷、肺水肿；利尿（呋塞米）可试验性使用，用于容量过负荷时，并非所有少尿者都需利尿；肺水肿属急症，予利尿或透析）；④透析指征（严重高钾且药物无效、严重酸中毒、容量过负荷（肺水肿）、尿毒症症状（脑病、心包炎）、严重电解质紊乱；可行血液透析或腹膜透析，为生命支持手段，等待肾功能恢复，重要）；⑤营养（高热量，适量蛋白（0.8~1.0g/kg，不宜限制过严，透析者增加）、电解质（磷、钙、镁）、监测）；⑥恢复期（多尿期利尿，需防脱水及低钾，予补液补钾；随访肾功能（多数急性肾小管坏死可完全恢复，需数周至数月；部分可慢性化，需长期随访）、病因，急性肾损伤后慢性肾脏病风险升高，需随访，重要）；由肾内科或ICU诊治，病因鉴别是关键（肾前性、肾性、肾后性），须重视高钾急症、透析指征，支持治疗、防止不可逆，重要。","处理方案":"【药物治疗】\n1. 袢利尿剂消肿：呋塞米片20mg po qd（晨服），连用3～5天，用于少尿期容量负荷过重者（前提：排除梗阻及低血容量），服药期间每日监测体重、24小时尿量及电解质；若尿量不增或出现利尿剂抵抗，立即停药并转住院行肾脏替代治疗。\n2. 纠正高钾血症：聚苯乙烯磺酸钠散15g po tid（加温水搅匀口服），同时严格限钾饮食；若血钾>6.5mmol/L或伴心电图高尖T波、QRS增宽，应急诊处理：10%葡萄糖酸钙注射液10ml缓慢静脉推注（3～5分钟），并联系肾内科住院行血液净化。\n3. 纠正代谢性酸中毒：碳酸氢钠片0.5g po tid，连用3～5天，据血气分析及血HCO₃⁻结果调整剂量，目标血HCO₃⁻≥18mmol/L；合并心力衰竭或容量负荷过重者慎用，避免钠负荷加重水肿。\n4. 对症支持：血压升高者选用钙通道阻滞剂（如氨氯地平片5mg po qd），避免使用ACEI/ARB及保钾利尿剂（螺内酯），以免加重高钾血症及加重肾损伤。\n\n【一般治疗及生活指导】\n1. 休息：急性期应卧床休息，避免劳累、剧烈运动、熬夜及精神紧张，病情稳定、尿量增多后可逐步增加活动量。\n2. 饮食：低盐、低钾、低磷、适量优质蛋白饮食（蛋白质0.6～0.8g/kg/d），少尿期严格限水（每日液体入量=前一日尿量+500ml），每日晨起测体重并记录24小时尿量；忌食香蕉、橙子、土豆、坚果、浓肉汤等高钾食物。\n3. 禁忌：禁用一切肾毒性药物及食物，包括非甾体抗炎药（布洛芬、双氯芬酸、对乙酰氨基酚过量）、氨基糖苷类抗生素、含马兜铃酸的中草药及保健品、静脉造影剂；未经医生指导不得自行服用任何药物。\n4. 监测：每日监测血压、体温及尿量变化，观察有无水肿加重、呼吸困难、恶心呕吐、乏力等症状，出现异常及时就医。\n\n【随诊要求】\n1. 治疗后3～5天复诊，复查血肌酐、尿素氮、血电解质及血气分析，评估肾功能恢复趋势；恢复期（多尿期）每周复查1次肾功能及电解质，直至肌酐恢复正常或进入稳定平台期。\n2. 若出现持续无尿（24小时尿量<100ml）、血钾进行性升高、血肌酐每日上升>44.2μmol/L、药物难以控制的代谢性酸中毒、肺水肿或尿毒症症状（恶心呕吐、意识障碍），须立即急诊并住院行血液透析或CRRT，切勿延误。\n3. 病因明确后至肾内科专科门诊随访3～6个月，完善尿常规、24小时尿蛋白、肾脏超声等检查明确肾损伤性质，评估远期肾功能恢复及是否转慢性肾脏病，指导后续用药及长期管理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":880,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d798b8c3720ff2d46947af7262ad1b01e74720015428046b01d982baa7a6dca6","pinyin":"jixingshenshuaijie","initials":"jxssj","setting":"out","caseName":"门诊病历748","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历748",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5e8062b2b8501db20da6","key":"v1-c9ccc21dfe2a3058|templates-5e8062b2b8501db20da6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"慢性肾衰竭","category":"门诊病历模板","raw":{"name":"慢性肾衰竭","category":"门诊病历模板","case":{"case_name":"门诊病历749","templates":{"主诉":"乏力、食欲减退伴水肿、夜尿增多5年","现病史":"患者有慢性肾小球肾炎（IgA肾病，为我国常见类型；基础肾病还可为糖尿病肾病，属最常见病因，是我国2型糖尿病所致终末期肾病的首要原因，须重视；高血压肾损害，因慢性高血压致肾小球硬化；多囊肾，为遗传性、多有家族史；以及梗阻性肾病、狼疮性肾炎、间质性肾炎等，明确病因并针对性控制可延缓进展），病程8年，按CKD分期（依据肾小球滤过率：1期≥90，为正常并伴肾损伤标志；2期60~89；3期30~59；4期15~29；5期<15，即终末期、尿毒症），并结合白蛋白尿分期（A1~A3，蛋白尿为进展因素），于1年前（慢性、渐进，历时数年）逐渐出现：消化系统症状（食欲减退、恶心、呕吐，因尿毒症毒素蓄积所致，为最早且最常见的表现；口臭，呈氨味）、乏力（由贫血及毒素蓄积引起，进行性加重）、贫血（肾性贫血，因促红细胞生成素减少，表现为乏力、苍白、心悸，较普遍）、水肿（水钠潴留，见于下肢及眼睑，重者可致肺水肿、端坐呼吸、心衰）、高血压（肾性高血压，与水钠潴留及肾素系统激活有关，常较难控制）、夜尿增多及多尿（浓缩功能下降，为早期表现）、皮肤瘙痒（与毒素蓄积、钙磷代谢紊乱有关）、骨痛（肾性骨病，与钙磷代谢紊乱、继发性甲状旁腺功能亢进有关）、出血倾向（血小板功能异常）、神经系统表现（周围神经病变可致麻木，尿毒症脑病见于晚期，可嗜睡、抽搐、昏迷）、月经紊乱或性功能减退、心肌损害（尿毒症心肌病，可致心衰，为主要死因）、电解质紊乱（高钾、高磷、低钙）、代谢性酸中毒、体重下降，以上均属代谢紊乱，晚期即尿毒症期，需行透析或肾移植；并发症包括心血管并发症（为主要死因，如心衰、心梗、卒中，CKD患者心血管风险升高，须重视）、感染（免疫力下降）、消化道出血、骨折。今日来我院肾内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P82次/分，R18次/分（尿毒症酸中毒时可呈深大呼吸），BP160/95mmHg（高血压，常较难控制）。神志清楚（尿毒症脑病多见于晚期，可表现为嗜睡）、贫血貌（面色苍白）、水肿（眼睑及下肢凹陷性水肿，重者波及全身）、皮肤（干燥、瘙痒、可见抓痕及色素沉着）、口臭（呈氨味；皮肤可见尿素霜）、心脏（心界扩大，可闻及心包摩擦音，提示尿毒症心包炎，多见于晚期，属急症）、颈静脉（怒张，提示心衰）、肺部（可闻及湿啰音，提示肺水肿或尿毒症肺）、眼底（可见高血压或糖尿病视网膜病变）、神经（扑翼样震颤，见于尿毒症；周围神经感觉减退）、骨（压痛，提示肾性骨病）、体重（用于评估营养状况）。","辅助检查":"【必做】肾功能（血肌酐、尿素氮、肾小球滤过率（估算肾小球滤过率，为分期核心指标））、电解质（血钾（升高提示危险）、钠、钙磷（高磷低钙提示肾性骨病）、二氧化碳结合力（评估酸中毒））、血常规（评估贫血程度，血红蛋白反映肾性贫血程度）、肝功能、白蛋白（评估营养状况）、血脂、血糖及糖化血红蛋白、尿酸；【骨代谢】甲状旁腺激素（继发甲旁亢，与肾性骨病相关）、25-羟维生素D（多降低）、碱性磷酸酶（反映骨转换）；【影像】肾脏超声（观察肾脏大小，慢性者CKD3~5期多缩小，皮质变薄、回声增强）、排除梗阻、囊肿、多囊肾等病因；【并发症评估】心电图（高钾、左室肥大）、超声心动图（心功能、心包积液）、眼底（高血压视网膜病变）、骨密度（肾性骨病）、腹部血管（钙化）；【随访】尿蛋白（尿白蛋白肌酐比，用于分期及评估进展）、肾小球滤过率（动态监测进展速率）。","初步诊断":"1. 慢性肾脏病（CKD）4期（按肾小球滤过率分期），白蛋白尿A3期；病因考虑慢性肾小球肾炎，需除外糖尿病、高血压等；并发症包括贫血、高血压、肾性骨病、代谢性酸中毒，并需评估终末期肾脏病。\n（注：治疗以延缓进展联合并发症管理为主，终末期需肾脏替代治疗：①病因治疗（为延缓进展的核心：糖尿病者严格控糖，糖化血红蛋白<7%，并予肾保护，可用钠-葡萄糖协同转运蛋白2抑制剂（达格列净或恩格列净），可降蛋白尿、延缓CKD进展，无论有无糖尿病近年均作为一线用药，须重视；高血压者血压控制<130/80mmHg，首选血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂，可降蛋白尿、具肾保护作用，须重视，并可联合钠-葡萄糖协同转运蛋白2抑制剂；慢性肾炎者按病理予免疫抑制治疗；多囊肾者予托伐普坦延缓进展；梗阻者解除梗阻）；②延缓进展（低盐低蛋白饮食，0.8g/kg/d，CKD3期后为0.6~0.8g/kg/d，加复方α-酮酸，可减少氮质、防止营养不良，需注意平衡；控制蛋白尿，用血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂，目标<0.5g/日；避免肾毒性药物，如非甾体抗炎药、造影剂，须重视；控制尿酸）；③并发症管理（贫血：予促红细胞生成素，如罗沙司他或重组人促红素，目标血红蛋白100~120g/L，并予铁剂补铁，优先补铁，监测铁蛋白，须重视；高血压：降压，可防心血管事件并延缓进展；肾性骨病：降磷，采用饮食限磷加磷结合剂（碳酸钙或司维拉姆），随餐服用，并用活性维生素D（骨化三醇）纠正低钙、治疗继发甲旁亢，继发甲旁亢严重者用西那卡塞；酸中毒：予碳酸氢钠，维持血碳酸氢盐>22mmol/L；高钾：低钾饮食，予聚苯乙烯磺酸钠，严重时按急症处理；血脂：予他汀，对心血管有益，须重视；心衰：综合治疗）；④终末期肾脏病管理（肾小球滤过率<15ml/min/1.73m²即为尿毒症，应评估肾脏替代治疗：血液透析（建立血管通路，动静脉瘘宜提前3~6个月建立，须重视）、腹膜透析（可居家，为可选择的治疗方式）、肾移植（最佳，长期生存获益，需评估供体）；启动指征为肾小球滤过率<10~15ml/min/1.73m²或出现尿毒症症状、难以控制的并发症，应适时启动，须重视；维持血液透析每周3次）；⑤随访（肾内科每1~3个月复查肾小球滤过率、电解质、血红蛋白、血压、蛋白尿，监测进展；每6~12个月复查钙磷、甲状旁腺激素及超声；转诊准备：肾小球滤过率<30ml/min/1.73m²转肾脏病专科，<15ml/min/1.73m²进行透析或移植教育，把握时机；患者教育：饮食、药物、自我监测血压、体重、尿量）。肾内科负责病因治疗加延缓进展、并发症管理及终末期肾脏替代，需多学科长期管理。","处理方案":"【药物治疗】\n1. 控制血压、延缓肾功能进展（首选RAS阻断剂）：缬沙坦胶囊80mg po qd（或贝那普利片10mg po qd），监测血压及血肌酐、血钾，若肌酐较基线升高>30%或血钾>5.5mmol/L需减量或停药。\n2. 纠正肾性贫血：重组人促红素注射液3000IU ih 每周2次，Hb目标110~120g/L；同时口服多糖铁复合物胶囊150mg qd（或琥珀酸亚铁片0.1g tid），空腹及餐后血铁蛋白<200μg/L时补铁。\n3. 调节钙磷代谢、防治继发性甲旁亢：醋酸钙片0.667g po tid（餐中嚼服）或碳酸钙D3片0.6g po qd（餐中服），控制血磷；血磷正常后加用骨化三醇软胶囊0.25μg po qd，监测血钙磷。\n4. 优质低蛋白饮食配合：复方α-酮酸片4片 po tid（餐中服），配合每日蛋白质摄入0.6g/kg，延缓肾功能恶化。\n\n【一般治疗及生活指导】\n1. 饮食：优质低蛋白（0.6~0.8g/kg·d，以蛋、奶、瘦肉为主）、低盐（<5g/d）、低磷、低钾饮食，限制高磷食物（动物内脏、坚果、浓汤）及高钾食物（香蕉、橘子、土豆），控制饮水，保持出入量平衡。\n2. 休息与活动：适当休息，避免劳累、熬夜及剧烈运动，注意保暖、预防感冒及感染；每日晨起测血压、体重，记录尿量。\n3. 用药禁忌：禁用或慎用非甾体抗炎药（布洛芬、双氯芬酸等）、氨基糖苷类、含马兜铃酸中草药及造影剂等肾毒性药物；未经医师指导勿自行服用保健品及\"补肾\"类中药。\n4. 戒烟限酒，积极控制血糖、血脂、尿酸，避免脱水（腹泻、大汗后及时补液）。\n\n【随诊要求】\n1. 每1~3个月门诊复查血常规、肾功能（血肌酐、尿素氮、eGFR）、电解质（血钾、血钙、血磷）、尿常规、尿蛋白定量及血压。\n2. 每3~6个月复查血清白蛋白、甲状旁腺激素（PTH）、铁代谢指标（血清铁蛋白、转铁蛋白饱和度）；贫血及钙磷紊乱者按医嘱缩短复查间隔。\n3. eGFR<15ml/min/1.73m²或出现顽固性高钾、水肿、少尿、尿毒症症状者，及时就诊评估血液透析、腹膜透析或肾移植等肾脏替代治疗时机，必要时转肾内科专科治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":881,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"148cbca4732c6afcc8d37e9e23b058b5802b6e5be757548b90f75dba963e0262","pinyin":"manxingshenshuaijie","initials":"mxssj","setting":"out","caseName":"门诊病历749","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历749",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e2244a1cdb0489e86bbd","key":"v1-c9ccc21dfe2a3058|templates-e2244a1cdb0489e86bbd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"尿毒症","category":"门诊病历模板","raw":{"name":"尿毒症","category":"门诊病历模板","case":{"case_name":"门诊病历750","templates":{"主诉":"乏力、恶心呕吐伴水肿少尿1年","现病史":"患者为慢性肾脏病终末期（肾小球滤过率<15ml/min/1.73m²，CKD5期），基础肾病考虑糖尿病肾病、高血压肾硬化、慢性肾小球肾炎（IgA肾病）、多囊肾、狼疮肾炎、梗阻性肾病或间质肾炎等，病程多年渐进，既往通过肌酐升高及肾小球滤过率下降进行监测，目前为透析或移植状态。患者于10年前起病，逐渐出现以下表现：消化系统方面，食欲减退、恶心呕吐，与尿毒症毒素蓄积有关，可伴口臭氨味及消化道出血倾向；全身乏力，与肾性贫血有关，因促红细胞生成素减少所致，可见面色苍白、心悸；心血管系统方面，血压难以控制，可出现心力衰竭、肺水肿，与容量过负荷有关，亦可出现尿毒症心包炎及动脉粥样硬化；神经系统方面，可出现周围神经病致末梢麻木，以及尿毒症脑病，表现为嗜睡、意识模糊、扑翼样震颤，晚期可出现抽搐、昏迷，并可有不安腿综合征。骨骼方面可出现肾性骨病，因高磷低钙及继发性甲状旁腺功能亢进所致，表现为骨痛、易骨折；皮肤瘙痒与磷潴留及毒素蓄积有关；尿量减少至无尿；电解质紊乱方面，高钾血症危险，可引起心律失常甚至猝死，并可有代谢性酸中毒。此外需评估贫血程度、血压控制情况、透析充分性、干体重及血管通路情况，并进行肾移植评估；心力衰竭与感染为常见死因。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P82次/分，R18次/分（深大，提示酸中毒），BP165/95mmHg（偏高），SpO2 95%。神志清楚，呈贫血貌；双下肢凹陷性水肿；皮肤干燥、瘙痒、可见抓痕及尿毒霜样色素沉着；呼气有氨味；心脏查体心界扩大，可闻及心包摩擦音及奔马律；肺部可闻及湿啰音，提示肺水肿；颈静脉怒张；可有腹水；扑翼样震颤阳性，提示尿毒症脑病；神经系统检查周围感觉减退、腱反射减弱；可有骨压痛；透析通路处可触及瘘震颤或见导管；呈恶病质表现。","辅助检查":"【必做】肾功能（肌酐、尿素氮、肾小球滤过率<15ml/min/1.73m²，为诊断依据）、电解质（血钾，为危险指标；钠、钙、磷，可见高磷低钙；二氧化碳结合力，用于判断酸中毒）、血常规（贫血，观察血红蛋白）、白蛋白（营养状况低下）、铁蛋白或转铁蛋白饱和度（评估铁状态，指导促红素治疗）、甲状旁腺激素（评估继发性甲旁亢）、维生素D、碱性磷酸酶、肝功能、血糖、糖化血红蛋白、血脂、尿酸；【影像】肾脏超声（可见肾脏缩小、皮质变薄或多囊肾，并可排除梗阻）、心脏超声（观察心包积液及心功能）、心电图（高钾时T波高尖，可见左室肥厚）、胸片（观察肺水肿及心影增大）、骨密度；【透析评估】充分性（尿素清除率或干体重、血压、水肿）、血管通路（多普勒或感染评估）、并发症（低血压、肌肉痉挛）；【移植评估】HLA配型或供体、多学科评估；【其他】感染（导管血培养）、肿瘤筛查（长期透析者）。","初步诊断":"1. 尿毒症（终末期肾病，CKD5期，肾小球滤过率<15ml/min/1.73m²；基础肾病；并发症包括贫血、高钾、酸中毒、肾性骨病、心包炎、脑病；肾脏替代治疗（透析或移植）状态及评估）\n（注：治疗：肾脏替代治疗为核心，包括血液透析（维持每周2~3次，动静脉内瘘需提前3~6个月建立，为重要环节）、腹膜透析（居家进行）、肾移植（最佳选择，长期生存获益，移植前需评估心血管及感染，移植后需终身免疫抑制）；启动时机为肾小球滤过率<10~15ml/min/1.73m²或出现尿毒症症状、难以控制的并发症，应适时透析，此点重要。并发症处理：贫血予促红细胞生成素或罗沙司他，目标Hb 100~120g/L，并补铁，监测铁蛋白；高血压控制目标<140/90mmHg，通过干体重及容量管理，选用ACEI或ARB；高钾予限钾饮食教育、降钾药，高钾急症时予钙剂、胰岛素加葡萄糖；高磷予限磷饮食加磷结合剂随餐服用；继发甲旁亢予活性维生素D或西那卡塞；酸中毒予碳酸氢钠；肾性骨病予钙剂、维生素D及磷管理；心衰予容量管理，必要时透析超滤；心包积液严重压塞时予穿刺，并加强透析；脑病予透析纠正。营养方面：优质低蛋白饮食，透析后适当增加蛋白摄入以补充透析丢失；限盐限水，透析间期体重增长<3~4%；限磷、限钾、限钠。随访：定期评估透析充分性、电解质、血压、贫血及骨代谢指标；药物依从性（磷结合剂、降压药、促红素）；血管通路护理；移植等待管理；心理支持；晚期患者进行临终及姑息治疗讨论）。","处理方案":"【药物治疗】\n1. 降压治疗：氨氯地平片5mg qd口服，目标血压＜140/90mmHg；伴蛋白尿者可联合缬沙坦胶囊80mg qd（监测血钾，血钾＞5.5mmol/L或高钾倾向者慎用），血压未达标者可加用β受体阻滞剂（如美托洛尔缓释片47.5mg qd）。\n2. 纠正肾性贫血：重组人促红细胞生成素3000IU皮下注射，每周2-3次，联合琥珀酸亚铁片0.1g tid（餐后服），维持血红蛋白100-120g/L，定期复查血常规、铁蛋白及转铁蛋白饱和度以调整剂量。\n3. 纠正钙磷代谢紊乱及继发性甲旁亢：碳酸钙D3片600mg tid餐中嚼服（与含铁药物间隔2小时以上），骨化三醇胶丸0.25μg qd口服，根据血钙、血磷、iPTH水平调整，定期复查防止高钙血症。\n4. 排毒辅助治疗（延缓病情进展，不能替代透析）：药用炭片（爱西特）1.2g tid口服，与牛奶、其他药物间隔2小时服用；若出现难以控制的高钾血症、严重代谢性酸中毒、心力衰竭或尿毒症脑病等，须尽快行血液透析/腹膜透析或肾移植评估。\n\n【一般治疗及生活指导】\n1. 休息与活动：避免劳累及剧烈运动，保证充足睡眠，可进行散步等轻度活动；水肿或血压明显升高者应卧床休息。\n2. 饮食：优质低蛋白饮食，蛋白质摄入量0.6-0.8g/kg/d，以鸡蛋、牛奶、瘦肉等优质蛋白为主；低盐（每日＜3g）、低磷低钾，忌食香蕉、橙子、土豆、蘑菇、坚果、动物内脏、浓汤等高钾高磷食物；控制饮水，每日液体入量＝前日尿量＋500ml，水肿明显者遵医嘱进一步限水。\n3. 禁忌：禁用肾毒性药物（非甾体抗炎药如布洛芬、双氯芬酸，氨基糖苷类抗生素，含马兜铃酸的中草药及偏方）；避免使用含镁、铝的抗酸剂；避免脱水、腹泻、大汗导致血容量不足。\n4. 自我监测：每日清晨测体重、血压并记录24小时尿量，监测有无乏力、恶心、皮肤瘙痒、胸闷气促、下肢水肿加重等变化。\n\n【随诊要求】\n1. 每周门诊复诊，复查血常规、肝肾功能、电解质（重点血钾）、血气分析（二氧化碳结合力）、尿常规，动态评估eGFR。\n2. 每1-3个月复查血钙、血磷、甲状旁腺激素（iPTH）、铁蛋白及转铁蛋白饱和度；每6个月复查胸片、心电图、心脏彩超。\n3. 出现少尿/无尿（24小时尿量＜400ml）、高钾血症、严重酸中毒、心力衰竭、消化道出血、抽搐或意识改变等危急情况，立即急诊就诊；符合透析指征（eGFR＜15ml/min/1.73m²或出现难以纠正的尿毒症并发症）时应及时住院评估并启动血液透析、腹膜透析或肾移植治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":882,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e09f735af3845438e0322f6cac35f308427f9c180ae0e0d9e7bc946754d731cc","pinyin":"niaoduzheng","initials":"ndz","setting":"out","caseName":"门诊病历750","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历750",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0df58eb287779248b614","key":"v1-c9ccc21dfe2a3058|templates-0df58eb287779248b614","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"间质性肾炎","category":"门诊病历模板","raw":{"name":"间质性肾炎","category":"门诊病历模板","case":{"case_name":"门诊病历751","templates":{"主诉":"水肿1天","现病史":"患者1周前无明显诱因出现间质性肾炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以水肿1天为主诉、1周来逐渐加重并伴轻度乏力，间质性肾炎常与药物、感染或免疫因素相关，须先完善尿常规检查明确有无无菌性脓尿、血尿、蛋白尿及尿糖，评估肾小管间质损伤；查尿微量白蛋白与24小时尿蛋白定量，了解蛋白尿程度，间质性肾炎蛋白尿通常轻至中度，有助于与其他肾小球疾病鉴别；完善肾功能、电解质检查明确有无肾功能减退及低钾、低钠、代谢性酸中毒等肾小管功能障碍表现；查泌尿系超声了解双肾大小、形态、皮质厚度及有无积水、结石，排除梗阻性因素；查血常规、肝功能、凝血功能以评估有无感染、贫血、基础肝病及出血风险，并作为肾脏穿刺的术前必查；因本病常继发于自身免疫性疾病或药物过敏，完善自身抗体检查以明确病因，并详细追问近期用药史；若肾功能持续恶化而病因不明，病情稳定后行肾脏穿刺活检明确病理类型，指导是否应用糖皮质激素；治疗期间定期复查尿常规、肾功能、电解质与尿蛋白定量，评估疗效并及时停用可疑致病药物。\n\n（检查清单）\n【必做检查】\n尿常规、尿微量白蛋白、24小时尿蛋白定量、肾功能、电解质\n\n【影像学检查】\n泌尿系超声、肾脏穿刺（必要时）\n\n【其他检查】\n血常规、肝功能、凝血功能、自身抗体（必要时）","初步诊断":"1. 间质性肾炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 糖皮质激素：醋酸泼尼松片，成人0.5~1mg/(kg·d)（常用30~40mg），晨起顿服，适用于急性间质性肾炎停用可疑致病药物后1周肾功能无改善者；疗程4~6周，有效后每1~2周减量5mg直至停药，用药期间监测血糖、血压、血钾及感染征象。\n2. 碱化尿液、纠正酸中毒：碳酸氢钠片1.0g tid口服，依据血气分析及尿pH调整剂量，维持血HCO₃⁻≥22mmol/L、尿pH 6.5~7.0。\n3. 降尿酸治疗（合并高尿酸血症者）：非布司他片40mg qd（或别嘌醇片100mg bid，用药前筛查HLA-B*5801，按eGFR调整剂量），目标血尿酸<360μmol/L，并与碱化尿液同用以防尿酸盐结晶沉积。\n4. 降压保肾（合并高血压或蛋白尿者）：氯沙坦钾片50mg qd，血压未达标可增至100mg qd，目标血压<130/80mmHg；用药后1~2周复查血肌酐及血钾，血钾>5.5mmol/L或eGFR显著下降时减量或停药。\n【一般治疗及生活指导】\n1. 立即停用可疑致病药物（非甾体抗炎药、含马兜铃酸成分中草药、青霉素类及头孢类抗生素、质子泵抑制剂等），避免使用氨基糖苷类抗生素、造影剂及其他肾毒性药物；急性期卧床休息，缓解后避免劳累、熬夜。\n2. 保证充分饮水，每日尿量维持在2000ml以上（心、肾功能允许时），促进尿酸及毒素排泄；避免脱水、剧烈运动及高温环境大量出汗。\n3. 低盐饮食（每日食盐<5g），优质蛋白摄入0.8~1.0g/(kg·d)，合并水肿或高血压者限制水钠摄入；少食高嘌呤食物（动物内脏、浓肉汤、海鲜等），避免饮酒及含糖饮料。\n4. 忌烟酒，慎用保健品及成分不明中草药；就诊时主动告知医师慢性肾病病史，避免重复用药及自行加药。\n【随诊要求】\n1. 急性期每1~2周复查血肌酐、尿素氮、eGFR、电解质、尿常规及尿沉渣镜检、24小时尿蛋白定量；停用糖皮质激素后每月复查1次，至少随访3~6个月至肾功能及尿检稳定。\n2. 慢性间质性肾炎每1~3个月复查血肌酐、eGFR、血电解质（重点血钾）、血气分析、血尿酸、尿常规；每6个月行肾脏超声检查，动态监测血压、血糖、血脂。\n3. 出现尿量明显减少、水肿加重、血肌酐进行性升高、血钾升高或恶心呕吐等症状时，立即复诊或急诊就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":883,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cfd35b510f2f200ba2b48d104a63b7d79b7cb2cfdf9a35d860185a653162a5cc","pinyin":"jianzhixingshenyan","initials":"jzxsy","setting":"out","caseName":"门诊病历751","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历751",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c4c148c0f43b2eebb548","key":"v1-c9ccc21dfe2a3058|templates-c4c148c0f43b2eebb548","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾结核","category":"门诊病历模板","raw":{"name":"肾结核","category":"门诊病历模板","case":{"case_name":"门诊病历752","templates":{"主诉":"尿频1天","现病史":"患者1周前无明显诱因出现肾结核相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以尿频1天为主诉、1周来逐渐加重并伴轻度乏力，肾结核多继发于肺结核，须完善血常规、CRP、降钙素原检查明确有无感染及炎症活动程度；因结核常累及肺部，查胸部X线片，必要时行胸部CT检查以明确有无肺结核或粟粒性播散灶；完善痰培养+药敏检查以寻找结核病原学证据、指导抗结核用药；患者尿频提示尿路刺激症状，查尿常规并留取晨尿连续三次行尿抗酸杆菌涂片及结核分枝杆菌培养，是诊断肾结核的关键；完善泌尿系超声检查以了解肾实质破坏、空洞、钙化、肾积水及膀胱挛缩情况；患者伴轻度乏力、感染消耗，必要时行血气分析以评估酸碱平衡与氧合状态，排除合并肺部感染或呼吸功能受损；病情稳定后可查肺功能以评估肺通气功能，为抗结核治疗及可能的手术麻醉提供依据；此外建议查肾功能、电解质与泌尿系CT尿路成像，明确受累范围及对侧肾功能，为是否需手术切除病肾提供依据；抗结核治疗期间定期复查血常规、CRP、肝肾功能及尿抗酸杆菌，评估疗效与药物不良反应。\n\n（检查清单）\n【必做检查】\n血常规、CRP、降钙素原\n\n【影像学检查】\n胸部X线片/胸部CT\n\n【其他检查】\n痰培养+药敏、血气分析（必要时）、肺功能（稳定期）","初步诊断":"1. 肾结核\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗结核化学治疗（首选方案，全程督导服药）：\n（1）强化期（2个月）：异烟肼片0.3g qd + 利福平胶囊0.45g qd（晨起空腹顿服）+ 吡嗪酰胺片0.5g tid + 乙胺丁醇片0.75g qd；\n（2）巩固期（4～7个月）：异烟肼片0.3g qd + 利福平胶囊0.45g qd，总疗程6～9个月。\n2. 辅助用药：维生素B6片10mg tid，预防异烟肼所致周围神经炎；治疗期间每月监测肝功能，若转氨酶升高＞3倍正常上限，遵医嘱调整抗结核方案并加用保肝药（如水飞蓟宾胶囊70mg tid）。\n3. 肾功能不全者调整剂量：肌酐清除率＜50ml/min时乙胺丁醇减至0.5g qd或隔日0.75g，异烟肼酌减并密切监测；治疗期间禁用氨基糖苷类等肾毒性药物。\n4. 合并泌尿系感染时，根据尿培养及药敏结果选用敏感抗生素（如头孢呋辛酯片0.25g bid×7天）。\n\n【一般治疗及生活指导】\n1. 休息：活动期及血尿、腰痛明显时应卧床休息，保证充足睡眠，避免劳累、熬夜及剧烈运动，防止腰部撞击致患肾损伤。\n2. 饮食：高蛋白、高维生素、高热量均衡饮食（蛋、奶、瘦肉、新鲜蔬果），忌辛辣刺激及油腻食物；戒烟、戒酒（酒精可加重利福平肝损伤）。\n3. 多饮水：每日饮水2000～3000ml，稀释尿液、减轻结核病灶刺激；开放性肾结核者尿液中可排菌，排泄物及尿液应消毒处理，注意个人卫生，避免污染餐具及伤口。\n4. 禁忌：避免自行服用非甾体抗炎药（如布洛芬）、氨基糖苷类等肾毒性药物；育龄期患者治疗期间避孕。\n\n【随诊要求】\n1. 治疗期间每月复诊1次，复查肝功能、肾功能、血尿酸、血常规；强化期每月复查尿常规及尿抗酸杆菌涂片（或培养），巩固期每2～3个月复查1次。\n2. 疗程第2、5、6（9）个月末复查泌尿系超声及尿抗酸杆菌检查，必要时行CTU或IVU评估肾实质、肾盂及输尿管病灶变化；疗程结束前行尿抗酸杆菌培养，连续3次阴性且影像学病灶稳定方可停药。\n3. 每3～6个月复查胸片或胸部CT排除合并肺结核；建议密切接触家属行结核病筛查。\n4. 若出现无痛性全程血尿、腰腹痛加剧、发热盗汗、尿频尿急尿痛加重或尿量骤减，及时就诊；出现进行性肾积水或输尿管狭窄者，评估行输尿管支架置入或球囊扩张等外科干预指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":884,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0c70f31a566822e24ca9c182dc623127203f55ba824df21863f113f7cf3d0b3a","pinyin":"shenjiehe","initials":"sjh","setting":"out","caseName":"门诊病历752","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历752",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d88815bac478752e37b1","key":"v1-c9ccc21dfe2a3058|templates-d88815bac478752e37b1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"输尿管结石","category":"门诊病历模板","raw":{"name":"输尿管结石","category":"门诊病历模板","case":{"case_name":"门诊病历753","templates":{"主诉":"突发腰部绞痛伴血尿6小时","现病史":"患者因输尿管结石就诊。输尿管结石多源于肾结石排入输尿管，是最常见的泌尿外科急症之一。危险因素包括：饮水不足（最重要且可改变的因素）、高钙饮食或高草酸饮食（浓茶、菠菜等）、高嘌呤饮食（痛风、尿酸结石）、高盐饮食、动物蛋白摄入过多、家族结石史、代谢异常（甲状旁腺功能亢进、高尿酸血症）、尿路梗阻或感染及解剖结构异常，以及复发性结石（既往有结石史）。\n\n患者于夜间睡眠中突发腰部及下腹剧烈绞痛，疼痛呈阵发性，间歇期仍有隐痛，系结石移动刺激输尿管蠕动痉挛所致；疼痛沿输尿管走行向下放射至下腹、会阴、阴囊及股内侧，为输尿管结石的特征性表现，疼痛部位可提示结石位置：上段结石以腰部及中上腹痛为主，中段结石以下腹痛为主，下段结石可出现会阴部疼痛并伴尿频、尿急等膀胱刺激症状。同时可见血尿，多为镜下血尿，活动后加重，系结石摩擦输尿管黏膜所致；伴恶心、呕吐，为肾绞痛时迷走神经反射所致，临床表现常似急腹症。下段结石可刺激膀胱，出现尿频、尿急、尿痛。若合并感染，可出现发热、寒战，提示肾盂肾炎、肾积水或脓肾，属急症情况，需重视；结石合并发热须及时引流。双侧梗阻或独肾者可出现无尿，导致急性肾衰竭，临床少见但属急症。膀胱结石可表现为排尿痛及尿流中断，与输尿管结石不同。绞痛可持续数分钟至数小时，缓解后可再次发作，患者曾自行服用止痛药物，效果不佳。今日来我院急诊、泌尿外科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.8℃，P96次/分，R20次/分，BP130/80mmHg。肾区叩击痛（+），以患侧肋脊角为重，局部有压痛；腹部输尿管走行区（下腹）轻压痛，无反跳痛（借此与腹膜炎鉴别）；肾绞痛发作时患者辗转不安、不断变换体位，不能安静平卧，与腹膜炎患者静卧不动的表现不同，为肾绞痛的特征；膀胱区有压痛；伴发热提示合并感染，可伴寒战；全身可见恶心、冷汗等疼痛反应。","辅助检查":"【必做】尿常规：重点观察血尿情况（镜下红细胞为核心支持依据，但完全梗阻时可无血尿，尿检阴性亦不能排除结石）、白细胞（提示合并感染）、尿pH（尿酸结石时呈酸性）、尿结晶及尿培养（用于感染评估）；血常规（白细胞升高提示感染或炎症）、CRP（用于感染评估）、肾功能（肌酐，用于评估梗阻程度及肾功能受损情况）、电解质（血钙，作为结石病因初筛）、尿酸、血糖。\n\n【影像】超声为首选初筛检查，可发现肾积水（输尿管梗阻致上游扩张，为核心征象）、肾结石及输尿管上段扩张，中下段因肠气干扰显示较差；腹部CT（无增强CT为结石检查的金标准，敏感度高，＞95%可检出全部输尿管结石，最小可至1mm，并能明确定位、结石大小、梗阻及积水情况，为急诊首选检查，临床意义重要）；腹部X线平片可见结石钙化显影，但尿酸结石及小结石不显影，临床患者较少，多由CT替代。\n\n【其他】疑合并感染时行CT检查，观察有无积气或脓；梗阻严重或双侧梗阻者复查肾功能以评估损害程度；排出结石应收集行结石成分分析，对预防复发具有重要意义。","初步诊断":"1. 输尿管结石（右侧：下段；结石大小4mm；轻度肾积水；肾绞痛；合并感染及肾功能评估）\n（注：治疗原则为止痛、排石及处理并发症，按结石大小与位置选择方案）：①急性肾绞痛处理：止痛为核心，非甾体抗炎药（双氯芬酸或酮咯酸，肌注或肛栓给药，为一线用药，解痉止痛效果优于阿片类）、阿片类（非甾体抗炎药无效的剧烈疼痛，可选吗啡或哌替啶）、解痉（山莨菪碱或黄体酮，作辅助治疗）、充分饮水（每日2~3L，促进排石，但绞痛急性发作期以先止痛为主）、观察（小结石多可自行排出）。②排石治疗：结石＜6~7mm时输尿管自行排出机会大（＜5mm者约90%可自行排出），可用α受体阻滞剂（坦索罗辛0.4mg每日1次，扩张输尿管、促进并加速排石、减少绞痛发作，为重要的医学排石治疗方法），配合多饮水、运动（跳跃等辅助排石），并随访（2~4周复查，确认结石是否排出及影像学变化，未排出或进展者进一步处理）。③介入与手术：指征为结石＞7~10mm（自行排出困难，需干预）、肾绞痛反复发作且药物控制不佳、肾积水进行性或合并感染、合并感染（发热者属急症，需引流加抗菌治疗，可行输尿管支架（双J管）或经皮肾造瘘引流减压，先引流后二期取石，结石合并感染属急症，切勿先取石，以免引起脓毒症）、肾功能受损、结石嵌顿不动超过3个月。方式包括：体外冲击波碎石（适用于＜2cm的上段或肾结石，非侵入性，为首选方式之一）、输尿管镜碎石（钬激光，适用于下段、中段及上段结石，经尿道输尿管镜碎石取石，成功率高、微创，为现代常用术式）、经皮肾镜（适用于＞2cm的大肾结石）、开放手术（罕见，已基本被内镜手术替代）。④病因治疗及预防（关键在于防止复发，结石复发率高，5年复发率约50%，十分重要）：大量饮水（每日2.5~3L，保持尿量＞2L，为核心且最重要的措施）、饮食（限盐、适量钙，勿过度限钙，因钙可结合草酸、减少肠道草酸吸收，低钙反而使草酸结石增加，此点重要；限草酸，如菠菜、浓茶、坚果；动物蛋白适量摄入；尿酸结石可用别嘌醇并碱化尿液）、结石分析（排出结石应收集并行成分分析，以针对性预防，十分重要）、代谢评估（反复发作或有家族史者筛查血钙、尿酸及甲状旁腺功能亢进）、药物（噻嗪类用于高钙尿及复发者，枸橼酸盐用于碱化尿液及结石预防）。⑤随访：绞痛缓解后观察排石（2~4周行超声或CT复查结石位置及积水消退情况）、双J管留置4~6周后取出、碎石或术后复查结石清除情况、复发监测（每6~12个月行超声检查有无新结石）、肾功能恢复情况。急诊与泌尿外科处理原则为止痛、排石，结石＞7mm或有并发症者行碎石或内镜治疗，合并感染需急诊引流，并强调饮水以预防复发。","处理方案":"【药物治疗】\n1. α受体阻滞剂（促进排石）：坦索罗辛缓释胶囊0.4mg qd口服，连用2-4周，松弛输尿管平滑肌、缓解痉挛，促进直径≤10mm结石排出。\n2. 解痉镇痛（绞痛发作时）：双氯芬酸钠缓释胶囊75mg bid（餐后）或布洛芬缓释胶囊300mg bid，按需口服，单次疗程不超过3-5天；恶心呕吐明显者可加用间苯三酚片40mg tid。\n3. 抗感染（合并尿路感染时）：如尿常规提示白细胞/亚硝酸盐阳性，予左氧氟沙星片0.5g qd×5-7天，或头孢呋辛酯片0.25g bid×5-7天（青霉素/头孢过敏者禁用，用前确认过敏史）。\n【一般治疗及生活指导】\n1. 大量饮水：每日饮水2500-3000ml，保证24小时尿量≥2000ml，睡前及夜间加饮一次，稀释尿液、促进小结石排出并预防新结石形成。\n2. 适当活动：多做跳跃、跑步、上下楼梯等震动性运动，利用重力促进结石下行；绞痛发作期或肾积水明显时避免剧烈活动及颠簸。\n3. 饮食管理：低盐饮食（每日<6g），限制动物蛋白、高嘌呤及高草酸食物（动物内脏、海鲜、浓茶、菠菜、坚果、巧克力），避免高糖及含糖碳酸饮料；草酸钙结石者减少草酸摄入，尿酸结石者限制嘌呤并碱化尿液。\n4. 生活禁忌：避免久坐憋尿、过度劳累及饮酒，大量出汗后及时补水，保持每日规律排尿。\n【随诊要求】\n1. 用药2-4周后复查泌尿系彩超（或CT）及尿常规，评估结石位置、大小变化及排石情况；结石排出者建议留取结石行成分分析以指导预防。\n2. 结石>10mm或保守治疗4周结石无下移、伴明显肾积水、反复感染或肾功能损害者，建议泌尿外科行体外冲击波碎石（ESWL）或输尿管镜碎石取石术。\n3. 治疗期间出现剧烈绞痛反复发作、发热寒战、无尿或少尿、恶心呕吐不止时，立即急诊就诊。\n4. 排石成功后每3-6个月复查泌尿系彩超，监测有无新发结石。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":885,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"80f77857bf91529c4f09eab6eaed53bea4ad10aa23c02741dafc56d7f79b7daf","pinyin":"shuniaoguanjieshi","initials":"sngjs","setting":"out","caseName":"门诊病历753","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历753",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-08eef8c667c6f0527405","key":"v1-c9ccc21dfe2a3058|templates-08eef8c667c6f0527405","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膀胱结石","category":"门诊病历模板","raw":{"name":"膀胱结石","category":"门诊病历模板","case":{"case_name":"门诊病历754","templates":{"主诉":"排尿痛1天","现病史":"患者1周前无明显诱因出现膀胱结石相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以排尿痛1天为主诉、1周来逐渐加重并伴轻度乏力，膀胱结石常伴尿路感染与排尿梗阻，须先完善尿常规检查明确有无血尿、脓尿及结晶，评估结石对尿路黏膜的损伤；查尿培养以明确有无合并尿路感染并指导抗感染治疗，感染也是结石形成与增大的重要诱因；完善肾功能、电解质检查了解有无梗阻性肾病及代谢异常，为病因分析与治疗决策提供依据；患者为尿路结石好发人群，查前列腺特异性抗原以排除前列腺增生或前列腺癌所致继发性排尿梗阻与结石；完善泌尿系超声检查以了解膀胱内结石大小、数目、位置及有无肾积水、前列腺增生；查KUB平片了解有无阳性结石及其大致大小与位置，为选择碎石或取石方式提供依据；必要时查CT尿路成像，以明确结石精确大小、数目、位置及有无输尿管结石、上尿路积水；若存在排尿困难或残余尿增多，查尿流动力学评估膀胱逼尿肌功能与下尿路梗阻程度；拟行膀胱镜取石者，查膀胱镜可直视结石并同时处理，同时查前列腺液常规以排除前列腺炎；治疗期间定期复查尿常规、尿培养与泌尿系超声，评估排石及感染控制情况。\n\n（检查清单）\n【必做检查】\n尿常规、尿培养、肾功能、电解质、前列腺特异性抗原\n\n【影像学检查】\n泌尿系超声、KUB平片、CT尿路成像\n\n【其他检查】\n尿流动力学、膀胱镜、前列腺液常规","初步诊断":"1. 膀胱结石\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 合并泌尿系感染者首选抗感染：头孢呋辛酯片0.25g bid×5～7天；青霉素过敏者可选用左氧氟沙星片0.5g qd×5～7天。\n2. 促进排石：坦索罗辛缓释胶囊0.4mg qd，晨起口服，疗程2～4周，可松弛输尿管及膀胱颈部平滑肌，利于小结石排出。\n3. 解痉止痛：疼痛明显时予布洛芬缓释胶囊0.3g bid×3～5天，或间苯三酚注射液80mg静滴（急诊对症处理）。\n4. 碱化尿液：考虑尿酸结石者予枸橼酸氢钾钠颗粒10g tid，监测尿pH维持于6.2～6.8，疗程2～4周。\n\n【一般治疗及生活指导】\n1. 大量饮水：每日饮水量2000～3000ml，保持24小时尿量＞2000ml，稀释尿液、冲刷结石。\n2. 调整饮食：限制高嘌呤（动物内脏、海鲜、啤酒）及高草酸（菠菜、浓茶、坚果）食物，减少钠盐及动物蛋白摄入。\n3. 适当活动：避免久坐憋尿，可进行跳绳、原地跳跃等运动，促进小结石排出；结石＜0.5cm者可配合倒立排尿体位辅助排石。\n4. 禁忌：避免饮用浓茶、咖啡及含酒精饮料；忌辛辣刺激饮食，以免诱发膀胱刺激症状及感染加重。\n\n【随诊要求】\n1. 治疗1～2周后复查尿常规、泌尿系B超，评估结石排出及感染控制情况；排石期间嘱患者排尿时注意观察有无结石排出。\n2. 若出现排尿突然中断伴剧痛、肉眼血尿加重、发热寒战、急性尿潴留等，立即就诊。\n3. 结石直径＞2cm、保守治疗2～4周无效或反复并发感染者，建议转泌尿外科行膀胱镜碎石取石术或耻骨上膀胱切开取石术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":886,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"88a39475dcf1bba7acfad5de37faeeb168092cb14072c5e7c111a23edfc094f3","pinyin":"pangguangjieshi","initials":"pgjs","setting":"out","caseName":"门诊病历754","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历754",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-bf1f25386228a0d74f7a","key":"v1-c9ccc21dfe2a3058|templates-bf1f25386228a0d74f7a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"尿道结石","category":"门诊病历模板","raw":{"name":"尿道结石","category":"门诊病历模板","case":{"case_name":"门诊病历755","templates":{"主诉":"排尿痛1天","现病史":"患者1周前无明显诱因出现尿道结石相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以排尿痛1天为主诉就诊，1周前起症状逐渐加重并伴轻度乏力，需先完善血常规检查排除尿路感染及贫血所致乏力；查尿常规了解有无镜下血尿、白细胞及尿pH异常，明确结石是否存在黏膜损伤及合并感染；查便常规排除消化道疾病所致全身乏力；患者起病后需用解痉止痛药物并经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，评估用药安全性；查血糖、血脂了解代谢状态，评估结石形成的代谢性危险因素；本次排尿痛明显，完善电解质检查排除电解质紊乱；尿道结石定位与大小评估依赖影像，查腹部超声了解泌尿系有无结石、积水及输尿管扩张；查心电图排除心脏疾病所致不适并评估手术耐受性；查胸部X线片了解心肺基础情况，为可能的碎石或取石治疗作术前评估；病情稳定后建议定期复查尿常规及泌尿系超声，观察结石排出及有无复发。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 尿道结石\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. α受体阻滞剂促排石：盐酸坦索罗辛缓释胶囊0.4mg qd po×7-14天（晨起或睡前服，松弛尿道平滑肌、降低尿道张力，利于结石排出）；\n2. 解痉镇痛：双氯芬酸钠缓释片75mg qd po（疼痛明显时加用），或布洛芬缓释胶囊0.3g bid po，按需服用；\n3. 抗感染（合并尿路感染或拟行器械操作时）：左氧氟沙星片0.5g qd po×5-7天，或头孢克肟分散片0.1g bid po×5-7天；\n4. 碱化尿液辅助排石（草酸钙/尿酸结石）：枸橼酸氢钾钠颗粒2.5g tid po，饭后冲服，服用期间监测尿pH维持在6.2-6.8。\n\n【一般治疗及生活指导】\n1. 大量饮水：每日饮水量2000-3000ml，保持24小时尿量≥2000ml，分次均匀饮用，避免一次性大量饮水；\n2. 适当活动促排石：行跳绳、原地跳跃、上下楼梯等震动性运动，每日2-3次，每次15-30分钟，促进结石向远端移动排出；避免长时间久坐及剧烈骑跨运动；\n3. 饮食调整：限制高嘌呤食物（动物内脏、海鲜、浓肉汤）及高草酸食物（菠菜、浓茶、坚果），减少钠盐及动物蛋白摄入，忌酒及辛辣刺激性食物；\n4. 观察排尿：注意有无排尿困难、尿线变细、尿痛加剧，如出现完全排尿不能（急性尿潴留）禁止强行用力排尿，立即就医。\n\n【随诊要求】\n1. 用药后1-2周复诊，复查泌尿系超声/腹部平片（KUB）评估结石是否排出及有无继发感染；\n2. 若结石排出，建议行结石成分分析，针对结石类型调整饮食及药物预防复发；\n3. 治疗期间出现急性尿潴留、剧烈疼痛、发热寒战或肉眼血尿加重者，随时急诊就诊，必要时行尿道取石或手术处理；\n4. 结石排出或处理后3-6个月复查泌尿系超声及尿常规，长期随访监测有无结石复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":887,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"273d34503a8268a6a4d0f0a048e7abc11b4dea09cc2a318670c2de55e18c23c5","pinyin":"niaodaojieshi","initials":"ndjs","setting":"out","caseName":"门诊病历755","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历755",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-823fd8c015b778f43d1c","key":"v1-c9ccc21dfe2a3058|templates-823fd8c015b778f43d1c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾肿瘤","category":"门诊病历模板","raw":{"name":"肾肿瘤","category":"门诊病历模板","case":{"case_name":"门诊病历756","templates":{"主诉":"腰痛1天","现病史":"患者1周前无明显诱因出现肾肿瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以腰痛1天为主诉，1周前起症状逐渐加重并伴轻度乏力，肾脏占位性病变需先完善尿常规检查了解有无血尿及尿路感染征象；查尿微量白蛋白、24小时尿蛋白定量评估肾小球滤过功能受损程度，明确肿瘤是否累及肾单位；完善肾功能检查了解肌酐、尿素氮水平，为后续可能的肾部分切除或根治性手术提供基线依据；查电解质检查排除电解质紊乱；查泌尿系超声明确肾脏占位的大小、部位、回声性质及有无肾静脉瘤栓，作为首选初筛影像；若超声提示性质不明，必要时行肾脏穿刺活检明确病理类型，指导治疗方案选择；患者起病伴随乏力、需评估全身状况及有无贫血与转移，完善血常规检查；因穿刺或手术前需评估凝血状态，查凝血功能排除凝血机制异常；查肝功能了解有无肝转移及肝功能储备；若临床怀疑自身免疫性疾病或肿瘤相关免疫异常，必要时完善自身抗体检查以鉴别诊断；术后定期复查肾功能及泌尿系超声评估残余肾功能与复发情况。\n\n（检查清单）\n【必做检查】\n尿常规、尿微量白蛋白、24小时尿蛋白定量、肾功能、电解质\n\n【影像学检查】\n泌尿系超声、肾脏穿刺（必要时）\n\n【其他检查】\n血常规、肝功能、凝血功能、自身抗体（必要时）","初步诊断":"1. 肾肿瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 晚期肾癌一线靶向治疗（酪氨酸激酶抑制剂TKI类）：舒尼替尼胶囊 50mg po qd，连服4周停药2周（4/2方案），6周为一周期；用药期间监测血压、血常规、肝肾功能、甲状腺功能及手足皮肤反应，不耐受时减量至37.5mg qd。不能耐受或进展者换用阿昔替尼片 5mg bid po（可据血压及毒性在2.5～10mg bid间调整）。\n2. 中高危晚期肾透明细胞癌一线免疫联合治疗：帕博利珠单抗注射液 200mg iv q3w＋阿昔替尼片 5mg bid po，21天为一周期；用药前排除活动性自身免疫病及活动性感染，治疗期间监测甲状腺功能、肝酶、血糖及皮疹、腹泻、肺炎等免疫相关不良反应。\n3. 对症支持治疗：骨转移性疼痛按WHO三阶梯镇痛，中重度疼痛予盐酸羟考酮缓释片 10mg q12h po，据NRS评分每1～2天按25%～50%幅度滴定调整；轻中度疼痛且肾功能正常者可选用布洛芬缓释胶囊 0.3g bid po（肾功能不全者禁用NSAIDs）。\n4. 靶向药相关性高血压：予苯磺酸氨氯地平片 5mg qd po，血压不达标者增至10mg qd，目标血压<130/80mmHg；避免合用维拉帕米、地尔硫卓及强CYP3A4抑制剂/诱导剂，每周自测血压2～3次。\n\n【一般治疗及生活指导】\n1. 休息与活动：保证充足睡眠、避免劳累；术后3个月内避免负重、剧烈运动及腹部撞击挤压，之后逐步恢复散步、太极拳等中等强度有氧运动。\n2. 饮食：低盐、低脂、优质蛋白饮食，每日饮水2000ml以上保证充足尿量；戒烟限酒，少吃腌制、熏烤食物；不自行服用成分不明中草药及保健品。\n3. 用药禁忌：避免肾毒性药物（氨基糖苷类、含马兜铃酸中草药、长期大剂量非甾体抗炎药）；需行增强CT/MRI检查时主动告知肾肿瘤病史，检查前后注意水化。\n4. 合并症管理：合并高血压、糖尿病者规范用药，血压<130/80mmHg、空腹血糖<7.0mmol/L；超重者减重，BMI控制在18.5～24kg/m²。\n\n【随诊要求】\n1. 术后患者：术后3个月首次复查腹部增强CT/MRI，其后每6个月1次至术后2年，再后每年1次；每次同时复查血常规、肝肾功能、电解质、尿常规、血压，肾功能不全者加密监测。\n2. 靶向/免疫治疗患者：每2～4周门诊复诊，监测血压、血常规、肝肾功能、电解质、甲状腺功能、血糖及手足皮肤反应、免疫相关不良反应；每6～12周复查影像学按RECIST评估疗效。\n3. 主动监测患者（小肾肿瘤、低危复杂囊肿）：每3～6个月超声或CT复查，动态评估肿瘤大小与分期；若肿瘤最大径年增长>0.5cm或达4cm，及时转泌尿外科评估手术。\n4. 出现肉眼血尿、腰痛、腹部包块、不明原因消瘦、发热或新发骨痛、咳嗽咯血等，随时就诊；治疗期间出现不能耐受的不良反应及时复诊调整方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":888,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a6e1624ef52d486add3f751a139c441feacaa8579fbf8b7dde8b776f6a99ab59","pinyin":"shenzhongliu","initials":"szl","setting":"out","caseName":"门诊病历756","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历756",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2f68b9a7d0eb9c148335","key":"v1-c9ccc21dfe2a3058|templates-2f68b9a7d0eb9c148335","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"膀胱肿瘤","category":"门诊病历模板","raw":{"name":"膀胱肿瘤","category":"门诊病历模板","case":{"case_name":"门诊病历757","templates":{"主诉":"血尿1天","现病史":"患者1周前无明显诱因出现膀胱肿瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以血尿1天为主诉，1周前起症状逐渐加重伴轻度乏力，无痛性血尿首先需排除膀胱肿瘤所致，完善尿常规检查明确血尿程度及有无合并感染；查尿培养排除尿路感染所致血尿，为后续膀胱镜及手术操作提供安全前提；完善肾功能检查了解上尿路功能及肌酐水平，评估肿瘤有无梗阻致肾功能损害；查电解质排除电解质紊乱；查前列腺特异性抗原了解前列腺情况，与前列腺增生、前列腺癌所致血尿相鉴别；查泌尿系超声了解膀胱壁占位、大小、数目及有无上尿路积水；查KUB平片了解泌尿系有无结石及钙化影，排除结石所致血尿；完善CT尿路成像明确肿瘤浸润深度、上尿路情况及有无淋巴结转移，指导分期；病情稳定后行尿流动力学检查评估膀胱排尿功能，为保留膀胱治疗提供依据；择期行膀胱镜检查并取活检，明确病理类型与分级，是确诊膀胱肿瘤的金标准；同时查前列腺液常规鉴别前列腺炎性疾病所致血尿。\n\n（检查清单）\n【必做检查】\n尿常规、尿培养、肾功能、电解质、前列腺特异性抗原\n\n【影像学检查】\n泌尿系超声、KUB平片、CT尿路成像\n\n【其他检查】\n尿流动力学、膀胱镜、前列腺液常规","初步诊断":"1. 膀胱肿瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 膀胱灌注化疗（非肌层浸润性膀胱癌TURBT术后首选）：表柔比星注射液50mg加0.9%氯化钠注射液50ml溶解，经导尿管注入膀胱，夹闭导尿管嘱患者仰、俯、左、右侧卧位变换体位，使药液充分接触膀胱黏膜，保留1小时后排空；每周1次连用8周，此后改为每月1次连用10个月。灌注后大量饮水以稀释药液、减轻刺激。\n2. 免疫检查点抑制剂（肌层浸润性膀胱癌含铂方案失败后或PD-L1阳性者）：替雷利珠单抗注射液200mg，静脉滴注30～60分钟，每3周1次；每周期前复查血常规、肝肾功能及甲状腺功能，监测免疫相关不良反应。\n3. 全身化疗（转移性膀胱癌一线、顺铂适用者，GC方案）：吉西他滨1000mg/m²，静脉滴注30分钟，第1、8天；顺铂70mg/m²，静脉滴注（用药前后充分水化、利尿、止吐），第2天；21天为1周期，共4～6周期。\n4. 对症治疗：合并泌尿系感染者，左氧氟沙星片0.5g每日1次口服，疗程5～7天；明显肉眼血尿者，酚磺乙胺片0.5g每日3次口服，疗程3～5天，并嘱多饮水、注意休息。\n\n【一般治疗及生活指导】\n1. 饮食：每日饮水2000～2500ml，稀释尿液、减少对膀胱黏膜刺激；戒烟戒酒，避免辛辣刺激、腌制及高亚硝酸盐食物，多食新鲜蔬菜水果及富含维生素A、C的食物。\n2. 活动与休息：治疗期间保证充足睡眠，避免剧烈运动及重体力劳动；膀胱灌注当日适当减少活动，保留药液期间按医嘱定时变换体位，使药液均匀接触全部膀胱黏膜。\n3. 禁忌：绝对戒烟；避免接触苯胺类染料、橡胶、油漆、石油化工品等职业及环境致癌物；避免憋尿，养成规律排尿习惯；不自行服用含马兜铃酸的中草药（如关木通、广防己等）及不明成分保健品。\n4. 症状观察：注意观察尿色及排尿情况，如出现肉眼血尿、排尿疼痛、尿频尿急加重、腰腹痛等，及时记录并告知医师。\n\n【随诊要求】\n1. 非肌层浸润性膀胱癌TURBT术后：术后3个月行首次膀胱镜检查，其后每3～6个月复查1次，连续2年无复发可延长至每6～12个月1次，5年后每年1次；同步每3～6个月复查尿常规、尿脱落细胞学，每6～12个月行泌尿系超声或CT尿路造影（CTU）评估上尿路。\n2. 肌层浸润性膀胱癌根治术后：每3～6个月复查胸部CT、腹部及盆腔CT/MRI、尿常规、肝肾功能、电解质，监测局部复发与远处转移；术后终身随访。\n3. 接受化疗或免疫治疗者：每周期前复查血常规、肝肾功能；治疗期间出现发热、寒战、呼吸困难、严重乏力、血尿加重或排尿困难等及时就诊；化疗结束后2年内每3～6个月复查膀胱镜及胸腹盆影像学检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":889,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c391490a4a5db2127260a0c11aad5817e5813b7eee0601049c8ec9f752563f19","pinyin":"pangguangzhongliu","initials":"pgzl","setting":"out","caseName":"门诊病历757","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历757",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2674809acb16a03da71e","key":"v1-c9ccc21dfe2a3058|templates-2674809acb16a03da71e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"睾丸肿瘤","category":"门诊病历模板","raw":{"name":"睾丸肿瘤","category":"门诊病历模板","case":{"case_name":"门诊病历758","templates":{"主诉":"阴囊肿大1天","现病史":"患者1周前无明显诱因出现睾丸肿瘤相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以阴囊肿大1天为主诉，1周前起症状逐渐加重伴轻度乏力，需与睾丸肿瘤、鞘膜积液、附睾炎相鉴别，完善尿常规检查明确有无血尿及感染征象；查尿培养排除尿路感染所致阴囊肿胀及疼痛；完善肾功能检查了解肌酐、尿素氮水平，为可能的腹膜后淋巴结清扫或化疗提供基线；查电解质排除电解质紊乱；查前列腺特异性抗原了解前列腺情况，排除前列腺病变所致阴囊及会阴部症状；查泌尿系超声明确睾丸及附睾形态、有无实性占位、鞘膜积液及腹膜后情况，是阴囊肿大首选影像检查；查KUB平片排除泌尿系结石及钙化；完善CT尿路成像了解腹膜后淋巴结有无转移及上尿路情况；查尿流动力学检查评估排尿功能，排除下尿路梗阻所致不适；病情需要时行膀胱镜检查排除膀胱病变；查前列腺液常规鉴别前列腺炎所致会阴部放射不适。\n\n（检查清单）\n【必做检查】\n尿常规、尿培养、肾功能、电解质、前列腺特异性抗原\n\n【影像学检查】\n泌尿系超声、KUB平片、CT尿路成像\n\n【其他检查】\n尿流动力学、膀胱镜、前列腺液常规","初步诊断":"1. 睾丸肿瘤\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 一线化疗（经病理确诊的转移性生殖细胞肿瘤，转肿瘤内科日间化疗病房执行）：BEP方案：顺铂20mg/m²静脉滴注d1-5，依托泊苷100mg/m²静脉滴注d1-5，博来霉素30U静脉注射d1、8、15，21天为1周期，低危者共3周期、中高危者共4周期；每次化疗前后充分水化，尿量维持2000ml/日以上。\n2. 预防性止吐（顺铂高致吐方案，每次化疗前使用）：阿瑞匹坦胶囊125mg化疗前1小时口服d1、80mg口服d2-3，联合昂丹司琼片8mg化疗前口服、化疗后8mg每12小时口服×3天。\n3. 疼痛对症（睾丸肿痛或术后切口痛）：轻中度疼痛予布洛芬缓释胶囊0.3g bid口服；效果不佳或中重度疼痛改用氨酚羟考酮片1片q6h口服，按需限时限量并遵麻醉药品处方管理规定。\n4. 化疗后骨髓抑制支持：每周复查血常规，白细胞＜2.0×10⁹/L或中性粒细胞＜1.0×10⁹/L时予重组人粒细胞集落刺激因子150μg皮下注射qd，直至血象恢复。\n【一般治疗及生活指导】\n1. 确诊后限期行腹股沟入路根治性睾丸切除术，术前避免挤压、揉捏肿物，严禁经阴囊途径穿刺活检或经阴囊切口手术（可致局部复发及区域淋巴结转移）；术后患侧阴囊以托带托起。\n2. 饮食：高蛋白、高维生素、易消化饮食，保证充足营养；化疗期间每日饮水2000ml以上，促进顺铂排泄、保护肾功能。\n3. 休息与活动：术后4-6周内避免剧烈运动、负重及骑跨动作，防止切口裂开与血肿；治疗期间保证充足睡眠，避免劳累、熬夜。\n4. 禁忌：戒烟限酒；化疗期间及停药后至少6个月内严格避孕（化疗药物具生殖毒性与致畸作用）；有生育需求者，治疗前尽早行精子库精子冻存。\n【随诊要求】\n1. 术后第1年每3个月、第2年每4-6个月、第3年起每6-12个月复诊1次，至少随访5年（I期精原细胞瘤随访10年）。\n2. 每次复诊复查肿瘤标志物（AFP、β-hCG、LDH）、血常规及肝肾功能，行胸部CT、腹部及盆腔CT（重点观察腹膜后淋巴结）和对侧睾丸超声。\n3. 化疗期间每周复查血常规、肝肾功能；出现发热、口腔黏膜炎、咯血、呼吸困难等化疗相关不良反应时随时复诊。\n4. 出现对侧睾丸肿痛、腰背部疼痛、颈部或锁骨上包块、咳嗽咯血、不明原因消瘦或发热等疑似复发转移征象时，立即复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":890,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cf8030cd97f0179c36a5859fd901e69c3e286a4f9245a35da3131e5bccdda301","pinyin":"gaowanzhongliu","initials":"gwzl","setting":"out","caseName":"门诊病历758","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历758",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-08a9b7b2f567618b44b3","key":"v1-c9ccc21dfe2a3058|templates-08a9b7b2f567618b44b3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"阴茎癌","category":"门诊病历模板","raw":{"name":"阴茎癌","category":"门诊病历模板","case":{"case_name":"门诊病历759","templates":{"主诉":"阴茎肿物1天","现病史":"患者1周前无明显诱因出现阴茎癌相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以阴茎肿物1天为主诉，1周前起症状逐渐加重伴轻度乏力，需按阴茎恶性肿瘤规范完善检查，先查血常规了解有无贫血及感染征象；完善肝肾功能检查评估药物代谢与手术耐受性，排除肝肾功能不全；查电解质排除电解质紊乱；因需行肿物活检或手术切除，查凝血功能排除凝血机制异常；完善肿瘤标志物检查（如SCC等）了解肿瘤负荷并作为疗效监测基线；行超声检查明确肿物大小、边界、血流及有无腹股沟淋巴结肿大；查CT了解腹股沟及盆腔淋巴结转移情况并评估分期；查MRI明确肿物浸润深度及有无海绵体、尿道受累；必要时完善PET-CT检查明确有无远处转移，指导治疗方案选择；行病理活检明确病理类型及分化程度，是确诊阴茎癌的金标准；完善免疫组化检查明确分子分型；必要时行基因检测指导靶向及免疫治疗选择；若怀疑骨髓受累或需化疗前评估，必要时行骨髓穿刺检查；治疗期间定期复查肿瘤标志物及影像学检查评估疗效。\n\n（检查清单）\n【必做检查】\n血常规、肝肾功能、电解质、凝血功能、肿瘤标志物\n\n【影像学检查】\nCT、MRI、PET-CT、超声\n\n【其他检查】\n病理活检、免疫组化、基因检测、骨髓穿刺（必要时）","初步诊断":"1. 阴茎癌\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 预防感染（活检/术后或创面继发感染）：头孢呋辛酯片0.25g bid po×5～7天；对头孢类过敏者改用左氧氟沙星片0.5g qd po×5天。\n2. 创面局部处理：莫匹罗星软膏适量外用bid，涂于阴茎局部溃疡/糜烂创面，连用7天，避免用手搔抓。\n3. 镇痛：洛索洛芬钠片60mg tid po（疼痛明显时服用，连续不超过5天）；或布洛芬缓释胶囊0.3g bid po，饭后服用。\n4. 确诊后按分期评估根治方案，需化疗者（如局部晚期/转移性病变）遵肿瘤科医嘱使用顺铂为基础的联合方案（如TIP：紫杉醇+异环磷酰胺+顺铂），具体剂量按体表面积计算，门诊不自行调整。\n【一般治疗及生活指导】\n1. 保持阴茎及包皮局部清洁干燥，每日温水清洗1～2次并擦干，勤换宽松棉质内裤，避免摩擦、搔抓刺激病灶；包皮过长/包茎者暂勿强行上翻。\n2. 治疗及术后恢复期（至少6～8周）禁止性生活及手淫，避免局部充血、创伤，防止出血和感染。\n3. 戒烟限酒，均衡营养，多食优质蛋白（鱼、蛋、奶、瘦肉）及新鲜蔬果，保证充足睡眠，避免劳累，增强机体抵抗力。\n4. 及时与家属沟通，完善腹股沟淋巴结超声/CT、胸片等分期检查，及早决定根治性手术等治疗方案，勿延误。\n【随诊要求】\n1. 术后第1～2年每3个月复查1次，第3～5年每6个月1次，5年后每年1次；复查包括局部查体、腹股沟淋巴结触诊及B超、胸片等。\n2. 若出现局部红肿、渗液增多、疼痛加重、创面不愈合、阴茎肿块复发或腹股沟淋巴结肿大，应立即返诊。\n3. 接受放疗或化疗者，按放疗科/肿瘤科医嘱定期复查血常规、肝肾功能及原发灶、区域淋巴结影像学，出现发热、出血、严重骨髓抑制等不良反应及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":891,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d7da9e998d8db963654fd8c2733ab7f57c15c1d68976db1ee3b9198483d0c150","pinyin":"yinjingai","initials":"yja","setting":"out","caseName":"门诊病历759","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历759",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8d88441d77e435b0aefd","key":"v1-c9ccc21dfe2a3058|templates-8d88441d77e435b0aefd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"睾丸炎","category":"门诊病历模板","raw":{"name":"睾丸炎","category":"门诊病历模板","case":{"case_name":"门诊病历760","templates":{"主诉":"睾丸肿痛伴发热3天","现病史":"患者（病因包括：病毒性，即腮腺炎后病毒性睾丸炎，多见于青少年及成人，常于腮腺炎后4~7天发病，以单侧多见；细菌性，属上行感染，继发于尿道炎、前列腺炎，多为大肠杆菌，多见于老年，常表现为附睾睾丸炎；性传播，由衣原体、淋菌引起，多见于年轻性活跃者；疫苗，接种MMR可预防）于1天前出现：睾丸肿痛（突发胀痛、下坠感，可放射至腹股沟及下腹）、睾丸肿大（约为正常的2~3倍，触痛明显）、发热（38~40℃，病毒性或细菌性均可出现）、腮腺肿大（可先于或后于睾丸肿痛出现）、阴囊皮肤红肿，病变以单侧为主。需与以下疾病鉴别：睾丸扭转（青少年突发剧痛，无发热及尿路症状，为精索扭转急症，6小时内手术可挽救血供，Doppler超声示血流减少，属重要鉴别）、附睾炎（附睾先出现压痛）、创伤、肿瘤（多表现为无痛肿块）、鞘膜积液。并发症包括睾丸萎缩（腮腺炎性双侧受累者约30%，存在不育风险）及慢性疼痛。可伴尿路症状（细菌性者可有尿频、尿痛及尿道分泌物）。需询问疫苗接种史。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T38.8℃，P102次/分，R22次/分，BP118/72mmHg。睾丸患侧肿大、触痛明显，附睾肿大伴压痛（符合附睾睾丸炎），阴囊红肿、皮温升高，精索增粗，Prehn征阳性（托起阴囊后疼痛缓解，提示炎症），对侧睾丸未见异常；可见腮腺肿大、尿道口分泌物（细菌性者），腹股沟淋巴结可触及肿大，伴发热。","辅助检查":"【必做】血常规（细菌性者白细胞升高，病毒性者可正常）、CRP、尿常规（细菌性者可见白细胞）、血培养（高热者）、腮腺炎血清学（IgM抗体，用于确诊）、衣原体及淋菌核酸检测（年轻、性活跃者）；【影像】阴囊彩色多普勒超声（为核心检查：睾丸炎时睾丸血流增多，睾丸扭转时血流减少或消失，为鉴别关键，属重要项目；并可显示睾丸肿大、回声不均、脓肿及脓腔、附睾增大）；【其他】精子分析（随访睾丸萎缩及不育）、促卵泡激素及睾酮（睾丸萎缩者随访）。","初步诊断":"1. 病毒性睾丸炎（腮腺炎后，单侧，伴发热及腮腺肿大；已通过多普勒超声血流检查排除睾丸扭转；已评估脓肿、睾丸萎缩及不育等并发症）\n（注：治疗：病毒性（腮腺炎性睾丸炎）以对症为主（卧床、阴囊托起、冷敷、非甾体抗炎药止痛，肿痛严重者短期口服泼尼松），多为自限性，1~2周缓解，需随访有无睾丸萎缩；细菌性者予抗生素（经验性用药：老年患者需覆盖大肠杆菌，可用左氧氟沙星500mg qd×10~14天或头孢类；年轻性传播者予头孢曲松单剂+多西环素10~14天，性伴需同治），形成脓肿者行穿刺引流或切开引流，合并败血症（老年、免疫低下者）需住院静脉用药；鉴别睾丸扭转（青少年突发剧痛、Doppler血流减少者应急诊手术探查，切勿按睾丸炎用抗生素观察，延误将丧失睾丸，属重要事项）；支持治疗：阴囊托高、休息、退热、多饮水；随访：1~2周复查消肿情况，3~6个月超声测量睾丸体积评估萎缩，双侧受累者行精子分析评估生育，接种MMR疫苗可预防腮腺炎性睾丸炎，属重要措施）。","处理方案":"【药物治疗】\n1. 抗生素（首选覆盖肠道菌群及性传播病原体）：左氧氟沙星片0.5g po qd×7天；或头孢克肟分散片0.1g po bid×7天（可疑衣原体/淋球菌感染时加用多西环素片0.1g po bid×10天）。\n2. 抗炎镇痛：布洛芬缓释胶囊0.3g po bid×5天，疼痛明显者可换用塞来昔布胶囊0.2g po qd×5天（饭后服，减轻睾丸肿胀及疼痛）。\n3. 对症处理：阴囊坠胀剧痛者予吲哚美辛栓0.1g 纳肛，疼痛缓解后停用（用药期间注意胃肠道反应）。\n\n【一般治疗及生活指导】\n1. 急性期卧床休息，用丁字带或毛巾卷抬高阴囊以减轻坠胀、坠痛，避免久站、久坐及剧烈运动、提重物。\n2. 急性期（发病48小时内）局部冰袋冷敷，每次15～20分钟、每日3～4次；48小时后改温热敷促进炎性渗出吸收。\n3. 清淡易消化饮食，忌辛辣刺激及烟酒，多饮水；急性期暂禁性生活，恢复期（症状消失2周内）仍应避免。\n4. 注意保持会阴部清洁干燥，穿宽松棉质内裤，避免阴囊局部受压及外伤。\n\n【随诊要求】\n1. 用药3天后复诊评估疗效；若持续高热不退、阴囊红肿加重或疼痛剧烈，须立即就诊，警惕睾丸脓肿、睾丸梗死等并发症。\n2. 疗程结束后复查血常规、尿常规及阴囊彩超，评估炎症消退情况。\n3. 症状完全缓解后4～6周复查精液常规评估生育功能；双侧或反复发作者建议泌尿外科门诊定期随访。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":892,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e84cbed323b11f289d4faed72a9f8469aa3d233a171a34d4c0998a90a683758b","pinyin":"gaowanyan","initials":"gwy","setting":"out","caseName":"门诊病历760","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历760",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-891387a0103a311282b7","key":"v1-c9ccc21dfe2a3058|templates-891387a0103a311282b7","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"精囊炎","category":"门诊病历模板","raw":{"name":"精囊炎","category":"门诊病历模板","case":{"case_name":"门诊病历761","templates":{"主诉":"血精1天","现病史":"患者1周前无明显诱因出现精囊炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以血精1天为主诉，1周前起症状逐渐加重伴轻度乏力，血精需先排除感染及肿瘤所致，完善血常规检查了解有无感染及贫血；查尿常规明确有无血尿、白细胞及尿路感染并存的可能；查便常规排除消化道疾病所致全身乏力；患者需用抗感染药物治疗且经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，评估用药安全性；查血糖了解有无糖尿病等感染易患因素，血脂了解代谢状态；查电解质排除电解质紊乱；完善心电图排除心脏疾病所致不适，评估治疗安全性；查胸部X线片了解心肺基础情况，排除结核等感染性疾病所致血精；查腹部超声了解前列腺、精囊及泌尿系情况，明确有无精囊增大、结石或占位；因血精需与精囊肿瘤、前列腺病变相鉴别，病情稳定后建议复查经直肠超声及精液检查，观察精囊炎症消退情况。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 精囊炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗生素（首选，喹诺酮类）：左氧氟沙星胶囊0.5g po qd×14天（本类药物脂溶性好，精囊腺组织浓度高，为精囊炎首选；如耐药可换用莫西沙星片0.4g po qd×14天）。\n2. 联合抗非典型病原体：阿奇霉素片0.5g po qd×3天（覆盖衣原体、支原体等感染，常与喹诺酮类联用）。\n3. 止血对症：血精明显者加用氨甲环酸片0.5g po tid×5～7天；疼痛明显者加用塞来昔布胶囊0.2g po qd×5～7天。\n4. 缓解排尿及射精不适：坦索罗辛缓释胶囊0.2mg po qd×14天（改善射精痛、排尿不畅等梗阻相关症状）。\n\n【一般治疗及生活指导】\n1. 急性期适当卧床休息，避免久坐、久站及长时间骑车压迫会阴；治疗期间（至少2～4周）暂停性生活及手淫，减少性冲动所致精囊充血、加重出血。\n2. 饮食清淡，忌辛辣刺激及饮酒、咖啡，多饮水（每日2000ml以上），保持大便通畅、避免用力排便。\n3. 温水坐浴（水温40℃左右），每日1～2次，每次15～20分钟，促进局部血液循环；注意会阴部保暖。\n4. 规律作息，避免熬夜、过度劳累，戒烟，增强抵抗力以利感染消退。\n\n【随诊要求】\n1. 用药1～2周后门诊复诊，评估血精、射精痛等症状变化，复查尿常规；必要时复查精液常规。\n2. 症状持续或治疗后血精反复者，及时复诊，完善经直肠超声（TRUS）等检查，评估精囊扩张、囊壁增厚及结石情况。\n3. 治疗后血精消失但精液参数异常者，建议3个月后复查精液分析。\n4. 若出现高热、寒战、会阴部剧痛等急性加重表现，随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":893,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"46b940b7729ba1568750128b7fafbc5763529ede445c4925965cf2418b588d08","pinyin":"jingnangyan","initials":"jny","setting":"out","caseName":"门诊病历761","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历761",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-0709bb5def7db21caab8","key":"v1-c9ccc21dfe2a3058|templates-0709bb5def7db21caab8","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"包皮过长","category":"门诊病历模板","raw":{"name":"包皮过长","category":"门诊病历模板","case":{"case_name":"门诊病历762","templates":{"主诉":"排尿不适1天","现病史":"患者1周前无明显诱因出现包皮过长相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以排尿不适1天为主诉，1周前起症状逐渐加重伴轻度乏力，包皮过长易致包皮垢积聚及反复感染，需完善血常规检查排除感染及贫血所致乏力；查尿常规明确有无尿路感染及尿糖异常；查便常规排除消化道疾病所致全身不适；若考虑择期行包皮环切术，需完善肝肾功能检查排除肝肾功能不全，评估麻醉及用药安全性；查血糖了解有无糖尿病，因高血糖显著增加术后感染及切口愈合不良风险；查血脂了解代谢状态；查电解质排除电解质紊乱；完善心电图排除心脏疾病所致不适，评估手术耐受性；查胸部X线片了解心肺基础情况，作为术前常规评估；查腹部超声了解泌尿系有无结石、积水等合并病变；术前建议复查尿常规确认无活动性感染，病情稳定后择期手术治疗。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 包皮过长\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 局部消毒清洗（首选）：1:5000高锰酸钾溶液稀释后浸泡清洗龟头及包皮内板，每日2次，每次10～15分钟，连用5～7天；清洗拭干后外涂莫匹罗星软膏适量，每日2次，连用5～7天。\n2. 抗真菌外用（疑念珠菌性龟头包皮炎时）：克霉唑乳膏适量涂于患处，每日1～2次，连用7～14天。\n3. 口服抗菌药物（炎症明显或伴全身感染征象时）：头孢克肟分散片0.1g，每日2次，连用5～7天；青霉素过敏者改用左氧氟沙星片0.5g，每日1次，连用5～7天。\n4. 口服镇痛药（疼痛明显者）：布洛芬缓释胶囊0.3g，每日2次，必要时服用，不超过3天。\n\n【一般治疗及生活指导】\n1. 每日翻转包皮用温水清洗龟头及冠状沟并彻底擦干，保持局部清洁干燥，及时清除包皮垢，防止诱发感染。\n2. 穿宽松棉质透气内裤并勤更换，内裤清洗后阳光暴晒或煮沸消毒；避免久坐、长时间骑车等局部压迫与摩擦。\n3. 清淡饮食，忌辛辣刺激食物，戒烟限酒，多饮水，减少局部充血刺激。\n4. 急性炎症期避免性生活及手淫，症状完全消退后再恢复；清洗时勿强行翻转包皮，防止发生包皮嵌顿。\n\n【随诊要求】\n1. 用药治疗1周后复诊，评估龟头包皮炎症状消退情况；症状无缓解或反复发作，建议转泌尿外科进一步诊治。\n2. 反复感染、影响排尿或性生活质量者，建议择期行包皮环切术，术前完善血常规、凝血功能等检查。\n3. 若出现包皮嵌顿、局部红肿热痛加重、化脓或发热，需立即就诊，急诊处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":894,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8cfef686d8c6aff791a8470e14efa9882afa418659c4c963b0873e3f94d1fea0","pinyin":"baopiguochang","initials":"bpgc","setting":"out","caseName":"门诊病历762","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历762",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b24805643385c585b8ed","key":"v1-c9ccc21dfe2a3058|templates-b24805643385c585b8ed","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"包茎","category":"门诊病历模板","raw":{"name":"包茎","category":"门诊病历模板","case":{"case_name":"门诊病历763","templates":{"主诉":"反复包茎相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现包茎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以反复包茎相关不适1周、加重1天为主诉，包茎可致排尿不畅、包皮垢积聚及反复感染，需完善血常规检查排除感染及贫血所致乏力；查尿常规明确有无尿路感染及有无尿糖异常；查便常规排除消化道疾病所致全身不适；若考虑择期行包皮环切术，需完善肝肾功能检查排除肝肾功能不全，评估麻醉及用药安全性；查血糖了解有无糖尿病，因高血糖显著增加术后感染及切口愈合不良风险；查血脂了解代谢状态；查电解质排除电解质紊乱；完善心电图排除心脏疾病所致不适，评估手术耐受性；查胸部X线片了解心肺基础情况，作为术前常规评估；查腹部超声了解泌尿系有无结石、积水等合并病变；术前建议复查尿常规确认无活动性感染，病情稳定后择期手术治疗。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 包茎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 包皮口松解治疗：0.05%倍他米松软膏（或0.1%糠酸莫米松乳膏）局部涂抹于包皮口及龟头处，每日2次，连用4～6周，可促进包皮口纤维组织软化、松解，适用于轻度包茎及无急性感染者。\n2. 合并包皮龟头炎（红肿、分泌物）：1:5000高锰酸钾溶液稀释后浸泡清洗局部，每次10～15分钟，每日1～2次；随后外涂莫匹罗星软膏，每日2次，连用5～7天。\n3. 感染明显伴脓性分泌物或发热：头孢克肟胶囊0.1g，口服，每日2次，连用5～7天（青霉素过敏者改用左氧氟沙星片0.5g，口服，每日1次，连用5天）。\n4. 疑真菌性包皮龟头炎（白色膜状分泌物、瘙痒）：克霉唑乳膏局部涂抹，每日2次，连用7～14天。\n【一般治疗及生活指导】\n1. 保持会阴部清洁干燥，每日温水清洗外阴及包皮口，清洗后将包皮复位，避免局部潮湿滋生细菌。\n2. 严禁强行上翻包皮，以免造成包皮嵌顿；若发生嵌顿（包皮无法回纳、龟头青紫肿胀），须立即急诊处理复位。\n3. 饮食清淡，忌辛辣刺激及饮酒，多饮水；规律作息，避免久坐及局部摩擦刺激。\n4. 炎症急性期及药物治疗期间避免性生活和手淫，待炎症消退、包皮口松解后再恢复。\n【随诊要求】\n1. 药物治疗后2～4周门诊复诊，评估包皮口松解情况及感染控制效果。\n2. 保守治疗4～6周无效、反复发生包皮龟头炎或包皮口呈瘢痕性狭窄者，建议转泌尿外科门诊评估，择期行包皮环切术。\n3. 术后按医嘱按时换药、复诊观察伤口愈合情况，术后1周、1个月各复诊1次。\n4. 治疗期间如出现排尿困难、包皮嵌顿、局部红肿疼痛加重或发热，应立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":895,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bc3e78e42966c2c349b630219d0abbf7d9e8ffbed139f48011442825b4dd0f44","pinyin":"baojing","initials":"bj","setting":"out","caseName":"门诊病历763","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历763",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-53ff5cffb1be15ef8c95","key":"v1-c9ccc21dfe2a3058|templates-53ff5cffb1be15ef8c95","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"隐睾","category":"门诊病历模板","raw":{"name":"隐睾","category":"门诊病历模板","case":{"case_name":"门诊病历764","templates":{"主诉":"反复隐睾相关不适1周，加重1天。","现病史":"患者1周前无明显诱因出现隐睾相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以反复隐睾相关不适1周、加重1天就诊，伴轻度乏力，无明显发热及恶心呕吐，初步诊断隐睾，需完善血常规检查排除感染、贫血所致全身不适；完善尿常规检查了解有无泌尿系统感染及血尿；完善便常规检查排除消化道慢性失血导致的乏力；患者自服药物效果欠佳且后续若需手术干预，完善肝肾功能检查评估肝肾功能及手术耐受性；完善血糖、血脂检查了解代谢状态并评估围手术期风险；完善电解质检查排除电解质紊乱所致乏力；复查心电图排除心律失常及心肌缺血等手术禁忌；查胸部X线片了解心肺基础情况以评估麻醉与手术耐受性；完善腹部超声检查明确隐睾侧别、位置及有无合并腹股沟疝；必要时进一步行阴囊及腹股沟区超声或盆腔CT检查明确睾丸具体位置，为手术方案提供依据；门诊定期复查睾酮等性激素水平评估睾丸功能及发育情况。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 隐睾\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 促性腺激素治疗（激素敏感型隐睾/术前辅助）：注射用绒促性腺激素（HCG）1500～2000U，肌内注射，每周2次，共4周为一疗程；用药前后复查血清睾酮、FSH/LH及阴囊彩超评估睾丸位置变化。成人隐睾激素治疗多不敏感，疗程结束睾丸仍未下降者应尽快转泌尿外科行睾丸下降固定术。\n2. 合并急性附睾炎/睾丸炎的抗感染治疗：头孢呋辛酯片0.25g bid，共7～10天；或左氧氟沙星片0.5g qd，共7～14天。用药期间观察阴囊红肿热痛变化，停药后复查血常规、尿常规及阴囊彩超。\n3. 睾丸切除后性腺功能减退者的雄激素补充：十一酸睾酮软胶囊（安特尔）40mg～80mg bid，口服，连用3～6个月后评估疗效；用药期间定期监测血清睾酮、PSA、血常规、肝功能及血脂。\n\n【一般治疗及生活指导】\n1. 避免剧烈运动、跑跳、骑跨及提重物等增加腹压的动作，防止隐睾或术后睾丸损伤及精索扭转；久坐及骑自行车时注意会阴部减压，穿宽松透气内裤，减少紧身裤对腹股沟区的压迫。\n2. 避免局部高温环境（桑拿、热水浴、高温作业），以保护生精功能；保持阴囊及腹股沟区皮肤清洁干燥，每日温水清洗。\n3. 饮食均衡，适当增加优质蛋白及富含锌、硒食物（瘦肉、鱼虾、坚果、蛋类），戒烟限酒，规律作息，增强体质。\n4. 禁忌：禁止自行反复推挤或按摩睾丸，禁止局部热敷及使用成分不明外用药膏；出现患侧突发剧痛、恶心呕吐（警惕精索扭转）时立即急诊就诊。\n\n【随诊要求】\n1. 激素治疗期间每2～4周复诊1次，疗程结束后4周内复查阴囊彩超评估睾丸位置，未下降者及时转泌尿外科行睾丸下降固定术。\n2. 术后1、3、6个月各复诊1次，评估睾丸位置、大小、质地及有无回缩、萎缩、鞘膜积液、切口感染等并发症。\n3. 定期复查性激素（睾酮、FSH、LH），有生育需求者行精液分析；合并睾丸萎缩者建议行患侧睾丸切除+对侧固定，术后随访。\n4. 隐睾恶变风险高于常人：术后仍需长期随访，每年1次阴囊彩超至中年；如出现患侧睾丸肿大、质硬结节或隐痛，立即就诊排除睾丸肿瘤。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":896,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6f47444438c975784287b0c0a1b0c4e3e419c39c313ce7badb56b3672d7c02c2","pinyin":"yingao","initials":"yg","setting":"out","caseName":"门诊病历764","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历764",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1295407929deafd32691","key":"v1-c9ccc21dfe2a3058|templates-1295407929deafd32691","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"1型糖尿病","category":"门诊病历模板","raw":{"name":"1型糖尿病","category":"门诊病历模板","case":{"case_name":"门诊病历765","templates":{"主诉":"多饮、多尿、多食伴体重下降1个月","现病史":"患者为1型糖尿病，因胰岛β细胞破坏所致，可为自身免疫性（Ⅰa型，谷氨酸脱羧酶抗体、胰岛细胞抗体、胰岛素自身抗体或IA-2抗体阳性）或特发性（Ⅰb型，无相关抗体）。发病年龄多见于儿童及青少年，高峰为12~14岁，成人亦可迟发，即成人隐匿性自身免疫糖尿病（LADA），多于30岁后缓慢起病、表现类似2型糖尿病，但抗体阳性，需早期患者胰岛素；遗传方面与HLA易感基因相关。患者于1个月前起病，出现以下表现：多饮多尿，烦渴、大量饮水、夜尿增多；多食，食欲亢进但体重下降，即多食而瘦，与胰岛素缺乏、糖利用障碍有关；体重下降明显；乏力；视物模糊，与高血糖致晶状体渗透压改变有关；可出现酮症及糖尿病酮症酸中毒（起病急，可为首发表现，表现为恶心、呕吐、腹痛、深大呼吸、呼气酮味，属急症）；易发生皮肤及尿路感染；可有蜜月期，即胰岛素治疗后残余β细胞功能短期缓解，过后仍需依赖胰岛素；存在高血糖；儿童患者可影响生长发育。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P92次/分，R18次/分，BP110/70mmHg。体重下降、形体消瘦；皮肤干燥、有脱水征；呼气有酮味；儿童需评估生长发育情况（身高、体重百分位）；检查胰岛素注射部位有无脂肪萎缩或脂肪增生，并指导注射部位轮换；行双足检查；眼底检查早期多正常；甲状腺检查以筛查自身免疫性多腺体综合征；注意皮肤及口腔感染灶；记录HbA1c。","辅助检查":"【必做】血糖（空腹或随机血糖升高）、HbA1c、尿酮或血酮（评估酮症）、胰岛自身抗体（核心诊断依据，包括谷氨酸脱羧酶抗体、胰岛细胞抗体、胰岛素自身抗体、IA-2抗体，阳性支持1型糖尿病）、C肽（低或测不出，提示胰岛素绝对缺乏，用于与2型糖尿病鉴别，为重要指标）、随机C肽<0.2nmol/L或刺激后<0.3nmol/L（支持1型糖尿病）、血常规、电解质及血气分析（评估DKA）、甲状腺功能及抗体（筛查自身免疫合并症）、乳糜泻筛查（谷氨酰胺转移酶抗体）、肾功能及尿白蛋白、血脂、肝功能；【随访】自我血糖监测（指尖空腹及餐后血糖）、动态血糖监测CGM（联合胰岛素泵闭环管理）、HbA1c每3个月复查（目标<7%）、记录胰岛素剂量调整情况。","初步诊断":"1. 1型糖尿病（自身免疫性（抗体阳性）或特发性；胰岛素绝对缺乏（C肽低）；DKA风险评估；血糖控制（HbA1c）评估；并发症筛查；合并自身免疫病（甲状腺疾病或乳糜泻）评估）\n（注：治疗：胰岛素终身必需，采用基础加餐时方案（MDI：长效基础胰岛素如甘精或德谷，加餐时速效胰岛素），或采用胰岛素泵CSII及闭环治疗；剂量按体重0.4~1U/kg/日计算（蜜月期酌减），并根据血糖调整，同时进行碳水化合物计数教育；低血糖处理采用15g糖法则（参见低血糖章节）。监测：自我血糖监测每日4~7次，加动态血糖监测（可提供趋势及低血糖警报，为重要手段），HbA1c每3个月复查，目标<7%（TIR>70%为新目标）。教育及营养运动：碳水化合物计数、运动时预防低血糖、生病日胰岛素不可停用并需加量及监测酮体以防DKA、备用胰高血糖素、注意驾驶安全。并发症筛查：眼底（病程5年后每年1次）、尿白蛋白及肾功能（每年）、足部（神经血管每年）、神经病变、血压血脂（他汀用于40岁以上或高危者）、戒烟、低血糖无感知者放宽目标以恢复感知、甲状腺功能每年。DKA预防与处理（急诊补液、胰岛素、补钾）。随访：内分泌科每3个月1次；青少年关注过渡期心理；妊娠计划（孕前血糖达标并补充叶酸，孕期强化胰岛素治疗））。","处理方案":"【药物治疗】\n1. 胰岛素强化治疗（基础-餐时方案，首选）：门冬胰岛素（诺和锐）三餐前即刻皮下注射，每次4-8U（每日总量按0.4-0.6U/kg计算，餐时剂量约占每日总量1/3，按血糖谱调整）；甘精胰岛素（来得时）每晚睡前皮下注射10-20U（约占每日总量40%-50%）。疗程：长期维持，无固定疗程，定期根据血糖监测结果调整剂量。\n2. 二甲双胍片0.5g bid 餐后口服：适用于超重/肥胖或血糖波动大者，可减少胰岛素用量、改善胰岛素敏感性；无胃肠道不适及禁忌证者长期服用。\n3. 阿托伐他汀钙片20mg 每晚睡前口服：适用于LDL-C＞2.6mmol/L或合并动脉粥样硬化性心血管疾病者，长期服用，每3-6个月复查血脂及肝功能。\n【一般治疗及生活指导】\n1. 饮食管理：定量定时进餐，按标准体重（25-30kcal/kg/d）计算每日总热量，碳水化合物占总热量50%-60%，采用碳水化合物计数法，三餐分配均匀、粗细搭配，限制含糖饮料、油炸食品及高GI食物。\n2. 运动指导：餐后1小时进行中等强度有氧运动（快走、慢跑、游泳、骑车等），每次30分钟、每周至少150分钟；运动前、后及睡前监测血糖，避免空腹及胰岛素作用高峰时运动，随身携带糖果或含糖饮料以预防低血糖。\n3. 血糖监测：每日自我监测血糖至少4次（空腹、三餐后2小时、睡前），记录血糖日记；每3个月检测糖化血红蛋白（HbA1c），目标＜7.0%（个体化调整）。\n4. 禁忌及日常防护：戒烟限酒，规律作息，避免熬夜与情绪剧烈波动；每日检查双足皮肤，保持足部清洁干燥，穿柔软合脚鞋袜，避免赤足行走及烫伤；外出随身携带糖尿病身份卡及含糖食品，警惕低血糖发生。\n【随诊要求】\n1. 血糖未达标或调整胰岛素方案期间每周复诊1次（可结合远程血糖管理平台随访），血糖平稳后每1-3个月复诊1次；每3个月复查糖化血红蛋白，每3-6个月复查血脂、肝肾功能、尿白蛋白/肌酐比值，每年行眼底、足部、周围神经病变及甲状腺功能筛查；若出现反复低血糖、血糖持续升高伴恶心呕吐、呼吸深快、呼气有烂苹果味或发热感染等酮症酸中毒征象，应立即就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":897,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"4cb8d0b133b5e5c44862c975439f94d4e837e3e587388d94f4d8b4a99a1bf6b2","pinyin":"1xingtangniaobing","initials":"1xtnb","setting":"out","caseName":"门诊病历765","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历765",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5b18d7fdcf2eff112317","key":"v1-c9ccc21dfe2a3058|templates-5b18d7fdcf2eff112317","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"妊娠糖尿病","category":"门诊病历模板","raw":{"name":"妊娠糖尿病","category":"门诊病历模板","case":{"case_name":"门诊病历766","templates":{"主诉":"多饮1天","现病史":"患者1周前无明显诱因出现妊娠糖尿病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者妊娠期出现多饮并逐渐加重，伴轻度乏力，初步诊断妊娠糖尿病，需完善空腹血糖、餐后2小时血糖检查明确血糖升高程度并作为诊断与控糖疗效判断依据；完善糖化血红蛋白检查了解近2至3个月平均血糖水平；完善胰岛素释放试验及C肽检查评估胰岛β细胞功能、鉴别糖尿病类型并指导是否需胰岛素治疗；完善甲状腺功能检查排除甲状腺功能异常所致代谢紊乱；完善尿微量白蛋白检查了解有无早期糖尿病肾脏损害；妊娠期用药及代谢负担加重，完善肝肾功能、血脂、电解质检查评估肝肾功能及代谢紊乱情况；必要时完善甲状腺超声检查明确甲状腺形态及结节情况；如血糖波动明显或疑及肾上腺疾病所致继发高血糖，必要时完善肾上腺CT检查以鉴别继发性糖尿病；孕期定期复查血糖及糖化血红蛋白监测控糖效果并指导饮食与胰岛素方案调整。\n\n（检查清单）\n【必做检查】\n空腹血糖、餐后2小时血糖、糖化血红蛋白、胰岛素释放试验、C肽\n\n【影像学检查】\n甲状腺超声（必要时）、肾上腺CT（必要时）\n\n【其他检查】\n甲状腺功能、尿微量白蛋白、肝肾功能、血脂、电解质","初步诊断":"1. 妊娠糖尿病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 门冬胰岛素注射液（速效胰岛素）：三餐前5～10 min皮下注射，起始每餐2～4 U，根据餐后2 h血糖每2～3天调整10%～20%，目标餐后2 h血糖≤6.7 mmol/L；为GDM\"基础+餐时\"方案的重要组成部分，妊娠期持续使用，分娩后据血糖谱减量或停用。\n2. 地特胰岛素注射液（基础胰岛素）：每晚睡前皮下注射，起始6～10 U，根据空腹血糖每2～3天调整2～4 U，目标空腹血糖≤5.3 mmol/L；与门冬胰岛素联合组成\"基础+餐时\"方案，为饮食运动控制1周后血糖仍不达标者的首选胰岛素治疗方案。\n3. 精蛋白锌重组人胰岛素混合注射液（预混胰岛素30R）：早餐前及晚餐前30 min皮下注射，起始每日总量0.2～0.4 U/kg，按2:1分配于早、晚餐前，据空腹及餐后血糖谱调整，目标空腹血糖≤5.3 mmol/L、餐后2 h血糖≤6.7 mmol/L；适用于血糖波动小、依从性好的患者。\n4. 盐酸二甲双胍片0.5 g bid，餐中或餐后口服：仅用于拒绝胰岛素或存在胰岛素使用困难且无禁忌（肝肾功能正常、无缺氧性疾病）者，国内属超说明书患者、不作首选；用药期间定期复查肝肾功能，分娩后停用。\n\n【一般治疗及生活指导】\n1. 医学营养治疗：控制总热量，孕早期按30 kcal/(kg·d)，孕中晚期1800～2200 kcal/d，碳水化合物占45%～55%，少食多餐（3正餐+2～3次加餐），主食选择低升糖指数食物（燕麦、糙米、全麦），保证优质蛋白（鱼、禽、蛋、奶）及足量膳食纤维（绿叶蔬菜），睡前加餐预防夜间低血糖，避免高糖饮料及甜食。\n2. 运动治疗：无先兆流产、早产、前置胎盘等禁忌者，餐后30 min进行中等强度有氧运动（如快走30 min），每周3～5次，运动心率控制在（220-年龄）×50%～70%，避免仰卧位运动、剧烈及长时间运动。\n3. 自我血糖监测：每日监测空腹及三餐后2 h血糖（血糖波动大时加测餐前及夜间血糖），记录血糖日记，目标空腹血糖≤5.3 mmol/L、餐后2 h血糖≤6.7 mmol/L；同步监测血压、体重增长及胎动情况。\n4. 禁忌与注意事项：戒烟戒酒，忌高糖、高脂饮食；避免长时间空腹及空腹剧烈运动以防酮症；掌握低血糖识别（心慌、出汗、手抖、饥饿感）与处理，随身携带糖果；规律作息，避免熬夜劳累，保持情绪平稳。\n\n【随诊要求】\n1. 血糖控制未达标者每1～2周复诊1次，评估血糖谱并调整饮食运动方案及胰岛素剂量；血糖达标稳定后每2～4周复诊1次。\n2. 每次复诊复查空腹及餐后2 h血糖谱、血压、体重，每1～2个月复查HbA1c，注意有无妊娠期高血压及体重增长异常。\n3. 按产科规范定期产前检查，产科超声评估胎儿生长发育及羊水量（警惕巨大儿、羊水过多），孕晚期行胎心监护；血糖控制欠佳者适当增加超声及胎心监护频次。\n4. 产后6～12周复查75 g OGTT明确糖代谢状态，恢复正常者此后每1～3年复查血糖；持续异常者转内分泌科长期管理，哺乳期维持合理营养及生活方式干预。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":898,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"de3397a205f0bc56dae81e1aa1308d63e59e4d96916735abff024a7e54083a78","pinyin":"renshentangniaobing","initials":"rstnb","setting":"out","caseName":"门诊病历766","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历766",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d6c16cf13a14e44db534","key":"v1-c9ccc21dfe2a3058|templates-d6c16cf13a14e44db534","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"特殊类型糖尿病","category":"门诊病历模板","raw":{"name":"特殊类型糖尿病","category":"门诊病历模板","case":{"case_name":"门诊病历767","templates":{"主诉":"多饮1天","现病史":"患者1周前无明显诱因出现特殊类型糖尿病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因多饮症状进行性加重并伴轻度乏力就诊，初步诊断特殊类型糖尿病，需完善空腹血糖、餐后2小时血糖检查明确血糖水平及血糖谱特点；完善糖化血红蛋白检查了解长期血糖控制情况；完善胰岛素释放试验及C肽检查评估胰岛β细胞储备功能，以鉴别1型糖尿病、MODY等特殊类型糖尿病并指导治疗方案选择；完善甲状腺功能检查排除甲状腺疾病所致糖代谢异常；完善尿微量白蛋白检查明确有无早期糖尿病肾病；患者需长期用药控制血糖，完善肝肾功能、血脂、电解质检查评估肝肾功能及药物耐受性并了解脂代谢情况；疑及甲状腺形态异常时完善甲状腺超声检查明确甲状腺结构；疑及肾上腺疾病或库欣综合征所致继发性高血糖时完善肾上腺CT检查以鉴别病因；门诊定期复查血糖及糖化血红蛋白评估治疗效果并调整用药。\n\n（检查清单）\n【必做检查】\n空腹血糖、餐后2小时血糖、糖化血红蛋白、胰岛素释放试验、C肽\n\n【影像学检查】\n甲状腺超声（必要时）、肾上腺CT（必要时）\n\n【其他检查】\n甲状腺功能、尿微量白蛋白、肝肾功能、血脂、电解质","初步诊断":"1. 特殊类型糖尿病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.MODY3型（HNF1A基因突变）：对磺脲类高度敏感，首选格列本脲片1.25mg，bid，餐前30分钟口服，根据血糖每1～2周上调1.25mg，最大4mg/d，长期维持；注意低血糖风险，从小剂量起始。\n2.MODY2型（GCK基因突变）：以空腹轻中度高血糖为特征，通常无需药物降糖，以生活方式干预为主；若HbA1c＞7.5%，可加用格列齐特缓释片30mg，qd，早餐前口服，疗程长期维持。\n3.糖皮质激素诱导性糖尿病：激素使用期间宜胰岛素治疗，首选门冬胰岛素30注射液，按0.3～0.5U/(kg·d)起始，分早晚2次餐前即刻皮下注射，每2～3天根据血糖调整10%～20%，疗程至激素减停后血糖恢复正常可停用；激素维持期间不可擅自停药。\n4.胰腺外分泌疾病相关（胰源性）糖尿病：需胰岛素替代，首选门冬胰岛素30注射液0.4～0.6U/(kg·d)分2次餐前皮下注射，或基础-餐时方案（甘精胰岛素睡前10U+门冬胰岛素三餐前4U起步），根据血糖调整，长期维持；同时口服胰酶肠溶胶囊0.3g，tid，随餐服用。\n【一般治疗及生活指导】\n1.病因治疗是核心：尽可能明确并去除诱因，包括停用或减量致糖药物（糖皮质激素、噻嗪类利尿剂、免疫抑制剂）、积极治疗原发胰腺疾病；MODY患者建议行家系基因检测与遗传咨询。\n2.饮食：根据病因个体化，总热量按25～30kcal/(kg·d)，碳水化合物占45%～60%并粗细搭配，规律三餐、定时定量，忌含糖饮料及高GI单糖食物；胰源性患者注意低脂饮食以减轻胰酶负荷。\n3.运动：病情稳定后每周至少150分钟中等强度有氧运动（快走、游泳），宜餐后30分钟进行；胰岛素治疗者运动前监测血糖，血糖＜5.6mmol/L时先加餐，运动时随身携带糖果以防低血糖。\n4.自我血糖监测：每日至少监测4次（空腹、三餐后2小时及睡前），记录血糖日记；使用胰岛素者警惕低血糖（心慌、出汗、手抖、饥饿感），发生时应立即进食15g糖类，15分钟后复测血糖。\n【随诊要求】\n1.起始用药或调整剂量期间每1～2周复诊，复查空腹及餐后2小时血糖，评估降糖疗效与低血糖风险，及时调整方案。\n2.病情稳定后每3个月复诊，复查HbA1c（一般目标＜7.0%，老年及低血糖高风险者个体化放宽）、空腹血糖、肝肾功能及电解质。\n3.每年进行糖尿病慢性并发症全面筛查（眼底照相、尿微量白蛋白与肌酐比值、血脂、足部检查及神经病变筛查）；胰腺性糖尿病每年复查胰腺影像及胰酶功能；糖皮质激素诱导性糖尿病在激素使用期间每周监测血糖并随激素减停动态调整降糖方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":899,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7e055f15faddab8ebd54c8faad78f58b2af6bf6b38c5b8e533bd443b5ee64aad","pinyin":"teshuleixingtangniaobing","initials":"tslxtnb","setting":"out","caseName":"门诊病历767","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历767",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4ac65cb506a27161dae9","key":"v1-c9ccc21dfe2a3058|templates-4ac65cb506a27161dae9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"糖尿病酮症酸中毒","category":"门诊病历模板","raw":{"name":"糖尿病酮症酸中毒","category":"门诊病历模板","case":{"case_name":"门诊病历768","templates":{"主诉":"口干多饮多尿加重伴恶心呕吐、腹痛2天","现病史":"患者有糖尿病史，可为1型（DKA最常见，因胰岛素绝对缺乏，起病即可发生DKA，常为首发表现，多见于儿童青少年，重要）、2型（应激时也可发生，如感染、停用胰岛素），或为新发（首诊即DKA，既往无糖尿病史，表现典型）。于3天前在诱因作用下出现症状，诱因包括：感染（最常见，如呼吸道、泌尿道、消化道感染）、胰岛素漏打、中断或剂量不足（依从性差）、应激（手术、创伤、心梗、卒中）、饮食不当、药物（糖皮质激素、噻嗪类、拟交感药）、新发糖尿病。临床表现包括：高血糖所致三多一少（口干、多饮、多尿加重，体重下降）、恶心呕吐（常见，因胃轻瘫及酮体刺激）、腹痛（DKA时可剧烈，类似急腹症，需鉴别，纠正后缓解，勿误诊为急腹症而手术）、深大呼吸（Kussmaul呼吸，因代谢性酸中毒，呼吸深快，呼气有烂苹果味（丙酮），为特征性表现）、乏力嗜睡（脱水、酸中毒所致，可累及脑）、意识改变（由清醒至嗜睡至昏迷，重度者DKA昏迷，儿童需警惕脑水肿）、脱水表现（皮肤弹性差、眼窝凹陷、口干；尿量早期多尿、晚期少尿，提示肾前性）、低血压、心动过速（脱水、休克，见于重度）。实验室可见血糖高（>13.9mmol/L）、血酮升高（β羟丁酸）、尿酮（+++）、血气示代谢性酸中毒（pH<7.3、碳酸氢根<15），符合DKA诊断（高血糖加酮症加酸中毒）。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P110次/分（增快），R28次/分（深快，呈Kussmaul呼吸），BP95/60mmHg（低血压，提示脱水、休克），体重（下降）。神志（清楚、嗜睡或昏迷，需评估GCS）、脱水貌（皮肤弹性差、眼窝凹陷、黏膜干燥）、呼吸（深大，有烂苹果味（丙酮），呼气时可闻及）、心率增快、腹部（轻压痛，见于DKA腹痛，但若有局限性压痛或反跳痛，需排除真性急腹症）、皮肤（干燥，需寻找感染灶，如皮肤、足部感染，为常见诱因）、感染征（肺部、泌尿系；体温可正常或偏低，严重者可不发热，勿据此排除感染）。","辅助检查":"【必做】血糖（快速检测，显著升高，>13.9mmol/L）、血酮（β羟丁酸升高，>3mmol/L提示严重，为DKA核心指标）、血气分析（代谢性酸中毒，pH<7.3、碳酸氢根<18、阴离子间隙增大，符合酮症酸中毒性代酸）、电解质（血钾重要：总钾可正常、降低或升高，因酸中毒时钾向细胞外移，初始可正常或偏高，但总体钾缺乏，补液及胰岛素治疗后钾骤降，可致低钾、心律失常，重要，需监测；钠可呈假性低钠，因高血糖稀释，需校正；氯）、肾功能（肌酐因脱水可呈肾前性升高，可逆；尿素氮）、血常规（感染时白细胞升高）、血培养及感染灶评估（寻找诱因，感染为DKA常见诱因）、尿常规（尿酮（+++）、尿糖）、淀粉酶及脂肪酶（DKA时可升高，需与胰腺炎鉴别，DKA腹痛）、血渗透压（计算，排除高渗状态，DKA渗透压多<330）、乳酸（DKA可伴乳酸性酸中毒，需鉴别，属混合性酸中毒）、心电图（血钾影响，可致心律失常，需监测）、降钙素原（感染）；【监测】血糖（每小时）、血酮、血气、电解质（每2~4小时，为治疗监测核心）、出入量及意识（监测）。","初步诊断":"1. 糖尿病酮症酸中毒（DKA，分度：轻、中、重度（pH<7.1、碳酸氢根<10、意识障碍）；诱因：感染、胰岛素中断、新发等；分型：1型、2型）\n（注：DKA为内分泌急症，可致死，补液加胰岛素加补钾为核心，需ICU或急诊密切监护：①补液（首要措施，恢复循环、降低血糖（稀释作用）：生理盐水快速输注，首1小时15~20ml/kg，之后按脱水程度调整，第一日总量4~6L（成人），监测出入量及心肺功能，老年、心衰者慎用；血糖<13.9mmol/L时改用5%葡萄糖（防止低血糖，同时继续用胰岛素，防止酮体再产生））；②胰岛素（小剂量持续静脉输注，0.1U/kg/h（或0.05~0.1U/kg/h），持续静滴，直至酮症酸中毒纠正（血酮正常、pH>7.3、碳酸氢根>15），改为皮下胰岛素（需重叠1~2小时，防止酮症反弹，重要）；勿过快降糖（每小时血糖下降3~5mmol/L，防止脑水肿（尤其儿童，血糖下降过快、渗透压变化可致脑水肿，重要）））；③补钾（关键，血钾<5.5mmol/L即补（即使血钾正常，酸中毒纠正及胰岛素使用后钾内移，存在低钾风险，故常规补钾），予氯化钾，监测心电图及血钾，每2~4小时一次，目标血钾4~5mmol/L）、补磷（严重低磷者少见，必要时补充）；④纠正酸中毒（胰岛素使用后酸中毒可自行纠正；重度者（pH<6.9）慎补碳酸氢钠（存在争议，仅极重者使用，缓慢补入，防止反常性脑脊液酸中毒及低钾））；⑤诱因治疗（核心，寻找并处理：感染予抗生素（经验性广谱，适用于发热或有感染灶者）、胰岛素中断者恢复用药、应激者处理原发病）、并发症处理（脑水肿（儿童多见，出现意识恶化、头痛时予甘露醇，属急症，需警惕；补液及降糖过快是诱因，应预防）、低血糖（监测，予葡萄糖）、血栓（脱水所致，高龄或高危者予低分子肝素）、胃扩张（禁食，胃肠减压，防止误吸））；⑥监测（血糖（每小时）、电解质、血气血酮（每2~4小时，评估纠正情况）、神志及出入量（每1~2小时）、心电图（血钾、心律失常））；⑦恢复期（酮症纠正后过渡至皮下胰岛素（计算平日方案），开展教育，防止复发（漏针、感染），教会识别早期DKA症状并自救；出院时血糖稳定、确定胰岛素方案，随访内分泌科，防止再发，重要）；由急诊、内分泌科或ICU诊治，规范化治疗（补液、胰岛素、补钾、监测）后预后好（规范治疗者死亡率<1%，延误者可因脑水肿、休克死亡）。","处理方案":"【药物治疗】\n1.补液治疗：0.9%氯化钠注射液静脉滴注，首2小时1000～2000ml（约10～20ml/kg），第1个24小时总量4000～6000ml；当血糖降至13.9mmol/L时，改用5%葡萄糖注射液，按胰岛素∶葡萄糖=1∶2～4（U∶g）比例加入胰岛素继续输注。\n2.胰岛素治疗：短效胰岛素（如重组人胰岛素注射液，诺和灵R）0.1U/kg/h持续静脉滴注（如胰岛素50U加入0.9%氯化钠注射液500ml中，以10ml/h起泵泵入），使血糖每小时下降3.9～6.1mmol/L为宜；血糖降至13.9mmol/L后胰岛素减量至0.02～0.05U/kg/h并联合葡萄糖输注，直至酮体转阴。\n3.纠正电解质紊乱：血钾＜3.3mmol/L时暂缓胰岛素，先于每升输液中加入10%氯化钾注射液30ml补钾；血钾3.3～5.0mmol/L时每升输液中加入10%氯化钾注射液10～15ml，使血钾维持在4.0～5.0mmol/L。\n4.纠正酸中毒与去除诱因：血pH＜6.9时予5%碳酸氢钠注射液125ml静脉滴注；合并感染者加用敏感抗生素（如头孢呋辛钠注射液1.5g q8h静脉滴注×7天），同时积极处理停用胰岛素、应激、妊娠等诱因。\n【一般治疗及生活指导】\n1.休息：急性期绝对卧床休息，监测生命体征、神志、尿量及血糖、血酮，每1～2小时测血糖1次，记录出入量。\n2.饮食：酮症纠正、血糖平稳后恢复糖尿病饮食，按标准体重每日总热量合理分配碳水化合物50%～60%、蛋白质15%～20%、脂肪20%～30%，多饮水，禁含糖饮料及酒精。\n3.活动：病情稳定后循序渐进恢复日常活动并规律运动，运动前后监测血糖，避免空腹剧烈运动，运动量骤增时及时调整胰岛素用量。\n4.禁忌：严禁自行停用、减量或漏用胰岛素；避免暴饮暴食、酗酒、感染等诱因；学会识别酮症早期信号（恶心、呕吐、乏力、食欲减退、呼气烂苹果味），出现上述症状立即就诊。\n【随诊要求】\n1.酮症酸中毒为糖尿病急症，首诊需急诊留观处理，若经补液及胰岛素治疗病情无好转、出现神志异常或持续高血糖，应及时转住院治疗。\n2.病情稳定后每周门诊复诊1次，复查血糖、血酮及糖化血红蛋白（HbA1c），直至血糖平稳；此后每1～3个月复诊1次，复诊时携带血糖监测记录及胰岛素注射记录。\n3.定期复查肝肾功能、血脂、尿微量白蛋白/肌酐比值，筛查糖尿病肾病、视网膜病变等慢性并发症。\n4.出现发热、呕吐、腹泻等感染诱因，或血糖持续＞13.9mmol/L伴尿酮阳性时，须立即就医，不可拖延。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":900,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0d86bb831329157b96ea593362fe39fdb8ea6242877f99937ef6aeff7c31c3ee","pinyin":"tangniaobingtongzhengsuanzhongdu","initials":"tnbtzszd","setting":"out","caseName":"门诊病历768","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历768",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-5945fb86f5d662da8cb6","key":"v1-c9ccc21dfe2a3058|templates-5945fb86f5d662da8cb6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高渗高血糖综合征","category":"门诊病历模板","raw":{"name":"高渗高血糖综合征","category":"门诊病历模板","case":{"case_name":"门诊病历769","templates":{"主诉":"多尿、多饮伴进行性脱水、意识障碍1周","现病史":"患者为老年2型糖尿病（2型糖尿病为最常见基础病，老年人最常见，多无酮症，与DKA不同），存在认知障碍及独居（饮水不足为重要诱因），并有感染、应激、停用降糖药、患者利尿剂及脱水等诱因，于数日至数周内缓慢起病、进行性加重，出现以下表现：多尿、多饮（早期即显著，因大量渗透性利尿所致）；进行性脱水（口干、皮肤弹性差、眼窝凹陷），因饮水不足（老年人渴感减退、行动不便而不能饮水）导致，严重脱水为病程核心；乏力、嗜睡；意识障碍（由嗜睡→昏睡→昏迷，当血浆渗透压>330mOsm/kg时意识障碍显著，为本病特征，较高渗状态所致脑细胞脱水，比DKA更明显）；局灶性神经体征（可逆性偏瘫、失语、抽搐，系高渗致脑细胞脱水，类似卒中，需鉴别，血糖纠正后可恢复）；无或轻微恶心呕吐（与DKA不同，酮症少）；低血压、心动过速（严重脱水、休克所致）；发热（感染诱因所致，常见）。实验室检查提示血糖极高（>33.3mmol/L，甚至>55mmol/L）；血浆渗透压>320mOsm/kg（有效渗透压升高，为核心诊断依据）；血酮阴性或轻微（无酮症，区别于DKA，因残存胰岛素抑制酮体生成）；尿酮阴性或微量；符合HHS诊断标准（血糖>33.3mmol/L+渗透压>320mOsm/kg+无显著酮症）。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T____℃，P____次/分（增快），R____次/分，BP____/____mmHg（低血压，脱水），体重（下降）。神志（嗜睡/昏睡/昏迷，显著高渗，程度与渗透压相关）、严重脱水（皮肤弹性显著差（捏起不回，重度）、眼窝深凹、黏膜干裂，休克（皮肤湿冷或干热，末梢差）、呼吸（可深快（若伴酸中毒，乳酸/酮症），无烂苹果味（无酮症）、神经（局灶体征（偏瘫/失语/抽搐，高渗可逆）、病理征，意识）、感染灶（寻找发热，肺/泌尿/皮肤诱因）。","辅助检查":"【必做】血糖（极高，>33.3mmol/L）、血浆渗透压（计算或直接测定，>320mOsm/kg；有效渗透压按2×钠+血糖/18计算，为核心指标）、血酮（无或轻度升高，β羟丁酸正常或轻度升高）、血气（正常或轻度代酸，为乳酸性或肾功能所致，无酮症酸中毒）、电解质（血钠高，脱水所致，可>150mmol/L；血钾可低，总钾缺乏，补液后需补钾；血氯）、肾功能（肌酐、尿素氮肾前性升高）、血常规、血培养及感染评估（感染为常见诱因）、尿常规（尿糖强阳性、尿酮阴性或微量，提示高渗）、乳酸（评估组织灌注）、肝功、血渗透压计算及动态监测（治疗核心）、心电图（监测电解质及心律失常）、胸部X线（排查感染、肺炎）。","初步诊断":"1. 高渗高血糖综合征（HHS：血糖>33.3mmol/L，有效渗透压>320mOsm/kg，无显著酮症；诱因：感染/饮水不足/停用降糖药；老年2型糖尿病）\n（注：HHS为内分泌急症，死亡率较DKA高（老年、严重脱水及并发症所致），治疗原则与DKA相似，但补液量更大、降糖更慢、且无酮症需注意：①补液为首要措施，纠正脱水（补液量比DKA更大，脱水常达体重的10~12%），选用生理盐水，前1~2小时快速输注（1~1.5L/h）；老年及心衰患者需密切监测心肺，防止肺水肿，酌情减慢速度；监测血浆渗透压及血钠，血钠>150mmol/L时可选用低渗液（0.45%盐水），当血糖降至16.7mmol/L时改用5%葡萄糖加胰岛素；②胰岛素治疗：小剂量静脉给药（0.05~0.1U/kg/h），比DKA更谨慎，因无酮症，降糖主要靠补液稀释（这一点很重要，HHS补液本身即可降低血糖），胰岛素用量可与DKA相比更小，目标为血糖下降每小时3.9~5.6mmol/L，防止下降过快导致渗透压骤降而引发脑水肿（风险尤其见于高渗透压者，缓慢纠正很重要），血糖降至13.9~16.7mmol/L时加葡萄糖（防止低血糖），因无酮症不需大剂量胰岛素（以防低血糖及脑水肿）；③补钾：血钾<5.5mmol/L即补钾（予氯化钾），即使血钾正常，补液及胰岛素治疗后仍可出现低钾，处理同DKA，并监测心电图及血钾；④诱因治疗（核心）：感染（经验性予广谱抗生素，并送血培养，为最常见诱因，很重要）、停用利尿剂及糖皮质激素、解决饮水障碍（护理干预）；老年人常合并多器官功能减退（如心衰，补液量需平衡，必要时ICU监测）；⑤并发症：血栓（严重脱水、高渗、高凝状态易致血栓，包括脑梗、心梗、DVT，对高龄及血管病患者可考虑低分子肝素预防，防血栓很重要）、脑水肿（渗透压纠正过快所致，儿童少见，老年亦需缓慢纠正）、低血糖、心律失常（电解质紊乱所致）、多器官衰竭（灌注不足，老年预后差）；⑥监测：血糖（每小时）、渗透压及电解质（每2~4小时计算，动态监测为核心）、神志（评估意识纠正情况）、出入量及心肺（监测补液情况）、神经体征（局灶体征于高渗纠正后评估恢复）；⑦恢复期：渗透压正常、神志恢复后过渡为皮下胰岛素（HHS多为2型糖尿病，过渡后可改口服降糖药，并请内分泌科评估），并加强教育（防止再发，保证饮水充足，老年人需家人协助，感染及时治疗，坚持血糖监测）；就诊科室为急诊/内分泌/ICU；老年危重症以补液为核心，缓慢降糖以防脑水肿，积极处理感染，预后较DKA差，死亡率5~20%，与年龄及诱因相关。）","处理方案":"【药物治疗】\n1. 补液治疗（首选核心治疗）：0.9%氯化钠注射液1000～1500ml于首1～2小时快速静脉输注（15～20ml/kg·h），后根据血压、心率、尿量每2～4小时调整滴速（约250～500ml/h）；当血糖降至16.7mmol/L时，改用5%葡萄糖注射液按100～250ml/h输注（每500ml可加入短效胰岛素6～8U），持续至血浆渗透压<320mOsm/L、脱水纠正，前24小时补足累计丢失量的1/2～2/3。\n2. 胰岛素治疗：短效胰岛素（人胰岛素R或门冬胰岛素）静脉泵入，先予负荷量0.1U/kg，继以0.1U/(kg·h)（约5～7U/h）持续泵入，使血糖下降速度控制在2.8～4.2mmol/L/h；血糖降至16.7mmol/L时减量至0.02～0.05U/(kg·h)并联合输注5%葡萄糖，待渗透压正常、能进食后过渡为皮下胰岛素（基础+餐时方案）。\n3. 补钾治疗：在尿量>30ml/h且血钾<5.0mmol/L时开始补钾，10%氯化钾注射液10～20ml加入500ml液体中静脉滴注（浓度不超过0.3%，滴速不超过10mmol/h），每4小时复查血钾，维持血钾在4.0～5.0mmol/L。\n4. 抗凝治疗：意识障碍或长期卧床者予依诺肝素钠4000U（0.4ml）皮下注射 qd，预防深静脉血栓，用药期间监测凝血功能及出血倾向。\n【一般治疗及生活指导】\n1. 休息与监护：绝对卧床休息，意识障碍者取侧卧位、头偏向一侧防止误吸，专人护理；每1～2小时监测生命体征、意识、血糖及出入量。\n2. 饮食：意识恢复、能进食后给予低盐低脂饮食，少量多餐，主食每日150～250g，保证足量饮水（清醒者每日2000～2500ml），忌含糖饮料及高糖食物。\n3. 活动与禁忌：避免剧烈活动及重体力劳动；严禁自行停用降糖药或胰岛素；积极处理发热、腹泻、呕吐、感染等诱因并及时补液，避免脱水。\n4. 日常防护：穿宽松鞋袜，防烫伤，保持皮肤清洁干燥，防止压疮及皮肤感染。\n【随诊要求】\n1. 治疗期每2～4小时复查血糖、电解质、血浆渗透压，每6～8小时复查肾功能及血气分析，记录24小时出入量。\n2. 病情稳定后1周内至内分泌科门诊复诊，评估血糖控制并调整降糖方案；每3个月复查糖化血红蛋白（HbA1c），每6～12个月筛查眼底、尿白蛋白/肌酐比值、肾功能等糖尿病并发症。\n3. 若再次出现多饮、多尿、乏力、食欲减退、恶心呕吐、意识模糊等先兆表现，立即就诊，不得自行增减降糖药物；本方案仅适用于意识清醒、血流动力学稳定的轻中度患者门诊留观处理，若出现休克、昏迷、持续少尿或血浆渗透压>350mOsm/L，须立即转急诊/住院治疗。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":901,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"946cdf83f8042dbe2552fb1aa0610d34c33556d90cde72848138ee91faf5a8af","pinyin":"gaoshengaoxuetangzonghezheng","initials":"gsgxtzhz","setting":"out","caseName":"门诊病历769","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历769",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e19a40a67c4bc96ea20b","key":"v1-c9ccc21dfe2a3058|templates-e19a40a67c4bc96ea20b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"糖尿病乳酸性酸中毒","category":"门诊病历模板","raw":{"name":"糖尿病乳酸性酸中毒","category":"门诊病历模板","case":{"case_name":"门诊病历770","templates":{"主诉":"乏力1天","现病史":"患者1周前无明显诱因出现糖尿病乳酸性酸中毒相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因乏力进行性加重1天就诊，初步诊断糖尿病乳酸性酸中毒，需急诊完善空腹血糖、餐后2小时血糖检查明确血糖水平；完善糖化血红蛋白检查了解近期血糖控制情况；完善胰岛素释放试验及C肽检查评估胰岛β细胞功能并指导降糖方案；完善肝肾功能检查明确有无肝肾功能不全导致乳酸清除障碍；完善电解质检查排除电解质紊乱并了解有无高钾、低钠等异常；完善血脂检查了解脂代谢紊乱情况；完善甲状腺功能检查排除甲状腺功能异常所致代谢紊乱；完善尿微量白蛋白检查了解有无糖尿病肾脏损害；必要时完善甲状腺超声检查明确甲状腺形态；疑及肾上腺疾病所致继发糖代谢异常时完善肾上腺CT检查以鉴别；治疗期定期复查血糖、电解质及乳酸评估酸中毒纠正情况并指导用药。\n\n（检查清单）\n【必做检查】\n空腹血糖、餐后2小时血糖、糖化血红蛋白、胰岛素释放试验、C肽\n\n【影像学检查】\n甲状腺超声（必要时）、肾上腺CT（必要时）\n\n【其他检查】\n甲状腺功能、尿微量白蛋白、肝肾功能、血脂、电解质","初步诊断":"1. 糖尿病乳酸性酸中毒\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 病因治疗：立即停用二甲双胍等双胍类降糖药及含乙醇饮品，积极去除感染、失水、缺氧、休克等诱因；肾功能不全、心衰、慢性缺氧患者应永久避免双胍类药物。\n2. 补液扩容：0.9%氯化钠注射液静脉滴注，第1小时1000ml，其后按血压、尿量及心功能调整，24小时总量约3000~5000ml；伴休克者必要时加用羟乙基淀粉或白蛋白扩容，纠正组织低灌注。\n3. 补碱纠酸：血pH<7.2或HCO₃⁻<10mmol/L时，予5%碳酸氢钠注射液100~150ml静脉滴注，每2~4小时复查血气分析调整用量，pH回升至7.2以上即停用，避免过度碱化。\n4. 胰岛素与补糖补钾：血糖>13.9mmol/L时予普通胰岛素0.1U/(kg·h)加入0.9%氯化钠注射液持续静脉滴注，每1~2小时测血糖；血糖降至13.9mmol/L时改用5%葡萄糖注射液按1U胰岛素配4~6g葡萄糖比例输注防低血糖；血钾<5.0mmol/L且有尿时，予10%氯化钾注射液按需加入输液中补钾，严密监测血钾及心电图。\n【一般治疗及生活指导】\n1. 绝对卧床休息，保持安静，避免剧烈活动以减少组织无氧代谢与乳酸生成；密切观察神志、呼吸频率与深度（深大呼吸为危重信号）。\n2. 神志清楚、无呕吐且心肾功能允许时，鼓励大量饮水（每日1500~2500ml）促进乳酸排泄；不能进食者以静脉补液维持。\n3. 治疗期间严格禁酒，禁用双胍类降糖药，避免自行联用其他影响乳酸代谢的药物；规律监测血糖，遵医嘱以胰岛素控制血糖，不可自行调整方案。\n4. 病情缓解后予低盐低脂清淡易消化饮食，少食多餐，血糖平稳后逐步过渡至糖尿病常规饮食管理。\n【随诊要求】\n1. 急性期每2~4小时复查血气分析、血乳酸、血糖、电解质及肾功能，直至血乳酸及pH恢复正常、循环稳定。\n2. 病情平稳后每日监测血糖谱，1周内复诊内分泌科，复查血乳酸、肾功能并评估是否可调整降糖方案；肾功能持续异常者终身禁用双胍类。\n3. 血乳酸显著升高（>5mmol/L）伴肾功能不全或药物难以清除者，应及时住院并行血液透析治疗；若再次出现深大呼吸、意识障碍加重、血压下降或少尿，须立即急诊就诊，本症属急危重症，必要时住院抢救。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":902,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8f9328bed1a9a1511f49d31b1fcdcad6c3f02954d823fb54d0734c5938e27e6b","pinyin":"tangniaobingrusuanxingsuanzhongdu","initials":"tnbrsxszd","setting":"out","caseName":"门诊病历770","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历770",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3adb6c52ed8f8275785f","key":"v1-c9ccc21dfe2a3058|templates-3adb6c52ed8f8275785f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"糖尿病低血糖","category":"门诊病历模板","raw":{"name":"糖尿病低血糖","category":"门诊病历模板","case":{"case_name":"门诊病历771","templates":{"主诉":"心慌、出汗、手抖伴饥饿感2小时","现病史":"患者因糖尿病使用降糖药物，常见诱因包括：胰岛素（最常见原因）、磺脲类（如格列本脲或格列齐特，属长效制剂，易致低血糖，对老年人尤其危险，需重视）、格列奈类等降糖药（如二甲双胍、西格列汀、达格列净，单用时多不引起低血糖，但联合用药时可发生）、其他因素（饮酒可抑制肝糖原异生而致低血糖，尤其空腹饮酒时；运动过量；进食不足或延迟，如漏餐、减餐；肝肾功能不全致药物蓄积；老年人对低血糖耐受差，可出现无感知性低血糖，反复发作危险；感染或腹泻致进食减少；药物相互作用，如普萘洛尔可掩盖低血糖症状，此点重要，另如水杨酸类、磺胺类）。患者于用药后、空腹、夜间或运动后等诱因下出现下列表现：交感神经兴奋症状（心慌、出汗尤其冷汗、手抖、饥饿感、焦虑、面色苍白，多见于轻中度，为早期表现）、神经低血糖症状（头晕、乏力、视物模糊、注意力不集中、言语不清、行为异常如似醉酒、意识模糊甚至昏迷，重度者属急症，低血糖昏迷可致不可逆脑损伤，此点重要，还可有抽搐、体温偏低）。低血糖分级为：轻度（有症状但能自救）、中度（需要他人帮助）、重度（昏迷，需他人急救，予胰高血糖素或静脉葡萄糖）。此外需注意夜间低血糖（凌晨出现噩梦、盗汗、晨起头痛，晨空腹血糖反而升高，即Somogyi效应，表现为低后高，需鉴别）与无感知性低血糖（反复低血糖后交感反应迟钝，可无症状而直接昏迷，十分危险，需调整方案预防，此点重要）。血糖检测低于3.9mmol/L即可诊断（无症状者也需处理），Whipple三联征（低血糖症状、血糖低、补糖后缓解）为诊断依据。今日来我院急诊或内分泌科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T____℃，P____次/分（增快，交感），R____次/分，BP____/____mmHg。神志（清楚/嗜睡/昏迷，重度）、出汗（湿冷，皮肤冷汗）、手抖、苍白、心率（快）、行为（异常，烦躁/淡漠）、瞳孔（正常）、神经（昏迷，病理征，脑病，低血糖不可逆，急救时间重要）、体温（可低）。","辅助检查":"【必做】血糖（即时检测，为核心项目，指尖快速测定低于3.9mmol/L可诊断，严重者低于2.8mmol/L，属危险值）、血常规、电解质（注意钾，胰岛素治疗可影响血钾）、肝肾功能（用于评估药物影响）、糖化血红蛋白（反映近期血糖控制情况）；【其他】C肽及胰岛素（疑胰岛素瘤时检测，非糖尿病者出现低血糖，发作时胰岛素不适当升高，可作鉴别，本病少见但重要；反复低血糖的非糖尿病人群应查胰岛素瘤，结合Whipple三联征并定位）、磺脲类药物浓度（疑过量时检测）、皮质醇（排查肾上腺皮质功能不全所致低血糖，为少见鉴别项目）、酒精（了解饮酒所致低血糖的病史）。","初步诊断":"1. 低血糖症（糖尿病相关，血糖2.8mmol/L，重度：轻度/中度/重度（昏迷），诱因为胰岛素或磺脲过量、漏餐、运动、饮酒，需行糖尿病药物治疗评估）\n（注：治疗要点，应立即纠正，分秒必争，以防脑损伤）：①神志清楚者（轻中度、能吞咽）予口服糖15~20g，可用葡萄糖片或含糖饮料（150~200ml可乐或果汁），也可用糖果或白糖水；15分钟后复测血糖，若仍低于3.9mmol/L，再进食15g，直至血糖正常，即15-15法则，此点重要；症状缓解后进食复合碳水化合物（如面包、饼干），以防血糖再降，尤其在使用长效胰岛素或磺脲类药物时；②神志不清或昏迷者（重度，属急症，不能口服，因有误吸风险，此点重要）：予静脉葡萄糖，即50%葡萄糖20~40ml静注，可立即起效并可重复至清醒，继以5~10%葡萄糖静滴维持；或予胰高血糖素1mg肌注，适用于无静脉通路或院前、家庭情况，应备药并教育家人，此点重要，一般10~20分钟起效，但用于磺脲类所致低血糖效果差；昏迷时间过长可致脑损伤，故及时纠正很重要；③长效药物过量（如格列本脲或长效胰岛素）：口服糖后仍可能出现血糖复降，需继续观察，或住院持续葡萄糖滴注并监测24~48小时，此点重要；磺脲类过量者应住院；④诱因处理及预防：调整药物（胰岛素或磺脲类减量，依据血糖调整，以防反复，此点重要）、饮食规律（按时进餐，运动前加餐，限制饮酒）、教育（对患者及家人进行教育，使其识别症状、自救补糖、随身携带糖及低血糖卡片，并培训家人使用胰高血糖素）、无感知性低血糖者采用宽松目标（将血糖目标上调，以防严重低血糖，数周后有望恢复感知，此点重要）、老年人目标应放宽，以防低血糖致跌倒及认知影响、驾驶方面（低血糖时禁驾，血糖低于5mmol/L时不驾车，此点重要）；⑤随访：血糖监测（空腹、餐后、夜间，据结果调整）、糖化血红蛋白目标应个体化（年轻者低于7%，老年或有并发症者放宽至7.5~8.5%，以平衡低血糖风险，此点重要）、反复低血糖者应评估药物及方案并调整，必要时至内分泌科就诊，此点重要；急诊或内分泌科处理原则为立即补糖、昏迷者予静脉葡萄糖、调整方案、加强教育、预防复发，此点重要。","处理方案":"【药物治疗】\n1. 意识清醒、可进食者：立即口服葡萄糖15-20g（或含糖饮料150-200ml、方糖3-4块、糖果2-3颗），15分钟后复测指尖血糖；若血糖仍<3.9mmol/L，重复上述处理直至血糖>3.9mmol/L，随后进食含淀粉主食（如面包、饼干50g或正常一餐）防止低血糖再发。\n2. 意识障碍或不能进食者：不可强行喂食，应立即拨打120或急诊就医，静脉推注50%葡萄糖注射液40-60ml，继以10%葡萄糖注射液静脉滴注维持，并根据血糖监测调整滴速；血糖回升、神志恢复后仍需留观并寻找诱因。\n3. 无法建立静脉通路者：可予胰高血糖素1mg肌肉注射，血糖回升约需10-15分钟；用药后需注意恶心、呕吐致误吸风险，神志恢复后仍需进食补充淀粉类食物，并尽快送医。\n4. 反复发作低血糖者调整降糖方案：磺脲类或胰岛素所致者，在医师指导下减少剂量（如预混胰岛素每次减少2-4U或基础胰岛素减量10%-20%），必要时改用低血糖风险较低的降糖药（如二甲双胍0.5g bid、西格列汀100mg qd），调整后1周内复诊复查血糖。\n【一般治疗及生活指导】\n1. 饮食：规律三餐、定时定量，避免过度节食、长时间空腹或延迟进餐；餐间可适当加餐（如水果、牛奶等）；空腹饮酒极易诱发低血糖，应严格限制或戒酒。\n2. 运动：运动前后及长时间活动（如爬山、游泳、长途驾驶）前均应监测血糖，运动前血糖<5.6mmol/L时先加餐15-30g碳水化合物；避免空腹剧烈运动，外出随身携带含糖食品（糖果、葡萄糖片等）。\n3. 自我监测与安全：规律监测血糖（尤其餐前、睡前、运动后及凌晨2-3点），记录低血糖发生时间、诱因及处理经过；随身携带糖尿病急救卡，标明姓名、诊断、降糖用药及紧急联系人电话，警惕夜间低血糖（睡前血糖<5.6mmol/L可少量加餐）。\n4. 用药依从性：遵医嘱按时按量使用胰岛素及口服降糖药，不自行增减剂量或漏服后补服；更换胰岛素种类、剂型或注射部位后初期应加强血糖监测。\n【随诊要求】\n建议1-2周内门诊复诊，复查空腹及餐后血糖、糖化血红蛋白，评估降糖方案并调整药物剂量；若反复发生低血糖（每周≥2次）或出现严重低血糖（需他人帮助、伴意识障碍、抽搐），应立即就诊或至急诊处理，必要时住院调整治疗方案；复诊时请携带血糖监测记录本及当前用药清单。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":903,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f8fc231f9431e80e77b2facf18cc173a1facaf2a419ecc498d9f96839b5d6f64","pinyin":"tangniaobingdixuetang","initials":"tnbdxt","setting":"out","caseName":"门诊病历771","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历771",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-191abfec1755ff0f8c22","key":"v1-c9ccc21dfe2a3058|templates-191abfec1755ff0f8c22","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"糖尿病肾病","category":"门诊病历模板","raw":{"name":"糖尿病肾病","category":"门诊病历模板","case":{"case_name":"门诊病历772","templates":{"主诉":"蛋白尿、水肿伴肾功能下降5年","现病史":"患者有糖尿病病史多年（若为1型糖尿病，病程≥5年即可出现肾损害；2型糖尿病确诊时可能已存在肾损害，故确诊后即应筛查），并伴血糖控制长期不佳（糖化血红蛋白升高）、高血压（合并高血压可加速肾病进展，较为重要）、血脂异常、吸烟、家族肾病史等危险因素，近5年来渐进性出现以下表现：微量白蛋白尿（早期唯一表现，患者常无症状，尿白蛋白肌酐比30~300mg/g，筛查发现，此期是逆转的关键期）、蛋白尿（进展至临床期，尿白蛋白肌酐比>300mg/g，24小时尿蛋白>0.5g，并逐渐增多至大量蛋白尿）、水肿（合并肾病综合征时可有大量蛋白尿、低蛋白血症，出现眼睑、下肢乃至全身水肿）、高血压（肾性高血压，较难控制）、肾功能下降（血肌酐升高，肾小球滤过率下降，呈渐进性，可发展至终末期即尿毒症，需透析或肾移植）、贫血（肾性贫血，因促红细胞生成素减少，多见于晚期）、夜尿增多（早期肾浓缩功能下降所致）。分期方面：慢性肾脏病依肾小球滤过率分为G1~G5期，依蛋白尿分为A1~A3期（见慢性肾衰竭，CKD）；糖尿病肾病另有Mogensen分期（Ⅰ~Ⅴ期）。筛查方面：1型糖尿病病程≥5年、2型糖尿病确诊时起以及此后每年，均应检查尿白蛋白肌酐比及肾功能，以便早期发现；眼底检查亦很重要，糖尿病视网膜病变常与肾病并存，两者同属微血管病变，若检查提示肾病合并视网膜病变，则支持糖尿病肾病的诊断。并发症方面需注意心血管病变（有蛋白尿者心血管风险显著升高，是主要死因）及感染。今日来我院内分泌科或肾内科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P82次/分，R18次/分，BP162/94mmHg（高血压，血压升高）。双下肢及眼睑水肿（呈凹陷性，肾病综合征时可遍及全身），可见贫血貌（多见于晚期）；眼底检查见糖尿病视网膜病变（出血、渗出）；心脏检查注意有无心力衰竭表现（多见于晚期）；腹部检查注意有无腹水（多见于晚期）；肾区无叩击痛（糖尿病肾病一般不引起肾区疼痛）；周围神经检查注意有无周围神经病变并存，需予评估；皮肤干燥、瘙痒（多见于晚期）。","辅助检查":"【必做】尿白蛋白肌酐比（核心项目，用于筛查及分期：晨尿尿白蛋白肌酐比<30为正常，30~300为微量白蛋白尿，>300为临床蛋白尿）、尿常规（了解有无蛋白尿）、肾功能（血肌酐、肾小球滤过率，其中估算肾小球滤过率用于分期）、电解质、血钾、糖化血红蛋白（评估血糖控制）、血脂、血尿酸。【影像】肾脏超声（观察肾脏大小，正常或晚期缩小，并排除梗阻及其他肾病，晚期尤需注意）。【其他】眼底检查（评估糖尿病视网膜病变是否并存，较为重要，可提示并支持糖尿病肾病的诊断；糖尿病肾病多依靠临床诊断，1型糖尿病具有典型病程加蛋白尿加视网膜病变者不需行肾活检）、肾活检（指征为表现不典型者，如无视网膜病变、快速进展、血尿明显，需排除其他肾小球肾炎，此项较为重要；肾功能急剧下降者亦需考虑；其他肾病因如血尿、管型明显者亦应检查）。【随访】血压（建议家庭监测）、尿白蛋白肌酐比及肾功能（每3~6个月复查，用于评估疗效）。","初步诊断":"1. 糖尿病肾病（慢性肾脏病分期：肾小球滤过率G3b期，蛋白尿A3；伴高血压、糖尿病视网膜病变，需评估肾功能进展情况）\n（注：治疗以延缓进展为核心，强调多因素干预，即降糖加降压加降蛋白加调脂同步进行。①血糖控制（为基础措施，应严格：糖化血红蛋白<7%，早期可延缓进展，对微量白蛋白尿有逆转作用，较为重要；但肾功能下降或老年患者目标应放宽至7.5~8.5%，以防低血糖。降糖药选择：肾功能不全时需调整，二甲双胍在肾小球滤过率<45时应停用或减量；SGLT2抑制剂（达格列净、恩格列净）具有肾保护作用，可降低蛋白尿、延缓进展，且无论血糖水平如何均可用，已成为标准用药，肾小球滤过率>20~25时可用，较为重要，为近年一线用药；GLP-1受体激动剂（利拉鲁肽、司美格鲁肽）亦有肾获益；胰岛素在晚期因肾小球滤过率下降、胰岛素降解减少，剂量应减少，并注意低血糖。②血压及降蛋白（为核心措施：血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂为一线首选，有蛋白尿者兼具降压与肾保护作用，可降低蛋白尿、延缓进展，已成为标准，较为重要；目标血压<130/80，有蛋白尿者血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂必用，即使血压正常亦应使用，无禁忌者均推荐；联合用药方面，蛋白尿仍多或血压未控制者可加钙通道阻滞剂或利尿剂。③调脂（他汀类，使低密度脂蛋白<1.8mmol/L；有蛋白尿者心血管风险高，故调脂较为重要）、抗血小板（阿司匹林，用于心血管高危者）。④生活方式（低盐，每日<5g/d，水肿、高血压者更应限盐；优质低蛋白饮食，0.8g/kg/d，CKD3期后为0.6~0.8g/kg/d并加用α酮酸，以延缓进展，但须防营养不良，应平衡掌握；戒烟、运动、限酒、控制体重）。⑤并发症处理（水肿或肾病综合征者予利尿（呋塞米）并限盐，严重低蛋白者可考虑白蛋白，但应慎重；肾性贫血者予促红细胞生成素加铁剂，多见晚期，参见肾衰竭；肾功能进展者需监测肾小球滤过率下降速率）。⑥终末期处理（肾脏替代治疗：透析（血液透析或腹膜透析）或肾移植，其中肾移植最佳，糖尿病肾病患者移植后长期生存优于透析；应评估，肾小球滤过率<15或出现尿毒症表现时转肾内科，准备动静脉瘘，宜提前进行，较为重要）。⑦随访（尿白蛋白肌酐比加肾小球滤过率每3~6个月复查，评估进展；血压应达标；糖化血红蛋白每3个月复查；眼底每年复查；药物依从性方面，血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂较为重要，须防自行停药，用药后肌酐早期可轻度升高，在30%以内属正常，勿停药，需监测；血钾亦需监测）。内分泌科或肾内科应行多因素综合管理，早筛查、早干预，采用血管紧张素转换酶抑制剂或血管紧张素Ⅱ受体拮抗剂加SGLT2抑制剂，以延缓进展至终末期，减少透析或肾移植需求，较为重要。","处理方案":"【药物治疗】\n1. 降糖治疗：首选具肾脏保护作用的SGLT2抑制剂，达格列净片10mg qd，eGFR≥45ml/min/1.73m²时足量使用，eGFR下降时减量并监测肾功能；或联合/改用GLP-1受体激动剂利拉鲁肽注射液0.6mg qd皮下注射，1周后增至1.2mg qd维持。同时继续原有口服降糖药（二甲双胍缓释片0.5g bid，eGFR<45ml/min/1.73m²时停用或减量），注意防低血糖。\n2. 降尿蛋白及降压治疗：首选ACEI/ARB类，如缬沙坦胶囊80mg qd（或贝那普利片10mg qd），血压不达标者2周后加至160mg qd（或贝那普利20mg qd），使血压<130/80mmHg、尿白蛋白/肌酐比值下降≥30%；用药期间监测血肌酐、血钾，血肌酐较基线升高>30%或血钾>5.5mmol/L时停用并就诊。\n3. 调脂治疗：阿托伐他汀钙片20mg qn，LDL-C目标<2.6mmol/L，合并ASCVD者<1.8mmol/L；定期复查肝功能、肌酸激酶，出现肌痛或转氨酶升高3倍以上停药就诊。\n4. 并发症对症：水肿明显者予呋塞米片20mg qd口服（根据尿量及体重调整），伴肾性贫血者（Hb<100g/L）予促红细胞生成素（重组人促红素注射液3000IU每周1次皮下注射）联合多糖铁复合物胶囊0.15g qd口服。\n【一般治疗及生活指导】\n1. 饮食：优质低蛋白饮食，蛋白摄入0.8g/(kg·d)，eGFR<60ml/min/1.73m²时减至0.6g/(kg·d)并补充α-酮酸（复方α-酮酸片4片tid随餐嚼服）；限盐<6g/d，伴水肿或高血压者<3g/d；控制总热量，脂肪供能<30%，限制磷、钾摄入。\n2. 生活方式：戒烟限酒，每日坚持30分钟以上中等强度有氧运动（如快走、太极拳），避免剧烈运动和清晨空腹运动以防低血糖；规律作息，避免劳累、感染和脱水。\n3. 血糖管理：居家自备血糖仪自我监测空腹及餐后2小时血糖，每周至少3天；HbA1c控制目标<7%，老年或低血糖风险高者可放宽至<8%，避免低血糖。\n4. 禁忌：禁用非甾体抗炎药（布洛芬、双氯芬酸等）及含马兜铃酸中草药等肾毒性药物，慎用含碘造影剂及氨基糖苷类抗菌药，如确需使用医师评估监测下进行；避免自行加用\"偏方\"或保健品。\n【随诊要求】\n1. 每1~3个月门诊复查：尿常规、尿微量白蛋白/肌酐比值、24小时尿蛋白定量、血肌酐及eGFR、血钾、空腹及餐后血糖、HbA1c，根据结果调整降糖、降压及利尿方案。\n2. 每3~6个月复查：血脂、肝功能、电解质（钠、氯、钙、磷）、血尿酸，监测他汀及利尿剂用药安全性。\n3. 每6~12个月行眼底检查（糖尿病视网膜病变筛查）、足部检查、心电图及心脏超声，评估心肾并发症。\n4. 出现以下情况随时就诊：尿量明显减少、体重短期内增加>2kg、水肿进行性加重、血压控制不佳、恶心呕吐、乏力嗜睡、发热或感染、血糖波动明显或反复低血糖。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":904,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"bebae5ebee8e844aad05425c5d730d7a3d346a1e473517476f0c246aa9e45822","pinyin":"tangniaobingshenbing","initials":"tnbsb","setting":"out","caseName":"门诊病历772","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历772",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-d02c30ddee88244ef16f","key":"v1-c9ccc21dfe2a3058|templates-d02c30ddee88244ef16f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"糖尿病神经病变","category":"门诊病历模板","raw":{"name":"糖尿病神经病变","category":"门诊病历模板","case":{"case_name":"门诊病历773","templates":{"主诉":"肢端麻木、刺痛伴烧灼感1年","现病史":"患者有糖尿病病史8年（病程>5~10年者风险高），血糖控制不佳（糖毒性可致神经损伤），并存微血管病变（视网膜病变、肾病），并有代谢异常（多元醇通路激活、AGEs及氧化应激）以及维生素B1、B12缺乏（长期服用二甲双胍可使B12下降，需筛查）。近1年来出现以下表现：周围神经病变（呈对称性远端袜套、手套样分布，足趾最先受累，表现为麻木、针刺感，如袜子套着的感觉；疼痛呈烧灼、刺痛、电击样，夜间加重；感觉减退，痛温触觉减退，10g尼龙单丝检查缺失，有足溃疡风险；本体感觉减退）、自主神经病变（直立性低血压，可有头晕、晕厥；胃轻瘫，表现为腹胀、早饱、恶心、呕吐，并致血糖波动；腹泻与便秘交替；膀胱残余尿增多，可致尿潴留及感染；勃起障碍；出汗异常，表现为无汗、皮肤干燥；心脏自主神经病变，心率固定、QT间期延长，有猝死风险）、单神经病（颅神经以动眼神经Ⅲ受累多见，瞳孔受累，表现为痛性眼肌麻痹；亦可累及尺神经、腓神经）、糖尿病性肌萎缩（股神经受累，表现为大腿疼痛、无力、萎缩）、慢性炎性脱髓鞘性多神经病（CIDP样表现）、足部损害（因麻木无知觉而易受损伤，可发展为糖尿病足）、跌倒与平衡障碍以及抑郁、睡眠障碍。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.5℃，P84次/分，R18次/分，BP138/82mmHg（直立血压于站立3分钟时收缩压下降>20mmHg，提示直立性低血压）。足部检查：外观可见畸形、胼胝，皮肤干燥、皲裂、溃疡。10g尼龙单丝测试示足底触觉缺失，为关键检查；音叉128Hz振动觉于踝部减退；踝反射消失；针刺觉及温度觉减退；Romberg征阳性（提示本体感觉减退）；步态及共济运动检查异常；颅神经检查（Ⅲ、Ⅳ、Ⅵ及瞳孔）；肌力减退及肌肉萎缩（以近端肌为主）；皮肤干燥无汗；心率固定（深呼吸时心率差减小）；膀胱残余尿增多。","辅助检查":"【必做】血糖、HbA1c、神经传导速度（NCV，用于周围神经病，可见感觉、运动传导速度下降，可评估轴索损害与脱髓鞘，有助于确诊及分型）、肌电图、单丝及音叉检查（临床筛查足部病变）。【排除其他病因】维生素B12（长期服用二甲双胍或营养不良可致缺乏，必查，较为重要）、甲状腺功能（排除甲减）、肾功能及电解质、酒精（鉴别酒精性神经病）、毒物、免疫学检查（CIDP时脑脊液蛋白升高）、淀粉样变、HIV及梅毒、腰椎病变（鉴别根性损害）。【自主神经】心率变异（深呼吸RR间期）、直立血压、胃排空闪烁扫描（胃轻瘫）、膀胱超声测残余尿。【并发症】眼底及尿白蛋白（了解微血管病变并存情况）、足畸形及溃疡评估。","初步诊断":"1. 糖尿病神经病变（远端对称性多发神经病变，呈袜套样感觉运动障碍，最为常见；自主神经病变，表现为直立性低血压、胃轻瘫、勃起障碍、膀胱功能障碍；单神经病或局灶性神经病；需评估血糖控制状态、疼痛及足溃疡风险、B12缺乏及鉴别诊断）\n（注：治疗：血糖控制为核心，HbA1c<7%，可延缓进展、防止加重，对已有神经病变的改善有限，但能防止进展，较为重要。神经病理性疼痛：一线药物为普瑞巴林、加巴喷丁（α2δ配体，对烧灼样、刺痛有效）、度洛西汀、文拉法辛（SNRI）、阿米替林（三环类，夜间镇静，老年慎用）、外用辣椒素（作用局限），不推荐长期使用阿片类；难治者评估后可行联合、阶梯治疗。自主神经病：直立性低血压予非药物措施（弹力袜、增加盐与水摄入、抬高床头），必要时用氟氢可的松、米多君，并停用加重药物；胃轻瘫予少食多餐、低脂低纤维饮食，甲氧氯普胺、多潘立酮促动力（短期使用），难治者可行胃电刺激；腹泻予洛哌丁胺或针对细菌过度生长使用抗生素；勃起障碍予PDE5抑制剂（西地那非）；膀胱功能障碍予定时排尿、清洁间歇导尿；心脏自主神经病变需监测QT间期。足保护为关键：因麻木无知觉，足部损伤常不易察觉，有糖尿病足溃疡、感染、截肢风险，应每日检查足部、穿合适鞋袜、温水洗足并试温、防外伤、处理嵌甲及胼胝，每年行单丝筛查，高危者每3~6个月筛查一次。随访：监测神经病变进展（NCV）、HbA1c、足溃疡、疼痛疗效并调整用药，行跌倒与平衡康复，补充B12，关注抑郁与睡眠，开展足护理教育。","处理方案":"【药物治疗】\n1. 营养神经：甲钴胺片0.5mg，每日3次口服，疗程3-6个月，必要时联合甲钴胺注射液500μg肌肉注射，每日1次，连用2-4周后改口服维持。\n2. 抗氧化应激：硫辛酸胶囊0.2g，每日3次口服（或硫辛酸注射液600mg加入0.9%氯化钠注射液250ml静脉滴注，每日1次，连用2-4周），疗程8-12周。\n3. 改善代谢异常：依帕司他片50mg，每日3次，餐前口服，疗程3-6个月。\n4. 神经病理性疼痛（如伴肢体疼痛、麻木刺痛）：普瑞巴林胶囊75mg，每晚1次起始，3-7天后根据疗效及耐受情况加量至75mg每日2次，最大150mg每日2次，逐渐减量停药；或度洛西汀肠溶胶囊60mg，每日1次口服，疗程4-8周后评估疗效。\n\n【一般治疗及生活指导】\n1. 严格控制血糖、血压、血脂，糖化血红蛋白控制在7.0%以下，戒烟限酒，避免使用异烟肼、呋喃唑酮等有神经毒性的药物。\n2. 每日以温水（水温<40℃）泡脚10-15分钟，泡后擦干尤其是趾缝，每日检查双足皮肤有无破损、水疱、胼胝、红肿，涂润肤霜保持皮肤柔软；穿宽松柔软合脚的鞋袜，避免赤足行走及穿硬底鞋、过紧鞋袜，防止足部损伤与感染。\n3. 适度规律有氧运动（如快走、游泳、骑车）每日30分钟，每周至少5次，运动时穿软底护足鞋；合并明显自主神经病变者避免剧烈运动、久蹲及快速起立，防止体位性低血压和跌倒。\n4. 均衡糖尿病饮食，控制总热量摄入，多食富含B族维生素及膳食纤维的食物，避免长时间保持同一姿势或久坐久站。\n\n【随诊要求】\n1. 每1-3个月复诊，监测血糖及糖化血红蛋白，评估肢体麻木、疼痛等神经症状变化及药物耐受情况，遵医嘱调整用药。\n2. 每6个月复查肌电图、神经传导速度等神经电生理检查，并查踝反射、足部10g尼龙丝压力觉、振动觉及足背动脉搏动，动态评估神经病变进展。\n3. 若出现足部破溃、感染、红肿热痛，或疼痛加重、新发感觉异常、行走困难等症状，应随时就诊；必要时转诊神经内科或糖尿病足专科诊治。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":905,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"61c865313a536bca4c21d92868b6e81ee0d4debfb2428669d4dc2d08d50ac83a","pinyin":"tangniaobingshenjingbingbian","initials":"tnbsjbb","setting":"out","caseName":"门诊病历773","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历773",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-7daa2289037c2c8dc5a9","key":"v1-c9ccc21dfe2a3058|templates-7daa2289037c2c8dc5a9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"糖尿病足","category":"门诊病历模板","raw":{"name":"糖尿病足","category":"门诊病历模板","case":{"case_name":"门诊病历774","templates":{"主诉":"足部溃疡伴坏疽、感染2周","现病史":"患者有糖尿病史10年，长期血糖控制不佳（需评估HbA1c），并发糖尿病周围神经病变（感觉减退，足部麻木，呈袜套样，对痛温觉不敏感，可发生无痛性溃疡，此为关键，因足部损伤无感知而易致溃疡，较为重要）、周围血管病变（下肢动脉硬化闭塞，足凉，间歇性跛行，足背动脉搏动减弱，属缺血性改变）、视网膜病变及肾病（微血管并发症并存）。患者于2周前因足部外伤（鞋磨伤、剪甲伤、烫伤，因感觉减退而烫伤无感，较常见，热水泡脚时尤应注意；亦可因真菌感染、胼胝（俗称老茧）所致压力）或长期受压（足底）后出现无痛性或少痛性表现：足部溃疡（神经性溃疡多见于足底受压区、胼胝下，溃疡较深，无痛，周围感觉减退，足温暖，血运好，足背动脉搏动存在；缺血性溃疡多见于足趾、足跟及足边缘，疼痛，为缺血性疼痛，可有夜间静息痛，足凉，皮肤苍白或发绀，足背动脉搏动减弱或消失，趾甲增厚；亦可为混合性）、坏疽（足趾干性坏疽，色黑，为缺血所致；湿性坏疽则感染，局部红肿热，有恶臭，属急症；亦可形成蜂窝织炎或脓肿，表现为红肿、有波动感；感染可深达骨组织形成骨髓炎，探针可及骨，溃疡较深，X线可见改变；全身感染可出现发热，重者致败血症，属急症；糖尿病足感染控制不佳者，截肢及死亡风险均较高，较为重要）、足畸形（Charcot足，即神经性骨关节病，足弓塌陷，无痛，肿胀、红热，急性期表现类似感染，需鉴别，可见骨破坏；亦可为锤状趾、拇外翻，致压力异常）、胼胝、嵌甲、真菌感染（足癣，皮肤裂口可成为感染入口）。此外，足部保护方面应注意日常检查、剪甲、鞋袜选择，有既往足溃疡或截肢史者属复发高危。今日来我院内分泌科或糖尿病足专科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.6℃，P88次/分，R18次/分，BP148/86mmHg。足部检查：皮肤颜色（苍白、发绀或潮红）、温度（发凉提示缺血）、溃疡（部位为足底或足趾、足跟，需记录大小、深度，探针可探及骨者提示骨髓炎；基底颜色可见坏死或肉芽，可有脓性分泌物及恶臭；周围红肿提示蜂窝织炎）、坏疽（干性或湿性，需记录范围及累及趾或足）、胼胝（位于溃疡周围压力点）、足癣、嵌甲。感觉检查：10g尼龙丝触觉减退，为神经病变筛查的关键；音叉检查振动觉；踝反射减弱，提示神经病变。血管检查：足背动脉、胫后动脉搏动减弱或消失提示缺血；踝肱指数（ABI）<0.9提示缺血；并测皮温。另检查有无畸形（Charcot足、足弓改变）、腹股沟淋巴结（感染时肿大）、全身情况（有无发热，评估败血症）、随机血糖（了解血糖控制状态）。","辅助检查":"【必做】血糖及糖化血红蛋白（评估血糖控制，围术期及感染期需强化控制）、血常规（白细胞升高提示感染）、CRP及降钙素原（评估感染及骨髓炎）、肾功能（评估糖尿病肾病，并指导用药及造影）、血培养（发热或败血症者，用抗生素前采血）、足部X线（可发现骨髓炎所致骨破坏及骨膜反应，溃疡深或探及骨者必查；并查异物、Charcot关节所致骨破坏及关节脱位、气性坏疽所致软组织气体）。【血管评估】踝肱指数（ABI，正常1.0~1.4，<0.9为缺血，<0.4为严重缺血）、下肢动脉超声（了解狭窄或闭塞部位，评估血运重建）、CT血管成像或磁共振血管成像（CTA或MRA，用于血管重建术前评估）。【神经评估】单丝及音叉检查（评估神经病变并分级）。【感染】溃疡分泌物培养（需氧加厌氧，做药敏，作为抗感染依据）、骨培养（骨髓炎者于手术时留取）、MRI（用于骨髓炎或脓肿，X线阴性而疑诊者敏感）。【其他】Wagner分级（0~5级，依溃疡深度及坏疽范围分级，指导治疗）；疑Charcot足者行MRI（可见骨髓水肿，用于急性期诊断）。","初步诊断":"1. 糖尿病足（Wagner分级3级：神经性、缺血性或混合性溃疡及坏疽，合并感染（骨髓炎、蜂窝织炎），需评估血管及神经病变）\n（注：糖尿病足需多学科综合治疗，以防截肢为核心，由内分泌科、血管外科、骨科及创面专科协作。①血糖控制（为基础，应强化，围术期及感染期使用胰岛素，良好血糖可促进愈合、防止感染扩散）。②清创（为关键措施，清除坏死组织、胼胝及异物，行锐性清创至新鲜创面，对保肢较为重要；湿性坏疽或深部感染者需急诊清创，充分引流脓肿需切开，骨髓炎者切除坏死骨以防深部感染；严重者行截趾或截肢，坏疽局限者行保肢手术，范围大者需截肢以挽救生命，应权衡并由多学科评估）。③抗感染（经验性广谱用药，覆盖革兰阳性菌（金葡菌、链球菌）、革兰阴性菌（肠杆菌、铜绿假单胞菌）及厌氧菌，可选用哌拉西林他唑巴坦，或万古霉素加哌拉西林，或头孢类加甲硝唑；MRSA高危者用万古霉素或利奈唑胺；深部感染或骨髓炎者予静脉用药，疗程为软组织感染2~4周、骨髓炎4~6周以上，依培养结果调整，较为重要）。④血运重建（缺血性者应评估，行血管成形或搭桥，严重缺血者需重建以促进愈合、防止截肢，此为关键；ABI<0.5或有静息痛者请血管外科处理，可行腔内治疗（球囊、支架，膝下）或旁路手术）。⑤创面处理（采用湿性愈合，可选用新型敷料（藻酸盐、泡沫、银敷料，以防感染）、负压引流（VSD，用于大创面，促进肉芽生长）；减压为关键，神经性足底溃疡应减轻压力，可行全接触石膏或减压鞋，防止受压，此为不愈合的主要原因；难治者可用生长因子或生物工程皮肤；缺血或难治者可行高压氧辅助治疗）。⑥神经性溃疡以减压为核心，加清创并防再损伤。⑦足部护理教育（预防为关键，应每日足检查（每日用镜子查看有无水疱、破溃、红肿）、洗足（温水，<37℃，勿烫，先用手试水温）、擦干（趾间尤需擦干）、保湿（用羊脂防干裂，趾间不涂）、剪甲（平剪，勿过短，防嵌甲）、鞋袜（合适宽松，选宽头鞋防挤压，高危者用糖尿病专用鞋；袜选棉质无缝，每日更换）、勿赤足（防外伤，室内外均应注意）、足部异常及时就医（勿自行处理鸡眼、胼胝，应由专业人员处理）、每日查足（视力差者可由家人帮助）、每年足部检查（行单丝及血管检查，高危者每3~6个月一次））。⑧随访（溃疡期每周复查，评估创面及感染，观察愈合；愈合后需预防复发，足部护理应终身坚持，高危者尤应重视；糖尿病足复发率高，防截肢为核心）。内分泌科、血管外科、骨科及创面专科应组成糖尿病足中心，多学科协作，保肢治疗，重视教育，预防为根本。","处理方案":"【药物治疗】\n1. 抗感染：阿莫西林克拉维酸钾片0.457g（0.4g/57mg）口服 tid×7～14天，覆盖革兰阳性球菌及厌氧菌；若创面渗出多、局部红肿明显或伴蜂窝织炎，可联用或改用头孢呋辛酯片0.25g bid口服。\n2. 控制血糖：伴感染时优先胰岛素强化降糖，如门冬胰岛素30注射液早14U、晚10U餐前即刻皮下注射（据血糖谱每3～5天调整），血糖稳定后视病情可改口服降糖药；如二甲双胍肠溶片0.5g bid 餐后服（肾功能正常者）。\n3. 改善神经病变及微循环：甲钴胺片0.5mg tid口服，硫辛酸胶囊0.3g qd口服，疗程≥8周；合并下肢动脉缺血者加用贝前列素钠片40μg tid口服。\n4. 抗血小板及调脂：阿司匹林肠溶片100mg qd口服，阿托伐他汀钙片20mg qn口服，长期维持（无禁忌证者）。\n【一般治疗及生活指导】\n1. 足部护理：每日检查双足皮肤颜色、温度、有无破损、水疱、胼胝及趾甲异常；穿宽松软底合脚鞋袜，鞋内无异物、趾甲平剪不过短，严禁赤脚行走及热水袋、暖宝宝取暖。\n2. 洗足方法：用<37℃温水（手肘试温）洗足，洗后轻轻擦干并重点擦干趾缝，涂抹润肤霜保持皮肤湿润，防止皲裂。\n3. 饮食与活动：坚持糖尿病饮食（低盐低脂、定时定量，蛋白摄入充足以利创面愈合）；避免久站久坐及下肢负重行走，抬高患肢休息，可做踝泵运动促进静脉回流；严格戒烟、限酒。\n4. 血糖管理：监测空腹及三餐后2小时血糖，控制空腹血糖<7.0mmol/L、餐后2h血糖<10.0mmol/L，糖化血红蛋白<7.0%，创面愈合期避免低血糖。\n【随诊要求】\n每2周门诊复诊评估创面愈合及感染控制情况；若出现足部红肿热痛加重、发热、创面渗出增多、异味或血糖明显波动，立即就诊；血糖平稳后每3～6个月复查糖化血红蛋白、血脂、肾功能，每年行下肢血管超声、踝肱指数及10g尼龙丝压力觉检查筛查足部风险。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":906,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"60ef72df4ddf6cabb98b8d716141fd9ec1895d810ddb516c48ecb7c85c03bef0","pinyin":"tangniaobingzu","initials":"tnbz","setting":"out","caseName":"门诊病历774","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历774",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e68cc396224ec0f2e3cf","key":"v1-c9ccc21dfe2a3058|templates-e68cc396224ec0f2e3cf","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"糖尿病心血管病变","category":"门诊病历模板","raw":{"name":"糖尿病心血管病变","category":"门诊病历模板","case":{"case_name":"门诊病历775","templates":{"主诉":"胸闷1天","现病史":"患者1周前无明显诱因出现糖尿病心血管病变相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因胸闷1天就诊，症状逐渐加重并伴乏力，初步诊断糖尿病心血管病变，需完善血常规检查排除感染、贫血所致胸闷乏力；完善生化全项检查评估肝肾功能、电解质、血糖、血脂水平，明确危险因素控制情况并指导降糖降脂用药；完善心肌酶谱及肌钙蛋白检查排除急性心肌损伤；急诊完善心电图检查明确有无心肌缺血及心律失常并观察动态演变；完善心脏超声检查了解心脏结构、室壁运动及射血分数以评估心功能；查胸部X线片了解心肺情况并排除肺部疾病所致胸闷，完善BNP/NT-proBNP检查明确有无心力衰竭；病情稳定后完善动态心电图检查明确有无阵发性心律失常及无症状心肌缺血；必要时完善冠脉CTA检查明确冠状动脉狭窄程度以指导血运重建决策；门诊定期复查血糖、血脂及心电图监测病情变化。\n\n（检查清单）\n【必做检查】\n血常规、生化全项（肝肾功能、电解质、血糖、血脂）、心肌酶谱、肌钙蛋白\n\n【影像学检查】\n心电图、心脏超声、胸部X线片\n\n【其他检查】\n动态心电图、冠脉CTA（必要时）、BNP/NT-proBNP","初步诊断":"1. 糖尿病心血管病变\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 降糖：二甲双胍片0.5g bid 随餐口服，长期服用，据血糖调整（糖化血红蛋白>9%或空腹血糖>11.1mmol/L时可联合SGLT-2抑制剂如达格列净10mg qd）；合并心衰、肾功能不全（eGFR<45）者首选SGLT-2抑制剂，二甲双胍减量或停用。\n2. 调脂：阿托伐他汀钙片20mg qn 睡前口服，长期服用，使LDL-C<1.8mmol/L（心血管极高危者<1.4mmol/L）。\n3. 抗血小板：阿司匹林肠溶片100mg qd 早餐前口服，长期服用；阿司匹林过敏或不耐受者换氯吡格雷片75mg qd。\n4. 保护心脏及抗重构：培哚普利叔丁胺片4mg qd 晨服（或缬沙坦胶囊80mg qd），长期服用；心率>70次/分、无禁忌者加用美托洛尔缓释片47.5mg qd，注意监测心率、血压及血钾、肾功能。\n\n【一般治疗及生活指导】\n1. 饮食：低盐低脂糖尿病饮食，食盐<5g/日，控制总热量，碳水化合物占总热量45%~60%，多食蔬菜、全谷物，限制饱和脂肪及反式脂肪，戒烟限酒。\n2. 运动：每周至少150分钟中等强度有氧运动（如快走、太极拳），可分次进行，运动前后监测血糖，血糖<5.6mmol/L或>16.7mmol/L、合并急性感染或心功能不全急性期时暂停运动；避免剧烈、屏气及无氧运动。\n3. 生活方式：保持规律作息，避免劳累、熬夜、情绪激动、饱餐及受凉，冬季注意保暖，防止血压血糖波动诱发心脑血管事件。\n4. 自我管理：每日监测血压并记录，规律自我血糖监测（空腹及餐后2小时），控制目标：空腹血糖4.4~7.0mmol/L、餐后2小时血糖<10.0mmol/L、血压<130/80mmHg、糖化血红蛋白<7%（老年及低血糖风险高者适当放宽）。\n\n【随诊要求】\n1. 每1~3个月门诊复诊，监测空腹及餐后血糖、糖化血红蛋白（每3个月）、血压、血脂、肝肾功能及血钾，评估降糖、调脂、降压及抗血小板方案达标情况并调整用药。\n2. 每3~6个月复查静息心电图，有胸闷、心悸者加做24小时动态心电图；每6~12个月复查心脏彩色多普勒超声，评估心功能及心脏结构变化。\n3. 每年复查颈动脉及下肢血管超声、尿微量白蛋白/肌酐比值、眼底检查，评估全身血管病变进展；必要时行冠脉CTA或负荷心肌灌注显像筛查无症状心肌缺血。\n4. 出现胸闷、胸痛、气促、心悸、黑矇、晕厥或双下肢水肿等症状时，立即就近急诊就诊，勿自行调整抗血小板、抗凝等药物。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":907,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2bb85b4dda5884c38286bfb6d854d7929bfc2dcc9bebf08c2911b11ae385837c","pinyin":"tangniaobingxinxueguanbingbian","initials":"tnbxxgbb","setting":"out","caseName":"门诊病历775","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历775",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-4336875b97efb44967be","key":"v1-c9ccc21dfe2a3058|templates-4336875b97efb44967be","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"糖尿病脑血管病变","category":"门诊病历模板","raw":{"name":"糖尿病脑血管病变","category":"门诊病历模板","case":{"case_name":"门诊病历776","templates":{"主诉":"头晕1天","现病史":"患者1周前无明显诱因出现糖尿病脑血管病变相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因头晕1天就诊并逐渐加重伴乏力，初步诊断糖尿病脑血管病变，需完善血常规、生化全项检查排除感染、贫血所致头晕并评估肝肾功能及血糖血脂水平；完善凝血功能检查了解凝血状态并评估缺血性卒中风险及溶栓禁忌；完善血脂检查明确代谢危险因素控制情况；完善同型半胱氨酸检查了解是否为脑血管病独立危险因素；急诊完善头颅CT/MRI检查明确有无脑梗死、脑出血及缺血灶部位范围；完善颈动脉超声检查了解颈部血管斑块及狭窄情况；完善经颅多普勒检查评估颅内血流及血管狭窄；完善心电图及心脏超声检查排查心房颤动、附壁血栓等栓子来源以明确病因；高度疑及颅内感染或蛛网膜下腔出血而影像不能解释时，必要时完善腰椎穿刺检查以进一步明确诊断；治疗期间定期复查血糖、血脂及头颅影像评估病情演变。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 糖尿病脑血管病变\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1.降糖治疗：二甲双胍片0.5g bid，餐中或餐后口服，监测空腹及餐后2h血糖，糖化血红蛋白（HbA1c）目标<7.0%，血糖控制不佳或急性期者遵医嘱加用或换用胰岛素。\n2.抗血小板：阿司匹林肠溶片100mg qd，晨起空腹顿服，长期服用；阿司匹林过敏或不耐受者改用硫酸氢氯吡格雷片75mg qd。\n3.调脂稳定斑块：阿托伐他汀钙片20mg qn口服（或瑞舒伐他汀钙片10mg qn），长期服用，定期复查肝功能和肌酶。\n4.控制血压（合并高血压者）：苯磺酸氨氯地平片5mg qd口服，血压目标<130/80mmHg（老年及体位性低血压者可放宽至<140/90mmHg）。\n\n【一般治疗及生活指导】\n1.合理饮食：糖尿病低盐低脂饮食，控制每日总热量，食盐摄入<5g/d，戒烟限酒。\n2.规律运动：病情稳定期每日中等强度有氧运动30分钟（如快走、太极拳），每周至少5天；急性期或肢体功能障碍者以卧床休息为主，病情平稳后循序渐进进行康复锻炼。\n3.避免诱因：避免劳累、情绪激动、用力排便及熬夜，保持大便通畅，防止血压血糖剧烈波动。\n4.自我监测：定期监测血糖、血压，出现突发剧烈头痛、言语不清、口角歪斜、肢体麻木无力、视物模糊等脑卒中征象时立即就医。\n\n【随诊要求】\n1.每1~3个月门诊复诊，监测空腹血糖、餐后2h血糖及糖化血红蛋白，评估血糖控制情况。\n2.每3~6个月复查血脂、肝肾功能、血同型半胱氨酸，长期服他汀者注意肌痛、肝功异常。\n3.每6~12个月行颈动脉彩超、经颅多普勒（TCD）、眼底检查及尿微量白蛋白检查，评估血管病变进展。\n4.长期服用抗血小板药者注意有无黑便、牙龈出血等出血倾向；遵医嘱定期至神经内科随诊，评估神经功能及卒中复发风险，出现异常及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":908,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"410b28b0aa9a7c5c2f82cea864dc79a3807eaf5876aeced1c849dbecca223aef","pinyin":"tangniaobingnaoxueguanbingbian","initials":"tnbnxgbb","setting":"out","caseName":"门诊病历776","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历776",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-39dc6e28fe96b8a1b3f6","key":"v1-c9ccc21dfe2a3058|templates-39dc6e28fe96b8a1b3f6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状腺肿","category":"门诊病历模板","raw":{"name":"甲状腺肿","category":"门诊病历模板","case":{"case_name":"门诊病历777","templates":{"主诉":"颈部肿大6个月","现病史":"患者于6个月前体检（超声或体检发现）或自行触及（颈前肿块，可随吞咽上下移动）发现甲状腺肿大，表现为：甲状腺肿，可为弥漫性或结节性；大小按Ⅰ~Ⅲ度分，轻度触诊可及，中度视诊可见，重度巨大者可产生压迫；质地可为软、中等或硬，有结节者需评估；功能方面可为正常（单纯性甲状腺肿多见，多因碘缺乏，即地方性甲状腺肿，我国通过碘盐防治，已成为历史情况；亦可为青春期或妊娠期生理性需求增加所致；结节性甲状腺肿多为多发结节，以良性为主）、功能亢进（甲亢，如Graves病，见甲亢，表现为弥漫性肿大加杂音加眼征；亦可为毒性多结节性甲状腺肿，多见于老年）、功能减退（桥本甲状腺炎、甲减，见甲减）、甲状腺炎（亚急性者疼痛，见甲状腺炎）、肿瘤（甲状腺癌，结节有恶性可能，见甲状腺肿瘤）；压迫症状（甲状腺肿较大者可压迫气管，引起呼吸困难、喘鸣，压迫较为重要；压迫食管可致吞咽困难；侵犯喉返神经可致声嘶，多见于恶性；压迫上腔静脉少见，可致头颈肿胀，见于胸骨后甲状腺肿）。另需询问：碘摄入情况（缺碘区或碘过量均可致甲状腺肿）、家族史（甲状腺肿或甲状腺疾病）、药物（锂盐、胺碘酮可致甲状腺肿）、食物（卷心菜、木薯等含致甲状腺肿物质，大量食用者少见）、有无疼痛（亚急性甲状腺炎可有痛）、有无发热、有无甲亢或甲减症状（心悸、多汗或怕冷、乏力，用于评估功能）、生长情况及结节变化、恶性警示征象（质地硬、固定、快速增大、声嘶、淋巴结肿大，较为重要）。今日来我院内分泌科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.4℃，P78次/分，R18次/分，BP126/78mmHg。甲状腺检查：视诊见颈部肿大，需注意对称与否；触诊记录大小（按分度）、质地（软、韧或硬）、表面（光滑或结节，结节需记录单发或多发、大小、形态）、有无压痛（亚急性甲状腺炎可有痛）、活动度（可随吞咽上下活动，固定者提示恶性浸润）、有无血管杂音（Graves病可闻及收缩期杂音，提示甲亢）、胸骨后甲状腺肿需叩诊判断；颈部淋巴结有无肿大（提示恶性）；气管有无偏移或受压（有喘鸣者需评估呼吸）；声带情况（有声嘶者提示喉返神经受累，必要时行喉镜检查）；并检查有无甲亢或甲减体征（手抖、突眼、黏液水肿，用于评估功能状态）。","辅助检查":"【必做】甲状腺功能（为核心检查，包括游离三碘甲状腺原氨酸、游离甲状腺素、促甲状腺激素，用于评估功能：正常者考虑单纯性甲状腺肿；促甲状腺激素降低提示甲亢，见于毒性结节或Graves病；促甲状腺激素升高提示甲减，见于桥本甲状腺炎）、甲状腺过氧化物酶抗体及甲状腺球蛋白抗体（用于桥本甲状腺炎等自身免疫性甲状腺病）、促甲状腺激素受体抗体（用于Graves病）、甲状腺超声（为核心检查，判断弥漫性或结节性，记录大小，并按TI-RADS对结节评估恶性风险，见甲状腺肿瘤，并判断细针穿刺指征，同时观察质地及回声、血流）。【其他】甲状腺摄碘率及核素显像（用于功能结节，热结节提示高功能、多为良性；亦可对异位或胸骨后甲状腺肿定位）、尿碘（评估碘缺乏或过量，判断地区性因素）、甲状腺球蛋白（甲状腺肿时可升高，但意义有限，术后可用于监测）、血钙（巨大甲状腺肿手术前需查，评估甲状旁腺）、气管影像（胸片或CT，用于甲状腺肿较大者评估压迫）。【随访】甲状腺肿大小（每年复查）、甲状腺功能（每年复查，评估向甲减或甲亢进展）。","初步诊断":"1. 甲状腺肿（结节性甲状腺肿：单纯性、弥漫性、与碘相关；需评估有无毒性（Graves病或毒性结节）、炎症性（桥本甲状腺炎伴甲减）或肿瘤性；功能状态为甲状腺功能正常；需评估压迫症状及结节恶性风险）\n（注：治疗依功能、大小、病因及结节情况而定。①功能正常的单纯性甲状腺肿：碘缺乏者应补碘（碘盐或碘化钾，适用于缺碘区；但碘过量亦可致甲状腺肿，故应适量并评估尿碘，个体化处理）；随访甲状腺肿大小（每6~12个月行超声）、甲状腺功能（每年复查，监测向甲减或甲亢转化），无压迫症状者不需手术。②甲亢：Graves病予抗甲状腺药、碘131或手术（见甲亢）；毒性结节多见于老年，可行碘131或手术，多结节者可行放射性碘治疗，亦可先用抗甲状腺药控制后手术。③甲减或桥本甲状腺炎：予左甲状腺素替代（见甲减，甲状腺肿多可缩小，需随访）。④有压迫症状者：甲状腺肿较大压迫气管、食管或声带（出现呼吸困难、吞咽困难、声嘶）者应手术，行甲状腺次全或全切，术前需评估结节情况；胸骨后甲状腺肿经CT评估后手术，并选择合适入路。⑤结节：按TI-RADS评估并行细针穿刺（见甲状腺肿瘤，结节>1~1.5cm或可疑者穿刺，良性者随访，恶性者手术）。⑥随访：甲状腺肿大小（每6~12个月行超声）、甲状腺功能（每年）、穿刺后结节随访，并保持碘平衡。内分泌科与甲状腺外科应共同完成功能评估与结节筛查，有压迫者手术，并重视随访。","处理方案":"【药物治疗】\n1.左甲状腺素钠片（优甲乐）25μg qd，晨起空腹顿服，2-4周后复查甲状腺功能（TSH）调整剂量，维持TSH于正常范围，疗程3-6个月（适用于弥漫性或结节性甲状腺肿伴TSH升高者）；TSH已受抑制（亚临床甲亢）者不宜使用。\n2.碘化钾片10mg qd口服，疗程1-3个月（适用于青春期、妊娠期等相对缺碘所致的单纯性甲状腺肿，用药前须排除甲亢）；或以加碘盐饮食替代。\n3.合并甲状腺功能亢进者：甲巯咪唑片（赛治）10mg tid口服，甲功控制后逐渐减量至5-10mg qd维持，每周复查血常规，每2-4周复查肝功能及甲状腺功能。\n【一般治疗及生活指导】\n1.饮食：坚持食用加碘盐；适量限制卷心菜、木薯、西兰花、萝卜等含致甲状腺肿物质的食物；避免过量摄入海带、紫菜、海蜇等高碘食物，合并甲亢者严格忌碘饮食。\n2.休息与活动：避免熬夜、劳累及精神紧张，保证充足睡眠；可进行散步等适度运动，避免剧烈活动和颈部过度受压、牵拉。\n3.禁忌：合并甲亢者戒烟酒、浓茶及咖啡；避免使用胺碘酮及含碘造影剂等药物；慎用致甲状腺肿药物（如锂剂、磺胺类）。\n4.自我监测：注意颈部外观及自我触诊，如发现甲状腺短期内明显增大、出现声音嘶哑、吞咽困难、呼吸不畅或颈部压迫感，及时就诊。\n【随诊要求】\n每1-3个月复查甲状腺功能（TSH、FT3、FT4）及甲状腺彩超，动态评估甲状腺大小及结节变化；服药期间定期复查血常规、肝功能；如结节短期内明显增大或出现压迫症状，及时复诊，必要时行甲状腺细针穿刺活检（FNA）或转外科会诊评估手术指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":909,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b51554c6751b79ad577180d81adc6849f666a6024b2e551602e33214de03f43b","pinyin":"jiazhuangxianzhong","initials":"jzxz","setting":"out","caseName":"门诊病历777","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历777",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e7f9ae8bae742d2f36bc","key":"v1-c9ccc21dfe2a3058|templates-e7f9ae8bae742d2f36bc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高胆固醇血症","category":"门诊病历模板","raw":{"name":"高胆固醇血症","category":"门诊病历模板","case":{"case_name":"门诊病历778","templates":{"主诉":"头晕1天","现病史":"患者1周前无明显诱因出现高胆固醇血症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因头晕1天就诊，伴轻度乏力且症状逐渐加重，初步诊断高胆固醇血症，需完善血常规检查排除贫血所致头晕；完善便常规加潜血检查排除消化道慢性失血，并了解有无寄生虫等继发因素；患者需长期服用他汀类降脂药物，完善肝功能检查了解肝脏合成与代谢功能，为启动降脂治疗提供安全性依据；完善淀粉酶、脂肪酶检查排除胰腺疾病所致脂代谢异常；完善腹部超声检查了解有无脂肪肝及胆囊结石等合并症；完善腹部CT检查进一步明确肝胆胰脾形态及有无占位性病变；完善幽门螺杆菌检测（C13/C14呼气试验）明确有无幽门螺杆菌感染；完善凝血功能检查评估凝血状态；必要时完善胃镜或肠镜检查排除消化道溃疡及肿瘤等导致继发性血脂异常或潜血阳性的病因；用药后定期复查血脂及肝功能评估降脂疗效与药物安全性，指导调脂方案调整。\n\n（检查清单）\n【必做检查】\n血常规、便常规+潜血、肝功能、淀粉酶、脂肪酶\n\n【影像学检查】\n腹部超声、胃镜/肠镜（必要时）、腹部CT\n\n【其他检查】\n幽门螺杆菌检测（C13/C14呼气试验）、肝功能、凝血功能","初步诊断":"1. 高胆固醇血症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 首选他汀类（HMG-CoA还原酶抑制剂）：阿托伐他汀钙片20mg qn（每晚睡前口服），或瑞舒伐他汀钙片10mg qn，长期维持治疗；用药4-6周后复查血脂，LDL-C未达标者可调整剂量（阿托伐他汀可增至40mg qn），达标后继续长期维持，不可随意停药。\n2. 单用他汀血脂仍不达标或他汀不耐受者，联合胆固醇吸收抑制剂：依折麦布片10mg qd，与他汀同服或单独服用。\n3. 极高危（ASCVD、家族性高胆固醇血症）经上述治疗后LDL-C仍不达标者，可联合PCSK9抑制剂：依洛尤单抗注射液140mg 皮下注射，每2周1次；或阿利西尤单抗注射液75mg 皮下注射，每2周1次。\n\n【一般治疗及生活指导】\n1. 饮食控制：低脂低胆固醇饮食，限制饱和脂肪酸及反式脂肪酸摄入，少食动物内脏、肥肉、油炸食品、奶油糕点等；每日胆固醇摄入量<300mg（高危患者<200mg）；增加全谷物、新鲜蔬菜、水果、豆类及富含可溶性纤维食物（燕麦、魔芋）摄入，适量食用深海鱼类。\n2. 运动与减重：坚持规律有氧运动，每周至少150分钟中等强度运动（如快走、慢跑、游泳、骑自行车），每周3-5次、每次30分钟以上；超重或肥胖者目标减重5%-10%。\n3. 戒烟限酒：严格戒烟并避免二手烟，男性每日酒精摄入量不宜超过25g（约白酒50ml或啤酒300ml），女性减半。\n4. 监测与自我管理：用药期间注意有无肌痛、肌无力、乏力、食欲减退等不适，定期监测血脂及肝功能。\n\n【随诊要求】\n1. 启动调脂治疗或调整剂量后4-6周门诊复诊，复查血脂（TC、TG、LDL-C、HDL-C）及肝功能（ALT、AST）、肌酸激酶（CK），评估疗效与安全性；血脂达标后每3-6个月复查1次。\n2. 若出现不明原因肌肉酸痛、肌无力、尿色加深（酱油色尿），或恶心、食欲减退、黄疸等表现，应立即就诊，查CK及肝功能以排除他汀相关肌病或肝损伤。\n3. 合并高血压、糖尿病、冠心病等高危因素者，建议每3个月门诊复诊，综合评估心血管风险并监测血压、血糖及肾功能。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":910,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"23a7eb007465dfb65c65d37629db70272b8c6ea40e1070a77c1a30a1a10cd23b","pinyin":"gaodanguchunxuezheng","initials":"gdgcxz","setting":"out","caseName":"门诊病历778","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历778",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2f7a3741bd6802f1747f","key":"v1-c9ccc21dfe2a3058|templates-2f7a3741bd6802f1747f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高甘油三酯血症","category":"门诊病历模板","raw":{"name":"高甘油三酯血症","category":"门诊病历模板","case":{"case_name":"门诊病历779","templates":{"主诉":"头晕1天","现病史":"患者1周前无明显诱因出现高甘油三酯血症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因头晕1天就诊并逐渐加重伴轻度乏力，初步诊断高甘油三酯血症，需完善血脂检查明确甘油三酯及总胆固醇水平以指导降脂方案；完善血常规检查排除贫血所致头晕；完善尿常规检查了解有无泌尿系统异常及肾脏损害；完善便常规检查排除消化道慢性失血；完善肝肾功能检查了解肝脏代谢功能与药物排泄能力，为降脂药物治疗提供安全性依据并评估药物耐受性；完善血糖检查排除糖尿病及其他继发性血脂异常；完善电解质检查排除电解质紊乱所致乏力；完善心电图检查排除心律失常及心肌缺血；完善胸部X线片了解心肺基础情况；完善腹部超声检查了解有无脂肪肝、胆囊结石，重度高甘油三酯血症者需警惕急性胰腺炎，必要时进一步检查明确胰腺情况；用药后定期复查血脂及肝功能评估疗效与安全性。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 高甘油三酯血症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 首选贝特类：非诺贝特胶囊0.2g qd（随晚餐服用），或微粒化非诺贝特0.2g qn；服药4-8周后复查血脂及肝肾功能，TG未达标（<1.7mmol/L）或出现肌痛、肝酶升高等不良反应时及时调整，达标后长期维持。\n2. 高纯度ω-3多不饱和脂肪酸：二十碳五烯酸乙酯（IPE）2g bid（每日总量4g），或ω-3脂肪酸乙酯1g tid，可与贝特类联合用于TG严重升高者。\n3. 合并LDL-C升高（混合型高脂血症）时加用他汀类：阿托伐他汀钙片20mg qn，或瑞舒伐他汀钙片10mg qn，每晚顿服，4-8周后复查血脂评估疗效。\n【一般治疗及生活指导】\n1. 饮食：限制脂肪摄入（每日烹调油<25g），忌油炸食品、肥肉、动物内脏及奶油糕点；严格减少精制碳水化合物和含糖饮料、甜食摄入；增加深海鱼类、蔬菜及全谷物；TG≥5.6mmol/L者须严格戒酒。\n2. 运动与减重：坚持中等强度有氧运动（快走、慢跑、游泳、骑车等）每周≥5次、每次30-60分钟；超重或肥胖者积极减重，目标体重下降5%-10%。\n3. 生活方式：规律作息、避免熬夜，戒烟；合并糖尿病者严格控糖（HbA1c<7%），合并高血压者低盐饮食。\n4. 禁忌：TG≥5.6mmol/L时避免饮酒及暴饮暴食，以防诱发急性胰腺炎；避免使用可升高TG的药物（噻嗪类利尿剂、非选择性β受体阻滞剂、雌激素、糖皮质激素等）。\n【随诊要求】\n1. 开始调脂治疗4-8周后复诊，复查血脂全套（TG、TC、LDL-C、HDL-C）及肝功能、肾功能、肌酸激酶，评估疗效与安全性。\n2. 血脂达标后每3-6个月复诊复查血脂及安全指标；TG≥5.6mmol/L的高危患者治疗初期每2-4周复诊1次，若出现持续性上腹痛、恶心、呕吐等急性胰腺炎前驱症状应立即急诊就诊。\n3. 复诊时同步监测空腹血糖、血尿酸及体质量，评估代谢综合征相关风险，定期评估心血管风险并根据患者具体情况制定个体化方案调整方案。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":911,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"45b1b4b27b85168cb10ce3fb5b20eb3ceda636f0940142010e661e701e14519a","pinyin":"gaoganyousanzhixuezheng","initials":"ggyszxz","setting":"out","caseName":"门诊病历779","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历779",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6a08a483b725fd783c64","key":"v1-c9ccc21dfe2a3058|templates-6a08a483b725fd783c64","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"混合型高脂血症","category":"门诊病历模板","raw":{"name":"混合型高脂血症","category":"门诊病历模板","case":{"case_name":"门诊病历780","templates":{"主诉":"头晕1天","现病史":"患者1周前无明显诱因出现混合型高脂血症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因头晕1天就诊，现病史提示近1周症状逐渐加重并伴轻度乏力，初步诊断混合型高脂血症，头晕需排除贫血、感染及电解质紊乱、血压异常所致。入院即刻完善血常规检查排除感染、贫血等血液系统异常；完善尿常规、便常规检查了解泌尿系与消化道有无基础病变，为长期调脂治疗提供基线；患者需接受他汀类等降脂药物治疗，药物经肝肾代谢，完善肝肾功能检查明确有无肝功能异常及肾功能不全，指导调脂药物种类与剂量选择，并作为用药安全监测基线；完善血糖检查排除糖尿病及糖代谢异常所致继发性血脂紊乱；完善血脂检查明确总胆固醇、甘油三酯、低密度脂蛋白胆固醇及高密度脂蛋白胆固醇的具体水平，了解血脂升高的组分特点，指导降脂目标设定与方案调整；完善电解质检查排除电解质紊乱所致头晕、乏力。混合型高脂血症是动脉粥样硬化性心血管疾病的重要危险因素，完善心电图检查了解有无心肌缺血及心律失常；完善胸部X线片检查了解心肺形态、有无主动脉增宽等改变；完善腹部超声检查了解有无脂肪肝、胆囊及胰腺病变，评估代谢综合征相关靶器官损害。上述结果回报后结合血压监测，若头晕持续或加重，必要时完善颈动脉超声及头颅CT检查进一步明确脑血管病变。病情稳定后定期复查血脂、肝肾功能，评估疗效及药物安全性。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 混合型高脂血症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 阿托伐他汀钙片20mg 每晚1次口服，长期服用（4-8周后复查血脂评估疗效，不达标者调整剂量至40mg qn）。\n2. 若甘油三酯仍明显升高（TG>2.3mmol/L），联用非诺贝特胶囊0.2g 每日1次口服，与他汀错开服用（如晨服贝特、晚服他汀），疗程4-8周后复查。\n3. 若LDL-C控制仍不达标，联用依折麦布片10mg 每日1次口服，与他汀合用进一步降低LDL-C。\n4. 高纯度鱼油制剂（含EPA/DHA）2g 每日2次口服，辅助降低甘油三酯。\n\n【一般治疗及生活指导】\n1. 低脂低胆固醇饮食：限制饱和脂肪酸及反式脂肪酸摄入，每日烹调用油<25g，避免动物内脏、肥肉、油炸食品及高糖糕点，增加蔬菜、水果及全谷类摄入。\n2. 严格戒烟、限酒（建议戒酒或酒精摄入男性<25g/日、女性<15g/日），避免饮含糖饮料。\n3. 适度规律有氧运动：每周至少5次、每次30分钟中等强度运动（如快走、慢跑、游泳），超重者减重，目标BMI<24kg/m²。\n4. 规律作息、保证充足睡眠，避免久坐及长期熬夜，合并高血压、糖尿病者同步控制血压血糖。\n\n【随诊要求】\n1. 开始用药后4-8周复查血脂、肝功能（ALT、AST）及肌酸激酶（CK），评估疗效与药物不良反应，据结果调整方案。\n2. 血脂达标后每3-6个月复查血脂，每6-12个月复查肝肾功能、血糖并评估心血管总体风险。\n3. 服药期间如出现肌肉酸痛、乏力、尿色加深（酱油色尿）、黄疸等，立即停用他汀/贝特并及时就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":912,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d3e14fbb3740db6d9028e174bbe2ec7968866df4bdc35a97c1e64a62f94b5992","pinyin":"hunhexinggaozhixuezheng","initials":"hhxgzxz","setting":"out","caseName":"门诊病历780","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历780",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-146c3cb5af43365b1ceb","key":"v1-c9ccc21dfe2a3058|templates-146c3cb5af43365b1ceb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"低高密度脂蛋白血症","category":"门诊病历模板","raw":{"name":"低高密度脂蛋白血症","category":"门诊病历模板","case":{"case_name":"门诊病历781","templates":{"主诉":"头晕1天","现病史":"患者1周前无明显诱因出现低高密度脂蛋白血症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因头晕1天就诊，现病史提示近1周症状逐渐加重伴轻度乏力，初步诊断低高密度脂蛋白血症，该病为动脉粥样硬化性心血管疾病的独立危险因素，头晕需排除贫血、血压异常及脑供血不足所致。入院即刻完善血常规检查排除感染、贫血；完善尿常规、便常规检查了解泌尿系与消化道情况，为长期调脂治疗提供基线评估；患者常需长期服用他汀类、贝特类等调脂药物，药物经肝肾代谢，完善肝肾功能检查明确有无肝肾功能不全，指导用药剂量与随访频次；完善血糖检查排除糖尿病及糖代谢异常所致继发性高密度脂蛋白胆固醇降低；完善血脂检查明确高密度脂蛋白胆固醇具体水平，并了解是否合并甘油三酯升高、低密度脂蛋白胆固醇升高，指导个体化调脂目标与治疗方案；完善电解质检查排除电解质紊乱所致头晕、乏力。低高密度脂蛋白血症提示动脉粥样硬化风险增高，完善心电图检查了解有无心肌缺血及心律失常；完善胸部X线片检查了解心肺形态及有无肺部基础病变；完善腹部超声检查了解有无脂肪肝及胆囊、胰腺病变。必要时完善颈动脉超声检查评估动脉粥样硬化斑块情况，明确心脑血管风险分层。病情稳定后定期复查血脂、肝肾功能，评估治疗反应并及时调整方案。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 低高密度脂蛋白血症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 贝特类（首选，适用于伴高甘油三酯血症者）：非诺贝特胶囊（微粒化）0.2g qd，随餐口服，疗程3-6个月，可升高HDL-C约10%-20%；用药期间监测肝功能、肾功能及肌酸激酶。\n2. 烟酸类（适用于HDL-C显著偏低、耐受良好者）：阿昔莫司胶囊0.25g tid，餐后口服，疗程3-6个月，可升高HDL-C约15%-25%；注意颜面潮红、皮肤瘙痒、胃肠道不适等不良反应，缓释烟酸因安全性问题不作为常规选择。\n3. 他汀类（适用于合并LDL-C升高或动脉粥样硬化性心血管疾病高危者）：阿托伐他汀钙片20mg qn口服，长期维持，以降低LDL-C为主，对HDL-C升高幅度有限（约5%-10%），不作为单纯升高HDL-C的常规用药。\n4. 重度原发性低HDL血症（如家族性ApoA-I缺陷、LCAT缺乏）可考虑重组HDL制剂等专科治疗，建议转心血管专科评估后用药，门诊不常规处方。\n\n【一般治疗及生活指导】\n1. 运动：坚持规律有氧运动，每周至少150分钟中等强度（如快走、慢跑、游泳、骑行），可使HDL-C升高5%-10%；避免久坐不动。\n2. 饮食：采用地中海式饮食，增加橄榄油、坚果、深海鱼（富含ω-3多不饱和脂肪酸）及新鲜蔬果，减少精制糖、甜饮料及反式脂肪酸摄入；吸烟者戒烟，饮酒者严格限量（男性≤2份/日，女性≤1份/日，1份约合酒精15g）。\n3. 体重管理：超重或肥胖者通过饮食与运动使体重下降5%-10%，可明显改善HDL-C水平；合并糖尿病、高血压者应同步控制血糖、血压。\n4. 禁忌：避免高糖高脂饮食、大量饮酒及吸烟；合并高甘油三酯血症者尤应限制酒精及单糖摄入，避免诱发急性胰腺炎。\n\n【随诊要求】\n1. 开始药物治疗后4-6周复查血脂全套（TC、TG、HDL-C、LDL-C）、肝功能及肌酸激酶，评估疗效与药物不良反应。\n2. 血脂稳定达标后每3-6个月复查1次，长期维持治疗者每6-12个月复查1次。\n3. 合并糖尿病、高血压或冠心病等动脉粥样硬化性心血管疾病高危者，按相应专科要求定期随访，并每1-3个月评估心血管综合危险因素。\n4. 治疗期间出现肌痛、肌无力、乏力、黄疸、尿色加深等不适，应及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":913,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"9fc965d6bf7cb50cf278a99a9a6a3b7f919df38514e573f8041ba1018330783f","pinyin":"digaomiduzhidanbaixuezheng","initials":"dgmdzdbxz","setting":"out","caseName":"门诊病历781","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历781",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-8cb6f2e649eec9f5861f","key":"v1-c9ccc21dfe2a3058|templates-8cb6f2e649eec9f5861f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痛风石","category":"门诊病历模板","raw":{"name":"痛风石","category":"门诊病历模板","case":{"case_name":"门诊病历782","templates":{"主诉":"关节肿痛1天","现病史":"患者1周前无明显诱因出现痛风石相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟；饮酒25年，约4两/日。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因关节肿痛1天就诊，查体见痛风石，考虑痛风性关节炎急性发作，关节肿痛需与感染性关节炎、假性痛风及外伤性关节病变鉴别。急性期完善血尿酸及电解质检查明确血尿酸水平及有无电解质紊乱，指导抗炎止痛与降尿酸治疗；痛风石提示长期嘌呤代谢紊乱，常与糖脂代谢异常并存，完善空腹血糖、餐后2小时血糖、糖化血红蛋白检查明确有无糖尿病或糖代谢异常，并了解近3个月血糖控制水平；完善胰岛素释放试验、C肽检查评估胰岛β细胞分泌功能及胰岛素抵抗程度，指导代谢综合管理；完善血脂检查了解血脂水平，指导调脂方案；痛风石常伴肾脏受累，完善尿微量白蛋白检查明确有无早期肾损害；降尿酸药物经肝肾代谢，完善肝肾功能检查明确有无肝肾功能不全，指导药物选择与剂量调整；完善甲状腺功能检查排除甲状腺功能异常所致代谢紊乱，必要时完善甲状腺超声检查了解甲状腺形态及有无结节；若需排查肾上腺源性代谢异常，必要时完善肾上腺CT检查明确肾上腺有无结节或增生。病情稳定后定期复查血尿酸、肝肾功能及尿微量白蛋白，评估痛风石变化及治疗反应。\n\n（检查清单）\n【必做检查】\n空腹血糖、餐后2小时血糖、糖化血红蛋白、胰岛素释放试验、C肽\n\n【影像学检查】\n甲状腺超声（必要时）、肾上腺CT（必要时）\n\n【其他检查】\n甲状腺功能、尿微量白蛋白、肝肾功能、血脂、电解质","初步诊断":"1. 痛风石\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 急性发作期抗炎镇痛：秋水仙碱片0.5mg bid（发作48小时内尽早服用，首剂1.0mg，1小时后加服0.5mg），或依托考昔片120mg qd×3～5天，症状缓解后停药，禁用于活动性消化道溃疡及肾功能不全者。\n2. 降尿酸治疗（痛风石需长期达标）：非布司他片40mg qd 起始，4周后据血尿酸调整至40～80mg qd；或别嘌醇片100mg qd 起始，每2周递增100mg，最大300mg qd（用药前检测HLA-B*5801基因，阳性者禁用）。目标：血尿酸降至300μmol/L以下并长期维持，以促进痛风石溶解。\n3. 碱化尿液：碳酸氢钠片1.0g tid，维持尿pH在6.2～6.9，以促进尿酸盐溶解排泄。\n4. 痛风石破溃感染时：局部清创换药，口服阿莫西林克拉维酸钾片0.457g（含阿莫西林0.4g）bid×7天（青霉素过敏者改用头孢呋辛酯片0.25g bid×7天）。\n\n【一般治疗及生活指导】\n1. 饮食：严格低嘌呤饮食，禁食动物内脏、浓肉汤、沙丁鱼、贝类等海产品及香菇、豆芽；限制牛肉、羊肉、猪肉及含果糖饮料摄入；乳制品、鸡蛋、新鲜蔬菜可正常食用。\n2. 饮水：每日饮水量2000～3000ml，尿量保持2000ml以上，分次饮用，促进尿酸排出。\n3. 活动与护理：避免受累关节剧烈活动及挤压摩擦，穿宽松软底鞋；痛风石表面皮肤注意保护，避免破损感染；急性期关节制动休息，缓解期适当进行非负重活动（如游泳、骑自行车）。\n4. 禁忌：严格戒酒（尤其啤酒及黄酒），戒烟；避免使用噻嗪类利尿剂、阿司匹林、环孢素等升高血尿酸药物。\n\n【随诊要求】\n1. 治疗初期每2～4周复查血尿酸，根据结果调整降尿酸药剂量；血尿酸达标后每3个月复查1次。\n2. 每1～3个月复查肝肾功能及血常规，监测药物不良反应。\n3. 服用别嘌醇者出现皮疹、发热、瘙痒立即停药并就诊；痛风石增大、破溃流液或伴发热、关节红肿加重时随时复诊。\n4. 每6个月评估痛风石大小变化及有无肾功能损害（尿常规、血肌酐），必要时行泌尿系超声检查。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":914,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7809350ae9462642fc69dbc5580301c1c2fa98283de9fe3f1de9c05f0344da44","pinyin":"tongfengshi","initials":"tfs","setting":"out","caseName":"门诊病历782","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历782",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-df3adb434d8ab11cb0b5","key":"v1-c9ccc21dfe2a3058|templates-df3adb434d8ab11cb0b5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"尿酸性肾病","category":"门诊病历模板","raw":{"name":"尿酸性肾病","category":"门诊病历模板","case":{"case_name":"门诊病历783","templates":{"主诉":"腰痛1天","现病史":"患者1周前无明显诱因出现尿酸性肾病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因腰痛1天就诊，初步诊断尿酸性肾病，腰痛需排除泌尿系结石、尿路感染及腰肌劳损所致。入院即刻完善尿常规检查明确有无血尿、蛋白尿、脓尿及尿酸盐结晶；完善尿微量白蛋白检查了解有无早期肾小球损伤；完善24小时尿蛋白定量检查明确蛋白尿程度，评估肾脏损伤轻重；完善肾功能检查明确血肌酐、尿素氮及血尿酸水平，了解肾小球滤过功能并据以分期，指导降尿酸药物剂量调整；完善电解质检查排除高钾血症、低钠血症等电解质紊乱；完善泌尿系超声检查明确有无尿酸性结石、肾积水及肾脏大小形态改变。尿酸性肾病需与其他肾小球疾病鉴别，完善血常规检查排除感染、贫血；完善肝功能检查了解肝脏合成功能，为用药治疗提供基线；完善凝血功能检查评估有无出血倾向，为有创检查做准备；怀疑免疫相关肾损害时完善自身抗体检查明确有无自身免疫性疾病。若蛋白尿持续加重、肾功能进行性下降或上述检查仍不能明确病因，病情稳定后完善肾脏穿刺活检明确病理诊断，指导治疗。治疗期间定期复查尿常规、肾功能、电解质及尿微量白蛋白。\n\n（检查清单）\n【必做检查】\n尿常规、尿微量白蛋白、24小时尿蛋白定量、肾功能、电解质\n\n【影像学检查】\n泌尿系超声、肾脏穿刺（必要时）\n\n【其他检查】\n血常规、肝功能、凝血功能、自身抗体（必要时）","初步诊断":"1. 尿酸性肾病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 降尿酸治疗：非布司他片20mg qd口服，2周后复查血尿酸，未达标（<360μmol/L，伴痛风石者<300μmol/L）可增至40mg qd，长期维持；或别嘌醇片100mg qd起始（用药前建议检测HLA-B*5801基因），2~4周后根据血尿酸渐增至100mg tid，最大量300mg/d，肾功能不全者减量。\n2. 碱化尿液：碳酸氢钠片1.0g tid，饭后口服，定期监测尿pH，维持晨尿pH 6.2~6.9（不宜>7.0，以免形成磷酸盐结石）。\n3. 促尿酸排泄（肾功能正常、无尿路结石时）：苯溴马隆片50mg qd晨起顿服，服药期间每日饮水量≥2000ml；与促尿酸排泄药联用降尿酸治疗初始可预防性小剂量秋水仙碱，肾功能不全者禁用。\n4. 急性关节炎发作（尿酸性肾病合并痛风发作时）：秋水仙碱片0.5mg bid，症状缓解后逐渐减停，肾功能不全者减量或换用泼尼松片10~20mg qd短期口服，慎用NSAIDs。\n\n【一般治疗及生活指导】\n1. 饮食：低嘌呤饮食，禁食动物内脏、浓肉汤、海产品（沙丁鱼、贝类）、啤酒及含果糖饮料；限制红肉、肉禽类摄入，鼓励新鲜蔬菜、低脂奶、蛋类及适量豆制品。\n2. 饮水：每日饮水量2000~3000ml（心肾功能允许时），保持尿量>2000ml/d，分次均匀饮水，稀释尿中尿酸并促进排泄。\n3. 休息与活动：急性发作期关节制动、卧床休息；缓解期适当有氧运动（快走、游泳等），控制体重，避免剧烈运动、受凉、关节外伤及长途步行诱发发作。\n4. 禁忌：戒酒（尤其啤酒），避免使用噻嗪类利尿剂、袢利尿剂、小剂量阿司匹林、吡嗪酰胺等影响尿酸排泄或升高尿酸的药物；需行造影检查者检查前充分水化并告知医生肾脏病史。\n\n【随诊要求】\n1. 降尿酸治疗起始后2周复查血尿酸、血肌酐、eGFR及尿常规，之后每1~3个月复查一次，根据血尿酸调整剂量，长期维持血尿酸<360μmol/L（伴痛风石者<300μmol/L）。\n2. 每2~4周监测尿pH，维持6.2~6.9，定期行泌尿系超声检查有无尿酸结石形成。\n3. 每3~6个月复查肾功能（血肌酐、eGFR）、24小时尿蛋白定量、尿微量白蛋白及肾脏超声，评估肾损害进展。\n4. 出现关节红肿热痛、腰腹疼痛、肉眼血尿、少尿、水肿加重等情况及时复诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":915,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"335fb9209aa2b187f96d092776751eed8f70e8069736f502249389c99a2d076f","pinyin":"niaosuanxingshenbing","initials":"nsxsb","setting":"out","caseName":"门诊病历783","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历783",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-95c36d588df5dc08db5d","key":"v1-c9ccc21dfe2a3058|templates-95c36d588df5dc08db5d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"佝偻病","category":"门诊病历模板","raw":{"name":"佝偻病","category":"门诊病历模板","case":{"case_name":"门诊病历784","templates":{"主诉":"多汗1天","现病史":"患者1周前无明显诱因出现佝偻病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。无吸烟、饮酒史，家庭无二手烟暴露。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因多汗1天就诊，现病史提示近1周症状逐渐加重伴轻度乏力，初步诊断佝偻病，多汗、乏力提示钙磷代谢及维生素D营养状态异常。入院即刻完善血常规检查排除感染、贫血；完善尿常规、便常规检查了解泌尿系与消化道情况，评估有无慢性腹泻、吸收不良等影响维生素D摄入与吸收的因素；完善肝肾功能检查明确有无肝肾功能不全影响维生素D的羟化活化，同时为补充治疗提供用药安全依据；完善血糖检查排除低血糖及糖代谢异常所致多汗、乏力；完善血脂检查了解脂溶性维生素吸收相关的营养与脂代谢状况；完善电解质检查明确有无低钙血症、低磷血症。佝偻病本质为骨矿化障碍，完善血钙、血磷及碱性磷酸酶检查明确骨矿化与骨转换指标，完善25-羟维生素D及甲状旁腺激素检查明确维生素D缺乏程度及有无继发性甲状旁腺功能亢进。完善心电图检查了解有无低钙所致QT间期延长及心律失常；完善胸部X线片检查了解心肺形态，排除肺部感染、结核等慢性消耗性疾病；完善腹部超声检查了解肝胆胰脾及肾脏情况；必要时完善腕关节X线检查了解骨骺端矿化情况。治疗期间定期复查血钙、血磷、碱性磷酸酶及25-羟维生素D，评估补充疗效。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 佝偻病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 维生素D制剂（首选维生素D3/胆骨化醇）：维生素D3滴剂或胶囊1000~2000IU qd口服，疗程4~8周；用药4周后复查血清25-(OH)D3，达标（>30ng/ml）后改维持量400~800IU qd长期维持。依从性差或重度缺乏者：维生素D2注射液30万IU单次肌注，1个月后复查血钙、血磷及25-(OH)D3再决定是否补注。\n2. 钙剂：碳酸钙D3片（每片含元素钙600mg、维生素D3 400IU）1片 qd口服，进餐时嚼服；钙摄入不足或血钙偏低者增至1片 bid，疗程与维生素D同步。注意：钙剂患者足量维生素D基础上服用，避免空腹服用，防止高钙血症。\n3. 骨化三醇（活性维生素D，适用于肝肾功能不全或常规维生素D疗效不佳者）：骨化三醇软胶囊0.25μg bid口服，2周后复查血钙、血磷、碱性磷酸酶，据结果调整剂量；治疗期间监测血钙、尿钙以防高钙血症。\n\n【一般治疗及生活指导】\n1. 日照：每日户外活动1~2小时，于上午10时前或下午4时后裸露面部、颈部及四肢皮肤直接日晒（勿隔玻璃、勿暴晒），促进皮肤内源性维生素D合成。\n2. 饮食：保证富含钙与维生素D饮食，每日奶及奶制品300~500ml，适量动物肝脏、蛋黄、深海鱼（三文鱼、沙丁鱼）、豆制品及绿叶蔬菜；避免浓茶、咖啡及高磷饮料（碳酸饮料）影响钙吸收。\n3. 活动：适度负重运动（快走、慢跑、抗阻训练）促进骨骼矿化；避免剧烈运动、长时间久站久行及跌倒，防止病理性骨折；下肢畸形者避免过度负重，必要时拄拐减负。\n4. 禁忌：戒烟限酒；避免长期或大剂量使用糖皮质激素、抗癫痫药（苯巴比妥、苯妥英钠）等影响钙磷代谢及骨形成的药物；不自行加量服用维生素D及钙剂。\n\n【随诊要求】\n1. 治疗4~8周后复诊，复查血清钙、磷、碱性磷酸酶及25-(OH)D3，评估疗效并调整维生素D及钙剂剂量。\n2. 稳定期每3~6个月复诊一次，监测25-(OH)D3及骨代谢指标；如出现厌食、恶心、呕吐、多尿、便秘、精神萎靡等表现，警惕维生素D中毒或高钙血症，应立即复诊。\n3. 骨痛不缓解、出现新发骨折或下肢畸形进行性加重者，及时复诊并行X线、骨密度等检查，必要时转骨科评估矫形治疗指征。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":916,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7a5cd5db8c37c45334e9d96445e27beb02eb0f307354b48db0e11a83c8593cf0","pinyin":"gouloubing","initials":"glb","setting":"out","caseName":"门诊病历784","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历784",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-ba3b644c8eda8d7ceb2c","key":"v1-c9ccc21dfe2a3058|templates-ba3b644c8eda8d7ceb2c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状旁腺功能亢进性骨病","category":"门诊病历模板","raw":{"name":"甲状旁腺功能亢进性骨病","category":"门诊病历模板","case":{"case_name":"门诊病历785","templates":{"主诉":"骨痛1天","现病史":"患者1周前无明显诱因出现甲状旁腺功能亢进性骨病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因骨痛1天就诊，现病史提示近1周骨痛逐渐加重伴轻度乏力，初步诊断甲状旁腺功能亢进性骨病，骨痛需与类风湿关节炎、强直性脊柱炎及骨肿瘤、骨转移鉴别。入院即刻完善血常规检查排除感染、贫血及血液系统疾病；完善血沉、CRP检查了解有无炎症活动；完善血钙磷碱性磷酸酶检查明确有无血钙升高、血磷降低及碱性磷酸酶升高的高骨转换状态，是本病诊断与病情评估的核心指标；同时完善甲状旁腺激素及25-羟维生素D检查明确甲状旁腺功能状态与维生素D水平，完善24小时尿钙检查了解尿钙排泄，评估高钙血症及泌尿系结石风险；完善类风湿因子检查排除类风湿关节炎；完善HLA-B27检查排除强直性脊柱炎等脊柱关节病；完善关节超声检查了解关节滑膜、肌腱及有无滑膜炎；骨痛伴肌无力者完善肌电图检查明确有无神经肌肉损害。影像方面完善X线片检查了解骨质稀疏、骨膜下骨吸收及有无纤维囊性骨炎；必要时完善CT、MRI检查明确骨病变范围及有无甲状旁腺病变定位；完善骨密度检查明确骨质疏松程度，评估骨折风险，指导抗骨质疏松治疗。病情稳定后定期复查血钙、血磷、碱性磷酸酶及甲状旁腺激素。\n\n（检查清单）\n【必做检查】\n血常规、血沉、CRP、血钙磷碱性磷酸酶\n\n【影像学检查】\nX线片、CT、MRI、骨密度检查\n\n【其他检查】\n关节超声、肌电图、类风湿因子、HLA-B27","初步诊断":"1. 甲状旁腺功能亢进性骨病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 拟钙剂：西那卡塞片25mg qd（餐后整片吞服），每2～4周根据血钙及全段甲状旁腺激素（iPTH）水平调整剂量，最大100mg/d，疗程至少3～6个月；适用于不能耐受或拒绝手术的原发性甲旁亢及透析合并继发性甲旁亢患者。\n2. 双膦酸盐：阿仑膦酸钠片70mg qw，晨起空腹以白水约200ml送服，服后至少30分钟内保持上半身直立且不进食、不饮水，用于合并骨质疏松或骨量减少、骨转换增高者，疗程3～6个月后复查骨转换指标及骨密度评估疗效；长期用药期间注意补充元素钙500mg/d及维生素D。\n3. 活性维生素D：骨化三醇软胶囊0.25μg bid口服（或0.25～0.5μg qd），用于继发性甲旁亢伴低钙血症或25-羟维生素D缺乏者，用药期间定期监测血钙、血磷，避免诱发高钙血症。\n4. 高钙血症对症处理：鲑降钙素注射液50～100IU，im，qd，短期使用（一般不超过2周）以快速降低血钙，同时保证每日饮水2000～3000ml促进尿钙排泄；顽固性高钙血症者及时转外科评估甲状旁腺切除术。\n\n【一般治疗及生活指导】\n1. 饮水：每日饮水2000～3000ml（心、肾功能允许时），稀释尿液、促进尿钙排泄，预防肾结石及泌尿系感染；注意观察有无肉眼血尿、腰痛等结石症状。\n2. 饮食：限制高钙、高磷及高钠饮食，少食奶制品、豆制品、坚果、动物内脏及含磷饮料，避免大量饮用浓茶、咖啡及碳酸饮料，戒烟限酒。\n3. 活动与防骨折：骨病期骨脆性增加，宜进行散步等缓和的负重活动，避免剧烈运动、搬重物及跌倒，必要时使用拐杖或腰围等支具保护，谨防病理性骨折；避免长期卧床。\n4. 禁忌：避免使用噻嗪类利尿剂、锂盐及过量维生素A（均可加重高钙血症），避免自行大量补钙或服用含钙保健品，用药及补钙方案医师指导下进行。\n\n【随诊要求】\n1. 每1～3个月门诊复查血钙、血磷、碱性磷酸酶（ALP）、全段甲状旁腺激素（iPTH）及24小时尿钙，评估病情变化及药物疗效，据此调整用药方案；\n2. 长期服用西那卡塞、双膦酸盐或骨化三醇者，每3～6个月复查肾功能（血肌酐、eGFR）、电解质及肝功能，监测药物不良反应；\n3. 每年行双能X线骨密度（DXA）检查监测骨密度变化；如出现骨痛进行性加重、新发骨折、明显多饮多尿、恶心呕吐、便秘或意识改变等表现，应随时就诊；\n4. 确诊原发性甲状旁腺功能亢进症且有手术指征（血钙显著升高、合并肾结石、骨密度明显下降等）者，建议及时转普外科或甲状腺外科评估甲状旁腺切除术。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":917,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0101a8c8b526de6b409b36eaf487a1470801d89f78083d2a6736072ec3f222be","pinyin":"jiazhuangpangxiangongnengkangjinxinggubing","initials":"jzpxgnkjxgb","setting":"out","caseName":"门诊病历785","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历785",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-e868ed7d0e1c09fd85d3","key":"v1-c9ccc21dfe2a3058|templates-e868ed7d0e1c09fd85d3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"肾性骨病","category":"门诊病历模板","raw":{"name":"肾性骨病","category":"门诊病历模板","case":{"case_name":"门诊病历786","templates":{"主诉":"骨痛1天","现病史":"患者1周前无明显诱因出现肾性骨病相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因骨痛1天就诊，现病史提示近1周骨痛逐渐加重伴轻度乏力，初步诊断肾性骨病，骨痛与慢性肾脏病所致钙磷代谢紊乱及继发性甲状旁腺功能亢进相关。入院即刻完善尿常规检查明确有无蛋白尿、血尿；完善尿微量白蛋白检查明确有无早期肾损伤；完善24小时尿蛋白定量检查明确蛋白尿程度；完善肾功能检查明确血肌酐、尿素氮及估算肾小球滤过率，评估慢性肾脏病分期，是肾性骨病诊治的基础；完善电解质检查明确有无高磷、低钙及高钾血症；完善泌尿系超声检查了解肾脏大小、形态及有无积水、结石；完善血常规检查排除感染、贫血并评估肾性贫血程度；完善肝功能检查了解肝脏合成功能与营养状况；完善凝血功能检查评估出血倾向，为有创检查做准备；考虑免疫性肾损害时完善自身抗体检查明确病因。骨代谢方面完善血钙、血磷及碱性磷酸酶检查了解骨矿化与骨转换状态，完善甲状旁腺激素及25-羟维生素D检查明确继发性甲状旁腺功能亢进程度及维生素D缺乏情况，完善骨密度检查及X线片检查了解骨质疏松与骨吸收改变，评估骨折风险。病因不明或肾功能快速恶化时，病情稳定后完善肾脏穿刺活检明确病理类型。定期复查肾功能、电解质、血钙、血磷及甲状旁腺激素。\n\n（检查清单）\n【必做检查】\n尿常规、尿微量白蛋白、24小时尿蛋白定量、肾功能、电解质\n\n【影像学检查】\n泌尿系超声、肾脏穿刺（必要时）\n\n【其他检查】\n血常规、肝功能、凝血功能、自身抗体（必要时）","初步诊断":"1. 肾性骨病\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 磷结合剂（降磷）：碳酸钙D3片（含元素钙125mg/片）0.5g 餐中嚼服 tid，随餐服用同步降磷；血磷>1.78mmol/L且血钙正常或偏低时首选，若出现高钙血症（血钙>2.54mmol/L）换用司维拉姆片0.8g 餐中吞服 tid。\n2. 活性维生素D（抑制PTH、纠正骨矿化障碍）：骨化三醇胶囊0.25μg 口服 qd（或0.5μg隔日一次），根据血iPTH水平每1-3个月调整剂量，维持iPTH在正常上限2-9倍的目标范围。\n3. 钙剂补充（纠正低钙血症，血钙<2.1mmol/L时）：碳酸钙D3片0.6g（含元素钙600mg）口服 qn，血钙达标后减量或停用。\n4. 拟钙剂（继发性甲状旁腺功能亢进明显、iPTH持续升高且血钙偏高者）：西那卡塞片25mg 口服 qd，餐后服用，据血钙及iPTH每1-3个月调整，长期维持治疗。\n【一般治疗及生活指导】\n1. 低磷饮食：忌坚果、动物内脏、蛋黄、奶酪、豆制品及含磷添加剂的加工食品和碳酸饮料，每日磷摄入<800mg；同时予优质低蛋白饮食（0.6-0.8g/kg·d），保证热量供应。\n2. 限制钠盐摄入（<5g/d），按血钾水平限制高钾食物（香蕉、橙子、土豆、菌菇等）；戒烟限酒，规律监测并控制血压、血糖。\n3. 活动指导：无骨痛及骨折者可行散步等低强度活动，避免剧烈运动、负重和跌倒，防止病理性骨折；已有骨痛或骨质疏松者注意休息，必要时拄拐或佩戴护具保护。\n4. 规律血液透析或腹膜透析患者按时透析，不自行停用磷结合剂及活性维生素D，避免擅自服用含铝抗酸剂或含磷保健品。\n【随诊要求】\n1. 每1-3个月复查血钙、血磷、血iPTH、碱性磷酸酶、肌酐及eGFR，据结果调整磷结合剂、活性维生素D及拟钙剂剂量。\n2. 每6-12个月复查25-羟维生素D及骨密度（DXA），每年摄骨X线（脊柱、骨盆、四肢）评估肾性骨病进展。\n3. 服药期间出现恶心、食欲减退、便秘（钙剂）或血钙>2.54mmol/L、iPTH下降过快时，及时复诊调整方案；骨痛加重、自发性骨折或疑似甲旁亢危象，立即就诊并转肾内科、内分泌科进一步评估。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":918,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b14858f3c4da0a24472cb0721e9637d051c5003ac7f5aed420ffa80078406c28","pinyin":"shenxinggubing","initials":"sxgb","setting":"out","caseName":"门诊病历786","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历786",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c84668ac4a9d01c64428","key":"v1-c9ccc21dfe2a3058|templates-c84668ac4a9d01c64428","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"维生素缺乏症","category":"门诊病历模板","raw":{"name":"维生素缺乏症","category":"门诊病历模板","case":{"case_name":"门诊病历787","templates":{"主诉":"乏力1天","现病史":"患者1周前无明显诱因出现维生素缺乏症相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者因乏力1天就诊，现病史提示近1周症状逐渐加重，初步诊断维生素缺乏症，乏力需排除贫血、感染、内分泌及代谢异常所致。入院即刻完善血常规检查排除感染、贫血及血液系统疾病；完善尿常规、便常规检查了解泌尿系与消化道情况，评估有无慢性腹泻、吸收不良等导致维生素摄入或吸收不足的原因；完善肝肾功能检查明确有无肝肾功能不全影响维生素代谢与活化，并为补充治疗提供用药安全依据；完善血糖检查排除低血糖及糖尿病所致乏力；完善血脂检查了解脂溶性维生素吸收相关的营养与脂代谢状况；完善电解质检查排除低钾、低钠等电解质紊乱所致乏力。根据缺乏类型针对性完善维生素水平测定（如维生素B12、叶酸、25-羟维生素D等），明确缺乏种类与程度，指导补充剂量与疗程。完善心电图检查了解有无心肌缺血、心律失常及低钾相关改变；完善胸部X线片检查了解心肺形态，排除肺部感染、结核等慢性消耗性疾病；完善腹部超声检查了解肝胆胰脾及有无吸收不良相关病变。病情稳定后定期复查血常规、相关维生素水平及电解质，评估补充治疗效果。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 维生素缺乏症\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 复合维生素B片（含维生素B1 3mg、维生素B2 1.5mg、维生素B6 0.2mg、烟酰胺10mg）2片 po tid×14天，餐后服用，用于口角炎、舌炎、周围神经炎等B族维生素缺乏。\n2. 维生素C片0.1g po tid×14天，餐后服用，用于牙龈出血、皮肤瘀点等维生素C缺乏表现。\n3. 维生素D3（胆骨化醇）800IU po qd，疗程4-8周；缺乏明显者改骨化三醇0.25μg po bid，4周后复查血25-(OH)D、血钙、尿钙调整剂量。\n4. 叶酸片5mg po tid×4周，用于合并叶酸缺乏性贫血者，并同时评估维生素B12水平以除外巨幼细胞性贫血。\n\n【一般治疗及生活指导】\n1. 饮食均衡：每日摄入深色蔬菜、新鲜水果、全谷类、瘦肉、动物肝脏、蛋奶等，纠正偏食、节食及长期素食；蔬菜急火快炒、避免长时间高温烹煮，防止维生素破坏。\n2. 生活习惯：戒烟限酒，规律作息、避免熬夜；长期酗酒者需同步戒酒，因酒精干扰B族维生素吸收利用。\n3. 户外活动：每日晒太阳15-30分钟（避开正午暴晒）促进维生素D合成，避免过度防晒；老年人、孕产妇、长期服药（如异烟肼、抗癫痫药）者注意相应维生素补充。\n4. 禁忌：避免自行大剂量滥用脂溶性维生素（A、D、E、K），以防蓄积中毒；服药期间忌与茶水同服（鞣酸影响吸收）。\n\n【随诊要求】\n1. 2周后复诊评估症状改善情况（口角炎、舌炎、牙龈出血、乏力等），按需调整剂量或疗程。\n2. 长期补充者每3-6个月复查血维生素水平（25-(OH)D、叶酸、维生素B12）及血常规、肝肾功能，监测疗效与蓄积风险。\n3. 若出现新发肢体麻木、步态不稳、感觉异常等神经症状，或皮疹、恶心、高钙血症等药物不良反应，及时返诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":919,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"42377c67285c1fd50c87916a88db55ddabda737544cf85e338f28543bddfc436","pinyin":"weishengsuquefazheng","initials":"wssqfz","setting":"out","caseName":"门诊病历787","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历787",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-23b92a8de8549aa83145","key":"v1-c9ccc21dfe2a3058|templates-23b92a8de8549aa83145","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"微量元素缺乏","category":"门诊病历模板","raw":{"name":"微量元素缺乏","category":"门诊病历模板","case":{"case_name":"门诊病历788","templates":{"主诉":"乏力1天","现病史":"患者1周前无明显诱因出现微量元素缺乏相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以乏力1天为主诉就诊，现病史提示近1周相关症状逐渐加重、自服药物效果欠佳，需先行血常规检查明确有无感染、贫血所致乏力，并了解血小板水平；完善尿常规检查排除泌尿系感染、尿糖及尿蛋白异常，完善便常规检查排除消化道慢性失血与寄生虫感染等导致营养吸收障碍的原因；长期营养摄入不足或吸收障碍可影响多种微量元素吸收，完善肝肾功能检查了解肝脏合成与肾脏排泄功能，排除肝肾疾病所致代谢异常及微量元素代谢紊乱；完善血糖检查排除糖尿病或低血糖所致乏力，查血脂检查了解脂代谢水平并评估营养状况；微量元素缺乏常伴电解质失衡，完善电解质检查明确有无低钾、低钠、低钙等紊乱，同时为后续补充治疗提供基线依据；乏力需警惕心脏病变，完善心电图检查排除心律失常与心肌缺血；完善胸部X线片检查排除肺部感染、肺结核及肺部占位性病变；患者诉食欲及消化功能欠佳，完善腹部超声检查了解肝胆胰脾形态，排除慢性肝病、胆道疾病及胰腺病变所致消化吸收不良。后续根据病情需要选择血清铁、锌、铜、硒等微量元素测定及相关内分泌、免疫学检查，进一步明确缺乏的具体元素种类与病因，必要时请营养科、消化内科会诊协助诊治。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 微量元素缺乏\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 锌缺乏：葡萄糖酸锌颗粒（70mg/袋，含元素锌10mg）1袋 po tid，餐后服用，连用4周后复查血锌调整方案；或甘草锌胶囊0.25g po tid，疗程4周。\n2. 铁缺乏：硫酸亚铁片0.3g po tid，餐后口服，联用维生素C片0.1g po tid促进铁吸收；血红蛋白恢复正常后继续服用3个月补足储存铁，总疗程3～6个月，服药前后1小时避免饮茶、咖啡。\n3. 硒缺乏：硒酵母片（含硒100μg/片）1片 po qd，连用4～8周后复查血硒。\n4. 多种微量元素缺乏或成分不明确者：多维元素片（含锌、铁、硒、铜、锰等）1片 po qd，餐后服用，连用4周后评估。\n\n【一般治疗及生活指导】\n1. 均衡膳食，食物多样化，纠正偏食、挑食；多摄入富含锌食物（牡蛎、贝类、瘦肉、动物肝脏、坚果）、富含铁食物（红肉、动物血、动物肝脏、蛋黄）及富含硒食物（海鱼、虾、蛋类、蘑菇）。\n2. 禁忌：避免进餐时或餐后立即饮用浓茶、浓咖啡及大量牛奶（影响铁、锌吸收）；服铁剂期间与钙剂、抗酸药（如铝碳酸镁）至少间隔2小时服用。\n3. 生活方式：规律作息，戒烟限酒；适当进行户外活动和体育锻炼（如快走、慢跑等中等强度运动30分钟/日，每周至少5次），增强体质、促进食欲。\n4. 素食者、胃肠手术史、慢性腹泻及长期服用抑酸药患者，应主动定期评估微量元素水平并针对性补充。\n\n【随诊要求】\n1. 补锌、补铁治疗2～4周后门诊复查血清锌、血清铁蛋白及血常规，评估疗效并调整剂量。\n2. 铁剂总疗程3～6个月（血红蛋白恢复正常后继续服用3个月补足储存铁）；治疗中出现明显恶心、腹痛、便秘等不耐受表现时及时复诊调整方案。\n3. 每3～6个月复查微量元素水平及肝肾功能；若症状无改善或出现异食癖、脱发加重、反复感染、生长发育迟缓等，建议进一步检查以排查慢性吸收障碍等病因。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":920,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"18981a916e8733936011e7a138a04ce518cd99da545608eafee290f03d66e3ed","pinyin":"weiliangyuansuquefa","initials":"wlysqf","setting":"out","caseName":"门诊病历788","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历788",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-a0fa355313738bc4181e","key":"v1-c9ccc21dfe2a3058|templates-a0fa355313738bc4181e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"水电解质紊乱","category":"门诊病历模板","raw":{"name":"水电解质紊乱","category":"门诊病历模板","case":{"case_name":"门诊病历789","templates":{"主诉":"乏力1天","现病史":"患者1周前无明显诱因出现水电解质紊乱相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以乏力1天为主诉就诊，现病史提示近1周相关症状逐渐加重、自服药物效果欠佳，水电解质紊乱常继发于呕吐、腹泻、利尿剂使用或内分泌疾病，需完善血常规检查排除感染、贫血所致乏力；完善尿常规检查了解尿比重、尿糖及尿蛋白，评估肾脏浓缩稀释功能与肾性失钠失钾的可能，完善便常规检查排除消化道感染、慢性失血及腹泻所致电解质经肠道丢失；完善肝肾功能检查排除肝肾功能不全所致水电解质代谢紊乱，并为补液及电解质补充方案提供依据；完善血糖检查排除糖尿病高渗状态及低血糖所致乏力，查血脂检查了解脂代谢水平；完善电解质检查明确钾、钠、氯、钙、镁的具体水平及紊乱类型，为精准补液补钾补钠提供依据，必要时加查血气分析明确有无酸碱失衡；水电解质紊乱易诱发心律失常，完善心电图检查排除低钾所致U波增高、心律失常及心肌缺血；完善胸部X线片检查排除肺部感染、胸腔积液等可能引起抗利尿激素分泌异常的原因；完善腹部超声检查了解肝胆胰脾及肾脏形态，排除肾上腺病变及肾性失盐所致电解质紊乱。后续根据病情需要选择血气分析、24小时尿电解质、醛固酮及甲状腺功能等检查，进一步明确水电解质紊乱的病因，必要时请肾内科、内分泌科会诊协助诊治。\n\n（检查清单）\n【必做检查】\n血常规、尿常规、便常规、肝肾功能、血糖、血脂、电解质\n\n【影像学检查】\n心电图、胸部X线片、腹部超声\n\n【其他检查】\n根据病情需要选择相应检查","初步诊断":"1. 水电解质紊乱\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 补液治疗：口服补液盐(Ⅲ)1袋冲温水250ml，少量多次口服，按脱水程度第1日总量约30-50ml/kg；轻中度脱水首选口服补液，不能口服或重度脱水者予0.9%氯化钠注射液500ml静脉滴注，视情况4-6小时后可重复。\n2. 补钾治疗：10%氯化钾口服溶液10ml tid（餐后服，可兑温水稀释），或氯化钾缓释片0.5g bid-tid；见尿补钾，静脉补钾浓度≤0.3%（1000ml液体中≤30ml 10%氯化钾注射液），滴速不超过1.5g/h，疗程3-7天复查血钾后调整。\n3. 低钾伴低镁血症：门冬氨酸钾镁片2片 tid，口服7-14天；纠正低镁有助于顽固性低钾纠正。\n4. 低钠血症（血钠<125mmol/L或有症状）：0.9%氯化钠注射液500ml静脉滴注，每日总量1000-2000ml，血钠上升速度每日不超过8-10mmol/L，防止渗透性脱髓鞘综合征；症状缓解后改口服补液及饮食调整。\n\n【一般治疗及生活指导】\n1. 休息：注意休息，避免劳累及剧烈运动、大量出汗；运动后及时补充含电解质的饮品（如口服补液盐或运动饮料），防止汗液丢失诱发或加重电解质紊乱。\n2. 饮食：清淡易消化饮食，适当进食富钾食物（香蕉、橙子、土豆、番茄、豆类）、富镁食物（坚果、深绿色蔬菜）；低钠者遵医嘱适度增加盐摄入，高钠者限制食盐（每日<5g）；避免长期禁食或过度节食。\n3. 记录每日出入量及体重变化，保证每日饮水量1500-2000ml（心肾功能不全者根据患者具体情况制定个体化方案），尿少时及时就医。\n4. 禁忌：慎用或停用影响电解质的药物（噻嗪类及袢利尿剂、泻药、糖皮质激素等），避免大量饮酒，避免自行长期服用含甘草的中成药及保健品。\n\n【随诊要求】\n1. 开始治疗后3-5天门诊复查电解质（血钾、钠、氯、钙、镁）及肾功能，评估纠正效果并调整用药。\n2. 电解质未完全恢复正常者每周复查1次，直至指标正常；恢复后每1-3个月监测1次电解质及原发病相关指标。\n3. 出现明显乏力、心悸、四肢麻木抽搐、恶心呕吐加重、意识模糊或尿量明显减少时，立即就近急诊就诊。\n4. 伴呕吐腹泻、发热等诱因未解除者，需在原发病随访基础上同步复查电解质，防止复发。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":921,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"22e7ca26e3b7c017b3ab873cc4aaa5cb2b86333b487384989ebc044ead7d4aba","pinyin":"shuidianjiezhiwenluan","initials":"sdjzwl","setting":"out","caseName":"门诊病历789","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历789",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-1500bf28d59bf6f6b5f5","key":"v1-c9ccc21dfe2a3058|templates-1500bf28d59bf6f6b5f5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"高颅压头痛","category":"门诊病历模板","raw":{"name":"高颅压头痛","category":"门诊病历模板","case":{"case_name":"门诊病历790","templates":{"主诉":"头痛1天","现病史":"患者1周前无明显诱因出现高颅压头痛相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以头痛1天为主诉就诊，现病史提示近1周头痛逐渐加重、自服药物效果欠佳，需警惕颅内压增高及颅内器质性病变，完善血常规检查排除感染、贫血所致头痛；完善生化全项检查了解肝肾功能、血糖及电解质水平，排除代谢性因素及肝肾功能不全所致头痛；完善凝血功能检查排除凝血机制障碍所致颅内静脉窦血栓及出血性疾病；完善血糖检查排除低血糖或糖尿病相关头痛，查血脂检查了解血脂水平、评估动脉粥样硬化危险因素；完善同型半胱氨酸检查评估高同型半胱氨酸血症所致血管内皮损伤及脑卒中风险；为明确有无颅内占位、出血、脑积水及静脉窦血栓，急诊完善头颅CT/MRI检查，必要时加做磁共振静脉成像明确静脉窦通畅情况；头痛需警惕颅外血管病变，完善颈动脉超声检查明确颈动脉有无斑块及狭窄，完善经颅多普勒检查了解颅内动脉血流速度及有无血管痉挛狭窄；完善心电图检查排除心律失常及心肌缺血，完善心脏超声检查排查心源性栓子来源；若头痛持续加重伴脑膜刺激征，病情稳定后必要时完善腰椎穿刺检查脑脊液压力、细胞及蛋白水平以鉴别颅内感染、蛛网膜下腔出血。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 高颅压头痛\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 碳酸酐酶抑制剂（首选降颅压药物）：乙酰唑胺片0.25g bid po，疗效不佳可增至tid，通过抑制脑脊液分泌降低颅内压，连用4周后根据眼底及颅内压复查结果评估减量；不耐受者改醋甲唑胺片25mg bid po。\n2. 脱水降颅压（急性颅压升高期）：20%甘露醇注射液125ml ivgtt q8h，门诊留观短期使用3~5天，期间监测电解质、肾功能及出入量，症状缓解后逐渐减量。\n3. 对症镇痛：对乙酰氨基酚片0.5g po prn（每日不超过3次）或布洛芬缓释胶囊0.3g bid po；禁用阿片类镇痛药及硝酸酯类扩血管药（可加重颅压升高）。\n【一般治疗及生活指导】\n1. 卧床休息，床头抬高15°~30°，保持环境安静；避免剧烈咳嗽、用力排便、屏气、弯腰负重等增加颅内压的动作，便秘者予乳果糖口服液通便。\n2. 低盐清淡饮食，适当限制饮水量（每日入量控制在1500~2000ml），戒烟限酒，避免咖啡因摄入过量。\n3. 超重或肥胖者（尤其育龄期女性）应积极减重5%~10%，可显著降低颅内压，配合规律有氧运动，但避免剧烈运动及倒立、下蹲起立过猛。\n4. 避免长时间低头、屈颈及驾驶、登高等活动，防止突发视物模糊或晕厥引发意外。\n【随诊要求】\n1. 用药期间每2~4周复诊1次，复查眼底、视力及视野检查，评估颅压控制情况。\n2. 治疗期间如出现视力下降、视野缺损、复视、头痛持续加重或意识改变，需立即急诊就诊。\n3. 长期使用乙酰唑胺者每月复查血常规、电解质及肝肾功能；甘露醇用药期间监测血钠、血钾及肾功能。\n4. 减量或停药须遵医嘱逐步进行，停药后2~4周复诊1次；病情稳定后每3个月随访1次，必要时复查头颅MRI/静脉窦成像评估病因。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":922,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e0c240eb800e2023e1c2acef851b5717772dd9411ee5b8f464ac4a803acf6a90","pinyin":"gaoluyatoutong","initials":"glytt","setting":"out","caseName":"门诊病历790","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历790",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-43e17a38b3e774ce7718","key":"v1-c9ccc21dfe2a3058|templates-43e17a38b3e774ce7718","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑梗死","category":"门诊病历模板","raw":{"name":"脑梗死","category":"门诊病历模板","case":{"case_name":"门诊病历791","templates":{"主诉":"突发右侧肢体无力伴言语不清3小时","现病史":"患者存在危险因素：高血压（最重要）、糖尿病、血脂异常、房颤（可致心源性栓塞，即心源性脑梗死，较为重要）、吸烟、颈动脉狭窄、既往TIA或卒中史。患者于3小时前突发（于活动中或睡眠后晨起发病，发病时间须明确，因发病时间是溶栓决策的关键，较为重要）以下表现：偏瘫（一侧肢体无力，累及上下肢，持物或行走不能）、面瘫（中枢性，口角歪斜，鼻唇沟变浅）、言语障碍（失语，表现为不能言语或理解障碍，见于左侧半球病变；或构音障碍，表现为言语含糊不清，见于脑干或小脑病变）、感觉障碍（一侧肢体麻木）、共济失调（小脑病变，行走不稳，可伴眩晕、恶心、呕吐，属后循环表现）、意识障碍（大面积梗死或脑干梗死可致昏迷）、视野缺损、吞咽困难、凝视麻痹、剧烈头痛（少见，提示出血或大血管病变）、癫痫（部分性发作）。发病形式可为突然起病（数秒内达高峰，提示栓塞）或渐进起病（数小时内进展，提示血栓进展，即卒中进展）。已行NIHSS评分，用于评估神经功能缺损程度并记录。今日来我院急诊卒中中心就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.8℃，P92次/分，R20次/分，BP168/96mmHg（高血压，急性期降压需谨慎）。神志清楚，格拉斯哥昏迷评分为15分；神经系统检查：偏瘫（左侧肢体肌力Ⅲ级，累及上下肢）、Babinski征阳性、中枢性面瘫（额纹存在）、运动性失语、感觉减退、共济运动欠稳、瞳孔等大（一侧散大提示脑疝，多见于大面积梗死，属急症）、无凝视麻痹、视野检查欠配合、NIHSS评分8分（记录基线）、心脏听诊未闻及房颤（心律绝对不齐提示房颤）、颈动脉未闻及杂音、吞咽功能已评估（注意误吸风险）。","辅助检查":"【必做】头颅CT平扫（为急诊首选，用于排除脑出血，溶栓前必须完成，为关键检查，属出血禁忌；早期脑梗死24小时内多正常，阴性不能排除；大面积梗死可见早期低密度及脑水肿征象）、血糖（低血糖可模拟卒中，必须检查，属急症可逆因素）、血常规、凝血功能（溶栓前必查）、电解质、心电图（了解有无房颤或心肌梗死，判断心源性因素）、肾功能。【确诊及评估】头颅MRI（弥散加权成像于发病数分钟即可显影，为早期梗死确诊的金标准，优于CT；MRA可评估血管及大血管闭塞）、头颅CT血管成像（CTA，评估大血管闭塞，为桥接取栓做准备）、灌注成像（评估缺血半暗带，用于取栓筛选）、颈动脉超声（评估狭窄）、超声心动图（评估心源性因素，如房颤、心内血栓）、经食管超声（评估卵圆孔未闭，用于隐源性卒中）、动态心电图（Holter，用于阵发房颤及隐源性卒中评估）。【其他】血脂、血糖、糖化血红蛋白（用于病因评估及二级预防）、同型半胱氨酸、血沉及自身抗体（用于青年卒中，评估血管炎及免疫因素）、梅毒及HIV（少见病因）。","初步诊断":"1. 急性脑梗死（定位：颈内动脉系统，即前循环；分型：动脉粥样硬化性；发病3小时；NIHSS评分8分）\n（注：脑梗死救治强调时间就是大脑，急性期患者卒中中心行时间窗内再灌注治疗，此为核心。①再灌注治疗：发病4.5小时内可行静脉溶栓（重组组织型纤溶酶原激活物rt-PA 0.9mg/kg，最大90mg，10%静推，余量静滴1小时；适应证为缺血性卒中4.5小时内、经NIHSS评估且无禁忌；禁忌包括出血史、近期手术、血压>185/110mmHg（需先控制），须严格筛查）；其获益为显著改善预后，越早越好，即所谓黄金一小时。大血管闭塞者（颈内动脉或大脑中动脉M1段）发病6小时内可行血管内取栓，若影像筛选提示灌注不匹配或侧支循环良好，可延长至24小时；机械取栓采用支架取栓器，若条件允许可行桥接治疗（溶栓后取栓），较为重要，可显著提高大血管闭塞的再通率。②一般治疗：气道、呼吸、循环管理（昏迷者需保护气道）；血压管理方面，溶栓或取栓后血压应<180/105mmHg，以防出血转化；未溶栓者急性期应谨慎降压，血压<220/120mmHg时可观察，除非合并其他器官损害，因降压过度可致梗死扩大，故早期不积极降压，较为重要；血糖应控制，高血糖可加重损害，可用胰岛素，目标<10mmol/L；体温升高需处理；营养方面应评估吞咽功能，防误吸，卒中相关肺炎是常见死因，吞咽困难者需鼻饲；预防深静脉血栓可用预防剂量肝素，并鼓励肢体活动；同时预防压疮。③抗血小板：未溶栓者发病48小时内予阿司匹林300mg首剂，继以氯吡格雷或阿司匹林加氯吡格雷（轻型卒中或TIA行双抗21天）；溶栓后24小时复查CT无出血后启动抗血小板治疗。④他汀：阿托伐他汀20~40mg，可稳定斑块，无论血脂水平如何，卒中后常规使用。⑤并发症处理：脑水肿见于大面积梗死，可用甘露醇，必要时行去骨瓣减压手术，适用于恶性大脑中动脉梗死，于48小时内实施，可降低死亡率，较为重要；出血转化需在抗栓后监测并处理；并防治肺炎、泌尿系感染；癫痫予抗癫痫治疗；抑郁可用SSRI，卒中后抑郁较常见。⑥病因及二级预防：心源性者如房颤需抗凝（华法林或新型口服抗凝药，于卒中后2周至数月启动，需评估）；颈动脉狭窄>70%者评估行内膜剥脱或支架治疗；控制血压<130/80mmHg、糖尿病HbA1c<7%、他汀治疗、戒烟、运动，并长期抗血小板。⑦康复：早期康复于病情稳定24~48小时后开始，包括物理、作业、言语及吞咽训练，在卒中单元进行，早期康复可显著改善功能，较为重要。随访：卒中门诊每1~3个月复查，评估危险因素控制及二级预防依从性，预防复发。急诊神经科及卒中中心患者时间窗内行溶栓或取栓，并行卒中单元综合管理、康复及二级预防。","处理方案":"【药物治疗】\n1. 抗血小板聚集：阿司匹林肠溶片100mg qd，晨起空腹口服，长期服用；不能耐受者改用氯吡格雷片75mg qd。\n2. 调脂稳定斑块：阿托伐他汀钙片20mg qn（睡前口服），长期服用，用药期间监测肝肾功能及肌酶。\n3. 改善脑循环及神经保护：丁苯酞软胶囊0.2g tid，疗程14天；或依达拉奉右莰醇注射用浓溶液30mg加入0.9%氯化钠注射液100ml静脉滴注qd，连用14天（门诊输液治疗）。\n4. 控制危险因素：合并高血压者予苯磺酸氨氯地平片5mg qd口服，使血压控制在130-140/80-90mmHg；合并糖尿病者予盐酸二甲双胍片0.5g bid口服，空腹血糖控制在4.4-7.0mmol/L。\n【一般治疗及生活指导】\n1. 休息与体位：急性期卧床休息，床头抬高15°-30°，保持呼吸道通畅，密切观察意识、瞳孔及肢体活动变化；病情平稳后尽早床上翻身及被动活动，预防压疮和深静脉血栓。\n2. 饮食：低盐低脂低糖饮食，每日食盐<6g，减少动物脂肪及内脏摄入，戒烟限酒，保证充足饮水，避免脱水致血液浓缩诱发再梗死。\n3. 活动：病情稳定后在康复治疗师指导下循序渐进进行肢体功能锻炼、平衡训练及语言康复，避免剧烈运动、过度劳累及情绪激动。\n4. 禁忌：避免用力排便、长时间屏气、蹲位起身过猛及突然扭头，保持大便通畅，必要时予乳果糖口服液15ml qd通便。\n【随诊要求】\n1. 2周内复诊，复查头颅CT/MRI、血脂、血糖、肝肾功能及肌酶，评估药物疗效与不良反应。\n2. 每日自我监测血压，每周监测血糖，记录于血压血糖日记，复诊时携带。\n3. 遵医嘱每1-3个月门诊随访，评估神经功能恢复（mRS评分）、调整抗血小板及他汀类等二级预防用药；如出现言语不清加重、肢体无力进展、口角歪斜或意识障碍等新发症状，立即急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":923,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"cf2658e459b52e8ab04e867a8b7a662bb262a82d7a7f806b709bd66a0a474ad6","pinyin":"naogengsi","initials":"ngs","setting":"out","caseName":"门诊病历791","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历791",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-6f1ee974cdc5300845be","key":"v1-c9ccc21dfe2a3058|templates-6f1ee974cdc5300845be","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑出血","category":"门诊病历模板","raw":{"name":"脑出血","category":"门诊病历模板","case":{"case_name":"门诊病历792","templates":{"主诉":"突发剧烈头痛、呕吐伴意识障碍1小时","现病史":"患者存在以下病因或诱因：高血压（最常见病因，慢性高血压致小动脉破裂，出血部位多为基底节（壳核最常见）、丘脑、脑叶、脑干（桥脑）、小脑）、脑血管淀粉样变（多见于老年，脑叶出血，可反复）、动静脉畸形（多见于青年）、动脉瘤（多为蛛网膜下腔出血，另述）、凝血障碍或使用抗凝药（如华法林致INR升高而出血）、溶栓或抗血小板治疗（少见）、脑肿瘤（瘤卒中）、吸毒（可卡因）、外伤。患者于1小时前（于活动中、情绪激动或用力时突发，高血压性者多于活动、血压骤升时发病；亦可于休息或睡眠中发病，淀粉样变者多见于老年）出现以下表现：突发剧烈头痛（最为突出，难以忍受）、恶心呕吐（颅压高，可呈喷射性）、意识障碍（由嗜睡进展至昏迷，见于血肿量大或脑干受压者，呈进行性）、偏瘫（基底节出血压迫内囊，致对侧肢体瘫痪）、失语或偏身感觉障碍（脑叶出血累及皮层）、瞳孔异常（丘脑出血可呈针尖样小瞳孔，双侧者提示丘脑病变，为其特征；脑疝时一侧瞳孔散大、光反射消失，为颞叶沟回疝，属急症，有生命危险）、凝视（凝视病灶侧，即同向偏视）、癫痫（脑叶出血）、脑干出血（桥脑出血表现为深昏迷、针尖样瞳孔、高热、呼吸异常，预后极差）、小脑出血（表现为剧烈眩晕、呕吐、共济失调、枕部疼痛，因位于后颅窝可压迫脑干，属急症，常需手术）。出血量及部位需经CT评估，血肿量幕上>30ml、幕下>10ml者为手术指征。今日来我院急诊卒中中心就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.9℃，P62次/分（可减慢，颅压高时呈Cushing反应），R18次/分（异常者提示脑干受累），BP196/112mmHg（显著升高，血压骤升较常见）。神志呈嗜睡，格拉斯哥昏迷评分9分；瞳孔等大等圆，对光反射存在，需注意有无脑疝（一侧散大属急症）；神经系统检查见偏瘫、中枢性面瘫、失语、偏身感觉减退，病理征Babinski征阳性；脑膜刺激征阴性（血液流入蛛网膜下腔时可出现颈强直）；眼底检查未见出血（高血压者可出现视网膜出血）；生命体征需警惕Cushing三联征（高血压加心率慢加呼吸慢，提示颅压高，为脑疝前兆）；并注意有无脑干体征（去脑强直或去皮层强直，提示深昏迷）。","辅助检查":"【必做】头颅CT平扫（为急诊首选，可见高密度血肿，可立即确诊，并判断部位（基底节、丘脑、脑叶、小脑、脑干）、血肿量（按多田公式计算体积，用于评估手术指征及预后）、是否破入脑室及中线移位情况，为急诊关键检查，快速可行）、血糖（用于鉴别低血糖，必查）、血常规、凝血功能（抗凝相关者需查，如华法林致INR及凝血酶原时间延长，需逆转，可用维生素K加凝血酶原复合物，属急症，较为重要；血小板减少者需输注血小板）、电解质、肝肾功能、心电图。【病因评估】头颅CT血管成像或磁共振血管成像（CTA或MRA，用于评估血管畸形、动脉瘤及淀粉样变；磁敏感加权成像SWI可见微出血，为淀粉样变的标志；青年或无高血压者疑血管畸形或动脉瘤时尤应检查）、MRI（急性期后评估病因及陈旧腔隙性病灶）。【其他】颅内压监测（重症者可行脑室穿刺，兼作监测及引流，用于合并脑积水者）、脑电图（疑癫痫者）。","初步诊断":"1. 脑出血（部位：基底节（壳核）、丘脑、脑叶、小脑、脑干；血肿量约35ml；已破入脑室；病因考虑高血压性、淀粉样变或血管畸形等；需行意识分级）\n（注：脑出血为神经急症，死亡率高，早期处理的重点是防止血肿扩大及脑疝，患者ICU或卒中单元治疗。①急性期管理：监护意识、瞳孔及生命体征，神经外科随时待命；血压管理目标为收缩压140~160mmHg（依据INTERACT2研究，强化降压至<140mmHg可能获益，可防血肿扩大，但降压过低可致灌注不足，故存在争议，一般控制在<160mmHg并缓慢降压、密切监测），急性期不宜急剧降压；止血方面，抗凝相关者需逆转，华法林者予维生素K 10mg静注加凝血酶原复合物（PCC为首选，优于新鲜冰冻血浆），并复查INR，肝素相关者用鱼精蛋白，血小板减少或使用抗血小板药者出血时输注血小板，不常规使用rFⅦa（有血栓风险）；渗透性脱水可用甘露醇0.5~1g/kg，用于颅压高及脑水肿，需监测电解质及肾功能，肾功能差者可用甘油果糖；床头抬高30°。②手术：血肿清除的手术指征为小脑出血>10ml或脑干受压、脑积水者应急诊手术以挽救生命，较为重要；幕上出血>30ml且意识恶化或有占位效应者可行手术（开颅或微创穿刺引流），但深部或大量出血者手术获益存在争议（STICH研究显示早期手术未显示普遍获益），故应选择性实施，适用于浅表、脑叶、年轻或病情恶化者，需综合评估；脑积水者行脑室引流。③并发症处理：再出血需预防，控制血压及凝血，暂停抗栓药物；脑水肿及脑疝可用甘露醇或手术减压；感染以肺炎及泌尿系感染为主，为卒中相关；深静脉血栓于出血停止后可用低分子肝素，需权衡；消化道出血为应激性，可用PPI；电解质紊乱以低钠多见，可为脑性盐耗；癫痫予抗癫痫治疗，脑叶出血者多见；同时控制血糖。④康复：病情稳定后早期康复，包括肢体、言语、吞咽训练，行物理及作业治疗，在卒中单元实施；长期随访以促进功能恢复。⑤二级预防：控制血压最为关键（<130/80mmHg，可防再出血，最重要），戒烟酒，并针对病因治疗（血管畸形者行手术、介入或放疗以防再出血；淀粉样变者应避免抗栓治疗，需权衡，如既往有缺血事件，应由多学科决策；使用抗凝药者如合并心房颤动，脑出血后重启抗凝的时机为4~8周后，需评估，可选用新型口服抗凝药，并由多学科共同决策）。随访：由神经科随访，控制血压，促进功能恢复，预防复发。急诊神经外科及卒中中心应快速完成CT，做好血压及手术管理，防止脑疝，挽救生命。","处理方案":"【药物治疗】\n1. 控制血压（预防再出血核心）：苯磺酸氨氯地平片5mg po qd；或缬沙坦胶囊80mg po qd，长期维持，目标血压<140/90mmHg，每日晨起自测血压，据血压水平在医生指导下调整剂量，避免血压波动过大。\n2. 改善脑代谢、营养神经：胞磷胆碱钠胶囊0.2g po tid，连用4周；可续用吡拉西坦片0.8g po tid，连用4-8周。\n3. 防治脑水肿（头颅CT提示血肿周围水肿者）：七叶皂苷钠片30mg po bid，连用2周；若出现意识障碍加重或水肿明显，需住院静脉患者甘露醇脱水降颅压，不宜门诊处理。\n4. 保持大便通畅、降低腹压：乳果糖口服溶液15ml po qd，必要时加至bid，防止用力排便诱发再出血。\n\n【一般治疗及生活指导】\n1. 休息：急性期绝对卧床休息2-4周，头部抬高15°-30°，减少搬动及探视，避免情绪激动、精神紧张；恢复期保证充足睡眠，避免熬夜、劳累。\n2. 饮食：低盐（每日<6g）、低脂、低胆固醇饮食，多食新鲜蔬菜、水果及粗纤维食物，控制体重，戒烟、限酒。\n3. 活动：病情稳定后循序渐进进行肢体功能及语言康复训练，动作轻柔，避免剧烈运动、提重物及屏气发力动作。\n4. 禁忌：避免用力排便、剧烈咳嗽、突然改变体位；未经神经科及心内科评估，禁止自行服用阿司匹林、氯吡格雷等抗血小板或抗凝药物；保持情绪平稳，避免暴怒。\n\n【随诊要求】\n1. 本次就诊后1-2周复诊，复查头颅CT，评估血肿吸收及水肿消退情况。\n2. 每日晨起及午后自测血压并记录，血压持续≥140/90mmHg或波动明显时及时复诊调整降压方案。\n3. 恢复期每月复诊1次，3-6个月复查头颅CT、血脂、血糖、糖化血红蛋白及同型半胱氨酸，评估并控制危险因素。\n4. 若出现剧烈头痛、呕吐、意识障碍加重、一侧肢体无力加重、言语不清或抽搐，立即急诊就医，切勿延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":924,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0fa484e3b120a9b01b408d5a1cd4663ee137ed78333b7fc703000615b492ecc5","pinyin":"naochuxie","initials":"ncx","setting":"out","caseName":"门诊病历792","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历792",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-3ebbe72dee06a8beb108","key":"v1-c9ccc21dfe2a3058|templates-3ebbe72dee06a8beb108","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"蛛网膜下腔出血","category":"门诊病历模板","raw":{"name":"蛛网膜下腔出血","category":"门诊病历模板","case":{"case_name":"门诊病历793","templates":{"主诉":"突发剧烈头痛伴恶心呕吐2小时","现病史":"患者存在以下病因：颅内动脉瘤（最常见病因，约占80%，好发于前交通动脉、后交通动脉及大脑中动脉分叉处，女性、吸烟、高血压及有家族史者多见，动脉瘤家族史者应行筛查）、动静脉畸形、其他少见原因（凝血障碍、吸毒）。患者于2小时前（于活动、用力、情绪激动、排便时发病，亦可于静息时发病）突发以下表现：雷击样头痛（突发剧烈，为一生中最剧烈的头痛，为其特征，即刻达峰）、恶心呕吐（可呈喷射性，因颅压骤升）、短暂意识丧失（约半数患者可出现，于出血瞬间昏迷，可自行恢复，再出血时可再次昏迷）、颈强直（脑膜刺激征，多于出血后数小时出现）、癫痫、局灶神经体征（动脉瘤压迫所致，后交通动脉瘤可致动眼神经麻痹，表现为眼睑下垂、瞳孔散大、复视，为警示征象，较为重要）、眼底玻璃体下出血（Terson综合征）、发热（吸收热，因血性脑脊液所致）。需警惕再出血（未处理动脉瘤者24小时内再出血风险最高，死亡率高，属急症，处理时机关键）及脑血管痉挛（多于出血后4~14天出现，可致迟发性脑缺血，表现为意识恶化或新发局灶体征，甚至梗死，为主要致残原因），亦可出现脑积水（急性者致意识障碍，慢性者即正常压力脑积水，后期表现为步态异常、认知障碍、尿失禁）。以上并发症均需警惕。今日来我院急诊就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T37.4℃，P88次/分，R20次/分，BP178/100mmHg（血压升高）。神志清楚，格拉斯哥昏迷评分14分（按Hunt-Hess分级Ⅰ~Ⅴ级评估预后）；脑膜刺激征阳性，颈强直（多于出血后数小时出现，为其特征），Kernig征阳性；瞳孔检查注意有无动眼神经麻痹（一侧瞳孔散大、光反射消失，提示后交通动脉瘤，为警示征象，属急症，需急诊处理动脉瘤）；眼底可见玻璃体下出血（Terson综合征）；局灶体征注意有无偏瘫或失语（见于血肿或血管痉挛）；神经系统需全面检查，新发缺损提示血管痉挛，应监测意识变化，较为重要。","辅助检查":"【必做】头颅CT平扫（为急诊首选，可见蛛网膜下腔高密度影，位于基底池及脑沟，6小时内敏感度>95%，随发病时间延长敏感度下降；同时可评估有无脑室出血及脑积水）、腰椎穿刺（CT阴性而高度怀疑者适用，如发病>6~12小时CT可阴性；脑脊液呈均匀血性、不凝固，上清液黄变于出血后数小时出现，可用于鉴别穿刺损伤，较为重要，可行三管试验，逐管变清提示穿刺损伤，持续血性提示蛛网膜下腔出血；压力升高）。【血管评估】CT血管成像（CTA，动脉瘤检出敏感性高、快速，为首选，可定位）、数字减影血管造影（DSA，为金标准，可精确显示动脉瘤、评估血管痉挛并用于介入治疗，属有创检查）、磁共振血管成像（MRA，用于随访或存在禁忌时）。【其他】心电图（可见心肌缺血样改变，为神经源性心电异常，心电图可类似心肌梗死，如T波倒置，多属良性，需鉴别）、血常规、电解质、血糖、脑电图（疑癫痫者）、脑积水评估（超声或CT随访）。","初步诊断":"1. 蛛网膜下腔出血（动脉瘤性，具体部位待CTA或DSA确认；Hunt-Hess分级Ⅱ级；Fisher分级3级，依CT出血量评估血管痉挛风险；需监测并发症）\n（注：蛛网膜下腔出血为神经急症，再出血可致死，处理核心为早期处理动脉瘤并防治血管痉挛。①早期处理：绝对卧床（头高位），在神经外科ICU监护意识及生命体征，头痛者予镇痛（吗啡），烦躁者予镇静，血压控制收缩压<160mmHg，以防再出血并避免低灌注，通便以防用力诱发再出血，予抗癫痫预防用药（苯妥英或左乙拉西坦，脑叶出血者尤需），并注意营养。②动脉瘤处理：为关键，应尽早进行（24~72小时内，此期为再出血高峰，以防再出血），可行血管内介入（弹簧圈栓塞，为首选，适用于多数动脉瘤，微创）或开颅夹闭（适用于宽颈、巨大动脉瘤或伴血肿占位者），具体选择依动脉瘤部位、形态及医院经验而定，由神经介入与神经外科多学科协作。③脑血管痉挛防治：多于出血后4~14天出现，可致迟发性脑缺血，为主要致残原因。尼莫地平（60mg每4小时口服或静脉给药）可预防血管痉挛，为所有蛛网膜下腔出血患者的标准用药，连用21天，较为重要，需监测血压；发生痉挛缺血时可行三高治疗（高血压、高血容量、血液稀释），在ICU实施；经颅多普勒可监测血管痉挛（血流速度增快）；难治者可行血管内治疗（球囊扩张或动脉内罂粟碱）。④并发症：脑积水，急性者行脑室引流（意识障碍者以减压），慢性者即正常压力脑积水，后期行分流手术，可改善步态及认知；再出血需防，未处理动脉瘤者应尽早处理；低钠较常见（脑性盐耗或抗利尿激素异常），需补盐并监测；心电异常需监测。⑤随访：动脉瘤处理后复查影像（栓塞后注意有无残留或复发，需随访）；血管痉挛期后行康复，蛛网膜下腔出血后认知障碍较常见，需长期康复；未破裂动脉瘤者评估处理指征并随访。急诊神经科及神经外科应通过CT快速诊断，早期行动脉瘤栓塞或夹闭并患者尼莫地平，防止再出血及血管痉挛。本病预后仍差，死亡率约30~40%，与早期再出血相关，及时处理是关键。","处理方案":"【药物治疗】\n1. 尼莫地平片60mg口服q4h，连用21天（预防迟发性脑血管痉挛，用药期间监测血压，收缩压<100mmHg时减量或暂停）。\n2. 乳果糖口服溶液15ml口服bid（保持大便通畅，避免用力排便诱发再出血）。\n3. 对乙酰氨基酚片0.5g口服，头痛剧烈时临时服用，间隔≥6小时，24小时总量不超过2g（避免使用阿司匹林等影响凝血的药物）。\n4. 苯磺酸氨氯地平片5mg口服qd（血压≥140/90mmHg时启用，目标维持收缩压<140mmHg，保持血压平稳，避免大幅波动）。\n【一般治疗及生活指导】\n1. 充分卧床休息，避免劳累、情绪激动、剧烈咳嗽、用力排便、屏气等一切可引起颅内压骤升的行为。\n2. 低盐低脂清淡饮食，保证充足饮水，多食富含膳食纤维的蔬菜水果以保持大便通畅，戒烟戒酒，避免浓茶、咖啡等兴奋性饮品。\n3. 3-6个月内避免驾车、高空作业及重体力劳动，康复期循序渐进恢复活动量。\n4. 保持情绪平稳，规律作息，家属密切观察病情变化。\n【随诊要求】\n1. 就诊后1周、1个月、3个月门诊复诊，复查头颅CT/CTA或MRI/MRA评估蛛网膜下腔出血吸收及脑血管情况。\n2. 症状性脑血管痉挛高发期（发病后4～14天）内如新发肢体无力、言语不清、意识障碍等，须立即急诊就诊。\n3. 若尚未行血管内介入或手术处理，遵医嘱于出血吸收后2～3个月复查脑血管造影（DSA），评估动脉瘤或血管畸形的处理时机。\n4. 如突发剧烈头痛、恶心呕吐、抽搐或意识障碍加重，随时急诊就诊，切勿延误。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":925,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"68510f972baa164cc21f3a018a355ccd7e7006757defb201901a112bd3d552dc","pinyin":"zhuwangmoxiaqiangchuxie","initials":"zwmxqcx","setting":"out","caseName":"门诊病历793","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历793",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-23771f4000ba9af5bcb3","key":"v1-c9ccc21dfe2a3058|templates-23771f4000ba9af5bcb3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"短暂性脑缺血发作","category":"门诊病历模板","raw":{"name":"短暂性脑缺血发作","category":"门诊病历模板","case":{"case_name":"门诊病历794","templates":{"主诉":"一过性肢体无力伴言语不清5小时","现病史":"患者存在危险因素：高血压、糖尿病、血脂异常、房颤（可致心源性TIA）、吸烟、颈动脉狭窄、既往卒中或TIA史。患者于5小时前（本次发作时间）出现以下表现：一过性神经功能缺损（短暂，持续数分钟至<1小时，通常<15分钟，完全恢复，不留后遗症，此为定义要点，较为重要；但部分患者可超过1小时，若影像显示梗死则不属于TIA）、局灶缺损（一侧肢体无力或麻木，属颈内动脉系统；言语障碍，表现为失语或构音障碍；一过性黑矇，即单眼视力丧失，持续数秒至数分钟，为颈动脉狭窄的特征表现，患者可描述为眼前一过性黑蒙；眩晕、共济失调、复视、吞咽困难，属椎基底动脉系统，即后循环）、发作频率（可为单次或反复发作，TIA后卒中风险在48小时内最高，约5%，7天内约10%，故应急诊评估，较为重要；TIA是卒中最强的预警信号；可行ABCD2评分，即依年龄、血压、临床表现、持续时间及糖尿病进行风险分层，用于急诊或门诊评估）。本次发作已完全恢复，持续时间约20分钟。就诊时机为发作后尽快，宜在48小时内完成评估。今日来我院急诊或神经科就诊。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T36.6℃，P76次/分，R18次/分，BP156/88mmHg。神经系统检查本次多已恢复，体征正常（发作时的表现可通过录像或家属描述获取，较为重要）；发作间期查体：颈动脉未闻及杂音（杂音提示狭窄）、心脏听诊未闻及房颤（心律绝对不齐提示房颤）、眼底检查注意视网膜有无胆固醇栓子或血管异常、测量双上肢血压差（了解有无锁骨下动脉病变）、并做全面神经查体以排除持续缺损（若仍存在缺损则不属TIA，应按急性卒中处理）。","辅助检查":"【必做】头颅CT或MRI（用于排除脑梗死，MRI的DWI序列可见部分临床诊断为TIA者存在急性梗死，若影像阳性则按脑梗死处理，较为重要；DWI阳性者不属于TIA，而属卒中；同时排除出血及占位）、颈动脉超声（评估狭窄，为TIA的重要病因，需评估颈动脉狭窄）、心电图（了解有无房颤，即心源性因素）、血糖（低血糖可类似TIA，属可逆因素，必查）、血常规、血脂、血糖及糖化血红蛋白、凝血功能、肝肾功能。【心源性评估】动态心电图或Holter（用于筛查阵发房颤及隐源性TIA，较为重要，监测≥24~72小时）、超声心动图（经胸可查心内血栓及卵圆孔未闭，经食管用于隐源性者）、血沉及自身抗体（青年或疑血管炎者）。【影像】CTA或MRA（评估颈动脉及颅内血管有无大血管狭窄或闭塞，必要时）、灌注检查（较少用）。","初步诊断":"1. 短暂性脑缺血发作（TIA，定位：颈内动脉系统；ABCD2评分3分；已行卒中危险因素评估）\n（注：TIA属急症，为卒中前兆，48小时内卒中风险最高，应按急性卒中处理，急诊评估并启动二级预防，较为重要，不可因症状已缓解而忽视。①评估：发作后尽快进行，理想为24小时内完成；ABCD2评分≥4者患者48小时内由神经科评估或住院，<4者可在门诊7天内评估（设快速门诊，行颈动脉超声等）。②抗血小板：无禁忌者立即予阿司匹林300mg负荷加氯吡格雷75mg（双抗，用于轻型卒中或TIA，疗程21天，依据CHANCE及POINT研究，可显著降低早期卒中复发，较为重要），此后改为单药长期服用。③病因处理：合并房颤者属心源性，应予抗凝（华法林或新型口服抗凝药），启动时机为TIA后早期，因卒中风险高，轻型者可在数天至2周内启动，需评估，若脑梗死灶小则应尽早；颈动脉狭窄者若为症状性且狭窄>50%，应评估行颈动脉内膜剥脱（CEA）或支架置入（CAS），2周内手术获益最大，较为重要。④危险因素控制：血压<130/80mmHg，使用抗高血压药；他汀治疗（阿托伐他汀20~40mg，可稳定斑块，无论血脂水平）；糖尿病者控制HbA1c<7%；并戒烟、限酒、运动、控制体重及改善生活方式。⑤随访：症状再发应立即就诊（属卒中警报）；二级预防依从性方面，抗血小板、他汀及降压药应长期服用；颈动脉术后或狭窄者需随访；并监测复发。神经科或卒中门诊应按TIA处理，因其为小中风、大预警，规范评估与二级预防可显著降低卒中风险，较为重要。","处理方案":"【药物治疗】\n1. 抗血小板聚集：阿司匹林肠溶片100mg qd口服；若发病72小时内且ABCD2评分≥4分的中高危患者，予阿司匹林肠溶片100mg qd＋氯吡格雷片首剂300mg负荷、继以75mg qd，双联抗血小板治疗21天，21天后改为单一抗血小板药长期维持。\n2. 强化降脂稳定斑块：阿托伐他汀钙片20mg qn口服（或瑞舒伐他汀钙片10mg qn），长期服用，LDL-C目标值<1.8mmol/L或较基线降低≥50%。\n3. 控制血压：合并高血压者予苯磺酸氨氯地平片5mg qd口服，使血压平稳控制在<140/90mmHg，避免血压波动。\n4. 危险因素药物干预：合并心房颤动者（无禁忌证）首选利伐沙班片15mg qd抗凝治疗；合并糖尿病者予二甲双胍片0.5g bid口服，控制糖化血红蛋白<7.0%。\n\n【一般治疗及生活指导】\n1. 休息：急性期注意休息，保证充足睡眠，避免情绪激动、精神紧张及过度劳累，避免熬夜。\n2. 饮食：低盐低脂饮食，每日食盐摄入<6g（合并高血压者<5g），减少动物脂肪、油炸食品及腌制食品摄入，多食新鲜蔬菜、水果和全谷物，戒烟限酒（男性每日酒精量<25g）。\n3. 活动：症状缓解后循序渐进地开始活动，每周至少150分钟中等强度有氧运动（如快走、慢跑、太极拳），避免剧烈运动、突然用力及屏气动作。\n4. 禁忌：避免用力排便及体位突然改变，保持大便通畅；规律监测血压、血糖，严格遵医嘱服药，切勿自行停药、减量或改药。\n\n【随诊要求】\n1. 发病后2周内到神经内科门诊复诊，复查血压、血脂、空腹血糖、肝肾功能及血常规；若再次出现一过性肢体无力、言语不清、面部歪斜、视物模糊等症状，应立即急诊就诊。\n2. 服用抗血小板/抗凝药物期间若出现牙龈出血、皮肤瘀斑、鼻衄、黑便或血尿等出血倾向，及时就诊并复查血常规及凝血功能。\n3. 每3～6个月定期门诊随访，动态评估血压、血脂、血糖等危险因素控制情况；每年复查颈动脉超声、经颅多普勒（TCD），必要时复查头颅MRI（含DWI），评估血管狭窄进展及有无新发缺血灶。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":926,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b360cc956d9502eb5397544c0d6325858713370d6206e8f3af4f19985ecb4778","pinyin":"duanzanxingnaoquexuefazuo","initials":"dzxnqxfz","setting":"out","caseName":"门诊病历794","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历794",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-c62f9efdd562524517f6","key":"v1-c9ccc21dfe2a3058|templates-c62f9efdd562524517f6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑血管畸形","category":"门诊病历模板","raw":{"name":"脑血管畸形","category":"门诊病历模板","case":{"case_name":"门诊病历795","templates":{"主诉":"头痛1天","现病史":"患者1周前无明显诱因出现脑血管畸形相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以头痛1天为主诉就诊，现病史提示近1周头痛逐渐加重、自服药物效果欠佳，脑血管畸形可表现为头痛、癫痫及颅内出血，需完善血常规检查排除感染、贫血所致头痛；完善生化全项检查了解肝肾功能、血糖、电解质水平，排除代谢性因素所致头痛，并为后续可能的介入或手术治疗评估重要脏器功能；完善凝血功能检查排除凝血机制障碍，为脑血管造影及介入治疗做好术前准备；完善血糖检查排除低血糖及糖尿病相关头痛，查血脂检查了解血脂水平、评估动脉粥样硬化危险因素；完善同型半胱氨酸检查评估血管内皮损伤及脑卒中风险；脑血管畸形确诊依靠影像学，急诊完善头颅CT/MRI检查排除颅内出血，并明确畸形血管团的位置、供血动脉及引流静脉，加做磁共振血管成像协助判断，必要时行全脑血管造影检查以明确诊断并指导治疗；完善颈动脉超声检查明确颈部血管有无斑块及狭窄，完善经颅多普勒检查了解颅内血流速度及有无盗血现象；完善心电图检查排除心律失常，完善心脏超声检查排查心源性栓子来源、明确有无合并心脏血管畸形；若头痛剧烈伴脑膜刺激征，病情稳定后必要时完善腰椎穿刺检查脑脊液以鉴别颅内感染、蛛网膜下腔出血，但需先行影像学检查排除颅内高压所致脑疝风险。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 脑血管畸形\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 预防及控制癫痫发作：左乙拉西坦片0.5g po bid，连续服用3-6个月（适用于伴癫痫发作或出血后预防者），用药期间定期复查血常规、肝肾功能，注意观察嗜睡、情绪异常等不良反应。\n2. 营养神经、促进神经功能恢复：胞磷胆碱钠片0.2g po tid，疗程4-8周。\n3. 控制血压（合并高血压者）：苯磺酸氨氯地平片5mg po qd，目标血压控制在130-140/80-90mmHg，避免血压剧烈波动诱发畸形血管破裂出血；禁用阿司匹林等抗血小板药及抗凝药物。\n4. 头痛对症治疗（伴头痛者）：对乙酰氨基酚片0.5g po prn，每日总量不超过2g，症状缓解即停用。\n【一般治疗及生活指导】\n1. 休息与活动：保证充足睡眠，避免熬夜、情绪激动及过度劳累；避免剧烈运动、重体力劳动、用力排便、剧烈咳嗽、屏气等增加颅内压的行为，可进行散步等舒缓活动。\n2. 饮食：低盐低脂饮食，多食新鲜蔬菜水果及富含膳食纤维食物以保持大便通畅，戒烟限酒，避免辛辣刺激性食物。\n3. 禁忌：严禁使用阿司匹林、华法林等抗血小板/抗凝药物及活血化瘀类药物；育龄期女性应避孕，避免使用口服避孕药；避免长时间低头、潜水、乘坐过山车等易致血压骤变的场景。\n4. 自我监测：若出现突发剧烈头痛（\"雷击样\"头痛）、恶心呕吐、肢体无力、言语不清、视物模糊、抽搐或意识障碍，立即急诊就诊。\n【随诊要求】\n建议每3-6个月于神经外科/神经内科门诊复诊1次，复查头颅MRI及MRA（必要时CTA）评估畸形血管团大小及血流动力学变化；有癫痫发作者每3个月复诊，遵医嘱调整抗癫痫药物剂量并监测血药浓度；有手术或介入治疗指征者，应完善全脑血管造影（DSA）明确供血动脉、引流静脉及畸形血管团分级（Spetzler-Martin分级），综合评估破裂出血风险后由神经外科制定介入栓塞、显微手术切除或立体定向放射外科（γ刀）等治疗方案；如出现上述紧急症状随时急诊就诊。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":927,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0c00960259f6eece7cec7dfaf58c7bcd4a6c6d1ed734fe49fe53919b59ef2789","pinyin":"naoxueguanjixing","initials":"nxgjx","setting":"out","caseName":"门诊病历795","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历795",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-2c47da6f172479c140d0","key":"v1-c9ccc21dfe2a3058|templates-2c47da6f172479c140d0","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑动脉炎","category":"门诊病历模板","raw":{"name":"脑动脉炎","category":"门诊病历模板","case":{"case_name":"门诊病历796","templates":{"主诉":"头痛1天","现病史":"患者1周前无明显诱因出现脑动脉炎相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以头痛1天为主诉就诊，现病史提示近1周头痛逐渐加重、自服药物效果欠佳，脑动脉炎多见于中青年，可致血管狭窄闭塞及脑梗死，需完善血常规检查了解有无贫血、血小板及白细胞异常，排除感染、血液系统疾病所致头痛；完善生化全项检查了解肝肾功能、血糖及电解质水平，排除代谢性因素所致头痛，并为免疫抑制治疗评估脏器功能；完善凝血功能检查排除凝血机制障碍及高凝状态；完善血糖检查排除低血糖及糖尿病相关头痛，查血脂检查了解血脂水平、评估动脉粥样硬化危险因素；完善同型半胱氨酸检查评估高同型半胱氨酸血症所致血管内皮损伤及脑卒中风险；脑动脉炎诊断依靠血管影像，急诊完善头颅CT/MRI检查排除颅内出血及占位，并明确颅内动脉管壁增厚、管腔狭窄及脑梗死灶情况，必要时加做磁共振血管成像；完善颈动脉超声检查明确颈部血管有无管壁增厚、斑块及狭窄，完善经颅多普勒检查了解颅内动脉血流速度增快及狭窄所致的涡流信号；完善心电图检查排除心律失常及心肌缺血，完善心脏超声检查排查心源性栓子来源；本病需与感染性、结缔组织病相关血管炎鉴别，病情稳定后必要时完善腰椎穿刺检查脑脊液压力、细胞及蛋白水平以鉴别颅内感染及自身免疫性疾病，同时完善血沉、C反应蛋白及自身抗体检查协助诊断。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 脑动脉炎\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 糖皮质激素（抗炎、免疫抑制核心用药）：泼尼松片 0.5～1mg/kg·d，成人常规40mg qd晨起顿服；炎症指标（ESR、CRP）及症状缓解后每2～4周递减5mg，至维持量5～10mg qd，总疗程6～12个月，需在医师指导下缓慢减量，不可骤然停药。\n2. 免疫抑制剂（中重度或激素依赖者联合）：环磷酰胺片 50mg bid口服，疗程3～6个月；或硫唑嘌呤片 50mg bid口服。用药期间每2周复查血常规、肝肾功能，白细胞<4.0×10⁹/L时暂停并复诊调整。\n3. 抗血小板聚集、防治脑梗死：阿司匹林肠溶片 100mg qd口服，餐后服用，长期维持；不能耐受者改用氯吡格雷片 75mg qd。\n4. 神经营养与脑保护：甲钴胺片 0.5mg tid＋维生素B1片 10mg tid口服，疗程4周；伴头痛、血管痉挛者加用尼莫地平片 30mg tid。\n【一般治疗及生活指导】\n1. 休息：急性期及症状明显时卧床休息，保证充足睡眠，避免劳累、情绪激动、剧烈活动及长时间低头用眼。\n2. 饮食：低盐低脂饮食，戒烟限酒，每日饮水1500～2000ml，控制血压、血糖、血脂达标；规律作息。\n3. 预防感染：注意保暖、预防呼吸道感染；合并结核、梅毒等感染源者需同步规范抗感染治疗（结核性脑动脉炎应规范抗结核治疗至少12个月）。\n4. 活动：病情稳定后循序渐进进行肢体功能、言语及平衡康复训练，避免跌倒；定期监测血压、体温。\n【随诊要求】\n1. 用药初期每2～4周复诊1次，评估头痛、肢体无力、言语障碍等症状变化及血压情况；患者免疫抑制剂者每2周复查血常规、肝肾功能。\n2. 每1～3个月复查血沉、C反应蛋白等炎症指标及自身抗体谱，评估病情活动度。\n3. 每3～6个月复查头颅MRI＋MRA（必要时CTA或DSA），评估脑血管狭窄、闭塞及病灶变化。\n4. 激素减量期间每2～4周随诊调整剂量，切勿自行停药；如出现新发偏瘫、失语、抽搐、剧烈头痛或视力下降，立即急诊就医。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":928,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ef147e4b83da37a1d3bf835f14bfcc9fa670c433a54120877602e9aa9b63ad6d","pinyin":"naodongmaiyan","initials":"ndmy","setting":"out","caseName":"门诊病历796","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历796",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]},{"id":"templates-b7263808eccc366453b5","key":"v1-c9ccc21dfe2a3058|templates-b7263808eccc366453b5","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"脑静脉窦血栓","category":"门诊病历模板","raw":{"name":"脑静脉窦血栓","category":"门诊病历模板","case":{"case_name":"门诊病历797","templates":{"主诉":"头痛1天","现病史":"患者1周前无明显诱因出现脑静脉窦血栓相关症状，逐渐加重，伴轻度乏力，无明显发热，无恶心呕吐。自服药物效果欠佳，今日来我院门诊就诊。发病以来饮食睡眠尚可，大小便正常，体重无明显变化。","既往史":"既往体健，否认高血压、糖尿病、冠心病等慢性病史。否认肝炎、结核等传染病史。否认手术外伤史。否认食物药物过敏史。预防接种史随社会。","个人史及过敏史":"生于原籍，久居本地，无疫区疫水接触史，无特殊粉尘毒物放射性物质接触史。不吸烟，不饮酒。生活规律。否认食物药物过敏史。","体格检查":"T 36.8℃，P 80次/分，R 18次/分，BP 125/80mmHg。神志清楚，精神可，自主体位，查体合作。皮肤黏膜无黄染，浅表淋巴结未触及肿大。颈软，无抵抗。双肺呼吸音清，未闻及干湿性啰音。心率80次/分，律齐，各瓣膜听诊区未闻及病理性杂音。腹平软，无压痛，肝脾肋下未触及。生理反射存在，病理反射未引出。","辅助检查":"检查计划：患者以头痛1天为主诉就诊，现病史提示近1周头痛逐渐加重、自服药物效果欠佳，脑静脉窦血栓以头痛、视乳头水肿及颅内压增高为主要表现，需完善血常规检查排除感染、贫血及血液系统疾病所致头痛；完善生化全项检查了解肝肾功能、血糖及电解质水平，排除代谢性因素所致头痛，并为抗凝治疗评估出血与脏器功能风险；完善凝血功能检查明确有无高凝状态及凝血机制异常，评估抗凝治疗的安全性；完善血糖检查排除低血糖及糖尿病相关头痛，查血脂检查了解血脂水平、评估血栓形成的危险因素；完善同型半胱氨酸检查评估高同型半胱氨酸血症所致血管内皮损伤及血栓形成风险；脑静脉窦血栓确诊依靠影像学，急诊完善头颅CT/MRI检查排除颅内出血及占位，加做磁共振静脉成像明确静脉窦血栓的部位、范围及有无静脉性梗死，必要时行全脑血管造影检查进一步明确诊断；完善颈动脉超声检查明确颈部血管情况，完善经颅多普勒检查了解颅内血流速度及有无静脉回流障碍；完善心电图检查排除心律失常及心肌缺血，完善心脏超声检查排查心源性栓子来源；若需与颅内感染、蛛网膜下腔出血鉴别，病情稳定后必要时完善腰椎穿刺检查脑脊液压力、细胞及蛋白水平，但颅内压明显增高者应先行影像学检查并谨慎操作，以防脑疝风险。\n\n（检查清单）\n【必做检查】\n血常规、生化全项、凝血功能、血糖、血脂、同型半胱氨酸\n\n【影像学检查】\n头颅CT/MRI、颈动脉超声、经颅多普勒\n\n【其他检查】\n心电图、心脏超声（排查栓子来源）、腰椎穿刺（必要时）","初步诊断":"1. 脑静脉窦血栓\n（注：根据患者病史、体征及辅助检查综合判断，必要时请相关科室会诊。）","处理方案":"【药物治疗】\n1. 抗凝治疗（核心治疗）：低分子肝素钙注射液4100IU（0.4ml）皮下注射 bid，连用5~7天，同时（或第2天起）桥接口服抗凝药；或直接口服利伐沙班片15mg bid×3周，此后改为20mg qd，总疗程3~6个月，疗程结束后由神经内科评估是否延长抗凝。\n2. 华法林方案：华法林钠片2.5mg qd起始，每3~5天根据INR调整剂量，维持INR 2.0~3.0，疗程3~6个月（妊娠相关或复发性血栓者疗程≥6个月）；用药期间每周监测INR，达标稳定后每2~4周复查。\n3. 降颅压治疗（合并颅内高压、视乳头水肿者）：乙酰唑胺片250mg bid，疗程1~2周后评估；必要时加用呋塞米片20mg qd短期患者，注意监测电解质及肾功能。若出现视力进行性下降或意识障碍，需急诊行血管内介入或手术减压评估。\n4. 对症治疗：头痛明显者予对乙酰氨基酚片0.5g prn，每日不超过2g，避免使用含雌激素成分药物；继发癫痫发作者予左乙拉西坦片500mg bid。\n\n【一般治疗及生活指导】\n1. 休息：急性期卧床休息，抬高床头15°~30°以利颅内静脉回流、降低颅内压；避免用力排便、剧烈咳嗽、摒气及Valsalva动作。\n2. 饮食：低盐低脂饮食，保证每日饮水1500~2000ml，避免脱水致血液浓缩；戒烟戒酒，避免进食辛辣刺激食物。\n3. 活动：病情稳定（症状缓解、无新发神经功能缺损）后循序渐进下床活动，避免长时间低头、猛起猛站及剧烈运动，防跌倒。\n4. 禁忌：停用口服避孕药、雌激素替代治疗及其他促血栓形成药物；抗凝期间避免磕碰及锐器作业，注意牙龈出血、皮肤瘀斑、鼻衄、血尿、黑便等出血征象，出现时及时就医。\n\n【随诊要求】\n1. 抗凝治疗期间每周复查凝血功能（INR）及血常规、肝肾功能；INR稳定后每2~4周复查一次，直至停用抗凝药。\n2. 治疗后1个月复查头颅MRV或DSA评估静脉窦再通情况，此后每3~6个月复查头颅MRI+MRV；出现新发剧烈头痛、视物模糊、癫痫发作、肢体无力或意识改变时立即就诊，勿等待预约复诊。\n3. 抗凝药减量、停药或调整方案前必须经神经内科医师评估，不可自行停药；明确病因（感染性、产后/妊娠期、口服避孕药相关、易栓症等）者，应于感染科、产科或血液科相应随访处理。"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":929,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6eb95e982859b94738e19fee8301ba438b51d08de0411aa665342f2425dee4c5","pinyin":"naojingmaidouxueshuan","initials":"njmdxs","setting":"out","caseName":"门诊病历797","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","处理方案"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历797",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 处理方案",30],["主要诊断编码","",30]]}]);